def crm_create_company(properties, associations=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_create_company"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers ----
    def _record_request(portal_id, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": now,
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _pick_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list) and objs:
            pid = objs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        if isinstance(props, list) and props:
            pid = props[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list) and assoc_types:
            pid = assoc_types[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list) and subs:
            pid = subs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    def _validate_uri(u):
        if not isinstance(u, str):
            return False
        u = u.strip()
        if not u:
            return True
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _tokenize(s):
        if not isinstance(s, str):
            return ""
        return " ".join(re.findall(r"[A-Za-z0-9]+", s.lower()))

    def _build_search_text(props):
        parts = []
        for k, v in props.items():
            if v is None:
                continue
            if isinstance(v, (str, int, float, bool)):
                parts.append(str(v))
        return _tokenize(" ".join(parts)) or None

    # ---- ambient auth / portal scope ----
    portal_id = _pick_portal_id()
    if not portal_id:
        _record_request(portal_id=None, status=401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available portal context in datastore.")

    # ---- validate inputs ----
    if not isinstance(properties, dict):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.")
    if associations is not None and not isinstance(associations, list):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "associations must be an array when provided.")

    allowed_lifecycle = {"lead", "customer", "opportunity", "subscriber", "other"}
    if "lifecyclestage" in properties and properties["lifecyclestage"] is not None:
        if not isinstance(properties["lifecyclestage"], str) or properties["lifecyclestage"] not in allowed_lifecycle:
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid lifecyclestage.", allowed=sorted(allowed_lifecycle))
    if "website" in properties and properties["website"] is not None:
        if not _validate_uri(properties["website"]):
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid website URI. Must be an http/https URL.")

    # Validate against property definitions when they exist for the object_type
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    company_defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "companies"]
    defs_by_name = {d.get("name"): d for d in company_defs if isinstance(d.get("name"), str)}
    if company_defs:
        unknown = [k for k in properties.keys() if k not in defs_by_name]
        # Tool schema allows additionalProperties, but business rules gate by portal policy; no policy store exists,
        # so default to allowing unknowns unless definitions are present AND they are explicitly hidden/archived checks.
        # We still enforce "archived definitions cannot be written".
        for k, v in properties.items():
            d = defs_by_name.get(k)
            if d:
                if d.get("status") == "archived" or d.get("archived") is True:
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be written.")
                # If definition type is enumeration, enforce options if present
                if d.get("type") == "enumeration" and v not in (None, ""):
                    opts = d.get("options") if isinstance(d.get("options"), list) else []
                    opt_values = {o.get("value") for o in opts if isinstance(o, dict) and "value" in o}
                    if opt_values and v not in opt_values:
                        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", f"Invalid value for '{k}'.", allowed=sorted([x for x in opt_values if isinstance(x, str)]))
        # Unknown allowed per tool schema; do not reject.

    # ---- validate associations payload first (atomic create) ----
    assoc_types = _load("crm_association_types.json")
    if not isinstance(assoc_types, list):
        assoc_types = []
    assoc_type_index = {}
    for r in assoc_types:
        if r.get("portal_id") != portal_id:
            continue
        k = (r.get("from_object_type"), r.get("to_object_type"), r.get("association_category"), r.get("association_type_id"))
        assoc_type_index[k] = r

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []
    objs_by_internal_id = {o.get("id"): o for o in objs if isinstance(o, dict) and isinstance(o.get("id"), str)}
    # For "to.id" the tool typically uses HubSpot object ID; we resolve within portal by hubspot_object_id across any type.
    to_by_hubspot_id = {}
    for o in objs:
        if o.get("portal_id") != portal_id:
            continue
        hid = o.get("hubspot_object_id")
        if isinstance(hid, str):
            to_by_hubspot_id.setdefault(hid, []).append(o)

    assoc_edges_to_create = []
    if associations:
        if not all(isinstance(a, dict) for a in associations):
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each association must be an object.")
        for a in associations:
            to = a.get("to")
            types = a.get("types")
            if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Association.to.id must be a non-empty string.")
            if not isinstance(types, list) or not types:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Association.types must be a non-empty array.")
            # resolve target object
            candidates = to_by_hubspot_id.get(to["id"], [])
            candidates = [c for c in candidates if c.get("status") == "active" and c.get("archived") is False]
            if not candidates:
                _record_request(portal_id, status=404, error_code="NOT_FOUND")
                return _err("NOT_FOUND", f"Associated object with id '{to['id']}' not found in portal.")
            if len(candidates) > 1:
                # Ambiguous hubspot_object_id across types; HubSpot ids are globally unique per portal, so treat as conflict.
                _record_request(portal_id, status=409, error_code="CONFLICT")
                return _err("CONFLICT", f"Ambiguous associated object id '{to['id']}' within portal.")
            target = candidates[0]
            to_internal_id = target["id"]
            to_type = target["object_type"]
            for t in types:
                if not isinstance(t, dict):
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Association type entry must be an object.")
                cat = t.get("associationCategory")
                atid = t.get("associationTypeId")
                if not isinstance(cat, str) or not cat:
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "associationCategory must be a non-empty string.")
                if not isinstance(atid, (int, float)) or int(atid) < 1:
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "associationTypeId must be a number >= 1.")
                atid_num = int(atid)
                k = ("companies", to_type, cat, atid_num)
                defn = assoc_type_index.get(k)
                if not defn or defn.get("status") != "active":
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Association type is not defined/active for this portal.", fromObjectType="companies", toObjectType=to_type, associationCategory=cat, associationTypeId=atid_num)
                assoc_edges_to_create.append((to_internal_id, to_type, cat, atid_num))

    # ---- create company object ----
    # enforce unique(portal_id, object_type, hubspot_object_id) by choosing a new hubspot_object_id not used
    used_hub_ids = {o.get("hubspot_object_id") for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == "companies"}
    # generate a numeric-ish id string
    base = int(time.time() * 1000)
    hub_id = str(base)
    i = 0
    while hub_id in used_hub_ids:
        i += 1
        hub_id = str(base + i)

    new_row_id = "obj_" + uuid.uuid4().hex
    new_props = dict(properties)
    created = {
        "id": new_row_id,
        "portal_id": portal_id,
        "object_type": "companies",
        "hubspot_object_id": hub_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": new_props,
        "properties_version": 1,
        "search_text": _build_search_text(new_props),
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now
    }

    # Uniqueness constraint (portal_id, object_type, hubspot_object_id) already satisfied by generation.
    objs.append(created)

    # ---- create/upsert associations ----
    assocs = _load("crm_associations.json")
    if not isinstance(assocs, list):
        assocs = []
    for (to_internal_id, to_type, cat, atid_num) in assoc_edges_to_create:
        if to_internal_id == new_row_id:
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "from_object_id cannot equal to_object_id.")
        # unique(portal_id, from_object_id, to_object_id, association_category, association_type_id)
        existing = None
        for e in assocs:
            if e.get("portal_id") == portal_id and e.get("from_object_id") == new_row_id and e.get("to_object_id") == to_internal_id and e.get("association_category") == cat and int(e.get("association_type_id") or 0) == atid_num:
                existing = e
                break
        if existing:
            # Upsert active: if archived, reactivate
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
                existing["updated_at"] = now
        else:
            assocs.append({
                "id": "asc_" + uuid.uuid4().hex,
                "portal_id": portal_id,
                "from_object_id": new_row_id,
                "to_object_id": to_internal_id,
                "from_object_type": "companies",
                "to_object_type": to_type,
                "association_category": cat,
                "association_type_id": atid_num,
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now
            })

    _save("crm_objects.json", objs)
    _save("crm_associations.json", assocs)

    _record_request(portal_id, status=201)
    # Return record in a HubSpot-like envelope
    return {
        "id": created["hubspot_object_id"],
        "properties": created["properties"],
        "createdAt": created["hubspot_created_at"],
        "updatedAt": created["hubspot_updated_at"],
        "archived": created["archived"]
    }

def crm_update_company(companyId, properties, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
