        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": now,
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _pick_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list) and objs:
            pid = objs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        if isinstance(props, list) and props:
            pid = props[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list) and assoc_types:
            pid = assoc_types[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list) and subs:
            pid = subs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    def _validate_uri(u):
        if not isinstance(u, str):
            return False
        u = u.strip()
        if not u:
            return True
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _tokenize(s):
        if not isinstance(s, str):
            return ""
        return " ".join(re.findall(r"[A-Za-z0-9]+", s.lower()))

    def _build_search_text(props):
        parts = []
        for k, v in props.items():
            if v is None:
                continue
            if isinstance(v, (str, int, float, bool)):
                parts.append(str(v))
        return _tokenize(" ".join(parts)) or None

    portal_id = _pick_portal_id()
    if not portal_id:
        _record_request(portal_id=None, status=401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available portal context in datastore.")

    if not isinstance(companyId, str) or not companyId:
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "companyId must be a non-empty string.")
    if not isinstance(properties, dict):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.")

    allowed_lifecycle = {"lead", "customer", "opportunity", "subscriber", "other"}
    if "lifecyclestage" in properties and properties["lifecyclestage"] is not None:
        if not isinstance(properties["lifecyclestage"], str) or properties["lifecyclestage"] not in allowed_lifecycle:
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid lifecyclestage.", allowed=sorted(allowed_lifecycle))
    if "website" in properties and properties["website"] is not None:
        if not _validate_uri(properties["website"]):
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid website URI. Must be an http/https URL.")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []
    target = None
    for o in objs:
        if o.get("portal_id") == portal_id and o.get("object_type") == "companies" and o.get("hubspot_object_id") == companyId:
            target = o
            break
    if not target or target.get("status") != "active" or target.get("archived") is True:
        _record_request(portal_id, status=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Company not found.")

    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    company_defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "companies"]
    defs_by_name = {d.get("name"): d for d in company_defs if isinstance(d.get("name"), str)}
    if company_defs:
        for k, v in properties.items():
            d = defs_by_name.get(k)
            if d:
                if d.get("status") == "archived" or d.get("archived") is True:
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be written.")
                if d.get("hidden") is True:
                    # Portal policy store not provided; default allow hidden fields if schema allows.
                    pass
                if d.get("type") == "enumeration" and v not in (None, ""):
                    opts = d.get("options") if isinstance(d.get("options"), list) else []
                    opt_values = {o.get("value") for o in opts if isinstance(o, dict) and "value" in o}
                    if opt_values and v not in opt_values:
                        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", f"Invalid value for '{k}'.", allowed=sorted([x for x in opt_values if isinstance(x, str)]))

    # Apply updates (empty string means clear)
    changed = False
    for k, v in properties.items():
        if v == "":
            if k in target.get("properties", {}):
                target["properties"].pop(k, None)
                changed = True
        else:
            if "properties" not in target or not isinstance(target["properties"], dict):
                target["properties"] = {}
            if target["properties"].get(k) != v:
                target["properties"][k] = v
                changed = True

    if not changed:
        # Still considered a successful update in HubSpot, but "no success without effect" rule: must have effect.
        _record_request(portal_id, status=409, error_code="CONFLICT")
        return _err("CONFLICT", "Update would not change any fields.")

    target["properties_version"] = int(target.get("properties_version") or 1) + 1
    target["updated_at"] = now
    target["hubspot_updated_at"] = now
    target["search_text"] = _build_search_text(target["properties"])

    _save("crm_objects.json", objs)
    _record_request(portal_id, status=200)
    return {
        "id": target["hubspot_object_id"],
        "properties": target["properties"],
        "createdAt": target.get("hubspot_created_at"),
        "updatedAt": target.get("hubspot_updated_at"),
        "archived": target["archived"]
    }

def crm_get_company(companyId, properties=None, associations=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_get_company"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_request(portal_id, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": now,
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _pick_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list) and objs:
            pid = objs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        if isinstance(props, list) and props:
            pid = props[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list) and assoc_types:
            pid = assoc_types[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list) and subs:
            pid = subs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    portal_id = _pick_portal_id()
    if not portal_id:
        _record_request(portal_id=None, status=401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available portal context in datastore.")

    if not isinstance(companyId, str) or not companyId:
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "companyId must be a non-empty string.")
    if properties is not None and not (isinstance(properties, list) and all(isinstance(x, str) for x in properties)):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an array of strings when provided.")
    if associations is not None:
        if not (isinstance(associations, list) and all(isinstance(x, str) for x in associations)):
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations must be an array of strings when provided.")
        allowed_assoc = {"contacts", "deals", "tickets"}
        bad = [a for a in associations if a not in allowed_assoc]
        if bad:
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported association name(s).", invalid=bad, allowed=sorted(allowed_assoc))

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []
    company = None
    for o in objs:
        if o.get("portal_id") == portal_id and o.get("object_type") == "companies" and o.get("hubspot_object_id") == companyId:
            company = o
            break
    if not company or company.get("archived") is True or company.get("status") != "active":
        _record_request(portal_id, status=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Company not found.")

    # Validate requested property names against definitions when they exist
    if properties is not None:
        prop_defs = _load("crm_object_properties.json")
        if not isinstance(prop_defs, list):
            prop_defs = []
        company_defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "companies" and d.get("status") == "active" and d.get("archived") is False]
        if company_defs:
            defs_by_name = {d.get("name") for d in company_defs if isinstance(d.get("name"), str)}
            bad = [p for p in properties if p not in defs_by_name]
            if bad:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown requested property name(s).", invalid=bad)

    out_props = {}
    stored_props = company.get("properties") if isinstance(company.get("properties"), dict) else {}
    if properties is None:
        out_props = dict(stored_props)
    else:
        for p in properties:
            if p in stored_props:
                out_props[p] = stored_props[p]

    result = {
        "id": company["hubspot_object_id"],
        "properties": out_props,
        "createdAt": company.get("hubspot_created_at"),
        "updatedAt": company.get("hubspot_updated_at"),
        "archived": company.get("archived", False)
    }

    if associations:
        assocs = _load("crm_associations.json")
        if not isinstance(assocs, list):
            assocs = []
        objs_by_id = {o.get("id"): o for o in objs if isinstance(o, dict) and o.get("portal_id") == portal_id and isinstance(o.get("id"), str)}
        internal_company_id = company.get("id")
        assoc_out = {}

        name_to_type = {"contacts": "contacts", "deals": "deals", "tickets": "tickets"}
        for assoc_name in associations:
            want_type = name_to_type[assoc_name]
            ids = []
            for e in assocs:
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                if e.get("from_object_id") == internal_company_id and e.get("from_object_type") == "companies" and e.get("to_object_type") == want_type:
                    tgt = objs_by_id.get(e.get("to_object_id"))
                    if tgt and tgt.get("status") == "active" and tgt.get("archived") is False:
                        hid = tgt.get("hubspot_object_id")
                        if isinstance(hid, str):
                            ids.append(hid)
                elif e.get("to_object_id") == internal_company_id and e.get("to_object_type") == "companies" and e.get("from_object_type") == want_type:
                    src = objs_by_id.get(e.get("from_object_id"))
                    if src and src.get("status") == "active" and src.get("archived") is False:
                        hid = src.get("hubspot_object_id")
                        if isinstance(hid, str):
                            ids.append(hid)
            assoc_out[assoc_name] = {"results": [{"id": x} for x in ids]}
        result["associations"] = assoc_out

    _record_request(portal_id, status=200)
    return result

def crm_search_companies(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_search_companies"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_request(portal_id, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": now,
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _pick_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list) and objs:
            pid = objs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        if isinstance(props, list) and props:
            pid = props[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list) and assoc_types:
            pid = assoc_types[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list) and subs:
            pid = subs[0].get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    def _as_number(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str) and x.strip() != "":
            try:
                return float(x)
            except Exception:
                return None
        return None

    def _tokenize(s):
        if not isinstance(s, str):
            return []
        return re.findall(r"[A-Za-z0-9]+", s.lower())

    def _get_prop(obj_props, name):
        if not isinstance(obj_props, dict):
            return None
        return obj_props.get(name)

    def _eval_filter(obj, flt):
        prop_name = flt.get("propertyName")
        op = flt.get("operator")
        val = flt.get("value", None)
        props_map = obj.get("properties") if isinstance(obj.get("properties"), dict) else {}

        if not isinstance(prop_name, str) or not prop_name:
            return _err("VALIDATION_ERROR", "filter.propertyName must be a non-empty string.")
        if op not in {"EQ", "NEQ", "LT", "LTE", "GT", "GTE", "BETWEEN", "IN", "NOT_IN", "HAS_PROPERTY", "NOT_HAS_PROPERTY", "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"}:
            return _err("VALIDATION_ERROR", "Invalid operator.", operator=op)

        if op in {"HAS_PROPERTY", "NOT_HAS_PROPERTY"}:
            has = prop_name in props_map and props_map.get(prop_name) not in (None, "")
            return (has if op == "HAS_PROPERTY" else (not has))

        prop_val = _get_prop(props_map, prop_name)

        if op in {"CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"}:
            if not isinstance(val, str) or not val.strip():
                return _err("VALIDATION_ERROR", "CONTAINS_TOKEN requires a non-empty string value.")
            hay = obj.get("search_text")
            if not isinstance(hay, str):
                hay = ""
            tokens = set(_tokenize(hay))
            needle_tokens = _tokenize(val)
            ok = all(t in tokens for t in needle_tokens) if needle_tokens else False
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        if op == "BETWEEN":
            if not (isinstance(val, list) and len(val) == 2):
                return _err("VALIDATION_ERROR", "BETWEEN requires a two-value array.")
            lo, hi = val[0], val[1]
            pv_num = _as_number(prop_val)
            lo_num = _as_number(lo)
            hi_num = _as_number(hi)
            if pv_num is None or lo_num is None or hi_num is None:
                return _err("VALIDATION_ERROR", "BETWEEN requires numeric comparable values.")
            return lo_num <= pv_num <= hi_num

        if op in {"IN", "NOT_IN"}:
            values = val
            if isinstance(values, list):
                if len(values) == 0:
                    return _err("VALIDATION_ERROR", f"{op} requires a non-empty values array.")
                candidates = values
            else:
                candidates = [values]
            ok = prop_val in candidates
            return ok if op == "IN" else (not ok)

        # Comparisons
        if op in {"LT", "LTE", "GT", "GTE"}:
            pv_num = _as_number(prop_val)
            vv_num = _as_number(val)
            if pv_num is None or vv_num is None:
                return _err("VALIDATION_ERROR", f"{op} requires numeric comparable values.")
            if op == "LT": return pv_num < vv_num
            if op == "LTE": return pv_num <= vv_num
            if op == "GT": return pv_num > vv_num
            if op == "GTE": return pv_num >= vv_num

        if op in {"EQ", "NEQ"}:
            ok = (prop_val == val)
            return ok if op == "EQ" else (not ok)

        return _err("VALIDATION_ERROR", "Unsupported filter operator.")

    portal_id = _pick_portal_id()
    if not portal_id:
        _record_request(portal_id=None, status=401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No available portal context in datastore.")

    if not (isinstance(filterGroups, list) and filterGroups):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array.")
    if properties is not None and not (isinstance(properties, list) and all(isinstance(x, str) for x in properties)):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an array of strings when provided.")
    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or isinstance(limit, bool) or int(limit) != limit or int(limit) < 1 or int(limit) > 100:
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    limit = int(limit)
    if after is not None and not isinstance(after, str):
        _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a string when provided.")
    if sorts is not None:
        if not (isinstance(sorts, list) and all(isinstance(s, dict) for s in sorts)):
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sorts must be an array of objects when provided.")
        for s in sorts:
            if not isinstance(s.get("propertyName"), str) or not s.get("propertyName"):
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sorts[].propertyName must be a non-empty string.")
            if s.get("direction") not in {"ASCENDING", "DESCENDING"}:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sorts[].direction must be ASCENDING or DESCENDING.")

    # Validate requested property names against active definitions when they exist
    if properties is not None:
        prop_defs = _load("crm_object_properties.json")
        if not isinstance(prop_defs, list):
            prop_defs = []
        company_defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "companies" and d.get("status") == "active" and d.get("archived") is False]
        if company_defs:
            defs_by_name = {d.get("name") for d in company_defs if isinstance(d.get("name"), str)}
            bad = [p for p in properties if p not in defs_by_name]
            if bad:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown requested property name(s).", invalid=bad)

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []
    companies = [o for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == "companies" and o.get("status") == "active" and o.get("archived") is False]

    # Evaluate filterGroups: OR across groups, AND within group filters
    matched = []
    for o in companies:
        group_ok = False
        for g in filterGroups:
            if not isinstance(g, dict) or "filters" not in g:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each filterGroup must be an object with filters.")
            fs = g.get("filters")
            if not isinstance(fs, list) or not fs:
                _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "filterGroup.filters must be a non-empty array.")
            ok = True
            for flt in fs:
                if not isinstance(flt, dict):
                    _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Each filter must be an object.")
                r = _eval_filter(o, flt)
                if isinstance(r, dict) and "error" in r:
                    _record_request(portal_id, status=400, error_code=r["error"]["code"])
                    return r
                if not r:
                    ok = False
                    break
            if ok:
                group_ok = True
                break
        if group_ok:
            matched.append(o)

    # Sorting
    if sorts:
        def _sort_key(obj):
            keys = []
            pmap = obj.get("properties") if isinstance(obj.get("properties"), dict) else {}
            for s in sorts:
                pn = s["propertyName"]
                v = pmap.get(pn)
                keys.append(v)
            return keys

        # Apply stable sorts from last to first
        for s in reversed(sorts):
            pn = s["propertyName"]
            direction = s["direction"]
            def keyf(obj, _pn=pn):
                pmap = obj.get("properties") if isinstance(obj.get("properties"), dict) else {}
                v = pmap.get(_pn)
                return (v is None, v)
            matched.sort(key=keyf, reverse=(direction == "DESCENDING"))

    # Pagination using 'after' as offset cursor
    start = 0
    if after:
        try:
            start = int(after)
            if start < 0:
                start = 0
        except Exception:
            _record_request(portal_id, status=400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "after cursor is invalid.")
    total = len(matched)
    page = matched[start:start + limit]
    next_after = None
    if start + limit < total:
        next_after = str(start + limit)

    results = []
    for o in page:
        pmap = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        out_props = dict(pmap) if properties is None else {k: pmap[k] for k in properties if k in pmap}
        results.append({
            "id": o.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": o.get("hubspot_created_at"),
            "updatedAt": o.get("hubspot_updated_at"),
            "archived": o.get("archived", False)
        })

    resp = {
        "total": total,
        "results": results
    }
    if next_after is not None:
        resp["paging"] = {"next": {"after": next_after}}

    _record_request(portal_id, status=200)
    return resp

def crm_batch_create_companies(inputs, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, portal_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "portal_id": portal_id,
            "credential": credential_used,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, portal_id):
        # Best-effort: enforce only if datastore has limit definitions/counters
        policies = _load("policies.json")
        usage = _load("usage.json")
        reqlogs = _load("request_logs.json")
        # Find policy applicable for this portal or global
        pol = None
        for p in policies:
            if p.get("portal_id") == portal_id or p.get("portal_id") in (None, "", "*"):
                pol = p
                break
        if not pol:
            return None
        rate = pol.get("rate_limit_per_minute")
        quota = pol.get("quota_per_day")
        # rate limit
        if isinstance(rate, (int, float)) and rate > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
            cnt = 0
            for r in reqlogs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("ts")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        # daily quota
        if isinstance(quota, (int, float)) and quota > 0:
            today = datetime.datetime.utcnow().date()
            used = 0
            for u in usage:
                if u.get("portal_id") == portal_id and u.get("date") == str(today):
                    used = u.get("requests", 0)
                    break
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _bump_usage(portal_id):
        usage = _load("usage.json")
        today = str(datetime.datetime.utcnow().date())
        found = False
        for u in usage:
            if u.get("portal_id") == portal_id and u.get("date") == today:
                u["requests"] = int(u.get("requests", 0)) + 1
                found = True
                break
        if not found:
            usage.append({"portal_id": portal_id, "date": today, "requests": 1})
        _save("usage.json", usage)

    def _resolve_portal():
        # Ambient auth: choose a portal that can serve this call; if multiple, pick first.
        portals = set()
        for row in _load("crm_objects.json"):
            if row.get("portal_id"):
                portals.add(row.get("portal_id"))
        for row in _load("crm_object_properties.json"):
            if row.get("portal_id"):
                portals.add(row.get("portal_id"))
        for row in _load("crm_association_types.json"):
            if row.get("portal_id"):
                portals.add(row.get("portal_id"))
        if portals:
            return sorted(portals)[0]
        # fallback: single-tenant default
        return "default"

    portal_id = _resolve_portal()
    limit_err = _enforce_limits("crm_batch_create_companies", portal_id)
    if limit_err:
        _log("crm_batch_create_companies", "error", portal_id=portal_id, meta={"code": limit_err["error"]["code"]})
        _bump_usage(portal_id)
        return limit_err

    # Validate inputs top-level
    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("crm_batch_create_companies", "error", portal_id=portal_id, meta={"code": "VALIDATION_ERROR"})
        _bump_usage(portal_id)
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array.")

    object_type = "companies"

    crm_objects = _load("crm_objects.json")
    crm_props = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    crm_assocs = _load("crm_associations.json")

    # property definitions for validation
    defs = [d for d in crm_props if d.get("portal_id") == portal_id and d.get("object_type") == object_type]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    defs_exist = len(defs_by_name) > 0

    # policy: allow unknown properties if tool allows additionalProperties (it does)
    # and portal policy allows it. Default allow if no policy file/flag present.
    portal_policies = _load("portal_policies.json")
    pol = None
    for p in portal_policies:
        if p.get("portal_id") == portal_id:
            pol = p
            break
    allow_unknown = True if pol is None else bool(pol.get("allow_additional_properties", True))
    forbid_hidden = False if pol is None else bool(pol.get("forbid_hidden_properties", False))

    allowed_lifecyclestage = {"lead", "customer", "opportunity", "subscriber", "other"}

    def _is_valid_uri(u):
        if not isinstance(u, str) or u == "":
            return True  # empty handled by caller; treat as ok
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # helper: find crm_object by hubspot_object_id for given type within portal
    def _find_obj_by_hs_id(obj_type, hs_id):
        for o in crm_objects:
            if o.get("portal_id") == portal_id and o.get("object_type") == obj_type and o.get("hubspot_object_id") == str(hs_id):
                return o
        return None

    # validate association type existence/active
    active_assoc_type_keys = set()
    for at in assoc_types:
        if at.get("portal_id") != portal_id:
            continue
        if at.get("status") != "active":
            continue
        k = (at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), at.get("association_type_id"))
        active_assoc_type_keys.add(k)

    results = []
    errors = []

    # id generators
    def _next_internal_id(prefix, rows):
        mx = 0
        for r in rows:
            rid = r.get("id", "")
            if isinstance(rid, str) and rid.startswith(prefix):
                m = re.search(r"(\d+)$", rid)
                if m:
                    mx = max(mx, int(m.group(1)))
        return f"{prefix}{mx+1}"

    # determine next hubspot_object_id numeric-ish
    def _next_hubspot_id_for_type(obj_type):
        mx = 0
        for o in crm_objects:
            if o.get("portal_id") == portal_id and o.get("object_type") == obj_type:
                hid = o.get("hubspot_object_id")
                if isinstance(hid, str) and hid.isdigit():
                    mx = max(mx, int(hid))
        return str(mx + 1 if mx > 0 else 1000)

    # Unique constraint for companies: (portal_id, object_type, hubspot_object_id) will be unique by generated id.
    # Also enforce unique properties where definitions set has_unique_value=true
    unique_prop_names = set()
    for d in defs_by_name.values():
        if d.get("has_unique_value") is True and d.get("status") == "active" and not d.get("archived", False):
            unique_prop_names.add(d.get("name"))

    def _validate_properties(props, idx):
        if not isinstance(props, dict):
            return _err("VALIDATION_ERROR", f"inputs[{idx}].properties must be an object.")
        # lifecyclestage enum
        if "lifecyclestage" in props and props["lifecyclestage"] is not None:
            if props["lifecyclestage"] not in allowed_lifecyclestage:
                return _err("VALIDATION_ERROR", f"inputs[{idx}].properties.lifecyclestage is invalid.")
        # website uri format
        if "website" in props and props["website"] is not None:
            if props["website"] != "" and not _is_valid_uri(props["website"]):
                return _err("VALIDATION_ERROR", f"inputs[{idx}].properties.website must be a valid URI.")
        # validate names against schema if definitions exist
        if defs_exist:
            for k, v in props.items():
                if k in defs_by_name:
                    d = defs_by_name[k]
                    # reject archived/hidden if policy forbids hidden (create: also reject hidden/archived defs)
                    if d.get("status") == "archived" or d.get("archived") is True:
                        return _err("VALIDATION_ERROR", f"inputs[{idx}].properties contains archived property '{k}'.")
                    if forbid_hidden and d.get("hidden") is True:
                        return _err("VALIDATION_ERROR", f"inputs[{idx}].properties contains hidden property '{k}'.")
                else:
                    if not allow_unknown:
                        return _err("VALIDATION_ERROR", f"inputs[{idx}].properties contains unknown property '{k}'.")
        return None

    def _validate_associations(associations, idx):
        if associations is None:
            return None
        if not isinstance(associations, list):
            return _err("VALIDATION_ERROR", f"inputs[{idx}].associations must be an array.")
        for j, a in enumerate(associations):
            if not isinstance(a, dict):
                return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}] must be an object.")
            to = a.get("to")
            types = a.get("types")
            if not isinstance(to, dict) or "id" not in to:
                return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}].to.id is required.")
            if not isinstance(types, list) or len(types) == 0:
                return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}].types must be a non-empty array.")
            to_id = to.get("id")
            if not isinstance(to_id, str) or to_id == "":
                return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}].to.id must be a string.")
            # target must exist as a CRM object in this portal by hubspot_object_id (unknown type; accept any type)
            target = None
            for o in crm_objects:
                if o.get("portal_id") == portal_id and o.get("hubspot_object_id") == to_id:
                    target = o
                    break
            if target is None:
                return _err("NOT_FOUND", f"Association target id '{to_id}' not found.", index=idx, associationIndex=j)
            for k, t in enumerate(types):
                if not isinstance(t, dict):
                    return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}].types[{k}] must be an object.")
                cat = t.get("associationCategory")
                tid = t.get("associationTypeId")
                if not isinstance(cat, str) or cat == "" or not isinstance(tid, (int, float)) or int(tid) < 1:
                    return _err("VALIDATION_ERROR", f"inputs[{idx}].associations[{j}].types[{k}] is invalid.")
                key = (object_type, target.get("object_type"), cat, int(tid))
                if key not in active_assoc_type_keys:
                    return _err("VALIDATION_ERROR", f"Association type not found or inactive for companies -> {target.get('object_type')}.", index=idx, associationIndex=j, typeIndex=k)
        return None

    # Pre-validate each item; collect per-item errors; only write for items that pass.
    staged_creates = []  # each: dict with new_obj, new_assocs(list)
    # To enforce uniqueness among batch and existing
    existing_unique_values = {p: set() for p in unique_prop_names}
    for o in crm_objects:
        if o.get("portal_id") != portal_id or o.get("object_type") != object_type or o.get("status") != "active":
            continue
        props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        for p in unique_prop_names:
            v = props.get(p)
            if isinstance(v, str) or isinstance(v, (int, float)) or v is not None:
                existing_unique_values[p].add(str(v))

    batch_unique_values = {p: set() for p in unique_prop_names}

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}] must be an object.")["error"]})
            continue
        if "properties" not in item:
            errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}].properties is required.")["error"]})
            continue

        props = item.get("properties")
        e = _validate_properties(props, idx)
        if e:
            errors.append({"index": idx, "error": e["error"]})
            continue

        assocs = item.get("associations")
        e = _validate_associations(assocs, idx)
        if e:
            errors.append({"index": idx, "error": e["error"]})
            continue

        # enforce unique properties if present
        if unique_prop_names:
            for p in unique_prop_names:
                if p in props and props[p] not in ("", None):
                    v = str(props[p])
                    if v in existing_unique_values[p] or v in batch_unique_values[p]:
                        errors.append({"index": idx, "error": _err("CONFLICT", f"Property '{p}' must be unique; value already exists.")["error"]})
                        break
            else:
                for p in unique_prop_names:
                    if p in props and props[p] not in ("", None):
                        batch_unique_values[p].add(str(props[p]))
                # ok
                pass
            if errors and errors[-1].get("index") == idx:
                continue

        # Stage creation with generated IDs
        new_internal_id = _next_internal_id("obj_", crm_objects + [s["new_obj"] for s in staged_creates])
        new_hs_id = _next_hubspot_id_for_type(object_type)

        new_obj = {
            "id": new_internal_id,
            "portal_id": portal_id,
            "object_type": object_type,
            "hubspot_object_id": new_hs_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props),
            "properties_version": 1,
            "search_text": None,
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        # stage associations edges
        new_edges = []
        if isinstance(assocs, list):
            for a in assocs:
                to_id = a["to"]["id"]
                target = None
                for o in crm_objects:
                    if o.get("portal_id") == portal_id and o.get("hubspot_object_id") == to_id:
                        target = o
                        break
                # already validated existence
                for t in a.get("types", []):
                    cat = t["associationCategory"]
                    tid = int(t["associationTypeId"])
                    # upsert semantics: if exists archived, reactivate; else create new.
                    new_edges.append({
                        "to_obj_internal": target.get("id"),
                        "to_obj_type": target.get("object_type"),
                        "association_category": cat,
                        "association_type_id": tid,
                    })

        staged_creates.append({"index": idx, "new_obj": new_obj, "new_edges": new_edges})

    # Apply writes for staged creates (each item atomic)
    for stage in staged_creates:
        idx = stage["index"]
        new_obj = stage["new_obj"]
        new_edges = stage["new_edges"]

        # Write object (unique constraints are already enforced)
        crm_objects.append(new_obj)

        # Write associations with upsert/reactivate semantics
        created_edge_rows = []
        for ed in new_edges:
            from_internal = new_obj["id"]
            to_internal = ed["to_obj_internal"]
            if from_internal == to_internal:
                # should not happen but avoid violating constraint
                continue

            # find existing identical edge
            existing = None
            for a in crm_assocs:
                if a.get("portal_id") == portal_id and a.get("from_object_id") == from_internal and a.get("to_object_id") == to_internal and a.get("association_category") == ed["association_category"] and int(a.get("association_type_id", 0)) == int(ed["association_type_id"]):
                    existing = a
                    break
            if existing:
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = now
                created_edge_rows.append(existing)
            else:
                # create
                new_aid = _next_internal_id("asc_", crm_assocs + created_edge_rows)
                row = {
                    "id": new_aid,
                    "portal_id": portal_id,
                    "from_object_id": from_internal,
                    "to_object_id": to_internal,
                    "from_object_type": object_type,
                    "to_object_type": ed["to_obj_type"],
                    "association_category": ed["association_category"],
                    "association_type_id": int(ed["association_type_id"]),
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now,
                }
                crm_assocs.append(row)
                created_edge_rows.append(row)

        results.append({
            "index": idx,
            "id": new_obj["hubspot_object_id"],
            "properties": new_obj["properties"],
            "createdAt": new_obj["hubspot_created_at"],
            "updatedAt": new_obj["hubspot_updated_at"],
            "archived": new_obj["archived"],
        })

    # Persist changes if any created
    if staged_creates:
        _save("crm_objects.json", crm_objects)
        _save("crm_associations.json", crm_assocs)

    body = {
        "status": "COMPLETE",
        "results": results,
        "errors": errors,
        "numRequested": len(inputs),
        "numSucceeded": len(results),
        "numErrored": len(errors),
    }

    _log("crm_batch_create_companies", "ok", portal_id=portal_id, meta={"succeeded": len(results), "errored": len(errors)})
    _bump_usage(portal_id)
    return body

def crm_batch_update_companies(inputs, **_extra):
    import json, os, datetime, time
    import re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, portal_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "portal_id": portal_id,
            "credential": credential_used,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, portal_id):
        policies = _load("policies.json")
        usage = _load("usage.json")
        reqlogs = _load("request_logs.json")
        pol = None
        for p in policies:
            if p.get("portal_id") == portal_id or p.get("portal_id") in (None, "", "*"):
                pol = p
                break
        if not pol:
            return None
        rate = pol.get("rate_limit_per_minute")
        quota = pol.get("quota_per_day")
        if isinstance(rate, (int, float)) and rate > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
            cnt = 0
            for r in reqlogs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("ts")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, (int, float)) and quota > 0:
            today = datetime.datetime.utcnow().date()
            used = 0
            for u in usage:
                if u.get("portal_id") == portal_id and u.get("date") == str(today):
                    used = u.get("requests", 0)
                    break
            if used >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _bump_usage(portal_id):
        usage = _load("usage.json")
        today = str(datetime.datetime.utcnow().date())
        found = False
        for u in usage:
            if u.get("portal_id") == portal_id and u.get("date") == today:
                u["requests"] = int(u.get("requests", 0)) + 1
                found = True
                break
        if not found:
            usage.append({"portal_id": portal_id, "date": today, "requests": 1})
        _save("usage.json", usage)

    def _resolve_portal():
        portals = set()
        for row in _load("crm_objects.json"):
            if row.get("portal_id"):
                portals.add(row.get("portal_id"))
        for row in _load("crm_object_properties.json"):
            if row.get("portal_id"):
                portals.add(row.get("portal_id"))
        if portals:
            return sorted(portals)[0]
        return "default"

    portal_id = _resolve_portal()
    limit_err = _enforce_limits("crm_batch_update_companies", portal_id)
    if limit_err:
        _log("crm_batch_update_companies", "error", portal_id=portal_id, meta={"code": limit_err["error"]["code"]})
        _bump_usage(portal_id)
        return limit_err

    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("crm_batch_update_companies", "error", portal_id=portal_id, meta={"code": "VALIDATION_ERROR"})
        _bump_usage(portal_id)
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array.")

    crm_objects = _load("crm_objects.json")
    crm_props = _load("crm_object_properties.json")

    object_type = "companies"
    defs = [d for d in crm_props if d.get("portal_id") == portal_id and d.get("object_type") == object_type]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    defs_exist = len(defs_by_name) > 0

    portal_policies = _load("portal_policies.json")
    pol = None
    for p in portal_policies:
        if p.get("portal_id") == portal_id:
            pol = p
            break
    allow_unknown = True if pol is None else bool(pol.get("allow_additional_properties", True))
    forbid_hidden = False if pol is None else bool(pol.get("forbid_hidden_properties", False))

    allowed_lifecyclestage = {"lead", "customer", "opportunity", "subscriber", "other"}

    def _is_valid_uri(u):
        if not isinstance(u, str) or u == "":
            return True
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # unique property enforcement
    unique_prop_names = set()
    for d in defs_by_name.values():
        if d.get("has_unique_value") is True and d.get("status") == "active" and not d.get("archived", False):
            unique_prop_names.add(d.get("name"))

    existing_unique_values = {p: {} for p in unique_prop_names}  # value -> hubspot_object_id
    for o in crm_objects:
        if o.get("portal_id") != portal_id or o.get("object_type") != object_type or o.get("status") != "active":
            continue
        props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        for p in unique_prop_names:
            v = props.get(p)
            if v not in (None, ""):
                existing_unique_values[p][str(v)] = o.get("hubspot_object_id")

    # index objects by hubspot_object_id
    by_hs_id = {}
    for o in crm_objects:
        if o.get("portal_id") == portal_id and o.get("object_type") == object_type:
            by_hs_id[o.get("hubspot_object_id")] = o

    results = []
    errors = []
    staged_updates = []  # (obj, new_props)

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}] must be an object.")["error"]})
            continue
        cid = item.get("id")
        props = item.get("properties")
        if not isinstance(cid, str) or cid == "":
            errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}].id is required.")["error"]})
            continue
        if not isinstance(props, dict):
            errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}].properties must be an object.")["error"]})
            continue

        obj = by_hs_id.get(cid)
        if obj is None:
            errors.append({"index": idx, "error": _err("NOT_FOUND", f"Company id '{cid}' not found.")["error"]})
            continue
        if obj.get("status") == "archived" or obj.get("archived") is True:
            errors.append({"index": idx, "error": _err("NOT_FOUND", f"Company id '{cid}' is archived and cannot be updated.")["error"]})
            continue

        # validate values
        if "lifecyclestage" in props and props["lifecyclestage"] is not None:
            if props["lifecyclestage"] not in allowed_lifecyclestage:
                errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}].properties.lifecyclestage is invalid.")["error"]})
                continue
        if "website" in props and props["website"] is not None:
            if props["website"] != "" and not _is_valid_uri(props["website"]):
                errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"inputs[{idx}].properties.website must be a valid URI.")["error"]})
                continue

        if defs_exist:
            for k, v in props.items():
                if k in defs_by_name:
                    d = defs_by_name[k]
                    if d.get("status") == "archived" or d.get("archived") is True:
                        errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be updated.")["error"]})
                        break
                    if forbid_hidden and d.get("hidden") is True:
                        errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"Property '{k}' is hidden and cannot be updated.")["error"]})
                        break
                else:
                    if not allow_unknown:
                        errors.append({"index": idx, "error": _err("VALIDATION_ERROR", f"Unknown property '{k}'.")["error"]})
                        break
            if errors and errors[-1]["index"] == idx:
                continue

        # uniqueness checks
        if unique_prop_names:
            for p in unique_prop_names:
                if p in props and props[p] not in (None, ""):
                    v = str(props[p])
                    owner = existing_unique_values[p].get(v)
                    if owner is not None and owner != cid:
                        errors.append({"index": idx, "error": _err("CONFLICT", f"Property '{p}' must be unique; value already exists.")["error"]})
                        break
            if errors and errors[-1]["index"] == idx:
                continue

        # compute merged properties; empty string means clear
        merged = dict(obj.get("properties") if isinstance(obj.get("properties"), dict) else {})
        for k, v in props.items():
            if v == "":
                if k in merged:
                    merged.pop(k, None)
            else:
                merged[k] = v

        staged_updates.append((idx, obj, merged))

    # apply updates
    for idx, obj, merged in staged_updates:
        obj["properties"] = merged
        obj["properties_version"] = int(obj.get("properties_version", 1)) + 1
        obj["updated_at"] = now
        obj["hubspot_updated_at"] = now
        results.append({
            "index": idx,
            "id": obj.get("hubspot_object_id"),
            "properties": obj.get("properties"),
            "createdAt": obj.get("hubspot_created_at"),
            "updatedAt": obj.get("hubspot_updated_at"),
            "archived": obj.get("archived"),
        })

    if staged_updates:
        _save("crm_objects.json", crm_objects)

    body = {
        "status": "COMPLETE",
        "results": results,
        "errors": errors,
        "numRequested": len(inputs),
        "numSucceeded": len(results),
        "numErrored": len(errors),
    }

    _log("crm_batch_update_companies", "ok", portal_id=portal_id, meta={"succeeded": len(results), "errored": len(errors)})
    _bump_usage(portal_id)
    return body

