            return _err("VALIDATION_ERROR", "properties must be an array of non-empty strings.")

    rows = _load("crm_object_properties.json")
    obj_type = "companies"

    filtered = [r for r in rows if r.get("portal_id") == portal_id and r.get("object_type") == obj_type]
    if not archived:
        filtered = [r for r in filtered if not r.get("archived", False) and r.get("status") != "archived"]

    if properties is not None:
        want = set(properties)
        known = set(r.get("name") for r in filtered if isinstance(r.get("name"), str))
        unknown = sorted(list(want - known))
        if unknown:
            _log("crm_get_company_properties", "error", portal_id=portal_id, meta={"code": "VALIDATION_ERROR", "unknown": unknown})
            _bump_usage(portal_id)
            return _err("VALIDATION_ERROR", "One or more requested property names do not exist.", unknown=unknown)
        filtered = [r for r in filtered if r.get("name") in want]

    # map field names to tool shape (HubSpot-like)
    out = []
    for r in filtered:
        out.append({
            "name": r.get("name"),
            "label": r.get("label"),
            "type": r.get("type"),
            "fieldType": r.get("field_type"),
            "groupName": r.get("group_name"),
            "description": r.get("description"),
            "displayOrder": r.get("display_order"),
            "hasUniqueValue": r.get("has_unique_value"),
            "hidden": r.get("hidden"),
            "formField": r.get("form_field"),
            "options": r.get("options") if isinstance(r.get("options"), list) else [],
            "archived": bool(r.get("archived", False)),
            "updatedAt": r.get("updated_at"),
            "createdAt": r.get("created_at"),
        })

    body = {"results": out, "total": len(out)}
    _log("crm_get_company_properties", "ok", portal_id=portal_id, meta={"total": len(out)})
    _bump_usage(portal_id)
    return body

def crm_create_company_property(name, label, type, fieldType, groupName, description=None, options=None, displayOrder=None, hasUniqueValue=None, hidden=None, formField=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_create_company_property"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, portal_id=None, error_code=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _enforce_limits(portal_id):
        # Basic limits driven by request_logs if policies/usage not present
        # Apply per-portal (when portal known) else global.
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        now = datetime.datetime.utcnow()
        def _parse(ts):
            if not isinstance(ts, str): return None
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None
        last_min = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if portal_id is not None and r.get("portal_id") not in (portal_id, None, ""):
                continue
            ts = _parse(r.get("timestamp"))
            if not ts: 
                continue
            dt = now - ts
            if dt.total_seconds() <= 60:
                last_min += 1
            if dt.total_seconds() <= 86400:
                last_day += 1
        # generous defaults
        if last_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if last_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    # Validate inputs (relaxed name format to accept real-world strings used in audit)
    if not isinstance(name, str) or not name.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if not isinstance(label, str) or not label.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string.", field="label")
    allowed_type = {"string", "number", "date", "datetime", "enumeration", "bool"}
    if not isinstance(type, str) or type not in allowed_type:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be one of string, number, date, datetime, enumeration, bool.", field="type")
    allowed_field = {"text", "textarea", "select", "radio", "checkbox", "number", "date", "file"}
    if not isinstance(fieldType, str) or fieldType not in allowed_field:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fieldType must be one of text, textarea, select, radio, checkbox, number, date, file.", field="fieldType")
    if not isinstance(groupName, str) or not groupName.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "groupName is required and must be a non-empty string.", field="groupName")
    if description is not None and not isinstance(description, str):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
    if displayOrder is not None and not isinstance(displayOrder, (int, float)):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "displayOrder must be a number when provided.", field="displayOrder")
    for bfield, bname in ((hasUniqueValue, "hasUniqueValue"), (hidden, "hidden"), (formField, "formField")):
        if bfield is not None and not isinstance(bfield, bool):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided.", field=bname)

    if options is None:
        options_list = []
    else:
        if not isinstance(options, list):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "options must be an array when provided.", field="options")
        options_list = options

    # options rules
    if type != "enumeration" and len(options_list) != 0:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "options must be empty unless type is 'enumeration'.", rule="type != 'enumeration' implies options.length = 0")
    if type == "enumeration":
        # Accept empty enumeration options (schema constraint says >=0)
        for i, opt in enumerate(options_list):
            if not isinstance(opt, dict):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each options item must be an object.", field=f"options[{i}]")
            if "label" not in opt or "value" not in opt:
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each options item must include label and value.", field=f"options[{i}]")
            if not isinstance(opt.get("label"), str) or not opt["label"].strip():
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.label must be a non-empty string.", field=f"options[{i}].label")
            if not isinstance(opt.get("value"), str) or not opt["value"].strip():
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.value must be a non-empty string.", field=f"options[{i}].value")
            if "description" in opt and opt["description"] is not None and not isinstance(opt["description"], str):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.description must be a string when provided.", field=f"options[{i}].description")
            if "displayOrder" in opt and opt["displayOrder"] is not None and not isinstance(opt["displayOrder"], (int, float)):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.displayOrder must be a number when provided.", field=f"options[{i}].displayOrder")
            if "hidden" in opt and opt["hidden"] is not None and not isinstance(opt["hidden"], bool):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.hidden must be a boolean when provided.", field=f"options[{i}].hidden")

    # Determine portal_id context: choose any portal that has CRM data (tenant-scoped) for companies
    props_defs = _load("crm_object_properties.json")
    if not isinstance(props_defs, list): props_defs = []
    objects = _load("crm_objects.json")
    if not isinstance(objects, list): objects = []

    candidate_portals = []
    portals_with_company_data = set()
    for o in objects:
        if isinstance(o, dict) and o.get("object_type") == "companies" and isinstance(o.get("portal_id"), str) and o.get("portal_id"):
            portals_with_company_data.add(o["portal_id"])
    portals_with_company_defs = set()
    for d in props_defs:
        if isinstance(d, dict) and d.get("object_type") == "companies" and isinstance(d.get("portal_id"), str) and d.get("portal_id"):
            portals_with_company_defs.add(d["portal_id"])

    # Prefer portal that already has company property definitions; else any portal that has companies; else any portal in props_defs.
    for pid in sorted(portals_with_company_defs):
        candidate_portals.append(pid)
    for pid in sorted(portals_with_company_data):
        if pid not in candidate_portals:
            candidate_portals.append(pid)
    if not candidate_portals:
        for d in props_defs:
            if isinstance(d, dict) and isinstance(d.get("portal_id"), str) and d.get("portal_id"):
                if d["portal_id"] not in candidate_portals:
                    candidate_portals.append(d["portal_id"])

    if not candidate_portals:
        _append_log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available to create property definition.")

    portal_id = candidate_portals[0]

    lim_err = _enforce_limits(portal_id)
    if lim_err:
        _append_log("error", portal_id=portal_id, error_code=lim_err["error"]["code"])
        return lim_err

    # Enforce uniqueness (portal_id, object_type, name)
    for d in props_defs:
        if not isinstance(d, dict): 
            continue
        if d.get("portal_id") == portal_id and d.get("object_type") == "companies" and str(d.get("name")) == name:
            _append_log("error", portal_id=portal_id, error_code="CONFLICT")
            return _err("CONFLICT", "A company property with this name already exists.", field="name")

    # Create id
    existing_ids = {d.get("id") for d in props_defs if isinstance(d, dict) and isinstance(d.get("id"), str)}
    while True:
        new_id = f"hs_propdef_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{secrets.token_hex(8)}"
        if new_id not in existing_ids:
            break

    now = _iso_now()
    row = {
        "id": new_id,
        "portal_id": portal_id,
        "object_type": "companies",
        "name": name,
        "label": label,
        "type": type,
        "field_type": fieldType,
        "group_name": groupName,
        "description": description if description is not None else None,
        "display_order": displayOrder if displayOrder is not None else None,
        "has_unique_value": bool(hasUniqueValue) if hasUniqueValue is not None else False,
        "hidden": bool(hidden) if hidden is not None else False,
        "form_field": bool(formField) if formField is not None else False,
        "options": options_list if type == "enumeration" else [],
        "archived": False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Persist
    props_defs.append(row)
    _save("crm_object_properties.json", props_defs)

    _append_log("success", portal_id=portal_id)
    return {"property": row}

def crm_list_objects(objectType, properties=None, after=None, limit=None, archived=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        logs.append({
            "id": f"req_{dt.strftime('%Y%m%d%H%M%S%f')}",
            "service": "hubspot_mcp",
            "endpoint": "crm_list_objects",
            "credential_id": credential_id,
            "status": status_code,
            "message": message,
            "latency_ms": latency_ms,
            "timestamp": dt.replace(microsecond=0).isoformat() + "Z",
        })
        _save("request_logs.json", logs)

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list):
            for r in objs:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        props = _load("crm_object_properties.json")
        if isinstance(props, list):
            for r in props:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list):
            for r in assoc_types:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list):
            for r in subs:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        return None

    portal_id = _resolve_portal_id()
    if not portal_id:
        _log("UNAUTHORIZED", None, "No portal context available")
        return _err("UNAUTHORIZED", "No authorized portal context available for this call.")

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if objectType not in allowed_types:
        _log("VALIDATION_ERROR", None, "Unsupported objectType")
        return _err("VALIDATION_ERROR", "Unsupported objectType.", field="objectType")

    if limit is None:
        limit = 100
    if not isinstance(limit, (int, float)) or isinstance(limit, bool):
        _log("VALIDATION_ERROR", None, "limit wrong type")
        return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100.", field="limit")
    limit = int(limit)
    if limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", None, "limit out of range")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")

    if archived is None:
        archived = False
    if not isinstance(archived, bool):
        _log("VALIDATION_ERROR", None, "archived wrong type")
        return _err("VALIDATION_ERROR", "archived must be boolean.", field="archived")

    if after is not None and not isinstance(after, str):
        _log("VALIDATION_ERROR", None, "after wrong type")
        return _err("VALIDATION_ERROR", "after must be a string cursor.", field="after")

    if properties is not None:
        if not isinstance(properties, list) or any(not isinstance(p, str) for p in properties):
            _log("VALIDATION_ERROR", None, "properties wrong type")
            return _err("VALIDATION_ERROR", "properties must be an array of strings.", field="properties")

    # Validate property names against definitions when they exist for the portal/objectType
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    defs_for_type = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    if properties is not None and len(defs_for_type) > 0:
        known = {d.get("name") for d in defs_for_type if d.get("name")}
        bad = [p for p in properties if p not in known]
        if bad:
            _log("VALIDATION_ERROR", None, "Unknown properties requested")
            return _err("VALIDATION_ERROR", "One or more requested properties are invalid for this object type.", invalid_properties=bad)

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []

    rows = [
        r for r in objs
        if isinstance(r, dict)
        and r.get("portal_id") == portal_id
        and r.get("object_type") == objectType
        and (archived or r.get("status") != "archived")
    ]

    # Stable ordering by hubspot_object_id numeric if possible, else lexicographic
    def _key(r):
        v = r.get("hubspot_object_id")
        try:
            return (0, int(v))
        except Exception:
            return (1, str(v) if v is not None else "")
    rows.sort(key=_key)

    start = 0
    if after:
        # Cursor is treated as the last seen hubspot_object_id
        for i, r in enumerate(rows):
            if str(r.get("hubspot_object_id")) == after:
                start = i + 1
                break

    page = rows[start:start + limit]
    results = []
    for r in page:
        props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        if properties is None:
            out_props = props
        else:
            out_props = {k: props.get(k, "") for k in properties}
        results.append({
            "id": str(r.get("hubspot_object_id")),
            "properties": out_props,
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
            "archived": bool(r.get("archived")),
        })

    next_cursor = None
    has_more = False
    if start + limit < len(rows) and len(page) > 0:
        next_cursor = str(page[-1].get("hubspot_object_id"))
        has_more = True

    _log("OK", None, None)
    return {
        "results": results,
        "paging": ({"next": {"after": next_cursor}} if has_more else None),
        "total": len(rows),
    }

