            # collect active edges from this object to that type
            linked = []
            for e in assoc_edges:
                if not isinstance(e, dict):
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                if e.get("from_object_id") != obj_row.get("id"):
                    continue
                if e.get("to_object_type") != to_type:
