                _log("VALIDATION_ERROR", None, "association.to invalid")
                return _err("VALIDATION_ERROR", "association.to.id is required and must be a string.", index=i)
            if not isinstance(types, list) or len(types) == 0:
                _log("VALIDATION_ERROR", None, "association.types invalid")
                return _err("VALIDATION_ERROR", "association.types must be a non-empty array.", index=i)
            for j, t in enumerate(types):
                if not isinstance(t, dict):
                    _log("VALIDATION_ERROR", None, "association type wrong type")
                    return _err("VALIDATION_ERROR", "association type entries must be objects.", index=i, type_index=j)
                if not isinstance(t.get("associationCategory"), str) or not t.get("associationCategory"):
                    _log("VALIDATION_ERROR", None, "associationCategory invalid")
