                if not isinstance(t.get("associationTypeId"), (int, float)) or isinstance(t.get("associationTypeId"), bool):
                    _log("VALIDATION_ERROR", None, "associationTypeId invalid")
                    return _err("VALIDATION_ERROR", "associationTypeId is required and must be a number.", index=i, type_index=j)
                if int(t.get("associationTypeId")) < 1:
                    _log("VALIDATION_ERROR", None, "associationTypeId out of range")
                    return _err("VALIDATION_ERROR", "associationTypeId must be >= 1.", index=i, type_index=j)

    # Validate property names against definitions when they exist
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    defs_for_type = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    if len(defs_for_type) > 0:
        known = {d.get("name") for d in defs_for_type if d.get("name")}
