            try:
                max_id = max(max_id, int(str(r.get("hubspot_object_id"))))
            except Exception:
                continue
    new_hs_id = str(max_id + 1)

    # Ensure unique(portal_id, object_type, hubspot_object_id)
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == objectType and str(r.get("hubspot_object_id")) == new_hs_id:
            _log("CONFLICT", None, "Unique constraint collision")
