    # Prepare association writes (validate references and association types) before mutating to keep atomicity
    assoc_types_rows = _load("crm_association_types.json")
    if not isinstance(assoc_types_rows, list):
        assoc_types_rows = []
    assoc_edges = _load("crm_associations.json")
    if not isinstance(assoc_edges, list):
        assoc_edges = []

    # Build object lookup by hubspot id + type in this portal for target resolution
    def _find_object_by_hs_id(obj_type, hs_id):
        for r in objs:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("object_type") != obj_type:
                continue
            if str(r.get("hubspot_object_id")) == str(hs_id):
                return r
        return None

    assoc_writes = []
    if associations:
        for a in associations:
            to_hs_id = a["to"]["id"]
            to_obj = None
            # try to resolve target across allowed_types; most tools pass matching to type via association type definition, but payload omits type
            # We'll accept any target object (any type) as long as an association type exists for (from=objectType,to=target_type,category,typeId).
            for candidate_type in ["companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements"]:
                to_obj = _find_object_by_hs_id(candidate_type, to_hs_id)
                if to_obj:
                    break
            if not to_obj:
                _log("NOT_FOUND", None, "Association target not found")
                return _err("NOT_FOUND", "Association target object not found.", targetId=str(to_hs_id))

            for t in a["types"]:
                cat = t["associationCategory"]
                tid = int(t["associationTypeId"])
                # validate association type exists and active for portal and (from,to)
                ok = False
                for at in assoc_types_rows:
                    if not isinstance(at, dict):
                        continue
                    if at.get("portal_id") != portal_id:
                        continue
                    if at.get("status") != "active":
                        continue
                    if at.get("from_object_type") == objectType and at.get("to_object_type") == to_obj.get("object_type") and at.get("association_category") == cat and int(at.get("association_type_id")) == tid:
                        ok = True
                        break
                if not ok:
                    _log("VALIDATION_ERROR", None, "Association type invalid")
                    return _err(
                        "VALIDATION_ERROR",
                        "Invalid association type for the given from/to object types.",
                        fromObjectType=objectType,
                        toObjectType=to_obj.get("object_type"),
                        associationCategory=cat,
                        associationTypeId=tid
                    )
                assoc_writes.append({
                    "to_internal_id": to_obj.get("id"),
                    "to_object_type": to_obj.get("object_type"),
                    "association_category": cat,
                    "association_type_id": tid,
                })

    # Commit: create object row
    obj_row = {
        "id": internal_id,
        "portal_id": portal_id,
        "object_type": objectType,
        "hubspot_object_id": new_hs_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": properties,
        "properties_version": 1,
        "search_text": None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }
    objs.append(obj_row)

    # Commit: upsert associations (reactivate if archived)
    created_links = []
    for w in assoc_writes:
        # unique(portal_id, from_object_id, to_object_id, association_category, association_type_id)
        existing = None
        for e in assoc_edges:
            if not isinstance(e, dict):
                continue
            if e.get("portal_id") == portal_id and e.get("from_object_id") == internal_id and e.get("to_object_id") == w["to_internal_id"] and e.get("association_category") == w["association_category"] and int(e.get("association_type_id")) == int(w["association_type_id"]):
                existing = e
                break
        if existing:
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
                existing["updated_at"] = now
            created_links.append(existing.get("id"))
        else:
            ae_id = f"assoc_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"
            edge = {
                "id": ae_id,
                "portal_id": portal_id,
                "from_object_id": internal_id,
                "to_object_id": w["to_internal_id"],
                "from_object_type": objectType,
                "to_object_type": w["to_object_type"],
                "association_category": w["association_category"],
                "association_type_id": w["association_type_id"],
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now,
            }
            assoc_edges.append(edge)
            created_links.append(ae_id)

    _save("crm_objects.json", objs)
    if assoc_writes:
        _save("crm_associations.json", assoc_edges)

    out = {
        "id": new_hs_id,
        "properties": properties,
        "createdAt": now,
        "updatedAt": now,
        "archived": False,
    }
    if assoc_writes:
        # HubSpot-style: include just the targets as linkage info
        out["associations"] = {"results": [{"toObjectId": str(_find_object_by_hs_id(w["to_object_type"], _find_object_by_hs_id(w["to_object_type"], str(_find_object_by_hs_id(w["to_object_type"], "0") or "")) or "") or "")} for w in []]}  # keep minimal; avoid fabricating rows
        # Instead, return created association target ids list explicitly without fabricating schema
        out["associationLinkIds"] = created_links

    _log("OK", None, None)
    return out

