            "message": message,
            "latency_ms": latency_ms,
            "timestamp": dt.replace(microsecond=0).isoformat() + "Z",
        })
        _save("request_logs.json", logs)

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        if isinstance(objs, list):
            for r in objs:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        props = _load("crm_object_properties.json")
        if isinstance(props, list):
            for r in props:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        assoc_types = _load("crm_association_types.json")
        if isinstance(assoc_types, list):
            for r in assoc_types:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        subs = _load("communications_subscriptions.json")
        if isinstance(subs, list):
            for r in subs:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        return None

    portal_id = _resolve_portal_id()
    if not portal_id:
        _log("UNAUTHORIZED", None, "No portal context available")
        return _err("UNAUTHORIZED", "No authorized portal context available for this call.")

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if objectType not in allowed_types:
        _log("VALIDATION_ERROR", None, "Unsupported objectType")
        return _err("VALIDATION_ERROR", "Unsupported objectType.", field="objectType")

    if not isinstance(objectId, str) or not objectId:
        _log("VALIDATION_ERROR", None, "objectId invalid")
        return _err("VALIDATION_ERROR", "objectId must be a non-empty string.", field="objectId")

    if not isinstance(properties, dict):
        _log("VALIDATION_ERROR", None, "properties wrong type")
        return _err("VALIDATION_ERROR", "properties must be an object.", field="properties")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []

    target = None
    for r in objs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") == portal_id and r.get("object_type") == objectType and str(r.get("hubspot_object_id")) == objectId:
            target = r
            break

    if not target or target.get("status") == "archived":
        _log("NOT_FOUND", None, "Object not found or archived")
        return _err("NOT_FOUND", "Object not found.")

    # Validate property writes: reject archived/hidden definitions when present and forbid them (policy assumed forbid hidden/archived)
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    defs_for_type = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    if len(defs_for_type) > 0:
        by_name = {d.get("name"): d for d in defs_for_type if d.get("name")}
        bad_unknown = [k for k in properties.keys() if k not in by_name]
        if bad_unknown:
            _log("VALIDATION_ERROR", None, "Unknown properties on update")
            return _err("VALIDATION_ERROR", "One or more provided properties are invalid for this object type.", invalid_properties=bad_unknown)

        bad_archived = []
        bad_hidden = []
        for k in properties.keys():
            d = by_name.get(k)
            if not d:
                continue
            if d.get("status") == "archived" or d.get("archived") is True:
                bad_archived.append(k)
            if d.get("hidden") is True:
                bad_hidden.append(k)
        if bad_archived:
            _log("VALIDATION_ERROR", None, "Attempt to write archived properties")
            return _err("VALIDATION_ERROR", "Cannot write archived properties.", archived_properties=bad_archived)
        if bad_hidden:
            _log("VALIDATION_ERROR", None, "Attempt to write hidden properties")
            return _err("VALIDATION_ERROR", "Cannot write hidden properties.", hidden_properties=bad_hidden)

    # Apply update (empty string means clear)
    stored_props = target.get("properties") if isinstance(target.get("properties"), dict) else {}
    changed = False
    for k, v in properties.items():
        if v == "":
            if k in stored_props:
                del stored_props[k]
                changed = True
        else:
            if stored_props.get(k) != v:
                stored_props[k] = v
                changed = True

    if not changed:
        # No success without effect: treat as conflict/no-op
        _log("CONFLICT", None, "No changes applied")
        return _err("CONFLICT", "Update would not change any properties.")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    target["properties"] = stored_props
    pv = target.get("properties_version")
    try:
        pv = int(pv)
    except Exception:
        pv = 0
    target["properties_version"] = max(1, pv + 1)
    target["updated_at"] = now
    target["hubspot_updated_at"] = now

    _save("crm_objects.json", objs)

    _log("OK", None, None)
    return {
        "id": str(target.get("hubspot_object_id")),
        "properties": stored_props,
        "createdAt": target.get("hubspot_created_at") or target.get("created_at"),
        "updatedAt": target.get("hubspot_updated_at") or target.get("updated_at"),
        "archived": bool(target.get("archived")),
    }

def crm_archive_object(objectType, objectId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_archive_object"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if not isinstance(objectType, str) or objectType not in allowed_types:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "objectType must be one of the supported CRM object types.", field="objectType")
    if not isinstance(objectId, str) or not objectId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "objectId must be a non-empty string.", field="objectId")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Datastore corrupted for crm_objects.")

    idx = None
    row = None
    for i, o in enumerate(objs):
        if not isinstance(o, dict):
            continue
        if o.get("object_type") != objectType:
            continue
        if str(o.get("hubspot_object_id")) == objectId or str(o.get("id")) == objectId:
            idx = i
            row = o
            break

    if row is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", f"{objectType[:-1].capitalize() if objectType.endswith('s') else 'Object'} not found.", objectType=objectType, objectId=objectId)

    portal_id = row.get("portal_id")
    if row.get("status") == "archived" or row.get("archived") is True:
        _log("error", portal_id=portal_id, error_code="CONFLICT")
        return _err("CONFLICT", "Object is already archived.", objectType=objectType, objectId=objectId)

    # lifecycle transition active -> archived only
    if row.get("status") not in (None, "active"):
        _log("error", portal_id=portal_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot archive object from status={row.get('status')}.", objectType=objectType, objectId=objectId)

    now = _iso_now()
    new_row = dict(row)
    new_row["status"] = "archived"
    new_row["archived"] = True
    new_row["updated_at"] = now
    new_row["hubspot_updated_at"] = now
    try:
        pv = int(new_row.get("properties_version") or 1)
    except Exception:
        pv = 1
    new_row["properties_version"] = max(1, pv + 1)

    objs[idx] = new_row
    _save("crm_objects.json", objs)

    _log("success", portal_id=portal_id)
    return {
        "id": new_row.get("hubspot_object_id"),
        "objectType": objectType,
        "archived": True,
        "status": "archived",
        "updatedAt": new_row.get("hubspot_updated_at") or new_row.get("updated_at"),
    }

def crm_search_objects(objectType, filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage():
        usage_files = ["request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"]
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    t0 = time.time()
    usage_file = _ensure_usage()
    usage = _load(usage_file) if usage_file else None

    def _log(status, detail=None):
        if not usage_file:
            return
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "crm_search_objects",
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                **({} if detail is None else {"detail": detail}),
            }
        )
        _save(usage_file, usage)

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if not isinstance(objectType, str) or objectType not in allowed_types:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid objectType.")
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array.")

    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or int(limit) != limit:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    limit = int(limit)
    if limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")

    if after is not None and (not isinstance(after, str) or not after.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a non-empty string when provided.")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str) or not p) for p in properties):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array of strings.")

    if sorts is not None:
        if not isinstance(sorts, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sorts must be an array.")
        for s in sorts:
            if not isinstance(s, dict):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sorts items must be objects.")
            if "propertyName" not in s or "direction" not in s:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each sort must include propertyName and direction.")
            if not isinstance(s["propertyName"], str) or not s["propertyName"]:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort.propertyName must be a string.")
            if s["direction"] not in ("ASCENDING", "DESCENDING"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort.direction must be ASCENDING or DESCENDING.")

    supported_ops = {
        "EQ", "NEQ", "LT", "LTE", "GT", "GTE", "BETWEEN", "IN", "NOT_IN",
        "HAS_PROPERTY", "NOT_HAS_PROPERTY", "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN",
    }

    # Load objects + properties and pick an ambient portal_id context that can serve request
    objs = _load("crm_objects.json")
    props = _load("crm_object_properties.json")
    if not isinstance(objs, list) or not isinstance(props, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Datastore corrupted.")

    portal_ids = sorted({o.get("portal_id") for o in objs if isinstance(o, dict) and o.get("object_type") == objectType and o.get("portal_id")})
    if not portal_ids:
        # No tenant has this object type; still a valid search returning empty results.
        resp = {"total": 0, "results": [], "paging": None}
        _log("ok")
        return resp
    portal_id = portal_ids[0]

    # Validate filterGroups structure
    for gi, g in enumerate(filterGroups):
        if not isinstance(g, dict) or "filters" not in g:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each filterGroup must be an object with filters.")
        if not isinstance(g["filters"], list) or len(g["filters"]) == 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each filterGroup.filters must be a non-empty array.")
        for fi, f in enumerate(g["filters"]):
            if not isinstance(f, dict):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each filter must be an object.")
            if "propertyName" not in f or "operator" not in f:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each filter must include propertyName and operator.")
            if not isinstance(f["propertyName"], str) or not f["propertyName"]:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "filter.propertyName must be a string.")
            if not isinstance(f["operator"], str) or f["operator"] not in supported_ops:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unsupported operator.", operator=f.get("operator"))
            op = f["operator"]
            has_val = "value" in f
            if op in {"HAS_PROPERTY", "NOT_HAS_PROPERTY"}:
                # value ignored / not required
                continue
            if not has_val:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Filter value is required for this operator.", operator=op)
            v = f.get("value")
            if op == "BETWEEN":
                if not isinstance(v, list) or len(v) != 2:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "BETWEEN requires a two-value array.", value=v)
            if op in {"IN", "NOT_IN"}:
                if isinstance(v, list):
                    if len(v) == 0:
                        _log("error", "VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", f"{op} requires a non-empty array.", value=v)
                else:
                    # singleton ok
                    pass

    def _coerce_num(x):
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    def _get_prop(obj, name):
        p = obj.get("properties")
        if isinstance(p, dict):
            return p.get(name)
        return None

    token_re = re.compile(r"[A-Za-z0-9_]+")

    def _contains_token(hay, needle):
        if needle is None:
            return False
        n = str(needle).lower()
        if not n:
            return False
        if hay is None:
            return False
        h = str(hay).lower()
        tokens = set(token_re.findall(h))
        return n.lower() in tokens

    def _eval_filter(obj, flt):
        name = flt["propertyName"]
        op = flt["operator"]
        val = flt.get("value", None)

        if op == "HAS_PROPERTY":
            v = _get_prop(obj, name)
            return v is not None and str(v) != ""
        if op == "NOT_HAS_PROPERTY":
            v = _get_prop(obj, name)
            return v is None or str(v) == ""

        objv = _get_prop(obj, name)

        if op in {"CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"}:
            # Use search_text when propertyName is "search_text" or a special "*" (not in schema); otherwise use property value.
            hay = obj.get("search_text") if name == "search_text" else objv
            res = _contains_token(hay, val)
            return res if op == "CONTAINS_TOKEN" else (not res)

        # For comparisons, treat missing as None
        if op in {"EQ", "NEQ"}:
            res = (str(objv) == str(val)) if (objv is not None and val is not None) else (objv is None and val is None)
            return res if op == "EQ" else (not res)

        # Numeric/date-like comparisons: attempt numeric; else string compare
        if op in {"LT", "LTE", "GT", "GTE"}:
            a_num = _coerce_num(objv)
            b_num = _coerce_num(val)
            if a_num is not None and b_num is not None:
                a = a_num
                b = b_num
            else:
                if objv is None or val is None:
                    return False
                a = str(objv)
                b = str(val)
            if op == "LT":
                return a < b
            if op == "LTE":
                return a <= b
            if op == "GT":
                return a > b
            return a >= b

        if op == "BETWEEN":
            lo, hi = val[0], val[1]
            a_num = _coerce_num(objv)
            lo_num = _coerce_num(lo)
            hi_num = _coerce_num(hi)
            if a_num is not None and lo_num is not None and hi_num is not None:
                return lo_num <= a_num <= hi_num
            if objv is None:
                return False
            a = str(objv)
            return str(lo) <= a <= str(hi)

        if op in {"IN", "NOT_IN"}:
            vals = val if isinstance(val, list) else [val]
            if objv is None:
                present = False
            else:
                present = any(str(objv) == str(x) for x in vals)
            return present if op == "IN" else (not present)

        return False

    def _matches(obj):
        # OR across filterGroups; AND within a group
        for g in filterGroups:
            ok = True
            for f in g["filters"]:
                if not _eval_filter(obj, f):
                    ok = False
                    break
            if ok:
                return True
        return False

    # Base set: portal-scoped, correct type, and exclude archived unless explicitly asked in filters (not supported by schema).
    base = [
        o for o in objs
        if isinstance(o, dict)
        and o.get("portal_id") == portal_id
        and o.get("object_type") == objectType
        and o.get("status") == "active"
        and o.get("archived") is False
    ]

    matched = [o for o in base if _matches(o)]

    # Sort
    if sorts:
        def _sort_key(obj, prop):
            if prop == "createdAt":
                return obj.get("hubspot_created_at") or obj.get("created_at") or ""
            if prop == "updatedAt":
                return obj.get("hubspot_updated_at") or obj.get("updated_at") or ""
            if prop == "id":
                return obj.get("hubspot_object_id") or ""
            v = _get_prop(obj, prop)
            return "" if v is None else v

        # Apply stable sorts from last to first
        for s in reversed(sorts):
            pn = s["propertyName"]
            rev = (s["direction"] == "DESCENDING")
            matched.sort(key=lambda o, p=pn: _sort_key(o, p), reverse=rev)
    else:
        matched.sort(key=lambda o: o.get("hubspot_object_id") or "")

    # Paging cursor: interpret as integer offset
    start = 0
    if after is not None:
        try:
            start = int(after)
            if start < 0:
                raise ValueError()
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "after must be a cursor string returned by a previous call.")
    page = matched[start:start + limit]
    next_after = start + limit
    has_more = next_after < len(matched)

    def _project(o):
        out_props = {}
        p = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        if properties is None:
            out_props = dict(p)
        else:
            for k in properties:
                if k in p:
                    out_props[k] = p.get(k)
        return {
            "id": o.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
            "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at"),
            "archived": bool(o.get("archived")),
        }

    resp = {
        "total": len(matched),
        "results": [_project(o) for o in page],
        "paging": ({"next": {"after": str(next_after)}} if has_more else None),
    }
    _log("ok")
    return resp

def crm_batch_create_objects(objectType, inputs, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage():
        usage_files = ["request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"]
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    t0 = time.time()
    usage_file = _ensure_usage()
    usage = _load(usage_file) if usage_file else None

    def _log(status, detail=None):
        if not usage_file:
            return
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "crm_batch_create_objects",
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                **({} if detail is None else {"detail": detail}),
            }
        )
        _save(usage_file, usage)

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if not isinstance(objectType, str) or objectType not in allowed_types:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid objectType.")
    if not isinstance(inputs, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be an array.")

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    if not all(isinstance(x, list) for x in [objs, prop_defs, assoc_types, assocs]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Datastore corrupted.")

    # Ambient portal selection: pick a portal_id that has relevant property defs or existing objects;
    # if none exist, create in a synthetic default portal.
    portal_ids = sorted({o.get("portal_id") for o in objs if isinstance(o, dict) and o.get("portal_id")})
    if portal_ids:
        portal_id = portal_ids[0]
    else:
        # No portal exists yet; create one implicitly.
        portal_id = "default"

    # Build property definition maps (active only) per portal+type
    defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    def_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    defs_exist = len(defs) > 0

    def _validate_properties(props):
        if not isinstance(props, dict):
            return _err("VALIDATION_ERROR", "properties must be an object.")
        if defs_exist:
            for k in props.keys():
                if k not in def_by_name:
                    return _err("VALIDATION_ERROR", "Unknown property for this object type.", propertyName=k)
                d = def_by_name[k]
                if d.get("status") == "archived" or d.get("archived") is True:
                    return _err("VALIDATION_ERROR", "Cannot write archived property.", propertyName=k)
                if d.get("hidden") is True:
                    # Portal policy: forbid hidden fields (per rules mention this may be forbidden)
                    return _err("VALIDATION_ERROR", "Cannot write hidden property.", propertyName=k)
        return None

    # Association type validation helper
    def _assoc_type_active(from_type, to_type, cat, type_id):
        for r in assoc_types:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("from_object_type") != from_type or r.get("to_object_type") != to_type:
                continue
            if r.get("association_category") != cat:
                continue
            if float(r.get("association_type_id") or 0) != float(type_id):
                continue
            return r.get("status") == "active"
        return False

    # Index objects by hubspot_object_id within portal for reference resolution
    objs_by_hsid = {}
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and isinstance(o.get("hubspot_object_id"), str):
            objs_by_hsid.setdefault((o.get("object_type"), o.get("hubspot_object_id")), []).append(o)

    def _find_obj_any_type_by_hsid(hsid):
        # Try to find target across all types in portal (as HubSpot association "to.id" is object id, type determined by association types)
        matches = []
        for (ot, oid), rows in objs_by_hsid.items():
            if oid == hsid:
                for r in rows:
                    if r.get("status") == "active" and r.get("archived") is False:
                        matches.append(r)
        return matches

    def _new_internal_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    # Determine next hubspot_object_id (string) for created objects if not provided by properties
    max_int = 0
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == objectType:
            hs = o.get("hubspot_object_id")
            if isinstance(hs, str) and hs.isdigit():
                max_int = max(max_int, int(hs))
    next_hsid = max_int + 1

    results = []
    any_success = False

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict) or "properties" not in item:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object with properties."}, "index": idx})
            continue

        props_in = item.get("properties")
        err = _validate_properties(props_in)
        if err:
            results.append({"status": "error", "error": err["error"], "index": idx})
            continue

        assoc_specs = item.get("associations")
        if assoc_specs is not None:
            if not isinstance(assoc_specs, list):
                results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array."}, "index": idx})
                continue
            # validate structure
            assoc_plan = []
            bad = None
            for a in assoc_specs:
                if not isinstance(a, dict) or "to" not in a or "types" not in a:
                    bad = {"code": "VALIDATION_ERROR", "message": "Each association must include to and types."}
                    break
                to = a.get("to")
                if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                    bad = {"code": "VALIDATION_ERROR", "message": "association.to.id must be a string."}
                    break
                types = a.get("types")
                if not isinstance(types, list) or len(types) == 0:
                    bad = {"code": "VALIDATION_ERROR", "message": "association.types must be a non-empty array."}
                    break
                for t in types:
                    if not isinstance(t, dict) or "associationCategory" not in t or "associationTypeId" not in t:
                        bad = {"code": "VALIDATION_ERROR", "message": "Each association type must include associationCategory and associationTypeId."}
                        break
                    cat = t.get("associationCategory")
                    tid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat:
                        bad = {"code": "VALIDATION_ERROR", "message": "associationCategory must be a string."}
                        break
                    if not isinstance(tid, (int, float)) or float(tid) < 1:
                        bad = {"code": "VALIDATION_ERROR", "message": "associationTypeId must be a number >= 1."}
                        break
                    assoc_plan.append({"to_hsid": to["id"], "cat": cat, "tid": tid})
                if bad:
                    break
            if bad:
                results.append({"status": "error", "error": bad, "index": idx})
                continue
        else:
            assoc_plan = []

        # Atomic per item: stage writes
        now = _now()
        hubspot_object_id = str(next_hsid)
        next_hsid += 1

        # Enforce unique(portal_id, object_type, hubspot_object_id)
        if (objectType, hubspot_object_id) in objs_by_hsid:
            results.append({"status": "error", "error": {"code": "CONFLICT", "message": "Object ID already exists."}, "index": idx})
            continue

        new_obj = {
            "id": _new_internal_id("obj"),
            "portal_id": portal_id,
            "object_type": objectType,
            "hubspot_object_id": hubspot_object_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props_in),
            "properties_version": 1,
            "search_text": None,
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        # Validate associations referenced objects and assoc type definitions (must exist and active)
        staged_assocs = []
        assoc_error = None
        for ap in assoc_plan:
            targets = _find_obj_any_type_by_hsid(ap["to_hsid"])
            if not targets:
                assoc_error = {"code": "NOT_FOUND", "message": "Association target not found.", "toObjectId": ap["to_hsid"]}
                break
            # Choose a target such that an active association type exists from objectType -> target.object_type for given cat/tid
            chosen = None
            for tgt in targets:
                if _assoc_type_active(objectType, tgt.get("object_type"), ap["cat"], ap["tid"]):
                    chosen = tgt
                    break
            if chosen is None:
                assoc_error = {"code": "VALIDATION_ERROR", "message": "Association type is not defined or not active for these object types.", "associationCategory": ap["cat"], "associationTypeId": ap["tid"]}
                break

            # Upsert behaviour: if identical edge exists archived, reactivate; else create
            staged_assocs.append(
                {
                    "to_internal_id": chosen.get("id"),
                    "to_object_type": chosen.get("object_type"),
                    "association_category": ap["cat"],
                    "association_type_id": ap["tid"],
                }
            )
        if assoc_error:
            results.append({"status": "error", "error": assoc_error, "index": idx})
            continue

        # Apply staged object + associations
        objs.append(new_obj)
        objs_by_hsid[(objectType, hubspot_object_id)] = [new_obj]

        # Upsert associations
        for sa in staged_assocs:
            # find existing
            existing = None
            for e in assocs:
                if not isinstance(e, dict):
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("from_object_id") == new_obj["id"] and e.get("to_object_id") == sa["to_internal_id"]:
                    if e.get("association_category") == sa["association_category"] and float(e.get("association_type_id") or 0) == float(sa["association_type_id"]):
                        existing = e
                        break
            if existing:
                # Reactivate if archived
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = now
            else:
                assocs.append(
                    {
                        "id": _new_internal_id("assoc"),
                        "portal_id": portal_id,
                        "from_object_id": new_obj["id"],
                        "to_object_id": sa["to_internal_id"],
                        "from_object_type": objectType,
                        "to_object_type": sa["to_object_type"],
                        "association_category": sa["association_category"],
                        "association_type_id": sa["association_type_id"],
                        "status": "active",
                        "archived": False,
                        "created_at": now,
                        "updated_at": now,
                    }
                )

        any_success = True
        results.append(
            {
                "status": "success",
                "index": idx,
                "result": {
                    "id": new_obj["hubspot_object_id"],
                    "properties": dict(new_obj["properties"]),
                    "createdAt": new_obj["hubspot_created_at"],
                    "updatedAt": new_obj["hubspot_updated_at"],
                    "archived": False,
                },
            }
        )

    # Persist only if at least one success (real effect)
    if any_success:
        _save("crm_objects.json", objs)
        _save("crm_associations.json", assocs)

    resp = {"results": results}
    _log("ok" if any_success else "error", "PARTIAL" if any_success else "NO_EFFECT")
    return resp

def crm_batch_read_objects(objectType, objectIds, propertiesWithHistory=None, idProperty=None, properties=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage():
        usage_files = ["request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"]
        for fn in usage_files:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    t0 = time.time()
    usage_file = _ensure_usage()
    usage = _load(usage_file) if usage_file else None

    def _log(status, detail=None):
        if not usage_file:
            return
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "crm_batch_read_objects",
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                **({} if detail is None else {"detail": detail}),
            }
        )
        _save(usage_file, usage)

    allowed_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}
    if not isinstance(objectType, str) or objectType not in allowed_types:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid objectType.")
    if not isinstance(objectIds, list) or any((not isinstance(x, str) or not x) for x in objectIds):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "objectIds must be an array of strings.")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str) or not p) for p in properties):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array of strings.")
    if propertiesWithHistory is not None:
        if not isinstance(propertiesWithHistory, list) or any((not isinstance(p, str) or not p) for p in propertiesWithHistory):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "propertiesWithHistory must be an array of strings.")
    if idProperty is not None and (not isinstance(idProperty, str) or not idProperty):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "idProperty must be a string when provided.")

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(objs, list) or not isinstance(prop_defs, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Datastore corrupted.")

    # Ambient portal resolution
    portal_ids = sorted({o.get("portal_id") for o in objs if isinstance(o, dict) and o.get("portal_id")})
    portal_id = portal_ids[0] if portal_ids else "default"

    # Validate requested properties against definitions when they exist
    defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    def_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    defs_exist = len(defs) > 0

    def _validate_prop_names(names, field):
        if names is None:
            return None
        if defs_exist:
            for n in names:
                if n not in def_by_name:
                    return _err("VALIDATION_ERROR", f"Unknown property requested in {field}.", propertyName=n)
        return None

    err = _validate_prop_names(properties, "properties")
    if err:
        _log("error", "VALIDATION_ERROR")
        return err
    err = _validate_prop_names(propertiesWithHistory, "propertiesWithHistory")
    if err:
        _log("error", "VALIDATION_ERROR")
        return err

    # idProperty support: must be defined and has_unique_value=true
    if idProperty is not None:
        if not defs_exist or idProperty not in def_by_name:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "idProperty is not valid for this object type.", idProperty=idProperty)
        if def_by_name[idProperty].get("has_unique_value") is not True:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "idProperty must be a unique property (has_unique_value=true).", idProperty=idProperty)

    # Index objects
    active_objs = [
        o for o in objs
        if isinstance(o, dict)
        and o.get("portal_id") == portal_id
        and o.get("object_type") == objectType
        and o.get("status") == "active"
        and o.get("archived") is False
    ]

    by_hsid = {o.get("hubspot_object_id"): o for o in active_objs if isinstance(o.get("hubspot_object_id"), str)}
    by_unique = {}
    if idProperty is not None:
        for o in active_objs:
            props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
            v = props.get(idProperty)
            if v is None or str(v) == "":
                continue
            k = str(v)
            by_unique.setdefault(k, []).append(o)

    def _project(o):
        p = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        if properties is None:
            out_props = dict(p)
        else:
            out_props = {k: p.get(k) for k in properties if k in p}

        out = {
            "id": o.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
            "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at"),
            "archived": bool(o.get("archived")),
        }

        # No history store in schema; return empty history entries for requested fields.
        if propertiesWithHistory is not None:
            hist = {}
            for k in propertiesWithHistory:
                if k in p:
                    hist[k] = [{"value": p.get(k), "timestamp": o.get("hubspot_updated_at") or o.get("updated_at")}]
                else:
                    hist[k] = []
            out["propertiesWithHistory"] = hist
        return out

    results = []
    for req_id in objectIds:
        o = None
        if idProperty is None:
            o = by_hsid.get(req_id)
        else:
            matches = by_unique.get(str(req_id), [])
            if len(matches) == 1:
                o = matches[0]
            elif len(matches) > 1:
                results.append({"status": "error", "id": req_id, "error": {"code": "CONFLICT", "message": "idProperty did not resolve uniquely.", "idProperty": idProperty}})
                continue

        if o is None:
            results.append({"status": "error", "id": req_id, "error": {"code": "NOT_FOUND", "message": "Object not found."}})
        else:
            results.append({"status": "success", "id": req_id, "result": _project(o)})

    resp = {"results": results}
    _log("ok")
    return resp

def crm_batch_update_objects(objectType, inputs, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # --- request logging / quota & rate limit (best-effort if collections exist) ---
    def _log(status_code, credential_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "crm_batch_update_objects",
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            }
            if details is not None:
                row["details"] = details
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _enforce_limits():
        # If there is a request log store, enforce simplistic limits:
        # - RATE_LIMIT: 120 req/min per portal if identifiable, else global
        # - QUOTA_EXCEEDED: 50k req/day global
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or not logs:
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        def _parse(ts):
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            ts = _parse(str(r.get("timestamp", "")))
            if not ts:
                continue
            dt = now - ts
            if dt.total_seconds() <= 60:
                last_min += 1
            if dt.total_seconds() <= 86400:
                last_day += 1
        if last_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(lim_err["error"]["code"])
        return lim_err

    # --- validation ---
    allowed_types = {"companies","contacts","deals","tickets","products","line_items","quotes","custom"}
    if objectType not in allowed_types:
        e = _err("VALIDATION_ERROR", "Invalid objectType.", field="objectType")
        _log("VALIDATION_ERROR")
        return e
    if not isinstance(inputs, list):
        e = _err("VALIDATION_ERROR", "Invalid inputs; expected array.", field="inputs")
        _log("VALIDATION_ERROR")
        return e
    if len(inputs) == 0:
        e = _err("VALIDATION_ERROR", "inputs must not be empty.", field="inputs")
        _log("VALIDATION_ERROR")
        return e

    crm_objects = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")

    if not isinstance(crm_objects, list):
        crm_objects = []
    if not isinstance(props_defs, list):
        props_defs = []

    # Ambient auth: choose a portal_id that can satisfy the request by finding at least one object in that type.
    portal_candidates = {}
    for o in crm_objects:
        if isinstance(o, dict) and o.get("object_type") == objectType and isinstance(o.get("portal_id"), str):
            portal_candidates[o["portal_id"]] = portal_candidates.get(o["portal_id"], 0) + 1
    portal_id = None
    if portal_candidates:
        portal_id = sorted(portal_candidates.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
    else:
        # No objects of that type exist in any portal; still allow update to return per-item NOT_FOUND,
        # but must pick some portal context if possible.
        portals = []
        for o in crm_objects:
            if isinstance(o, dict) and isinstance(o.get("portal_id"), str):
                portals.append(o["portal_id"])
        portal_id = portals[0] if portals else None
    if portal_id is None:
        e = _err("UNAUTHORIZED", "No authorized portal context available.")
        _log("UNAUTHORIZED")
        return e

    # Build property definition map for this portal/type
    defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == objectType]
    def_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    have_defs = len(def_by_name) > 0

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    # Identify objects map by hubspot_object_id within portal/type
    objs_idx = {}
    for i, o in enumerate(crm_objects):
        if not isinstance(o, dict): 
            continue
        if o.get("portal_id") != portal_id or o.get("object_type") != objectType:
            continue
        hid = o.get("hubspot_object_id")
        if isinstance(hid, str):
            objs_idx[hid] = i

    # Per-item processing (atomic per item: validate first, then apply)
    results = []
    any_change = False

    def _validate_properties_update(patch_props):
        if not isinstance(patch_props, dict):
            return _err("VALIDATION_ERROR", "properties must be an object.", field="properties")
        # When definitions exist, validate property names exist; reject archived/hidden definitions.
        if have_defs:
            for k, v in patch_props.items():
                if not isinstance(k, str) or k == "":
                    return _err("VALIDATION_ERROR", "Invalid property name.", field="properties")
                d = def_by_name.get(k)
                if d is None:
                    return _err("VALIDATION_ERROR", f"Unknown property '{k}' for {objectType}.", field="properties", property=k)
                if d.get("archived") is True or d.get("status") == "archived":
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be updated.", field="properties", property=k)
                if d.get("hidden") is True:
                    # Portal policy not provided; default to forbidding hidden field writes as per rules.
                    return _err("VALIDATION_ERROR", f"Property '{k}' is hidden and cannot be updated.", field="properties", property=k)
                # Basic type validation (lightweight)
                typ = d.get("type")
                if typ in ("string", "enumeration"):
                    if not (isinstance(v, str) or v is None):
                        return _err("VALIDATION_ERROR", f"Invalid value type for '{k}'. Expected string.", field="properties", property=k)
                    if typ == "enumeration" and isinstance(v, str):
                        opts = d.get("options") if isinstance(d.get("options"), list) else []
                        allowed = {o.get("value") for o in opts if isinstance(o, dict) and isinstance(o.get("value"), str)}
                        # allow empty string to clear
                        if v != "" and allowed and v not in allowed:
                            return _err("VALIDATION_ERROR", f"Invalid enumeration value for '{k}'.", field="properties", property=k)
                elif typ == "number":
                    if not (isinstance(v, (int, float)) or (isinstance(v, str) and v == "") or v is None):
                        return _err("VALIDATION_ERROR", f"Invalid value type for '{k}'. Expected number.", field="properties", property=k)
                elif typ in ("date", "datetime"):
                    # allow ISO string or empty string for clear
                    if not (isinstance(v, str) or v is None):
                        return _err("VALIDATION_ERROR", f"Invalid value type for '{k}'. Expected string timestamp.", field="properties", property=k)
                elif typ == "bool":
                    if not (isinstance(v, bool) or (isinstance(v, str) and v == "") or v is None):
                        return _err("VALIDATION_ERROR", f"Invalid value type for '{k}'. Expected boolean.", field="properties", property=k)
        else:
            # No definitions exist: tool schema allows additionalProperties; accept dict as-is.
            for k in patch_props.keys():
                if not isinstance(k, str) or k == "":
                    return _err("VALIDATION_ERROR", "Invalid property name.", field="properties")
        return None

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        if "id" not in item or "properties" not in item:
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input requires id and properties."}})
            continue
        obj_id = item.get("id")
        patch_props = item.get("properties")
        if not isinstance(obj_id, str) or obj_id == "":
            results.append({"index": idx, "id": obj_id, "error": {"code": "VALIDATION_ERROR", "message": "id must be a non-empty string."}})
            continue

        v_err = _validate_properties_update(patch_props)
        if v_err:
            results.append({"index": idx, "id": obj_id, "error": v_err["error"]})
            continue

        pos = objs_idx.get(obj_id)
        if pos is None:
            results.append({"index": idx, "id": obj_id, "error": {"code": "NOT_FOUND", "message": "Object not found."}})
            continue

        # Apply update
        o = crm_objects[pos]
        if not isinstance(o, dict):
            results.append({"index": idx, "id": obj_id, "error": {"code": "NOT_FOUND", "message": "Object not found."}})
            continue

        # Update properties (empty string means clear)
        props = o.get("properties")
        if not isinstance(props, dict):
            props = {}

        changed = False
        for k, v in patch_props.items():
            if v == "":
                if k in props:
                    props.pop(k, None)
                    changed = True
            else:
                if props.get(k) != v:
                    props[k] = v
                    changed = True

        if not changed:
            # No success without effect: return a conflict-like per-item error
            results.append({"index": idx, "id": obj_id, "error": {"code": "CONFLICT", "message": "No changes to apply."}})
            continue

        o["properties"] = props
        try:
            pv = int(o.get("properties_version", 1))
        except Exception:
            pv = 1
        o["properties_version"] = max(1, pv + 1)
        o["updated_at"] = now
        o["hubspot_updated_at"] = now

        # Update search_text best-effort
        try:
            blob_parts = []
            for kk, vv in props.items():
                if isinstance(vv, (str, int, float, bool)):
                    blob_parts.append(str(vv))
            o["search_text"] = " ".join(blob_parts)[:20000] if blob_parts else o.get("search_text")
        except Exception:
            pass

        crm_objects[pos] = o
        any_change = True
        results.append({
            "index": idx,
            "id": obj_id,
            "status": "UPDATED",
            "record": {
                "id": o.get("hubspot_object_id"),
                "objectType": objectType,
                "archived": bool(o.get("archived", False)),
                "properties": o.get("properties", {}),
                "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
                "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at")
            }
        })

    if any_change:
        _save("crm_objects.json", crm_objects)

    resp = {
        "objectType": objectType,
        "portalId": portal_id,
        "results": results
    }
    _log("OK")
    return resp

