        o = crm_objects[pos]
        if not isinstance(o, dict):
            results.append({"id": oid, "error": {"code": "NOT_FOUND", "message": "Object not found."}})
            continue
        if o.get("status") == "archived" or o.get("archived") is True:
            results.append({"id": oid, "error": {"code": "CONFLICT", "message": "Object is already archived."}})
            continue

        # Lifecycle transition active -> archived
        o["status"] = "archived"
        o["archived"] = True
        o["updated_at"] = now
        o["hubspot_updated_at"] = now
        crm_objects[pos] = o
        any_change = True

        # Cascade: archive associations touching this object's internal id
        internal_id = o.get("id")
        if isinstance(internal_id, str):
            for a in crm_associations:
                if not isinstance(a, dict):
                    continue
                if a.get("portal_id") != portal_id:
                    continue
                if a.get("from_object_id") == internal_id or a.get("to_object_id") == internal_id:
                    if a.get("status") != "archived" or a.get("archived") is not True:
                        a["status"] = "archived"
                        a["archived"] = True
                        a["updated_at"] = now
                        any_change = True

            # Cascade for communications contact_status referencing this contact internal id
            if objectType == "contacts":
                # remove rows referencing this contact to avoid FK to archived object; treat as cascade delete
                new_comm = []
                comm_changed = False
                for r in communications:
                    if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("row_type") == "contact_status" and r.get("contact_object_id") == internal_id:
                        comm_changed = True
                        continue
                    new_comm.append(r)
                if comm_changed:
                    communications = new_comm
                    any_change = True

        results.append({"id": oid, "status": "ARCHIVED"})

    if any_change:
        _save("crm_objects.json", crm_objects)
        _save("crm_associations.json", crm_associations)
        _save("communications_subscriptions.json", communications)

    resp = {"objectType": objectType, "portalId": portal_id, "results": results}
    _log("OK")
    return resp

def crm_list_association_types(fromObjectType, toObjectType, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_code, credential_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "crm_list_association_types",
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            }
            if details is not None:
                row["details"] = details
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or not logs:
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        def _parse(ts):
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                return None
        last_min = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            ts = _parse(str(r.get("timestamp", "")))
            if not ts:
                continue
            dt = now - ts
            if dt.total_seconds() <= 60:
                last_min += 1
            if dt.total_seconds() <= 86400:
                last_day += 1
        if last_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(lim_err["error"]["code"])
        return lim_err

    allowed_types = {"companies","contacts","deals","tickets","products","line_items","quotes","custom"}
    if fromObjectType not in allowed_types:
        e = _err("VALIDATION_ERROR", "Invalid fromObjectType.", field="fromObjectType")
        _log("VALIDATION_ERROR")
        return e
    if toObjectType not in allowed_types:
        e = _err("VALIDATION_ERROR", "Invalid toObjectType.", field="toObjectType")
        _log("VALIDATION_ERROR")
        return e

    assoc_types = _load("crm_association_types.json")
    crm_objects = _load("crm_objects.json")
    if not isinstance(assoc_types, list):
        assoc_types = []
    if not isinstance(crm_objects, list):
        crm_objects = []

    # Ambient portal selection: pick any portal that has association types for this pair; else any portal with data.
    portals = {}
    for r in assoc_types:
        if not isinstance(r, dict):
            continue
        if r.get("from_object_type") == fromObjectType and r.get("to_object_type") == toObjectType and isinstance(r.get("portal_id"), str):
            portals[r["portal_id"]] = portals.get(r["portal_id"], 0) + 1
    portal_id = None
    if portals:
        portal_id = sorted(portals.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
    else:
        for o in crm_objects:
            if isinstance(o, dict) and isinstance(o.get("portal_id"), str):
                portal_id = o["portal_id"]
                break
    if portal_id is None:
        e = _err("UNAUTHORIZED", "No authorized portal context available.")
        _log("UNAUTHORIZED")
        return e

    rows = [
        r for r in assoc_types
        if isinstance(r, dict)
        and r.get("portal_id") == portal_id
        and r.get("from_object_type") == fromObjectType
        and r.get("to_object_type") == toObjectType
        and r.get("status") == "active"
    ]

    # NOT_FOUND if the object-type pair is not recognized by backend (no definitions at all for the pair)
    any_pair_rows = any(
        isinstance(r, dict)
        and r.get("portal_id") == portal_id
        and r.get("from_object_type") == fromObjectType
        and r.get("to_object_type") == toObjectType
        for r in assoc_types
    )
    if not any_pair_rows:
        e = _err("NOT_FOUND", "Association type pair not recognized.", fromObjectType=fromObjectType, toObjectType=toObjectType)
        _log("NOT_FOUND")
        return e

    out = []
    for r in rows:
        out.append({
            "associationCategory": r.get("association_category"),
            "associationTypeId": r.get("association_type_id"),
            "label": r.get("label"),
            "status": r.get("status"),
        })

    resp = {
        "portalId": portal_id,
        "fromObjectType": fromObjectType,
        "toObjectType": toObjectType,
        "results": out,
        "total": len(out)
    }
    _log("OK")
    return resp

def crm_get_associations(fromObjectType, toObjectType, fromObjectId, after=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_get_associations"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    allowed = {"companies","contacts","deals","tickets","products","line_items","quotes","custom"}
    if not isinstance(fromObjectType, str) or fromObjectType not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectType must be one of the supported CRM object types.", field="fromObjectType")
    if not isinstance(toObjectType, str) or toObjectType not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "toObjectType must be one of the supported CRM object types.", field="toObjectType")
    if not isinstance(fromObjectId, str) or not fromObjectId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectId must be a non-empty string.", field="fromObjectId")
    if after is not None and not isinstance(after, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a string when provided.", field="after")
    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, (int, float)):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number between 1 and 500.", field="limit")
        lim = int(limit)
    if lim < 1 or lim > 500:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")

    objs = _load("crm_objects.json")
    assocs = _load("crm_associations.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(assocs, list): assocs = []

    # Find from object by hubspot_object_id (tool ID) or internal id
    from_row = None
    for o in objs:
        if not isinstance(o, dict): 
            continue
        if o.get("object_type") != fromObjectType:
            continue
        if str(o.get("hubspot_object_id")) == fromObjectId or str(o.get("id")) == fromObjectId:
            from_row = o
            break
    if not from_row:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "From object not found.", fromObjectId=fromObjectId)

    portal_id = from_row.get("portal_id")
    from_internal_id = from_row.get("id")

    # gather active associations from -> to type, same portal, active edge, and to object not archived
    to_by_internal = {}
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and isinstance(o.get("id"), str):
            to_by_internal[o["id"]] = o

    links = []
    for e in assocs:
        if not isinstance(e, dict): 
            continue
        if e.get("portal_id") != portal_id:
            continue
        if e.get("from_object_id") != from_internal_id:
            continue
        if e.get("from_object_type") != fromObjectType or e.get("to_object_type") != toObjectType:
            continue
        if e.get("status") != "active" or e.get("archived") is True:
            continue
        to_obj = to_by_internal.get(e.get("to_object_id"))
        if not isinstance(to_obj, dict):
            continue
        if to_obj.get("status") == "archived" or to_obj.get("archived") is True:
            continue
        links.append((str(e.get("id")), e, to_obj))

    # Sort by association id for stable cursor paging
    links.sort(key=lambda t: t[0])

    start_idx = 0
    if after:
        for i, (aid, _, __) in enumerate(links):
            if aid == after:
                start_idx = i + 1
                break

    page = links[start_idx:start_idx + lim]
    results = []
    for aid, e, to_obj in page:
        results.append({
            "fromObjectId": fromObjectId,
            "toObjectId": str(to_obj.get("hubspot_object_id")),
            "toObjectType": toObjectType,
            "associationCategory": e.get("association_category"),
            "associationTypeId": e.get("association_type_id"),
            "associationId": aid,
        })

    next_after = None
    if start_idx + lim < len(links) and page:
        next_after = page[-1][0]

    _log("success", portal_id=portal_id)
    resp = {"results": results}
    if next_after is not None:
        resp["paging"] = {"next": {"after": next_after}}
    return resp

def crm_create_association(fromObjectType, toObjectType, fromObjectId, toObjectId, associationTypes, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_create_association"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    allowed = {"companies","contacts","deals","tickets","products","line_items","quotes","custom"}
    if not isinstance(fromObjectType, str) or fromObjectType not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectType must be a supported CRM object type.", field="fromObjectType")
    if not isinstance(toObjectType, str) or toObjectType not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "toObjectType must be a supported CRM object type.", field="toObjectType")
    if not isinstance(fromObjectId, str) or not fromObjectId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectId must be a non-empty string.", field="fromObjectId")
    if not isinstance(toObjectId, str) or not toObjectId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "toObjectId must be a non-empty string.", field="toObjectId")
    if not isinstance(associationTypes, list) or len(associationTypes) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "associationTypes must be a non-empty array.", field="associationTypes")

    # Validate each association type entry
    norm_types = []
    for i, at in enumerate(associationTypes):
        if not isinstance(at, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associationTypes entries must be objects.", field=f"associationTypes[{i}]")
        if "associationCategory" not in at or "associationTypeId" not in at:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associationTypes entries must include associationCategory and associationTypeId.", field=f"associationTypes[{i}]")
        cat = at.get("associationCategory")
        tid = at.get("associationTypeId")
        if not isinstance(cat, str) or not cat.strip():
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associationCategory must be a non-empty string.", field=f"associationTypes[{i}].associationCategory")
        if not isinstance(tid, (int, float)) or int(tid) < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associationTypeId must be a number >= 1.", field=f"associationTypes[{i}].associationTypeId")
        norm_types.append((cat, int(tid)))

    objs = _load("crm_objects.json")
    assoc_types = _load("crm_association_types.json")
    assoc_edges = _load("crm_associations.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(assoc_types, list): assoc_types = []
    if not isinstance(assoc_edges, list): assoc_edges = []

    # resolve objects by hubspot_object_id or internal id
    from_row = None
    to_row = None
    for o in objs:
        if not isinstance(o, dict): 
            continue
        if o.get("object_type") == fromObjectType and (str(o.get("hubspot_object_id")) == fromObjectId or str(o.get("id")) == fromObjectId):
            from_row = o
        if o.get("object_type") == toObjectType and (str(o.get("hubspot_object_id")) == toObjectId or str(o.get("id")) == toObjectId):
            to_row = o
        if from_row and to_row:
            break
    if not from_row or not to_row:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "One or both objects not found.", missing={"from": from_row is None, "to": to_row is None})

    portal_id = from_row.get("portal_id")
    if portal_id != to_row.get("portal_id"):
        _log("error", portal_id=portal_id, error_code="CONFLICT")
        return _err("CONFLICT", "Objects belong to different portals; cross-portal associations are not allowed.")

    from_internal = from_row.get("id")
    to_internal = to_row.get("id")
    if from_internal == to_internal:
        _log("error", portal_id=portal_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectId and toObjectId must refer to different objects.", rule="from_object_id != to_object_id")

    # validate association type exists and active (business rule)
    valid_type_set = set()
    for r in assoc_types:
        if not isinstance(r, dict): 
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("from_object_type") != fromObjectType or r.get("to_object_type") != toObjectType:
            continue
        if r.get("status") != "active":
            continue
        valid_type_set.add((str(r.get("association_category")), int(r.get("association_type_id"))))
    for cat, tid in norm_types:
        if (cat, tid) not in valid_type_set:
            _log("error", portal_id=portal_id, error_code="VALIDATION_ERROR")
            return _err(
                "VALIDATION_ERROR",
                "Association type is not available/active for this portal and object-type pair.",
                rule="Association creation tools must validate association type exists and is active",
                associationCategory=cat,
                associationTypeId=tid
            )

    # Upsert edges: if same edge exists archived, reactivate
    existing_ids = {e.get("id") for e in assoc_edges if isinstance(e, dict) and isinstance(e.get("id"), str)}
    created_or_updated = []
    now = _iso_now()

    for cat, tid in norm_types:
        match_idx = None
        for i, e in enumerate(assoc_edges):
            if not isinstance(e, dict): 
                continue
            if e.get("portal_id") == portal_id and e.get("from_object_id") == from_internal and e.get("to_object_id") == to_internal and str(e.get("association_category")) == cat and int(e.get("association_type_id") or 0) == tid:
                match_idx = i
                break

        if match_idx is not None:
            e = assoc_edges[match_idx]
            # If archived, restore (reactivate). If active, idempotent.
            if e.get("status") == "archived" or e.get("archived") is True:
                e2 = dict(e)
                e2["status"] = "active"
                e2["archived"] = False
                e2["updated_at"] = now
                assoc_edges[match_idx] = e2
                created_or_updated.append(e2)
            else:
                created_or_updated.append(e)
        else:
            while True:
                nid = f"hs_assoc_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{secrets.token_hex(8)}"
                if nid not in existing_ids:
                    existing_ids.add(nid)
                    break
            new_edge = {
                "id": nid,
                "portal_id": portal_id,
                "from_object_id": from_internal,
                "to_object_id": to_internal,
                "from_object_type": fromObjectType,
                "to_object_type": toObjectType,
                "association_category": cat,
                "association_type_id": tid,
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now,
            }
            assoc_edges.append(new_edge)
            created_or_updated.append(new_edge)

    _save("crm_associations.json", assoc_edges)
    _log("success", portal_id=portal_id)
    return {"results": created_or_updated}

