        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "One or both objects not found.", missing={"from": from_row is None, "to": to_row is None})

    portal_id = from_row.get("portal_id")
    if portal_id != to_row.get("portal_id"):
        _log("error", portal_id=portal_id, error_code="CONFLICT")
        return _err("CONFLICT", "Objects belong to different portals; cross-portal associations are not allowed.")

    from_internal = from_row.get("id")
    to_internal = to_row.get("id")

    # archive all matching active associations between these two, regardless of type/category
    now = _iso_now()
    changed = []
    for i, e in enumerate(edges):
        if not isinstance(e, dict):
            continue
        if e.get("portal_id") != portal_id:
            continue
        if e.get("from_object_id") != from_internal or e.get("to_object_id") != to_internal:
            continue
        if e.get("from_object_type") != fromObjectType or e.get("to_object_type") != toObjectType:
            continue
        if e.get("status") == "archived" or e.get("archived") is True:
            continue
        e2 = dict(e)
        e2["status"] = "archived"
        e2["archived"] = True
        e2["updated_at"] = now
        edges[i] = e2
        changed.append(e2)

    if not changed:
        _log("error", portal_id=portal_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No association exists between the specified objects to archive.")

    _save("crm_associations.json", edges)
    _log("success", portal_id=portal_id)
    return {"results": changed}

def crm_batch_create_associations(fromObjectType, toObjectType, inputs, **_extra):
    import json, os, datetime, time, uuid, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_batch_create_associations"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": _now(),
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    allowed = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}

    if not isinstance(fromObjectType, str) or fromObjectType not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported fromObjectType.", field="fromObjectType")
    if not isinstance(toObjectType, str) or toObjectType not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported toObjectType.", field="toObjectType")
    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array.", field="inputs")

    objs = _load("crm_objects.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    # Index objects by (portal_id, object_type, hubspot_object_id)
    obj_idx = {}
    for o in objs:
        obj_idx[(o.get("portal_id"), o.get("object_type"), o.get("hubspot_object_id"))] = o

    # Index active association types by (portal, from_type, to_type, category, type_id)
    at_idx = {}
    for at in assoc_types:
        if at.get("status") != "active":
            continue
        try:
            tid = int(at.get("association_type_id"))
        except Exception:
            continue
        at_idx[(at.get("portal_id"), at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), tid)] = at

    # Candidate portals to try for each input: portals where both object ids exist for given types.
    # We'll pick the first portal per item where prerequisites are met.
    def _item_portals(from_id, to_id):
        portals = set()
        for o in objs:
            if o.get("object_type") == fromObjectType and o.get("hubspot_object_id") == from_id:
                portals.add(o.get("portal_id"))
        for o in objs:
            if o.get("object_type") == toObjectType and o.get("hubspot_object_id") == to_id:
                portals.add(o.get("portal_id"))
        return [p for p in portals if p]

    results = []
    any_success = False
    now = _now()

    for idx, item in enumerate(inputs):
        # Validate shape
        if not isinstance(item, dict):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        fr = item.get("from")
        to = item.get("to")
        types = item.get("types")
        if not isinstance(fr, dict) or "id" not in fr or not isinstance(fr.get("id"), str) or not fr.get("id"):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing or invalid from.id."}})
            continue
        if not isinstance(to, dict) or "id" not in to or not isinstance(to.get("id"), str) or not to.get("id"):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing or invalid to.id."}})
            continue
        if not isinstance(types, list) or len(types) == 0:
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "types must be a non-empty array."}})
            continue

        # Parse types
        parsed = []
        bad = None
        for j, t in enumerate(types):
            if not isinstance(t, dict) or "associationCategory" not in t or "associationTypeId" not in t:
                bad = ("VALIDATION_ERROR", f"types[{j}] is missing required fields.")
                break
            cat = t.get("associationCategory")
            tid = t.get("associationTypeId")
            if not isinstance(cat, str) or not cat:
                bad = ("VALIDATION_ERROR", f"types[{j}].associationCategory must be a non-empty string.")
                break
            if not (isinstance(tid, int) or isinstance(tid, float)) or int(tid) != tid or tid < 1:
                bad = ("VALIDATION_ERROR", f"types[{j}].associationTypeId must be an integer >= 1.")
                break
            parsed.append((cat, int(tid)))
        if bad:
            results.append({"index": idx, "error": {"code": bad[0], "message": bad[1]}})
            continue

        from_id = fr["id"]
        to_id = to["id"]

        # Item atomicity: work on a copy of assocs for this item and commit only if all its edges validate & apply.
        item_portal = None
        from_row = None
        to_row = None
        for p in _item_portals(from_id, to_id):
            fr_row = obj_idx.get((p, fromObjectType, from_id))
            to_row2 = obj_idx.get((p, toObjectType, to_id))
            if not fr_row or not to_row2:
                continue
            ok = True
            for (cat, tid) in parsed:
                if (p, fromObjectType, toObjectType, cat, tid) not in at_idx:
                    ok = False
                    break
            if ok:
                item_portal = p
                from_row = fr_row
                to_row = to_row2
                break

        if item_portal is None:
            # discriminate NOT_FOUND vs validation
            any_from = any(o.get("object_type") == fromObjectType and o.get("hubspot_object_id") == from_id for o in objs)
            any_to = any(o.get("object_type") == toObjectType and o.get("hubspot_object_id") == to_id for o in objs)
            if not any_from or not any_to:
                results.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "Either the from or to object does not exist in the synced CRM subset."}})
            else:
                results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "No active association type definition exists for one or more requested types."}})
            continue

        if from_row["id"] == to_row["id"]:
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "from.id and to.id must refer to different objects."}})
            continue

        # Apply for this item
        new_edges = []
        assocs_work = assocs  # we will mutate directly but only after we know we can apply all; here all validated.
        for (cat, tid) in parsed:
            existing = None
            for e in assocs_work:
                if e.get("portal_id") == item_portal and e.get("from_object_id") == from_row["id"] and e.get("to_object_id") == to_row["id"] and e.get("association_category") == cat and int(e.get("association_type_id")) == tid:
                    existing = e
                    break
            if existing:
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = now
                new_edges.append(existing)
            else:
                row = {
                    "id": "assoc_" + uuid.uuid4().hex,
                    "portal_id": item_portal,
                    "from_object_id": from_row["id"],
                    "to_object_id": to_row["id"],
                    "from_object_type": fromObjectType,
                    "to_object_type": toObjectType,
                    "association_category": cat,
                    "association_type_id": tid,
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now
                }
                assocs_work.append(row)
                new_edges.append(row)

        any_success = True
        results.append({
            "index": idx,
            "from": {"id": from_id},
            "to": {"id": to_id},
            "results": [{"id": e.get("id"), "associationCategory": e.get("association_category"), "associationTypeId": e.get("association_type_id"), "status": e.get("status"), "archived": e.get("archived")} for e in new_edges]
        })

    if any_success:
        _save("crm_associations.json", assocs)
        _log("ok", None)
    else:
        _log("error", "VALIDATION_ERROR")

    return {"fromObjectType": fromObjectType, "toObjectType": toObjectType, "results": results}

def crm_batch_archive_associations(fromObjectType, toObjectType, inputs, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
