    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_batch_archive_associations"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_log.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": _now(),
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    allowed = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom"}

    if not isinstance(fromObjectType, str) or fromObjectType not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported fromObjectType.", field="fromObjectType")
    if not isinstance(toObjectType, str) or toObjectType not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported toObjectType.", field="toObjectType")
    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array.", field="inputs")

    objs = _load("crm_objects.json")
    assocs = _load("crm_associations.json")

    # index objects by portal,type,hubspot_object_id
    obj_idx = {}
    for o in objs:
        obj_idx[(o.get("portal_id"), o.get("object_type"), o.get("hubspot_object_id"))] = o

    def _candidate_portals(from_id, to_id):
        portals = set()
        for o in objs:
            if o.get("object_type") == fromObjectType and o.get("hubspot_object_id") == from_id:
                portals.add(o.get("portal_id"))
        for o in objs:
            if o.get("object_type") == toObjectType and o.get("hubspot_object_id") == to_id:
                portals.add(o.get("portal_id"))
        return [p for p in portals if p]

    now = _now()
    results = []
    any_success = False

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        fr = item.get("from")
        to = item.get("to")
        if not isinstance(fr, dict) or "id" not in fr or not isinstance(fr.get("id"), str) or not fr.get("id"):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing or invalid from.id."}})
            continue
        if not isinstance(to, dict) or "id" not in to or not isinstance(to.get("id"), str) or not to.get("id"):
            results.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing or invalid to.id."}})
            continue

        from_id = fr["id"]
        to_id = to["id"]

        portal = None
        from_row = None
        to_row = None
        for p in _candidate_portals(from_id, to_id):
            fr_row = obj_idx.get((p, fromObjectType, from_id))
            to_row2 = obj_idx.get((p, toObjectType, to_id))
            if fr_row and to_row2:
                portal = p
                from_row = fr_row
                to_row = to_row2
                break

        if portal is None:
            any_from = any(o.get("object_type") == fromObjectType and o.get("hubspot_object_id") == from_id for o in objs)
            any_to = any(o.get("object_type") == toObjectType and o.get("hubspot_object_id") == to_id for o in objs)
            if not any_from or not any_to:
                results.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "Either the from or to object does not exist in the synced CRM subset."}})
            else:
                results.append({"index": idx, "error": {"code": "UNAUTHORIZED", "message": "No authorized portal context could be resolved for this request."}})
            continue

        # Archive all active edges between the pair for this portal
        touched = []
        for e in assocs:
            if e.get("portal_id") == portal and e.get("from_object_id") == from_row["id"] and e.get("to_object_id") == to_row["id"] and e.get("status") == "active" and e.get("archived") is False:
                e["status"] = "archived"
                e["archived"] = True
                e["updated_at"] = now
                touched.append(e)

        if not touched:
            results.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "No association exists between the specified objects to archive."}})
            continue

        any_success = True
        results.append({
            "index": idx,
            "from": {"id": from_id},
            "to": {"id": to_id},
            "archivedCount": len(touched),
            "results": [{"id": e.get("id")} for e in touched]
        })

    if any_success:
        _save("crm_associations.json", assocs)
        _log("ok", None)
    else:
        _log("error", "VALIDATION_ERROR")

    return {"fromObjectType": fromObjectType, "toObjectType": toObjectType, "results": results}

def crm_create_contact(properties, associations=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_create_contact"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        for r in props:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        for r in assoc_types:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        for r in subs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    portal_id = _get_portal_id()

    def _log(status, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _validate_email(v):
        if not isinstance(v, str) or not v:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", v) is not None

    def _validate_uri(v):
        if not isinstance(v, str) or not v:
            return False
        try:
            p = urllib.parse.urlparse(v)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _tokenize_search(props):
        parts = []
        for k, v in (props or {}).items():
            if v is None:
                continue
            if isinstance(v, (str, int, float, bool)):
                parts.append(str(v))
        blob = " ".join(parts).lower()
        blob = re.sub(r"[^a-z0-9]+", " ", blob).strip()
        return blob if blob else None

    # Validate portal context
    if not portal_id:
        _log("error", {"code": "UNAUTHORIZED", "message": "No tenant context available"})
        return _err("UNAUTHORIZED", "No tenant context available")

    # Validate inputs
    if not isinstance(properties, dict):
        _log("error", {"code": "VALIDATION_ERROR", "message": "properties must be an object"})
        return _err("VALIDATION_ERROR", "properties must be an object")

    if associations is not None and not isinstance(associations, list):
        _log("error", {"code": "VALIDATION_ERROR", "message": "associations must be an array"})
        return _err("VALIDATION_ERROR", "associations must be an array")

    # Validate schema-required-like expectations (tool requires properties object only; no required fields inside)
    lifecyclestage_allowed = {
        "subscriber", "lead", "marketingqualifiedlead", "salesqualifiedlead",
        "opportunity", "customer", "evangelist", "other"
    }
    leadstatus_allowed = {
        "new", "open", "inprogress", "opennotcontacted",
        "opencontacted", "closedconverted", "closednotconverted"
    }

    if "email" in properties and properties["email"] not in (None, "") and not _validate_email(properties["email"]):
        _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid email format", "field": "email"})
        return _err("VALIDATION_ERROR", "Invalid email format", field="email")

    if "website" in properties and properties["website"] not in (None, "") and not _validate_uri(properties["website"]):
        _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid website format", "field": "website"})
        return _err("VALIDATION_ERROR", "Invalid website format", field="website")

    if "lifecyclestage" in properties and properties["lifecyclestage"] not in (None, ""):
        if properties["lifecyclestage"] not in lifecyclestage_allowed:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid lifecyclestage", "field": "lifecyclestage"})
            return _err("VALIDATION_ERROR", "Invalid lifecyclestage", field="lifecyclestage")

    if "leadstatus" in properties and properties["leadstatus"] not in (None, ""):
        if properties["leadstatus"] not in leadstatus_allowed:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid leadstatus", "field": "leadstatus"})
            return _err("VALIDATION_ERROR", "Invalid leadstatus", field="leadstatus")

    # Property definitions validation (when definitions exist)
    prop_defs = _load("crm_object_properties.json")
    defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "contacts"]
    if defs:
        defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
        unknown = [k for k in properties.keys() if k not in defs_by_name]
        # Tool schema allows additionalProperties, but portal policy is not modeled -> allow unknown
        # Must still reject writes to archived definitions; create also should respect archived/hidden when policy forbids hidden.
        for k, v in properties.items():
            d = defs_by_name.get(k)
            if not d:
                continue
            if d.get("status") == "archived" or d.get("archived") is True:
                _log("error", {"code": "VALIDATION_ERROR", "message": f"Property '{k}' is archived", "field": k})
                return _err("VALIDATION_ERROR", f"Property '{k}' is archived", field=k)

    # Validate associations payload and references, plus association type definitions
    assoc_types = _load("crm_association_types.json")
    assoc_types_active = {
        (r.get("portal_id"), r.get("from_object_type"), r.get("to_object_type"), r.get("association_category"), r.get("association_type_id"))
        for r in assoc_types
        if r.get("portal_id") == portal_id and r.get("status") == "active"
    }

    objects = _load("crm_objects.json")
    objects_by_hs = {}
    for r in objects:
        if r.get("portal_id") != portal_id:
            continue
        key = (r.get("object_type"), r.get("hubspot_object_id"))
        if all(isinstance(x, str) and x for x in key):
            objects_by_hs[key] = r

    assoc_edges_to_create = []
    if associations:
        if not isinstance(associations, list):
            _log("error", {"code": "VALIDATION_ERROR", "message": "associations must be an array"})
            return _err("VALIDATION_ERROR", "associations must be an array")
        for i, a in enumerate(associations):
            if not isinstance(a, dict):
                _log("error", {"code": "VALIDATION_ERROR", "message": "association entry must be an object", "index": i})
                return _err("VALIDATION_ERROR", "association entry must be an object", index=i)
            to = a.get("to")
            types = a.get("types")
            if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                _log("error", {"code": "VALIDATION_ERROR", "message": "association.to.id is required", "index": i})
                return _err("VALIDATION_ERROR", "association.to.id is required", index=i)
            if not isinstance(types, list) or not types:
                _log("error", {"code": "VALIDATION_ERROR", "message": "association.types must be a non-empty array", "index": i})
                return _err("VALIDATION_ERROR", "association.types must be a non-empty array", index=i)

            # Interpret association target id as HubSpot object id (string) for some object in tenant
            to_obj = None
            # Prefer non-archived objects if multiple (uniqueness constraint should prevent duplicates)
            for ot in ["companies", "deals", "tickets", "calls", "emails", "meetings", "notes", "contacts", "products", "line_items", "quotes", "leads", "tasks", "engagements", "custom"]:
                cand = objects_by_hs.get((ot, to["id"]))
                if cand:
                    to_obj = cand
                    break
            if not to_obj:
                _log("error", {"code": "NOT_FOUND", "message": "Associated object not found", "index": i, "toId": to["id"]})
                return _err("NOT_FOUND", "Associated object not found", index=i, toId=to["id"])

            for j, typ in enumerate(types):
                if not isinstance(typ, dict):
                    _log("error", {"code": "VALIDATION_ERROR", "message": "association type entry must be an object", "index": i, "typeIndex": j})
                    return _err("VALIDATION_ERROR", "association type entry must be an object", index=i, typeIndex=j)
                cat = typ.get("associationCategory")
                atid = typ.get("associationTypeId")
                if not isinstance(cat, str) or not cat:
                    _log("error", {"code": "VALIDATION_ERROR", "message": "associationCategory is required", "index": i, "typeIndex": j})
                    return _err("VALIDATION_ERROR", "associationCategory is required", index=i, typeIndex=j)
                if not isinstance(atid, (int, float)) or int(atid) < 1:
                    _log("error", {"code": "VALIDATION_ERROR", "message": "associationTypeId must be >= 1", "index": i, "typeIndex": j})
                    return _err("VALIDATION_ERROR", "associationTypeId must be >= 1", index=i, typeIndex=j)
                atid_num = int(atid)

                key = (portal_id, "contacts", to_obj.get("object_type"), cat, atid_num)
                if key not in assoc_types_active:
                    _log("error", {"code": "VALIDATION_ERROR", "message": "Association type is not active or not defined", "index": i, "typeIndex": j})
                    return _err("VALIDATION_ERROR", "Association type is not active or not defined", index=i, typeIndex=j)

                assoc_edges_to_create.append({
                    "to_object": to_obj,
                    "association_category": cat,
                    "association_type_id": atid_num
                })

    # Enforce unique(portal_id, object_type, hubspot_object_id)
    # Generate new HubSpot-like id: numeric string greater than any existing for contacts in portal
    max_id = 0
    for r in objects:
        if r.get("portal_id") == portal_id and r.get("object_type") == "contacts":
            hs = r.get("hubspot_object_id")
            if isinstance(hs, str) and hs.isdigit():
                max_id = max(max_id, int(hs))
    new_hs_id = str(max_id + 1 if max_id else 1)

    if (("contacts", new_hs_id) in objects_by_hs):
        _log("error", {"code": "CONFLICT", "message": "Generated hubspot_object_id conflicts"})
        return _err("CONFLICT", "Generated hubspot_object_id conflicts")

    # Create row
    now = _now()
    obj_row = {
        "id": "obj_" + uuid.uuid4().hex,
        "portal_id": portal_id,
        "object_type": "contacts",
        "hubspot_object_id": new_hs_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": dict(properties),
        "properties_version": 1,
        "search_text": _tokenize_search(properties),
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Persist object and associations atomically (best-effort: validate done above, then commit both files)
    associations_rows = _load("crm_associations.json")
    for edge in assoc_edges_to_create:
        to_obj = edge["to_object"]
        if to_obj.get("id") == obj_row["id"]:
            _log("error", {"code": "VALIDATION_ERROR", "message": "from_object_id cannot equal to_object_id"})
            return _err("VALIDATION_ERROR", "from_object_id cannot equal to_object_id")
        # upsert active unique edge
        existing = None
        for ar in associations_rows:
            if ar.get("portal_id") != portal_id:
                continue
            if ar.get("from_object_id") == obj_row["id"] and ar.get("to_object_id") == to_obj.get("id") and ar.get("association_category") == edge["association_category"] and int(ar.get("association_type_id") or 0) == edge["association_type_id"]:
                existing = ar
                break
        if existing:
            # reactivate if archived
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
                existing["updated_at"] = now
            # else already active: idempotent
        else:
            associations_rows.append({
                "id": "asc_" + uuid.uuid4().hex,
                "portal_id": portal_id,
                "from_object_id": obj_row["id"],
                "to_object_id": to_obj.get("id"),
                "from_object_type": "contacts",
                "to_object_type": to_obj.get("object_type"),
                "association_category": edge["association_category"],
                "association_type_id": edge["association_type_id"],
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now
            })

    objects.append(obj_row)
    _save("crm_objects.json", objects)
    _save("crm_associations.json", associations_rows)

    resp = {
        "id": obj_row["hubspot_object_id"],
        "properties": obj_row["properties"],
        "createdAt": obj_row["hubspot_created_at"],
        "updatedAt": obj_row["hubspot_updated_at"],
        "archived": obj_row["archived"]
    }
    _log("success", meta={"object_type": "contacts", "hubspot_object_id": obj_row["hubspot_object_id"]})
    return resp

def crm_update_contact(contactId, properties, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_update_contact"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        for r in props:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        for r in assoc_types:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        for r in subs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    portal_id = _get_portal_id()

    def _log(status, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _validate_email(v):
        if not isinstance(v, str) or not v:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", v) is not None

    def _validate_uri(v):
        if not isinstance(v, str) or not v:
            return False
        try:
            p = urllib.parse.urlparse(v)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _tokenize_search(props):
        parts = []
        for k, v in (props or {}).items():
            if v is None:
                continue
            if isinstance(v, (str, int, float, bool)):
                parts.append(str(v))
        blob = " ".join(parts).lower()
        blob = re.sub(r"[^a-z0-9]+", " ", blob).strip()
        return blob if blob else None

    if not portal_id:
        _log("error", {"code": "UNAUTHORIZED", "message": "No tenant context available"})
        return _err("UNAUTHORIZED", "No tenant context available")

    if not isinstance(contactId, str) or not contactId:
        _log("error", {"code": "VALIDATION_ERROR", "message": "contactId must be a non-empty string"})
        return _err("VALIDATION_ERROR", "contactId must be a non-empty string")

    if not isinstance(properties, dict):
        _log("error", {"code": "VALIDATION_ERROR", "message": "properties must be an object"})
        return _err("VALIDATION_ERROR", "properties must be an object")

    lifecyclestage_allowed = {
        "subscriber", "lead", "marketingqualifiedlead", "salesqualifiedlead",
        "opportunity", "customer", "evangelist", "other"
    }
    leadstatus_allowed = {
        "new", "open", "inprogress", "opennotcontacted",
        "opencontacted", "closedconverted", "closednotconverted"
    }

    if "email" in properties and properties["email"] not in (None, "") and not _validate_email(properties["email"]):
        _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid email format", "field": "email"})
        return _err("VALIDATION_ERROR", "Invalid email format", field="email")

    if "website" in properties and properties["website"] not in (None, "") and not _validate_uri(properties["website"]):
        _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid website format", "field": "website"})
        return _err("VALIDATION_ERROR", "Invalid website format", field="website")

    if "lifecyclestage" in properties and properties["lifecyclestage"] not in (None, ""):
        if properties["lifecyclestage"] not in lifecyclestage_allowed:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid lifecyclestage", "field": "lifecyclestage"})
            return _err("VALIDATION_ERROR", "Invalid lifecyclestage", field="lifecyclestage")

    if "leadstatus" in properties and properties["leadstatus"] not in (None, ""):
        if properties["leadstatus"] not in leadstatus_allowed:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Invalid leadstatus", "field": "leadstatus"})
            return _err("VALIDATION_ERROR", "Invalid leadstatus", field="leadstatus")

    # Validate against property definitions: cannot write archived definitions
    prop_defs = _load("crm_object_properties.json")
    defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "contacts"]
    if defs:
        defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
        for k in properties.keys():
            d = defs_by_name.get(k)
            if d and (d.get("status") == "archived" or d.get("archived") is True):
                _log("error", {"code": "VALIDATION_ERROR", "message": f"Property '{k}' is archived", "field": k})
                return _err("VALIDATION_ERROR", f"Property '{k}' is archived", field=k)

    # Find contact
    objects = _load("crm_objects.json")
    target = None
    for r in objects:
        if r.get("portal_id") == portal_id and r.get("object_type") == "contacts" and r.get("hubspot_object_id") == contactId:
            target = r
            break

    if not target:
        _log("error", {"code": "NOT_FOUND", "message": "Contact not found"})
        return _err("NOT_FOUND", "Contact not found")

    # Apply update
    now = _now()
    if not isinstance(target.get("properties"), dict):
        target["properties"] = {}
    for k, v in properties.items():
        # clearing represented by empty string per business rules: keep as empty string
        target["properties"][k] = v

    pv = target.get("properties_version")
    if not isinstance(pv, int) or pv < 1:
        pv = 1
    target["properties_version"] = pv + 1
    target["updated_at"] = now
    target["hubspot_updated_at"] = now
    target["search_text"] = _tokenize_search(target["properties"])

    _save("crm_objects.json", objects)

    resp = {
        "id": target["hubspot_object_id"],
        "properties": target["properties"],
        "createdAt": target.get("hubspot_created_at"),
        "updatedAt": target.get("hubspot_updated_at"),
        "archived": target.get("archived", False)
    }
    _log("success", meta={"object_type": "contacts", "hubspot_object_id": target["hubspot_object_id"]})
    return resp

def crm_get_contact(contactId, properties=None, associations=None, **_extra):
