        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_get_contact"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        for r in props:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        for r in assoc_types:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        for r in subs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    portal_id = _get_portal_id()

    def _log(status, error=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not portal_id:
        _log("error", {"code": "UNAUTHORIZED", "message": "No tenant context available"})
        return _err("UNAUTHORIZED", "No tenant context available")

    if not isinstance(contactId, str) or not contactId:
        _log("error", {"code": "VALIDATION_ERROR", "message": "contactId must be a non-empty string"})
        return _err("VALIDATION_ERROR", "contactId must be a non-empty string")

    if properties is not None and not isinstance(properties, list):
        _log("error", {"code": "VALIDATION_ERROR", "message": "properties must be an array of strings"})
        return _err("VALIDATION_ERROR", "properties must be an array of strings")
    if properties is not None and any(not isinstance(p, str) for p in properties):
        _log("error", {"code": "VALIDATION_ERROR", "message": "properties must be an array of strings"})
        return _err("VALIDATION_ERROR", "properties must be an array of strings")

    supported_assocs = {"companies", "deals", "tickets", "calls", "emails", "meetings", "notes"}
    if associations is not None:
        if not isinstance(associations, list) or any(not isinstance(a, str) for a in associations):
            _log("error", {"code": "VALIDATION_ERROR", "message": "associations must be an array of strings"})
            return _err("VALIDATION_ERROR", "associations must be an array of strings")
        bad = [a for a in associations if a not in supported_assocs]
        if bad:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Unsupported association requested", "unsupported": bad})
            return _err("VALIDATION_ERROR", "Unsupported association requested", unsupported=bad)

    objects = _load("crm_objects.json")
    contact = None
    for r in objects:
        if r.get("portal_id") == portal_id and r.get("object_type") == "contacts" and r.get("hubspot_object_id") == contactId:
            contact = r
            break

    if not contact:
        _log("error", {"code": "NOT_FOUND", "message": "Contact not found"})
        return _err("NOT_FOUND", "Contact not found")

    if contact.get("status") == "archived" or contact.get("archived") is True:
        # HubSpot get returns archived if asked; this tool doesn't have archived flag; treat as NOT_FOUND in synced subset
        _log("error", {"code": "NOT_FOUND", "message": "Contact not found"})
        return _err("NOT_FOUND", "Contact not found")

    props_out = {}
    stored_props = contact.get("properties") if isinstance(contact.get("properties"), dict) else {}
    if properties is None:
        props_out = dict(stored_props)
    else:
        for p in properties:
            if p in stored_props:
                props_out[p] = stored_props[p]

    resp = {
        "id": contact.get("hubspot_object_id"),
        "properties": props_out,
        "createdAt": contact.get("hubspot_created_at"),
        "updatedAt": contact.get("hubspot_updated_at"),
        "archived": contact.get("archived", False),
    }

    # Associations join
    if associations:
        assocs_rows = _load("crm_associations.json")
        by_internal_id = {o.get("id"): o for o in objects if o.get("portal_id") == portal_id}
        assoc_block = {}
        for atype in associations:
            assoc_ids = []
            for e in assocs_rows:
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                if e.get("from_object_id") != contact.get("id"):
                    continue
                if e.get("to_object_type") != atype:
                    continue
                to_obj = by_internal_id.get(e.get("to_object_id"))
                if not to_obj:
                    continue
                if to_obj.get("status") != "active" or to_obj.get("archived") is True:
                    continue
                assoc_ids.append({"id": to_obj.get("hubspot_object_id")})
            assoc_block[atype] = {"results": assoc_ids}
        resp["associations"] = assoc_block

    _log("success", meta={"object_type": "contacts", "hubspot_object_id": contact.get("hubspot_object_id")})
    return resp

