            # treat as ms epoch
            try:
                return datetime.datetime.utcfromtimestamp(float(x)/1000.0)
            except Exception:
                return None
        if isinstance(x, str) and x:
            s = x
            if s.endswith("Z"):
                s = s[:-1]
            try:
                # fromisoformat supports "YYYY-MM-DD" and "YYYY-MM-DDTHH:MM:SS"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _cmp(prop_val, op, value):
        # HAS_PROPERTY/NOT_HAS_PROPERTY handled outside
        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            if not isinstance(value, str) or not value.strip():
                return None
            token = re.sub(r"[^a-z0-9]+", " ", value.lower()).strip()
            if not token:
                return None
            hay = ""
            if isinstance(prop_val, str):
                hay = prop_val.lower()
            elif prop_val is None:
                hay = ""
            else:
                hay = str(prop_val).lower()
            # token match as word boundary-ish split
            words = set(re.sub(r"[^a-z0-9]+", " ", hay).split())
            ok = token in words
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        if op in ("IN", "NOT_IN"):
            vals = value
            if isinstance(vals, list):
                if len(vals) == 0:
                    return None
                candidates = vals
            else:
                candidates = [vals]
            ok = str(prop_val) in {str(v) for v in candidates}
            return ok if op == "IN" else (not ok)

        if op == "BETWEEN":
            if not isinstance(value, list) or len(value) != 2:
                return None
            a, b = value[0], value[1]
            # compare numbers if possible else datetime else string
            pv_num = _as_number(prop_val)
            a_num = _as_number(a)
            b_num = _as_number(b)
            if pv_num is not None and a_num is not None and b_num is not None:
                lo, hi = (a_num, b_num) if a_num <= b_num else (b_num, a_num)
                return lo <= pv_num <= hi
            pv_dt = _as_datetime(prop_val)
            a_dt = _as_datetime(a)
            b_dt = _as_datetime(b)
            if pv_dt is not None and a_dt is not None and b_dt is not None:
                lo, hi = (a_dt, b_dt) if a_dt <= b_dt else (b_dt, a_dt)
                return lo <= pv_dt <= hi
            # fallback lexical
            pv = "" if prop_val is None else str(prop_val)
            lo, hi = (str(a), str(b)) if str(a) <= str(b) else (str(b), str(a))
            return lo <= pv <= hi

        # Scalar compares
        if value is None and op in ("EQ", "NEQ"):
            ok = (prop_val is None)
            return ok if op == "EQ" else (not ok)

        pv_num = _as_number(prop_val)
        v_num = _as_number(value)
        if pv_num is not None and v_num is not None:
            if op == "EQ": return pv_num == v_num
            if op == "NEQ": return pv_num != v_num
            if op == "LT": return pv_num < v_num
            if op == "LTE": return pv_num <= v_num
            if op == "GT": return pv_num > v_num
            if op == "GTE": return pv_num >= v_num

        pv_dt = _as_datetime(prop_val)
        v_dt = _as_datetime(value)
        if pv_dt is not None and v_dt is not None:
            if op == "EQ": return pv_dt == v_dt
            if op == "NEQ": return pv_dt != v_dt
            if op == "LT": return pv_dt < v_dt
            if op == "LTE": return pv_dt <= v_dt
            if op == "GT": return pv_dt > v_dt
            if op == "GTE": return pv_dt >= v_dt

        pv = "" if prop_val is None else str(prop_val)
        vv = "" if value is None else str(value)
        if op == "EQ": return pv == vv
        if op == "NEQ": return pv != vv
        if op == "LT": return pv < vv
        if op == "LTE": return pv <= vv
        if op == "GT": return pv > vv
        if op == "GTE": return pv >= vv
        return None

    # Validate filterGroups shape and filter operator/value requirements
    for gi, g in enumerate(filterGroups):
        if not isinstance(g, dict):
            _log("error", {"code": "VALIDATION_ERROR", "message": "filterGroups entries must be objects", "index": gi})
            return _err("VALIDATION_ERROR", "filterGroups entries must be objects", index=gi)
        fs = g.get("filters")
        if not isinstance(fs, list) or not fs:
            _log("error", {"code": "VALIDATION_ERROR", "message": "filterGroups.filters must be a non-empty array", "index": gi})
            return _err("VALIDATION_ERROR", "filterGroups.filters must be a non-empty array", index=gi)
        for fi, f in enumerate(fs):
            if not isinstance(f, dict):
                _log("error", {"code": "VALIDATION_ERROR", "message": "filter must be an object", "groupIndex": gi, "filterIndex": fi})
                return _err("VALIDATION_ERROR", "filter must be an object", groupIndex=gi, filterIndex=fi)
            pn = f.get("propertyName")
            op = f.get("operator")
            if not isinstance(pn, str) or not pn:
                _log("error", {"code": "VALIDATION_ERROR", "message": "filter.propertyName is required", "groupIndex": gi, "filterIndex": fi})
                return _err("VALIDATION_ERROR", "filter.propertyName is required", groupIndex=gi, filterIndex=fi)
            if op not in supported_ops:
                _log("error", {"code": "VALIDATION_ERROR", "message": "Unsupported operator", "groupIndex": gi, "filterIndex": fi})
                return _err("VALIDATION_ERROR", "Unsupported operator", groupIndex=gi, filterIndex=fi)
            has_value = "value" in f
            if op in ("HAS_PROPERTY", "NOT_HAS_PROPERTY"):
                # value optional/ignored
                pass
            elif op == "BETWEEN":
                if (not has_value) or (not isinstance(f.get("value"), list)) or len(f.get("value")) != 2:
                    _log("error", {"code": "VALIDATION_ERROR", "message": "BETWEEN requires value as a two-item array", "groupIndex": gi, "filterIndex": fi})
                    return _err("VALIDATION_ERROR", "BETWEEN requires value as a two-item array", groupIndex=gi, filterIndex=fi)
            elif op in ("IN", "NOT_IN"):
                if not has_value:
                    _log("error", {"code": "VALIDATION_ERROR", "message": f"{op} requires a value", "groupIndex": gi, "filterIndex": fi})
                    return _err("VALIDATION_ERROR", f"{op} requires a value", groupIndex=gi, filterIndex=fi)
                v = f.get("value")
                if isinstance(v, list) and len(v) == 0:
                    _log("error", {"code": "VALIDATION_ERROR", "message": f"{op} requires a non-empty array", "groupIndex": gi, "filterIndex": fi})
                    return _err("VALIDATION_ERROR", f"{op} requires a non-empty array", groupIndex=gi, filterIndex=fi)
            else:
                if not has_value:
                    _log("error", {"code": "VALIDATION_ERROR", "message": f"{op} requires value", "groupIndex": gi, "filterIndex": fi})
                    return _err("VALIDATION_ERROR", f"{op} requires value", groupIndex=gi, filterIndex=fi)

    # Load objects and filter tenant + active only
    objs = _load("crm_objects.json")
    candidates = [
        o for o in objs
        if o.get("portal_id") == portal_id and o.get("object_type") == "contacts"
        and not (o.get("archived") is True or o.get("status") == "archived")
    ]

    def _matches(obj):
        props = obj.get("properties") if isinstance(obj.get("properties"), dict) else {}
        search_text = obj.get("search_text") if isinstance(obj.get("search_text"), str) else None

        for g in filterGroups:
            ok_group = True
            for f in g.get("filters", []):
                pn = f.get("propertyName")
                op = f.get("operator")
                val = f.get("value", None)
                if op == "HAS_PROPERTY":
                    cond = pn in props and props.get(pn) not in (None, "")
                elif op == "NOT_HAS_PROPERTY":
                    cond = not (pn in props and props.get(pn) not in (None, ""))
                elif op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN") and pn == "hs_search_text":
                    # allow searching against denormalized field via synthetic property
                    cond = None
                    if not isinstance(val, str) or not val.strip():
                        cond = None
                    else:
                        token = re.sub(r"[^a-z0-9]+", " ", val.lower()).strip()
                        words = set((search_text or "").split())
                        cond = (token in words)
                        if op == "NOT_CONTAINS_TOKEN":
                            cond = not cond
                else:
                    prop_val = props.get(pn)
                    cond = _cmp(prop_val, op, val)
                if cond is None:
                    return False
                if not cond:
                    ok_group = False
                    break
            if ok_group:
                return True
        return False

    matched = [o for o in candidates if _matches(o)]

    # Sorting
    def _sort_key(prop_name, obj):
        props = obj.get("properties") if isinstance(obj.get("properties"), dict) else {}
        v = props.get(prop_name)
        if v is None:
            return (1, "")
        if isinstance(v, (int, float)):
            return (0, float(v))
        return (0, str(v))

    if sorts:
        # apply stable sorts reversed
        for s in reversed(sorts):
            pn = s["propertyName"]
            reverse = (s["direction"] == "DESCENDING")
            matched.sort(key=lambda o, pn=pn: _sort_key(pn, o), reverse=reverse)
    else:
        # default sort by hubspot_object_id numeric if possible
        def _default_key(o):
            hs = o.get("hubspot_object_id")
            if isinstance(hs, str) and hs.isdigit():
                return (0, int(hs))
            return (1, str(hs) if hs is not None else "")
        matched.sort(key=_default_key)

    # Pagination using after cursor as hubspot_object_id of last seen
    start_idx = 0
    if after:
        idx = None
        for i, o in enumerate(matched):
            if str(o.get("hubspot_object_id")) == after:
                idx = i
                break
        if idx is not None:
            start_idx = idx + 1
        else:
            start_idx = 0

    page = matched[start_idx:start_idx + limit_i]
    has_more = (start_idx + limit_i) < len(matched)
    next_after = str(page[-1].get("hubspot_object_id")) if (has_more and page) else None

    results = []
    for o in page:
        stored_props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        if properties is None:
            props_out = dict(stored_props)
        else:
            props_out = {p: stored_props[p] for p in properties if p in stored_props}
        results.append({
            "id": o.get("hubspot_object_id"),
            "properties": props_out,
            "createdAt": o.get("hubspot_created_at"),
            "updatedAt": o.get("hubspot_updated_at"),
            "archived": o.get("archived", False)
        })

    resp = {
        "total": len(matched),
        "results": results,
        "paging": {"next": {"after": next_after}} if has_more else None
    }
    _log("success", meta={"matched": len(matched), "returned": len(results), "has_more": has_more})
    return resp

def crm_batch_create_contacts(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Ambient tenant resolution (portal_id) ---
    crm_objects = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    portal_ids = set()
    for r in crm_objects:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in props_defs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in assoc_types:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in assocs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))

    if not portal_ids:
        return _err("UNAUTHORIZED", "No available portal context for this operation.")
    portal_id = sorted(portal_ids)[0]

    # --- Validation helpers ---
    allowed_lifecyclestage = {"subscriber","lead","marketingqualifiedlead","salesqualifiedlead","opportunity","customer","evangelist","other"}
    allowed_leadstatus = {"new","open","inprogress","opennotcontacted","opencontacted","closedconverted","closednotconverted"}
    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    def _is_obj(x): return isinstance(x, dict)
    def _is_arr(x): return isinstance(x, list)

    def _new_id(prefix, rows):
        # deterministic-ish unique id
        base = int(time.time() * 1000)
        used = {r.get("id") for r in rows if isinstance(r, dict)}
        i = 0
        while True:
            cid = f"{prefix}_{base+i}"
            if cid not in used:
                return cid
            i += 1

    def _validate_properties(p):
        if not _is_obj(p):
            return _err("VALIDATION_ERROR", "properties must be an object.")
        # schema-typed checks for known fields if present
        if "email" in p and p["email"] not in ("", None):
            if not isinstance(p["email"], str) or not email_re.match(p["email"]):
                return _err("VALIDATION_ERROR", "properties.email must be a valid email string.")
        if "website" in p and p["website"] not in ("", None):
            if not isinstance(p["website"], str):
                return _err("VALIDATION_ERROR", "properties.website must be a string.")
        if "lifecyclestage" in p and p["lifecyclestage"] not in ("", None):
            if p["lifecyclestage"] not in allowed_lifecyclestage:
                return _err("VALIDATION_ERROR", "properties.lifecyclestage has an invalid value.")
        if "leadstatus" in p and p["leadstatus"] not in ("", None):
            if p["leadstatus"] not in allowed_leadstatus:
                return _err("VALIDATION_ERROR", "properties.leadstatus has an invalid value.")
        # all values must be JSON-serializable primitives/objects/arrays; allow empty string for clearing
        for k, v in p.items():
            if not isinstance(k, str) or not k:
                return _err("VALIDATION_ERROR", "Property names must be non-empty strings.")
            # no further restriction; HubSpot properties can be stringified
        return None

    # Determine whether property definitions exist for contacts; if they do, validate names
    contact_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "contacts"]
    defs_exist = len(contact_defs) > 0
    def_by_name = {d.get("name"): d for d in contact_defs if isinstance(d.get("name"), str)}
    # Policy: allow additionalProperties (tool schema permits), even if defs exist; but still forbid writes to archived defs.
    def _validate_property_names_against_defs(p):
        if not defs_exist:
            return None
        for name in p.keys():
            d = def_by_name.get(name)
            if d is not None:
                if d.get("status") == "archived" or d.get("archived") is True:
                    return _err("VALIDATION_ERROR", f"Property '{name}' is archived and cannot be written.")
            # unknown properties allowed by tool additionalProperties
        return None

    # Association type validation
    assoc_type_index = {}
    for at in assoc_types:
        if not isinstance(at, dict): 
            continue
        if at.get("portal_id") != portal_id:
            continue
        key = (at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), at.get("association_type_id"))
        assoc_type_index[key] = at

    # Build mapping from hubspot_object_id to internal id per portal/type (for resolving association "to.id")
    by_portal_type_hsid = {}
    for o in crm_objects:
        if not isinstance(o, dict): 
            continue
        if o.get("portal_id") != portal_id:
            continue
        key = (o.get("object_type"), o.get("hubspot_object_id"))
        if key[0] and key[1]:
            by_portal_type_hsid[key] = o

    # --- Input validation ---
    if not isinstance(inputs, list):
        return _err("VALIDATION_ERROR", "inputs must be an array.")

    results = []
    errors = []
    # preflight per item; for atomic-per-item, we stage each item then apply
    staged_new_objects = []
    staged_new_assocs = []

    # precompute unique constraint check for contacts (portal_id, object_type, hubspot_object_id)
    existing_contact_hsids = set()
    for o in crm_objects:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "contacts":
            existing_contact_hsids.add(o.get("hubspot_object_id"))

    def _compute_search_text(props):
        parts = []
        if isinstance(props, dict):
            for k, v in props.items():
                if v is None:
                    continue
                if isinstance(v, (str, int, float, bool)):
                    s = str(v).strip()
                    if s:
                        parts.append(s)
        blob = " ".join(parts)
        return blob[:20000] if blob else None

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        if "properties" not in item:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing required field: properties."}})
            continue

        p = item.get("properties")
        e = _validate_properties(p)
        if e:
            errors.append({"index": idx, "error": e["error"]})
            continue
        e = _validate_property_names_against_defs(p)
        if e:
            errors.append({"index": idx, "error": e["error"]})
            continue

        # generate a new hubspot_object_id as string (simulating HS object id)
        # ensure unique within existing + staged
        candidate = str(int(time.time() * 1000) + idx)
        while candidate in existing_contact_hsids or any(s["hubspot_object_id"] == candidate for s in staged_new_objects):
            candidate = str(int(candidate) + 1)

        # validate associations if present
        assoc_inputs = item.get("associations", [])
        if assoc_inputs is None:
            assoc_inputs = []
        if assoc_inputs != [] and not isinstance(assoc_inputs, list):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array when provided."}})
            continue

        # stage object
        new_internal_id = _new_id("obj", crm_objects + staged_new_objects)
        new_obj = {
            "id": new_internal_id,
            "portal_id": portal_id,
            "object_type": "contacts",
            "hubspot_object_id": candidate,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": p,
            "properties_version": 1,
            "search_text": _compute_search_text(p),
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now
        }

        # stage associations (all-or-nothing for this item)
        item_new_assocs = []
        if assoc_inputs:
            for aidx, a in enumerate(assoc_inputs):
                if not isinstance(a, dict) or "to" not in a or "types" not in a:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each association must include to and types."}})
                    item_new_assocs = None
                    break
                to = a.get("to")
                if not isinstance(to, dict) or "id" not in to or not isinstance(to.get("id"), str) or not to.get("id"):
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.to.id must be a non-empty string."}})
                    item_new_assocs = None
                    break
                types = a.get("types")
                if not isinstance(types, list) or not types:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.types must be a non-empty array."}})
                    item_new_assocs = None
                    break

                # resolve to object by hubspot_object_id across any object_type? Here types determine from/to types.
                # For contacts batch create, from is contacts; to type determined per assoc type definition.
                to_hs_id = to.get("id")

                for tidx, t in enumerate(types):
                    if not isinstance(t, dict):
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each association type must be an object."}})
                        item_new_assocs = None
                        break
                    cat = t.get("associationCategory")
                    atid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationCategory must be a string."}})
                        item_new_assocs = None
                        break
                    if not (isinstance(atid, int) or isinstance(atid, float)) or int(atid) != atid or atid < 1:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationTypeId must be a number >= 1."}})
                        item_new_assocs = None
                        break
                    atid = int(atid)

                    # find an active association type that matches from=contacts and any to_object_type with this category+id
                    # we must choose the one that makes the request satisfiable; so search for a matching type with an existing 'to' object.
                    chosen = None
                    chosen_to_obj = None
                    for at in assoc_types:
                        if not isinstance(at, dict): 
                            continue
                        if at.get("portal_id") != portal_id:
                            continue
                        if at.get("from_object_type") != "contacts":
                            continue
                        if at.get("association_category") != cat:
                            continue
                        if int(at.get("association_type_id", -1)) != atid:
                            continue
                        if at.get("status") != "active":
                            continue
                        to_type = at.get("to_object_type")
                        cand_to_obj = by_portal_type_hsid.get((to_type, to_hs_id))
                        if cand_to_obj and cand_to_obj.get("status") == "active" and cand_to_obj.get("archived") is False:
                            chosen = at
                            chosen_to_obj = cand_to_obj
                            break
                    if chosen is None:
                        # Could be because to object not found or assoc type not defined
                        # Distinguish: if there exists active assoc type but to object missing, report NOT_FOUND for object; else VALIDATION_ERROR
                        any_type = None
                        for at in assoc_types:
                            if not isinstance(at, dict): 
                                continue
                            if at.get("portal_id") != portal_id:
                                continue
                            if at.get("from_object_type") == "contacts" and at.get("association_category") == cat and int(at.get("association_type_id", -1)) == atid and at.get("status") == "active":
                                any_type = at
                                break
                        if any_type is None:
                            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Association type is not defined or not active for this portal."}})
                        else:
                            errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "Associated object not found for provided to.id."}})
                        item_new_assocs = None
                        break

                    edge = {
                        "id": _new_id("assoc", assocs + staged_new_assocs + item_new_assocs),
                        "portal_id": portal_id,
                        "from_object_id": new_internal_id,
                        "to_object_id": chosen_to_obj["id"],
                        "from_object_type": "contacts",
                        "to_object_type": chosen["to_object_type"],
                        "association_category": cat,
                        "association_type_id": atid,
                        "status": "active",
                        "archived": False,
                        "created_at": now,
                        "updated_at": now
                    }
                    item_new_assocs.append(edge)
                if item_new_assocs is None:
                    break
            if item_new_assocs is None:
                continue  # item failed; do not stage object either
        staged_new_objects.append(new_obj)
        staged_new_assocs.extend(item_new_assocs)
        results.append({
            "id": new_obj["hubspot_object_id"],
            "properties": new_obj["properties"],
            "createdAt": new_obj["hubspot_created_at"],
            "updatedAt": new_obj["hubspot_updated_at"],
            "archived": new_obj["archived"]
        })

    # Apply writes
    if staged_new_objects:
        crm_objects.extend(staged_new_objects)
        assocs.extend(staged_new_assocs)
        _save("crm_objects.json", crm_objects)
        _save("crm_associations.json", assocs)

    # envelope similar to HubSpot batch: results + errors
    resp = {
        "status": "COMPLETE",
        "results": results,
        "numErrors": len(errors),
        "errors": errors
    }
    # If no successes and there are errors, still return envelope (HubSpot style)
    # If empty inputs, return empty successful envelope
    latency_ms = int((time.time() - t0) * 1000)
    resp["meta"] = {"portalId": portal_id, "latency_ms": latency_ms}
    return resp

def crm_batch_update_contacts(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_batch_update_contacts"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(inputs, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be an array.")
    now = _iso_now()

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(prop_defs, list): prop_defs = []

    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    allowed_lifecyclestage = {"subscriber","lead","marketingqualifiedlead","salesqualifiedlead","opportunity","customer","evangelist","other"}
    allowed_leadstatus = {"new","open","inprogress","opennotcontacted","opencontacted","closedconverted","closednotconverted"}

    # Build defs per portal for contacts
    defs_by_portal = {}
    for d in prop_defs:
        if not isinstance(d, dict): 
            continue
        if d.get("object_type") != "contacts":
            continue
        pid = d.get("portal_id")
        name = d.get("name")
        if not isinstance(pid, str) or not pid or not isinstance(name, str) or not name:
            continue
        defs_by_portal.setdefault(pid, {})[name] = d

    def _find_contact(pid, cid):
        for i, r in enumerate(objs):
            if not isinstance(r, dict): 
                continue
            if r.get("portal_id") != pid: 
                continue
            if r.get("object_type") != "contacts": 
                continue
            if str(r.get("hubspot_object_id")) == cid or str(r.get("id")) == cid:
                return i, r
        return None, None

    def _validate_props(pid, props):
        if not isinstance(props, dict):
            return _err("VALIDATION_ERROR", "properties must be an object.")
        defs = defs_by_portal.get(pid) or {}
        defs_exist = len(defs) > 0
        for k, v in props.items():
            # schema allows additionalProperties, so unknown allowed when defs exist? enforce only archived/hidden rules
            if defs_exist and k in defs:
                d = defs[k]
                if d.get("status") == "archived" or d.get("archived") is True:
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be written.")
                if d.get("hidden") is True:
                    # portal policy unknown; be permissive (do not reject), per audit guidance
                    pass
            # Format checks from tool schema
            if k == "email" and v not in ("", None):
                if not isinstance(v, str) or not email_re.match(v):
                    return _err("VALIDATION_ERROR", "properties.email must be a valid email string.")
            if k == "lifecyclestage" and v not in ("", None):
                if not isinstance(v, str) or v not in allowed_lifecyclestage:
                    return _err("VALIDATION_ERROR", "properties.lifecyclestage has an invalid value.")
            if k == "leadstatus" and v not in ("", None):
                if not isinstance(v, str) or v not in allowed_leadstatus:
                    return _err("VALIDATION_ERROR", "properties.leadstatus has an invalid value.")
            if k in ("website",) and v not in ("", None):
                if not isinstance(v, str) or not (v.startswith("http://") or v.startswith("https://")):
                    return _err("VALIDATION_ERROR", "properties.website must be a valid uri string.")
        return None

    # Per-item atomic update with per-item errors; apply updates and then save once.
    results = []
    any_success = False
    touched_portal = None

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            results.append({"index": idx, "error": _err("VALIDATION_ERROR", "Each input must be an object.", index=idx)["error"]})
            continue
        cid = item.get("id")
        props = item.get("properties")
        if not isinstance(cid, str) or not cid.strip():
            results.append({"id": cid, "error": _err("VALIDATION_ERROR", "Each input requires id as a non-empty string.", index=idx)["error"]})
            continue
        if not isinstance(props, dict):
            results.append({"id": cid, "error": _err("VALIDATION_ERROR", "Each input requires properties as an object.", index=idx)["error"]})
            continue

        # Resolve a portal where contact exists
        found = None
        for pid in sorted(set(r.get("portal_id") for r in objs if isinstance(r, dict) and isinstance(r.get("portal_id"), str) and r.get("portal_id"))):
            oi, row = _find_contact(pid, cid)
            if row is not None:
                found = (pid, oi, row)
                break
        if not found:
            results.append({"id": cid, "error": _err("NOT_FOUND", "Contact not found.", id=cid)["error"]})
            continue

        pid, oi, row = found
        touched_portal = touched_portal or pid
        if row.get("status") == "archived" or row.get("archived") is True:
            results.append({"id": cid, "error": _err("CONFLICT", "Contact is archived and cannot be updated.", id=cid)["error"]})
            continue

        verr = _validate_props(pid, props)
        if verr:
            results.append({"id": cid, "error": verr["error"]})
            continue

        # Apply mutation
        new_row = dict(row)
        existing_props = new_row.get("properties")
        if not isinstance(existing_props, dict):
            existing_props = {}
        merged = dict(existing_props)
        for k, v in props.items():
            # clearing represented by empty string
            merged[k] = v
        new_row["properties"] = merged
        new_row["updated_at"] = now
        new_row["hubspot_updated_at"] = now
        try:
            pv = int(new_row.get("properties_version") or 1)
        except Exception:
            pv = 1
        new_row["properties_version"] = max(1, pv + 1)

        objs[oi] = new_row
        any_success = True
        results.append({
            "id": new_row.get("hubspot_object_id"),
            "properties": new_row.get("properties", {}),
            "updatedAt": new_row.get("hubspot_updated_at") or new_row.get("updated_at"),
        })

    if any_success:
        _save("crm_objects.json", objs)
        _log("success", portal_id=touched_portal)
    else:
        _log("error", portal_id=touched_portal, error_code="NOT_FOUND")

    return {"results": results}

def crm_get_contact_properties(archived=None, properties=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    defs = _load("crm_object_properties.json")
    portal_ids = {r.get("portal_id") for r in defs if isinstance(r, dict) and r.get("portal_id")}
    if not portal_ids:
        # still authorized if portal can be inferred from objects (schema read should work)
        objs = _load("crm_objects.json")
        portal_ids = {r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")}
    if not portal_ids:
        return _err("UNAUTHORIZED", "No available portal context for this operation.")
    portal_id = sorted(portal_ids)[0]

    if archived is not None and not isinstance(archived, bool):
        return _err("VALIDATION_ERROR", "archived must be a boolean when provided.")

    if properties is not None:
        if not isinstance(properties, list):
            return _err("VALIDATION_ERROR", "properties must be an array of strings when provided.")
        for p in properties:
            if not isinstance(p, str) or not p:
                return _err("VALIDATION_ERROR", "properties must contain only non-empty strings.")

    want_archived = bool(archived) if archived is not None else False

    rows = []
    for r in defs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("object_type") != "contacts":
            continue
        if not want_archived and (r.get("archived") is True or r.get("status") == "archived"):
            continue
        if properties is not None and r.get("name") not in set(properties):
            continue
        # map to tool-ish casing
        rows.append({
            "name": r.get("name"),
            "label": r.get("label"),
            "type": r.get("type"),
            "fieldType": r.get("field_type"),
            "groupName": r.get("group_name"),
            "description": r.get("description"),
            "options": r.get("options") if isinstance(r.get("options"), list) else [],
            "displayOrder": r.get("display_order"),
            "hasUniqueValue": r.get("has_unique_value"),
            "hidden": r.get("hidden"),
            "formField": r.get("form_field"),
            "archived": r.get("archived"),
            "createdAt": r.get("created_at"),
            "updatedAt": r.get("updated_at")
        })

    # full list, not paged
    return {
        "results": rows,
        "total": len(rows),
        "meta": {"portalId": portal_id, "latency_ms": int((time.time() - t0) * 1000)}
    }

def crm_create_contact_property(name, label, type, fieldType, groupName, description=None, options=None, displayOrder=None, hasUniqueValue=None, hidden=None, formField=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_type = {"string","number","date","datetime","enumeration","bool"}
    allowed_field = {"text","textarea","select","radio","checkbox","number","date","file"}

    # basic validation
    if not isinstance(name, str) or not name:
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(label, str) or not label:
        return _err("VALIDATION_ERROR", "label must be a non-empty string.")
    if type not in allowed_type:
        return _err("VALIDATION_ERROR", "type is not supported.")
    if fieldType not in allowed_field:
        return _err("VALIDATION_ERROR", "fieldType is not supported.")
    if not isinstance(groupName, str) or not groupName:
        return _err("VALIDATION_ERROR", "groupName must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string when provided.")
    if displayOrder is not None and not (isinstance(displayOrder, int) or isinstance(displayOrder, float)):
        return _err("VALIDATION_ERROR", "displayOrder must be a number when provided.")
    if hasUniqueValue is not None and not isinstance(hasUniqueValue, bool):
        return _err("VALIDATION_ERROR", "hasUniqueValue must be a boolean when provided.")
    if hidden is not None and not isinstance(hidden, bool):
        return _err("VALIDATION_ERROR", "hidden must be a boolean when provided.")
    if formField is not None and not isinstance(formField, bool):
        return _err("VALIDATION_ERROR", "formField must be a boolean when provided.")

    # options validation
    if options is None:
        options = []
    if not isinstance(options, list):
        return _err("VALIDATION_ERROR", "options must be an array when provided.")
    if type != "enumeration" and len(options) != 0:
        return _err("VALIDATION_ERROR", "options must be empty unless type is 'enumeration'.")
    if type == "enumeration":
        seen_vals = set()
        for i, opt in enumerate(options):
            if not isinstance(opt, dict):
                return _err("VALIDATION_ERROR", f"options[{i}] must be an object.")
            if "label" not in opt or "value" not in opt:
                return _err("VALIDATION_ERROR", f"options[{i}] must include label and value.")
            if not isinstance(opt.get("label"), str) or not opt.get("label"):
                return _err("VALIDATION_ERROR", f"options[{i}].label must be a non-empty string.")
            if not isinstance(opt.get("value"), str) or not opt.get("value"):
                return _err("VALIDATION_ERROR", f"options[{i}].value must be a non-empty string.")
            if opt.get("description") is not None and not isinstance(opt.get("description"), str):
                return _err("VALIDATION_ERROR", f"options[{i}].description must be a string when provided.")
            if opt.get("displayOrder") is not None and not (isinstance(opt.get("displayOrder"), int) or isinstance(opt.get("displayOrder"), float)):
                return _err("VALIDATION_ERROR", f"options[{i}].displayOrder must be a number when provided.")
            if opt.get("hidden") is not None and not isinstance(opt.get("hidden"), bool):
                return _err("VALIDATION_ERROR", f"options[{i}].hidden must be a boolean when provided.")
            if opt["value"] in seen_vals:
                return _err("VALIDATION_ERROR", f"Duplicate option value '{opt['value']}'.")
            seen_vals.add(opt["value"])

    defs = _load("crm_object_properties.json")
    objs = _load("crm_objects.json")

    portal_ids = {r.get("portal_id") for r in defs if isinstance(r, dict) and r.get("portal_id")}
    if not portal_ids:
        portal_ids = {r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")}
    if not portal_ids:
        return _err("UNAUTHORIZED", "No available portal context for this operation.")
    portal_id = sorted(portal_ids)[0]

    # conflict check unique(portal_id, object_type, name)
    for r in defs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") == portal_id and r.get("object_type") == "contacts" and r.get("name") == name:
            return _err("CONFLICT", "A contact property with this name already exists.")

    # generate id
    used = {r.get("id") for r in defs if isinstance(r, dict)}
    base = int(time.time() * 1000)
    pid = f"prop_{base}"
    j = 0
    while pid in used:
        j += 1
        pid = f"prop_{base+j}"

    row = {
        "id": pid,
        "portal_id": portal_id,
        "object_type": "contacts",
        "name": name,
        "label": label,
        "type": type,
        "field_type": fieldType,
        "group_name": groupName,
        "description": description if description is not None else None,
        "display_order": displayOrder if displayOrder is not None else None,
        "has_unique_value": bool(hasUniqueValue) if hasUniqueValue is not None else False,
        "hidden": bool(hidden) if hidden is not None else False,
        "form_field": bool(formField) if formField is not None else False,
        "options": options if type == "enumeration" else [],
        "archived": False,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # constraints sanity
    if row["type"] != "enumeration" and len(row["options"]) != 0:
        return _err("VALIDATION_ERROR", "Invalid options for non-enumeration type.")
    if row["type"] == "enumeration" and not isinstance(row["options"], list):
        return _err("VALIDATION_ERROR", "options must be an array for enumeration type.")

    defs.append(row)
    _save("crm_object_properties.json", defs)

    return {
        "result": {
            "name": row["name"],
            "label": row["label"],
            "type": row["type"],
            "fieldType": row["field_type"],
            "groupName": row["group_name"],
            "description": row["description"],
            "options": row["options"],
            "displayOrder": row["display_order"],
            "hasUniqueValue": row["has_unique_value"],
            "hidden": row["hidden"],
            "formField": row["form_field"],
            "archived": row["archived"],
            "createdAt": row["created_at"],
            "updatedAt": row["updated_at"]
        },
        "meta": {"portalId": portal_id, "latency_ms": int((time.time() - t0) * 1000)}
    }

def crm_create_lead(properties, associations=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Determine portal_id context (ambient auth): choose any portal with schema present
    objs = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    portal_ids = set()
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in props_defs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in assoc_types:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    portal_id = next(iter(sorted(portal_ids))) if portal_ids else None

    def _log(status, error_code=None):
        # Best-effort request logging: if no collection exists, skip.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": now,
                    "endpoint": "crm_create_lead",
                    "portal_id": portal_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    if not portal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")

    # Validate input types
    if not isinstance(properties, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`properties` must be an object.")
    if associations is not None and not isinstance(associations, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`associations` must be an array when provided.")

    # Tool-schema constraints & formats/enums
    leadstatus_enum = {"new", "open", "in_progress", "qualified", "unqualified", "converted", "lost"}
    rating_enum = {"hot", "warm", "cold"}

    def _is_email(s):
        if not isinstance(s, str):
            return False
        # simple email check
        return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s.strip()))

    def _is_uri(s):
        if not isinstance(s, str):
            return False
        try:
            u = urllib.parse.urlparse(s.strip())
            return bool(u.scheme and u.netloc)
        except Exception:
            return False

    # Validate property values per tool schema
    if "email" in properties and properties["email"] != "" and not _is_email(properties["email"]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid email format for `email`.")
    if "website" in properties and properties["website"] != "" and not _is_uri(properties["website"]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid uri format for `website`.")
    if "leadstatus" in properties and properties["leadstatus"] != "" and properties["leadstatus"] not in leadstatus_enum:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid enum value for `leadstatus`.", allowed=list(sorted(leadstatus_enum)))
    if "rating" in properties and properties["rating"] != "" and properties["rating"] not in rating_enum:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid enum value for `rating`.", allowed=list(sorted(rating_enum)))
    for num_key in ("annualrevenue", "numberofemployees"):
        if num_key in properties and properties[num_key] != "" and not isinstance(properties[num_key], (int, float)):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`{num_key}` must be a number.")

    # Business rule: validate property names against definitions when definitions exist
    lead_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "leads"]
    defs_by_name = {d.get("name"): d for d in lead_defs if d.get("name")}
    if lead_defs:
        for k in properties.keys():
            if k not in defs_by_name:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Unknown property `{k}` for leads.")
            d = defs_by_name[k]
            if d.get("status") == "archived" or d.get("archived") is True:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property `{k}` is archived and cannot be written.")
            if d.get("hidden") is True:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property `{k}` is hidden and cannot be written.")

        # Enforce unique properties if any have_unique_value=true
        unique_props = [d.get("name") for d in lead_defs if d.get("has_unique_value") is True and d.get("name")]
        for up in unique_props:
            if up in properties and properties[up] != "":
                for o in objs:
                    if not isinstance(o, dict):
                        continue
                    if o.get("portal_id") != portal_id or o.get("object_type") != "leads":
                        continue
                    if o.get("status") == "archived" or o.get("archived") is True:
                        continue
                    pv = (o.get("properties") or {}).get(up)
                    if pv == properties[up]:
                        _log("error", "CONFLICT")
                        return _err("CONFLICT", f"Duplicate value for unique property `{up}`.")

    # Validate associations payload and association type existence+active
    assoc_creates = []
    if associations is not None:
        # Determine from/to object types by resolving target ids (tool uses hubspot_object_id as id)
        assoc_type_index = {}
        for at in assoc_types:
            if not isinstance(at, dict):
                continue
            if at.get("portal_id") != portal_id:
                continue
            key = (at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), at.get("association_type_id"))
            assoc_type_index[key] = at

        allowed_to_types = {"companies", "contacts", "deals", "tickets", "products", "line_items", "quotes", "custom", "leads",
                            "meetings", "notes", "tasks", "calls", "emails", "engagements"}

        for i, a in enumerate(associations):
            if not isinstance(a, dict):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Association at index {i} must be an object.")
            to = a.get("to")
            types = a.get("types")
            if not isinstance(to, dict) or "id" not in to or not isinstance(to.get("id"), str) or not to.get("id"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Association.to.id is required at index {i}.")
            if not isinstance(types, list) or len(types) == 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Association.types must be a non-empty array at index {i}.")

            # Resolve target object by hubspot_object_id within portal (any type)
            target = None
            for o in objs:
                if not isinstance(o, dict):
                    continue
                if o.get("portal_id") == portal_id and o.get("hubspot_object_id") == to["id"]:
                    target = o
                    break
            if not target or target.get("status") == "archived" or target.get("archived") is True:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", f"Association target object `{to['id']}` not found or archived.", index=i)

            to_type = target.get("object_type")
            if to_type not in allowed_to_types:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Unsupported association target object type `{to_type}`.", index=i)

            for t in types:
                if not isinstance(t, dict):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Association.types entry must be an object at index {i}.")
                cat = t.get("associationCategory")
                tid = t.get("associationTypeId")
                if not isinstance(cat, str) or not cat:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"associationCategory is required at index {i}.")
                if not isinstance(tid, (int, float)) or int(tid) < 1:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"associationTypeId must be a number >= 1 at index {i}.")
                tid = int(tid)

                key = ("leads", to_type, cat, tid)
                atrow = assoc_type_index.get(key)
                if not atrow or atrow.get("status") != "active":
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Association type is missing or not active for portal.", details={
                        "from_object_type": "leads",
                        "to_object_type": to_type,
                        "associationCategory": cat,
                        "associationTypeId": tid
                    })
                assoc_creates.append((target, cat, tid))

    # Create lead object
    # Enforce unique(portal_id, object_type, hubspot_object_id)
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    hubspot_object_id = str(int(time.time() * 1000))  # simple monotonic-ish string id
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "leads" and o.get("hubspot_object_id") == hubspot_object_id:
            hubspot_object_id = str(int(time.time() * 1000) + 1)
            break

    lead_row = {
        "id": _new_id("obj"),
        "portal_id": portal_id,
        "object_type": "leads",
        "hubspot_object_id": hubspot_object_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": dict(properties),
        "properties_version": 1,
        "search_text": None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": None,
        "hubspot_updated_at": None
    }

    # Persist lead + associations (as separate edges)
    objs.append(lead_row)

    # Create edges, upserting reactivation if identical archived exists
    for (target, cat, tid) in assoc_creates:
        # unique(portal_id, from_object_id, to_object_id, association_category, association_type_id)
        existing = None
        for e in assocs:
            if not isinstance(e, dict):
                continue
            if e.get("portal_id") == portal_id and e.get("from_object_id") == lead_row["id"] and e.get("to_object_id") == target.get("id") and e.get("association_category") == cat and int(e.get("association_type_id") or 0) == tid:
                existing = e
                break
        if existing:
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
                existing["updated_at"] = now
        else:
            assocs.append({
                "id": _new_id("asc"),
                "portal_id": portal_id,
                "from_object_id": lead_row["id"],
                "to_object_id": target.get("id"),
                "from_object_type": "leads",
                "to_object_type": target.get("object_type"),
                "association_category": cat,
                "association_type_id": tid,
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now
            })

    _save("crm_objects.json", objs)
    if assoc_creates:
        _save("crm_associations.json", assocs)

    _log("success")
    return {"id": lead_row["hubspot_object_id"], "object": lead_row}

def crm_update_lead(leadId, properties, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")

    portal_ids = set()
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in props_defs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    portal_id = next(iter(sorted(portal_ids))) if portal_ids else None

    def _log(status, error_code=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": now,
                    "endpoint": "crm_update_lead",
                    "portal_id": portal_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    if not portal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")
    if not isinstance(leadId, str) or not leadId:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`leadId` must be a non-empty string.")
    if not isinstance(properties, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`properties` must be an object.")

    # Find lead by hubspot_object_id
    lead = None
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "leads" and o.get("hubspot_object_id") == leadId:
            lead = o
            break
    if not lead or lead.get("status") == "archived" or lead.get("archived") is True:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Lead not found.")

    # Tool-schema validations
    leadstatus_enum = {"new", "open", "in_progress", "qualified", "unqualified", "converted", "lost"}
    rating_enum = {"hot", "warm", "cold"}

    def _is_email(s):
        if not isinstance(s, str):
            return False
        return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s.strip()))

    def _is_uri(s):
        if not isinstance(s, str):
            return False
        try:
            u = urllib.parse.urlparse(s.strip())
            return bool(u.scheme and u.netloc)
        except Exception:
            return False

    if "email" in properties and properties["email"] != "" and not _is_email(properties["email"]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid email format for `email`.")
    if "website" in properties and properties["website"] != "" and not _is_uri(properties["website"]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid uri format for `website`.")
    if "leadstatus" in properties and properties["leadstatus"] != "" and properties["leadstatus"] not in leadstatus_enum:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid enum value for `leadstatus`.", allowed=list(sorted(leadstatus_enum)))
    if "rating" in properties and properties["rating"] != "" and properties["rating"] not in rating_enum:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid enum value for `rating`.", allowed=list(sorted(rating_enum)))
    for num_key in ("annualrevenue", "numberofemployees"):
        if num_key in properties and properties[num_key] != "" and not isinstance(properties[num_key], (int, float)):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"`{num_key}` must be a number.")

    # Business rule: validate property names against definitions when definitions exist;
    # reject writes to archived/hidden definitions.
    lead_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "leads"]
    defs_by_name = {d.get("name"): d for d in lead_defs if d.get("name")}
    if lead_defs:
        for k in properties.keys():
            if k not in defs_by_name:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Unknown property `{k}` for leads.")
            d = defs_by_name[k]
            if d.get("status") == "archived" or d.get("archived") is True:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property `{k}` is archived and cannot be written.")
            if d.get("hidden") is True:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property `{k}` is hidden and cannot be written.")

        # Enforce uniqueness for has_unique_value fields if changed to non-empty
        unique_props = [d.get("name") for d in lead_defs if d.get("has_unique_value") is True and d.get("name")]
        for up in unique_props:
            if up in properties and properties[up] != "":
                for o in objs:
                    if not isinstance(o, dict):
                        continue
                    if o.get("portal_id") != portal_id or o.get("object_type") != "leads":
                        continue
                    if o.get("id") == lead.get("id"):
                        continue
                    if o.get("status") == "archived" or o.get("archived") is True:
                        continue
                    if (o.get("properties") or {}).get(up) == properties[up]:
                        _log("error", "CONFLICT")
                        return _err("CONFLICT", f"Duplicate value for unique property `{up}`.")

    # Apply updates (empty string means clearing)
    cur_props = lead.get("properties") or {}
    if not isinstance(cur_props, dict):
        cur_props = {}
    for k, v in properties.items():
        cur_props[k] = v

    lead["properties"] = cur_props
    lead["properties_version"] = int(lead.get("properties_version") or 1) + 1
    lead["updated_at"] = now
    lead["hubspot_updated_at"] = now

    _save("crm_objects.json", objs)
    _log("success")
    return {"id": lead.get("hubspot_object_id"), "object": lead}

def crm_get_lead(leadId, properties=None, associations=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    assocs = _load("crm_associations.json")

    portal_ids = set()
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    portal_id = next(iter(sorted(portal_ids))) if portal_ids else None

    def _log(status, error_code=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": now,
                    "endpoint": "crm_get_lead",
                    "portal_id": portal_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    if not portal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")
    if not isinstance(leadId, str) or not leadId:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`leadId` must be a non-empty string.")
    if properties is not None and (not isinstance(properties, list) or any(not isinstance(p, str) for p in properties)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`properties` must be an array of strings when provided.")
    if associations is not None and (not isinstance(associations, list) or any(not isinstance(a, str) for a in associations)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`associations` must be an array of strings when provided.")

    # Validate associations enum
    allowed_assoc = {"companies", "contacts", "deals", "notes", "tasks"}
    if associations is not None:
        for a in associations:
            if a not in allowed_assoc:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Unsupported association name `{a}`.", allowed=list(sorted(allowed_assoc)))

    # Find lead
    lead = None
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "leads" and o.get("hubspot_object_id") == leadId:
            lead = o
            break
    if not lead or lead.get("status") == "archived" or lead.get("archived") is True:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Lead not found.")

    # Project properties
    obj_out = dict(lead)
    props = obj_out.get("properties") or {}
    if not isinstance(props, dict):
        props = {}
    if properties is not None:
        obj_out["properties"] = {k: props.get(k) for k in properties}
    else:
        obj_out["properties"] = props

    # Resolve associations (active, non-archived only)
    assoc_out = {}
    if associations:
        # Build index of objects by internal id
        obj_by_id = {}
        for o in objs:
            if isinstance(o, dict) and o.get("portal_id") == portal_id:
                obj_by_id[o.get("id")] = o

        for to_type in associations:
            ids = []
            for e in assocs:
                if not isinstance(e, dict):
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                if e.get("from_object_id") != lead.get("id"):
                    continue
                if e.get("to_object_type") != to_type:
                    continue
                tgt = obj_by_id.get(e.get("to_object_id"))
                if not tgt:
                    continue
                if tgt.get("status") != "active" or tgt.get("archived") is True:
                    continue
                ids.append(tgt.get("hubspot_object_id"))
            assoc_out[to_type] = {"results": [{"id": i} for i in ids]}

    resp = {"id": lead.get("hubspot_object_id"), "object": obj_out}
    if associations:
        resp["associations"] = assoc_out

    _log("success")
    return resp

