                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save(fname, logs)
                break

    if not portal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")

    # Validate inputs
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`filterGroups` must be a non-empty array.")
    if properties is not None and (not isinstance(properties, list) or any(not isinstance(p, str) for p in properties)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`properties` must be an array of strings when provided.")
    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or int(limit) != limit or int(limit) < 1 or int(limit) > 100:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 100.")
    limit = int(limit)

    if after is not None and not isinstance(after, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`after` must be a string when provided.")
    if sorts is not None:
        if not isinstance(sorts, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`sorts` must be an array when provided.")
        for s in sorts:
            if not isinstance(s, dict) or "propertyName" not in s or "direction" not in s:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each sort must include `propertyName` and `direction`.")
            if s["direction"] not in ("ASCENDING", "DESCENDING"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid sort direction.", allowed=["ASCENDING", "DESCENDING"])
            if not isinstance(s["propertyName"], str) or not s["propertyName"]:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Sort `propertyName` must be a non-empty string.")

    # Property name validation against definitions when they exist
    lead_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "leads"]
    defs_by_name = {d.get("name"): d for d in lead_defs if d.get("name")}
    if lead_defs:
        # validate filter property names exist
        for gi, g in enumerate(filterGroups):
            if not isinstance(g, dict) or "filters" not in g or not isinstance(g.get("filters"), list):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"filterGroups[{gi}].filters must be an array.")
            for fi, f in enumerate(g["filters"]):
                if not isinstance(f, dict) or "propertyName" not in f or "operator" not in f:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Malformed filter at filterGroups[{gi}].filters[{fi}].")
                pn = f.get("propertyName")
                if pn not in defs_by_name and pn not in ("hs_object_id",):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Invalid propertyName `{pn}` for leads.")
        # validate requested properties exist (if provided)
        if properties is not None:
            for pn in properties:
                if pn not in defs_by_name and pn not in ("hs_object_id",):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Invalid requested property `{pn}` for leads.")

    supported_ops = {"EQ", "NEQ", "LT", "LTE", "GT", "GTE", "BETWEEN", "IN", "NOT_IN",
                     "HAS_PROPERTY", "NOT_HAS_PROPERTY", "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"}

    def _coerce_num(x):
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str) and x.strip() != "":
            try:
                return float(x.strip())
            except ValueError:
                return None
        return None

    def _tokenize(v):
        if v is None:
            return []
        if not isinstance(v, str):
            v = str(v)
        return [t for t in re_split.split(v.lower()) if t]

    import re
    re_split = re.compile(r"[^a-z0-9]+")

    def _get_prop(obj, name):
        if name == "hs_object_id":
            return obj.get("hubspot_object_id")
        props = obj.get("properties") or {}
        if not isinstance(props, dict):
            return None
        return props.get(name)

    def _eval_filter(obj, flt):
        pn = flt.get("propertyName")
        op = flt.get("operator")
        val = flt.get("value", None)
        if op not in supported_ops:
            return None, _err("VALIDATION_ERROR", f"Unsupported operator `{op}`.")
        pv = _get_prop(obj, pn)

        if op == "HAS_PROPERTY":
            return (pv is not None and pv != ""), None
        if op == "NOT_HAS_PROPERTY":
            return (pv is None or pv == ""), None

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            if val is None or (not isinstance(val, str) and not isinstance(val, (int, float))):
                return None, _err("VALIDATION_ERROR", f"Operator `{op}` requires a scalar `value`.")
            hay = obj.get("search_text")
            if not isinstance(hay, str):
                # fallback to properties concatenation
                p = obj.get("properties") or {}
                if isinstance(p, dict):
                    hay = " ".join([str(x) for x in p.values() if x not in (None, "")])
                else:
                    hay = ""
            needle = str(val).lower()
            found = needle in _tokenize(hay)
            return ((found and op == "CONTAINS_TOKEN") or ((not found) and op == "NOT_CONTAINS_TOKEN")), None

        if op == "BETWEEN":
            if not isinstance(val, list) or len(val) != 2:
                return None, _err("VALIDATION_ERROR", "BETWEEN requires a two-value array in `value`.")
            a = _coerce_num(val[0])
            b = _coerce_num(val[1])
            x = _coerce_num(pv)
            if a is None or b is None or x is None:
                return False, None
            lo, hi = (a, b) if a <= b else (b, a)
            return (lo <= x <= hi), None

        if op in ("IN", "NOT_IN"):
            if isinstance(val, list):
                if len(val) == 0:
                    return None, _err("VALIDATION_ERROR", f"{op} requires a non-empty array or scalar `value`.")
                vals = val
            else:
                vals = [val]
            # string compare or numeric compare if possible
            if pv is None:
                in_set = False
            else:
                # allow both numeric and string match
                pv_num = _coerce_num(pv)
                in_set = False
                for vv in vals:
                    if pv == vv:
                        in_set = True
                        break
                    if pv_num is not None:
                        vv_num = _coerce_num(vv)
                        if vv_num is not None and pv_num == vv_num:
                            in_set = True
                            break
                    if isinstance(pv, str) and isinstance(vv, str) and pv == vv:
                        in_set = True
                        break
            return (in_set if op == "IN" else (not in_set)), None

        # Comparisons
        if val is None:
            return None, _err("VALIDATION_ERROR", f"Operator `{op}` requires `value`.")
        # try numeric
        pv_num = _coerce_num(pv)
        val_num = _coerce_num(val)
        if pv_num is not None and val_num is not None:
            a, b = pv_num, val_num
        else:
            a, b = ("" if pv is None else str(pv)), str(val)

        if op == "EQ":
            return (a == b), None
        if op == "NEQ":
            return (a != b), None
        if op == "LT":
            return (a < b), None
        if op == "LTE":
            return (a <= b), None
        if op == "GT":
            return (a > b), None
        if op == "GTE":
            return (a >= b), None

        return None, _err("VALIDATION_ERROR", f"Unsupported operator `{op}`.")

    # Gather active leads for portal (exclude archived)
    lead_rows = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("portal_id") != portal_id or o.get("object_type") != "leads":
            continue
        if o.get("status") == "archived" or o.get("archived") is True:
            continue
        lead_rows.append(o)

    # Apply filterGroups: OR across groups, AND within group
    def _matches(obj):
        for g in filterGroups:
            if not isinstance(g, dict) or not isinstance(g.get("filters"), list):
                return None, _err("VALIDATION_ERROR", "Malformed filterGroups entry.")
            ok = True
            for flt in g["filters"]:
                if not isinstance(flt, dict):
                    return None, _err("VALIDATION_ERROR", "Malformed filter object.")
                res, err = _eval_filter(obj, flt)
                if err:
                    return None, err
                if not res:
                    ok = False
                    break
            if ok:
                return True, None
        return False, None

    filtered = []
    for o in lead_rows:
        m, err = _matches(o)
        if err:
            _log("error", err["error"]["code"])
            return err
        if m:
            filtered.append(o)

    # Sorting
    if not sorts:
        # default by updated_at desc then hubspot_object_id
        def _key(o):
            return (o.get("updated_at") or "", o.get("hubspot_object_id") or "")
        filtered.sort(key=_key, reverse=True)
    else:
        # apply in order
        def _sort_key(o):
            keys = []
            for s in sorts:
                pn = s["propertyName"]
                v = (o.get("properties") or {}).get(pn)
                if pn == "hs_object_id":
                    v = o.get("hubspot_object_id")
                keys.append(v)
            return tuple(keys)

        # For mixed directions, stable sort from last to first
        data = filtered[:]
        for s in reversed(sorts):
            pn = s["propertyName"]
            rev = (s["direction"] == "DESCENDING")

            def _k(o, pn=pn):
                if pn == "hs_object_id":
                    v = o.get("hubspot_object_id")
                else:
                    v = (o.get("properties") or {}).get(pn)
                # normalize None for comparability
                if v is None:
                    return ""
                return v
            data.sort(key=_k, reverse=rev)
        filtered = data

    # Cursor pagination: 'after' is base64 of integer offset
    offset = 0
    if after:
        try:
            raw = base64.urlsafe_b64decode(after.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw.split(":", 1)[1])
            else:
                offset = int(raw)
            if offset < 0:
                offset = 0
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid `after` cursor.")
    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=") if has_more else None

    # Project properties
    results = []
    for o in page:
        out = {"id": o.get("hubspot_object_id")}
        if properties is None:
            out["properties"] = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        else:
            p = o.get("properties") if isinstance(o.get("properties"), dict) else {}
            out["properties"] = {k: p.get(k) for k in properties}
        out["createdAt"] = o.get("hubspot_created_at") or o.get("created_at")
        out["updatedAt"] = o.get("hubspot_updated_at") or o.get("updated_at")
        results.append(out)

    resp = {
        "total": total,
        "results": results,
        "paging": {"next": {"after": next_cursor}} if has_more else None,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

    _log("success")
    return resp

def crm_batch_create_leads(inputs, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Ambient auth: choose a portal_id that can serve the request (any existing portal in store)
    objs = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    portal_ids = set()
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in props_defs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in assoc_types:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in assocs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))

    if not portal_ids:
        # No tenant context exists at all
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No portal context available to authorize this request.", latency_ms=latency_ms)

    portal_id = sorted(portal_ids)[0]

    # Basic validation
    if not isinstance(inputs, list):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "`inputs` must be an array.", latency_ms=latency_ms)

    # Helpers
    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    def _is_uri(s):
        if not isinstance(s, str):
            return False
        # minimal offline URI check
        return s.startswith("http://") or s.startswith("https://")

    allowed_leadstatus = {"new", "open", "in_progress", "qualified", "unqualified", "converted", "lost"}
    allowed_rating = {"hot", "warm", "cold"}

    # property definitions for leads in this portal
    lead_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "leads"]
    defs_by_name = {d.get("name"): d for d in lead_defs if isinstance(d.get("name"), str)}
    definitions_exist = len(defs_by_name) > 0

    def _validate_prop_value(k, v):
        # Tool schema validation for known fields (format/enums/types)
        if k == "email":
            if not isinstance(v, str) or not email_re.match(v):
                return "email must be a valid email string"
        elif k in ("firstname", "lastname", "phone", "company", "jobtitle", "leadsource", "industry", "address", "city", "state", "zip", "country", "notes"):
            if not isinstance(v, str):
                return f"{k} must be a string"
        elif k == "leadstatus":
            if not isinstance(v, str) or v not in allowed_leadstatus:
                return "leadstatus must be one of: " + ", ".join(sorted(allowed_leadstatus))
        elif k == "annualrevenue":
            if not isinstance(v, (int, float)) or isinstance(v, bool):
                return "annualrevenue must be a number"
        elif k == "numberofemployees":
            if not isinstance(v, (int, float)) or isinstance(v, bool):
                return "numberofemployees must be a number"
        elif k == "rating":
            if not isinstance(v, str) or v not in allowed_rating:
                return "rating must be one of: " + ", ".join(sorted(allowed_rating))
        elif k == "website":
            if not isinstance(v, str) or not _is_uri(v):
                return "website must be a valid uri string (http/https)"
        else:
            # additionalProperties allowed by tool schema; do not validate type here
            pass
        return None

    # Association type lookup: active only
    active_assoc_type_keys = set()
    for t in assoc_types:
        if not isinstance(t, dict):
            continue
        if t.get("portal_id") != portal_id:
            continue
        if t.get("status") != "active":
            continue
        key = (t.get("from_object_type"), t.get("to_object_type"), t.get("association_category"), t.get("association_type_id"))
        active_assoc_type_keys.add(key)

    # Map hubspot_object_id -> internal id for portal/type
    obj_index = {}
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("portal_id") != portal_id:
            continue
        ot = o.get("object_type")
        hid = o.get("hubspot_object_id")
        if isinstance(ot, str) and isinstance(hid, str):
            obj_index[(ot, hid)] = o

    # Unique constraint for objects: (portal_id, object_type, hubspot_object_id)
    existing_lead_hubspot_ids = set()
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "leads" and isinstance(o.get("hubspot_object_id"), str):
            existing_lead_hubspot_ids.add(o.get("hubspot_object_id"))

    def _new_internal_id(prefix):
        # internal id convention: <prefix>_<uuid4hex>
        return f"{prefix}_{uuid.uuid4().hex}"

    def _next_hubspot_object_id():
        # generate a numeric-ish string not present for leads in this portal
        max_n = 0
        for s in existing_lead_hubspot_ids:
            try:
                n = int(s)
                if n > max_n:
                    max_n = n
            except Exception:
                continue
        return str(max_n + 1)

    def _compute_search_text(properties):
        parts = []
        if isinstance(properties, dict):
            for _, v in properties.items():
                if isinstance(v, str) and v.strip():
                    parts.append(v.strip())
                elif isinstance(v, (int, float)) and not isinstance(v, bool):
                    parts.append(str(v))
        blob = " ".join(parts).strip()
        return blob if blob else None

    # Validate each input and stage mutations (atomic per item)
    results = []
    staged_new_objs = []
    staged_new_assocs = []
    any_error = False

    # Pre-load associations list for uniqueness checks
    assoc_by_key = {}
    for e in assocs:
        if not isinstance(e, dict):
            continue
        if e.get("portal_id") != portal_id:
            continue
        k = (e.get("from_object_id"), e.get("to_object_id"), e.get("association_category"), e.get("association_type_id"))
        assoc_by_key[k] = e

    # We need internal leads being created to also be target of association? Not in tool schema; only outgoing from created lead.
    # For referenced "to.id", interpret as hubspot object id (string) and resolve across all object types in portal.
    def _resolve_to_object(hubspot_id):
        if not isinstance(hubspot_id, str) or not hubspot_id:
            return None
        # Find a unique match across types by hubspot_object_id in this portal
        matches = []
        for o in objs:
            if not isinstance(o, dict):
                continue
            if o.get("portal_id") != portal_id:
                continue
            if o.get("hubspot_object_id") == hubspot_id:
                matches.append(o)
        if len(matches) == 1:
            return matches[0]
        # ambiguous or not found -> treat as not found
        return None

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            any_error = True
            results.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        if "properties" not in item or not isinstance(item.get("properties"), dict):
            any_error = True
            results.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Missing required field `properties` (object)."}})
            continue

        properties = item.get("properties") or {}
        associations_in = item.get("associations")
        if associations_in is not None and not isinstance(associations_in, list):
            any_error = True
            results.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "`associations` must be an array when provided."}})
            continue

        # Validate properties against definitions when they exist
        prop_errors = []
        for k, v in properties.items():
            if not isinstance(k, str) or not k:
                prop_errors.append("Property names must be non-empty strings")
                continue
            # format/enums/types for known keys
            msg = _validate_prop_value(k, v)
            if msg:
                prop_errors.append(msg)
                continue

            if definitions_exist:
                d = defs_by_name.get(k)
                if d is None:
                    # allow additionalProperties by tool schema; policy unknown -> allow
                    continue
                # reject archived definitions
                if d.get("status") == "archived" or d.get("archived") is True:
                    prop_errors.append(f"Property `{k}` is archived and cannot be written.")
                # hidden policy unknown -> allow; but if hidden==True and we had strict policy we'd reject
        if prop_errors:
            any_error = True
            results.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "; ".join(prop_errors)}})
            continue

        # Stage object create
        new_hsid = _next_hubspot_object_id()
        existing_lead_hubspot_ids.add(new_hsid)

        new_obj = {
            "id": _new_internal_id("obj"),
            "portal_id": portal_id,
            "object_type": "leads",
            "hubspot_object_id": new_hsid,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(properties),
            "properties_version": 1,
            "search_text": _compute_search_text(properties),
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now
        }

        # Validate and stage associations for this item (atomic with this object)
        item_new_assocs = []
        if associations_in:
            for aidx, a in enumerate(associations_in):
                if not isinstance(a, dict):
                    prop_errors.append("Each association must be an object")
                    continue
                to = a.get("to")
                types = a.get("types")
                if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                    prop_errors.append("Association `to.id` must be a non-empty string")
                    continue
                if not isinstance(types, list) or len(types) == 0:
                    prop_errors.append("Association `types` must be a non-empty array")
                    continue

                to_obj = _resolve_to_object(to.get("id"))
                if to_obj is None:
                    # referenced object not found (or ambiguous)
                    prop_errors.append(f"Associated object with id `{to.get('id')}` was not found")
                    continue

                for tidx, t in enumerate(types):
                    if not isinstance(t, dict):
                        prop_errors.append("Association type entries must be objects")
                        continue
                    cat = t.get("associationCategory")
                    atid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat:
                        prop_errors.append("associationCategory must be a non-empty string")
                        continue
                    if not isinstance(atid, (int, float)) or isinstance(atid, bool) or int(atid) != atid or atid < 1:
                        prop_errors.append("associationTypeId must be a positive integer")
                        continue
                    atid = int(atid)

                    key = ("leads", to_obj.get("object_type"), cat, atid)
                    if key not in active_assoc_type_keys:
                        prop_errors.append(f"Association type not found or inactive for leads -> {to_obj.get('object_type')} ({cat}, {atid})")
                        continue

                    if new_obj["id"] == to_obj.get("id"):
                        prop_errors.append("from_object_id must not equal to_object_id")
                        continue

                    assoc_key = (new_obj["id"], to_obj.get("id"), cat, atid)
                    existing = assoc_by_key.get(assoc_key)
                    if existing:
                        # upsert active: if archived, reactivate; if active, idempotent no-op
                        if existing.get("status") == "archived" or existing.get("archived") is True:
                            item_new_assocs.append(("reactivate", existing))
                        else:
                            item_new_assocs.append(("noop", existing))
                    else:
                        edge = {
                            "id": _new_internal_id("asc"),
                            "portal_id": portal_id,
                            "from_object_id": new_obj["id"],
                            "to_object_id": to_obj.get("id"),
                            "from_object_type": "leads",
                            "to_object_type": to_obj.get("object_type"),
                            "association_category": cat,
                            "association_type_id": atid,
                            "status": "active",
                            "archived": False,
                            "created_at": now,
                            "updated_at": now
                        }
                        item_new_assocs.append(("create", edge))

        if prop_errors:
            any_error = True
            results.append({"index": idx, "status": "error", "error": {"code": "NOT_FOUND" if any("was not found" in e for e in prop_errors) else "VALIDATION_ERROR", "message": "; ".join(prop_errors)}})
            continue

        staged_new_objs.append((idx, new_obj))
        staged_new_assocs.append((idx, item_new_assocs))
        results.append({"index": idx, "status": "created", "id": new_obj["hubspot_object_id"], "record": new_obj})

    # Persist staged changes (only for successful items)
    if staged_new_objs:
        for _, o in staged_new_objs:
            objs.append(o)

        # apply association changes
        if staged_new_assocs:
            for _, changes in staged_new_assocs:
                for action, payload in changes:
                    if action == "create":
                        assocs.append(payload)
                        assoc_by_key[(payload["from_object_id"], payload["to_object_id"], payload["association_category"], payload["association_type_id"])] = payload
                    elif action == "reactivate":
                        payload["status"] = "active"
                        payload["archived"] = False
                        payload["updated_at"] = now
                    elif action == "noop":
                        pass

        _save("crm_objects.json", objs)
        _save("crm_associations.json", assocs)

    latency_ms = int((time.time() - t0) * 1000)
    # HubSpot batch envelope-like response
    return {
        "portal_id": portal_id,
        "object_type": "leads",
        "completed_at": now,
        "results": results,
        "summary": {
            "requested": len(inputs),
            "created": sum(1 for r in results if r.get("status") == "created"),
            "errors": sum(1 for r in results if r.get("status") == "error")
        },
        "latency_ms": latency_ms
    }

def crm_batch_update_leads(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_batch_update_leads"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(inputs, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`inputs` must be an array.")

    now = _iso_now()
    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(prop_defs, list): prop_defs = []

    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    allowed_leadstatus = {"new", "open", "in_progress", "qualified", "unqualified", "converted", "lost"}
    allowed_rating = {"hot", "warm", "cold"}

    defs_by_portal = {}
    for d in prop_defs:
        if not isinstance(d, dict):
            continue
        if d.get("object_type") != "leads":
            continue
        pid = d.get("portal_id")
        name = d.get("name")
        if not isinstance(pid, str) or not pid or not isinstance(name, str) or not name:
            continue
        defs_by_portal.setdefault(pid, {})[name] = d

    def _find_lead(pid, lid):
        for i, r in enumerate(objs):
            if not isinstance(r, dict): 
                continue
            if r.get("portal_id") != pid:
                continue
            if r.get("object_type") != "leads":
                continue
            if str(r.get("hubspot_object_id")) == lid or str(r.get("id")) == lid:
                return i, r
        return None, None

    def _is_uri(s):
        return isinstance(s, str) and (s.startswith("http://") or s.startswith("https://"))

    def _validate_props(pid, props):
        if not isinstance(props, dict):
            return _err("VALIDATION_ERROR", "properties must be an object.")
        defs = defs_by_portal.get(pid) or {}
        defs_exist = len(defs) > 0
        for k, v in props.items():
            if defs_exist and k in defs:
                d = defs[k]
                if d.get("status") == "archived" or d.get("archived") is True:
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be written.")
                if d.get("hidden") is True:
                    pass
            if v in ("", None):
                continue
            if k == "email":
                if not isinstance(v, str) or not email_re.match(v):
                    return _err("VALIDATION_ERROR", "email must be a valid email string")
            elif k in ("firstname", "lastname", "phone", "company", "jobtitle", "leadsource", "industry", "address", "city", "state", "zip", "country", "notes"):
                if not isinstance(v, str):
                    return _err("VALIDATION_ERROR", f"{k} must be a string")
            elif k == "leadstatus":
                if not isinstance(v, str) or v not in allowed_leadstatus:
                    return _err("VALIDATION_ERROR", "leadstatus has an invalid value")
            elif k == "rating":
                if not isinstance(v, str) or v not in allowed_rating:
                    return _err("VALIDATION_ERROR", "rating has an invalid value")
            elif k in ("annualrevenue", "numberofemployees"):
                if not isinstance(v, (int, float)):
                    return _err("VALIDATION_ERROR", f"{k} must be a number")
            elif k == "website":
                if not _is_uri(v):
                    return _err("VALIDATION_ERROR", "website must be a valid uri string")
        return None

    portal_ids = sorted(set(r.get("portal_id") for r in objs if isinstance(r, dict) and isinstance(r.get("portal_id"), str) and r.get("portal_id")))
    results = []
    any_success = False
    touched_portal = None

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            results.append({"index": idx, "error": _err("VALIDATION_ERROR", "Each input must be an object.", index=idx)["error"]})
            continue
        lid = item.get("id")
        props = item.get("properties")
        if not isinstance(lid, str) or not lid.strip():
            results.append({"id": lid, "error": _err("VALIDATION_ERROR", "Each input requires id as a non-empty string.", index=idx)["error"]})
            continue
        if not isinstance(props, dict):
            results.append({"id": lid, "error": _err("VALIDATION_ERROR", "Each input requires properties as an object.", index=idx)["error"]})
            continue

        found = None
        for pid in portal_ids:
            oi, row = _find_lead(pid, lid)
            if row is not None:
                found = (pid, oi, row)
                break
        if not found:
            results.append({"id": lid, "error": _err("NOT_FOUND", "Lead not found.", id=lid)["error"]})
            continue

        pid, oi, row = found
        touched_portal = touched_portal or pid
        if row.get("status") == "archived" or row.get("archived") is True:
            results.append({"id": lid, "error": _err("CONFLICT", "Lead is archived and cannot be updated.", id=lid)["error"]})
            continue

        verr = _validate_props(pid, props)
        if verr:
            results.append({"id": lid, "error": verr["error"]})
            continue

        new_row = dict(row)
        existing_props = new_row.get("properties")
        if not isinstance(existing_props, dict):
            existing_props = {}
        merged = dict(existing_props)
        for k, v in props.items():
            merged[k] = v
        new_row["properties"] = merged
        new_row["updated_at"] = now
        new_row["hubspot_updated_at"] = now
        try:
            pv = int(new_row.get("properties_version") or 1)
        except Exception:
            pv = 1
        new_row["properties_version"] = max(1, pv + 1)

        objs[oi] = new_row
        any_success = True
        results.append({
            "id": new_row.get("hubspot_object_id"),
            "properties": new_row.get("properties", {}),
            "updatedAt": new_row.get("hubspot_updated_at") or new_row.get("updated_at"),
        })

    if any_success:
        _save("crm_objects.json", objs)
        _log("success", portal_id=touched_portal)
    else:
        _log("error", portal_id=touched_portal, error_code="NOT_FOUND")

    return {"results": results}

def crm_get_lead_properties(archived=None, properties=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    defs = _load("crm_object_properties.json")
    objs = _load("crm_objects.json")

    portal_ids = set()
    for r in defs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_ids.add(r.get("portal_id"))
    if not portal_ids:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No portal context available to authorize this request.", latency_ms=latency_ms)
    portal_id = sorted(portal_ids)[0]

    if archived is not None and not isinstance(archived, bool):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "`archived` must be a boolean when provided.", latency_ms=latency_ms)

    if properties is not None:
        if not isinstance(properties, list) or any(not isinstance(x, str) for x in properties):
            latency_ms = int((time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "`properties` must be an array of strings when provided.", latency_ms=latency_ms)
        prop_set = set(properties)
    else:
        prop_set = None

    include_archived = bool(archived) if archived is not None else False

    out = []
    for d in defs:
        if not isinstance(d, dict):
            continue
        if d.get("portal_id") != portal_id:
            continue
        if d.get("object_type") != "leads":
            continue
        if not include_archived and (d.get("archived") is True or d.get("status") == "archived"):
            continue
        if prop_set is not None and d.get("name") not in prop_set:
            continue

        # Tool schema uses camelCase for some fields; return in a vendor-ish shape
        out.append({
            "name": d.get("name"),
            "label": d.get("label"),
            "type": d.get("type"),
            "fieldType": d.get("field_type"),
            "groupName": d.get("group_name"),
            "description": d.get("description"),
            "options": d.get("options", []),
            "displayOrder": d.get("display_order"),
            "hasUniqueValue": d.get("has_unique_value"),
            "hidden": d.get("hidden"),
            "formField": d.get("form_field"),
            "archived": d.get("archived"),
            "createdAt": d.get("created_at"),
            "updatedAt": d.get("updated_at")
        })

    # stable sort: group then display_order then name
    def _sort_key(x):
        disp = x.get("displayOrder")
        if not isinstance(disp, (int, float)) or isinstance(disp, bool):
            disp = 1e18
        return (str(x.get("groupName") or ""), float(disp), str(x.get("name") or ""))
    out.sort(key=_sort_key)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "portal_id": portal_id,
        "object_type": "leads",
        "archived": include_archived,
        "total": len(out),
        "results": out,
        "retrieved_at": now,
        "latency_ms": latency_ms
    }

