    # Validate required fields
    if not isinstance(name, str) or not name:
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string.")
    if not isinstance(label, str) or not label:
        return _err("VALIDATION_ERROR", "`label` must be a non-empty string.")
    if not isinstance(type, str):
        return _err("VALIDATION_ERROR", "`type` must be a string.")
    if not isinstance(fieldType, str):
        return _err("VALIDATION_ERROR", "`fieldType` must be a string.")
    if not isinstance(groupName, str) or not groupName:
        return _err("VALIDATION_ERROR", "`groupName` must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "`description` must be a string when provided.")
    if displayOrder is not None and (not isinstance(displayOrder, (int, float)) or isinstance(displayOrder, bool)):
        return _err("VALIDATION_ERROR", "`displayOrder` must be a number when provided.")
    if hasUniqueValue is not None and not isinstance(hasUniqueValue, bool):
        return _err("VALIDATION_ERROR", "`hasUniqueValue` must be a boolean when provided.")
    if hidden is not None and not isinstance(hidden, bool):
        return _err("VALIDATION_ERROR", "`hidden` must be a boolean when provided.")
    if formField is not None and not isinstance(formField, bool):
        return _err("VALIDATION_ERROR", "`formField` must be a boolean when provided.")

    allowed_type = {"string", "number", "date", "datetime", "enumeration", "bool"}
    allowed_field_type = {"text", "textarea", "select", "radio", "checkbox", "number", "date", "file"}
    if type not in allowed_type:
        return _err("VALIDATION_ERROR", f"`type` must be one of: {', '.join(sorted(allowed_type))}.")
    if fieldType not in allowed_field_type:
        return _err("VALIDATION_ERROR", f"`fieldType` must be one of: {', '.join(sorted(allowed_field_type))}.")

    if options is None:
        options = []
    if not isinstance(options, list):
        return _err("VALIDATION_ERROR", "`options` must be an array when provided.")
    for i, opt in enumerate(options):
        if not isinstance(opt, dict):
            return _err("VALIDATION_ERROR", f"options[{i}] must be an object.")
        if "label" not in opt or "value" not in opt:
            return _err("VALIDATION_ERROR", f"options[{i}] must include `label` and `value`.")
        if not isinstance(opt.get("label"), str) or not opt.get("label"):
            return _err("VALIDATION_ERROR", f"options[{i}].label must be a non-empty string.")
        if not isinstance(opt.get("value"), str) or not opt.get("value"):
            return _err("VALIDATION_ERROR", f"options[{i}].value must be a non-empty string.")
