        if "displayOrder" in opt and opt.get("displayOrder") is not None and (not isinstance(opt.get("displayOrder"), (int, float)) or isinstance(opt.get("displayOrder"), bool)):
            return _err("VALIDATION_ERROR", f"options[{i}].displayOrder must be a number when provided.")
        if "hidden" in opt and opt.get("hidden") is not None and not isinstance(opt.get("hidden"), bool):
            return _err("VALIDATION_ERROR", f"options[{i}].hidden must be a boolean when provided.")

    # Enforce options constraints
    if type != "enumeration" and len(options) != 0:
        return _err("VALIDATION_ERROR", "Non-enumeration properties must have an empty options array.")
    if type == "enumeration":
        # schema allows empty; keep as-is
        pass

    # Unique constraint: unique(portal_id, object_type, name)
    for d in defs:
        if not isinstance(d, dict):
            continue
        if d.get("portal_id") == portal_id and d.get("object_type") == "leads" and d.get("name") == name:
