def meetings_list(after=None, limit=None, createdAfter=None, createdBefore=None, properties=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "meetings_list"
    status_code = "ok"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a datetime string")
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid datetime string")

    def _audit(portal_id, status, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_portal():
        objs = _load("crm_objects.json")
        for r in objs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        props = _load("crm_object_properties.json")
        for r in props:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        assoc_types = _load("crm_association_types.json")
        for r in assoc_types:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        subs = _load("communications_subscriptions.json")
        for r in subs:
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                return pid
        return None

    portal_id = _resolve_portal()
    if not portal_id:
        status_code = "UNAUTHORIZED"
        _audit(portal_id, status_code, {"reason": "no portal context available"})
        return _err("UNAUTHORIZED", "No authorized portal context available for this request")

    # Validation
    if limit is None:
        limit = 100
    if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "limit must be a number")
    limit = int(limit)
    if limit < 1 or limit > 100:
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    if after is not None and (not isinstance(after, str) or not after.strip()):
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "after must be a non-empty string when provided")

    ca, e = _parse_dt(createdAfter, "createdAfter")
    if e:
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return e
    cb, e = _parse_dt(createdBefore, "createdBefore")
    if e:
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return e
    if ca and cb and ca > cb:
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str)) for p in properties):
            status_code = "VALIDATION_ERROR"
            _audit(portal_id, status_code)
            return _err("VALIDATION_ERROR", "properties must be an array of strings")

    # Rate/quota enforcement (if a quota config exists)
    quotas = _load("quotas.json")
    # Expected shapes (best-effort):
    # [{"portal_id":"...", "scope":"meetings", "requests_per_minute":60, "requests_per_day":10000}] etc.
    if isinstance(quotas, list) and quotas:
        cfg = None
        for q in quotas:
            if q.get("portal_id") == portal_id and (q.get("scope") in (None, "meetings", "crm", "all")):
                cfg = q
                break
        if cfg:
            logs = _load("request_logs.json")
            now = datetime.datetime.now(datetime.timezone.utc)
            rpm = cfg.get("requests_per_minute")
            rpd = cfg.get("requests_per_day")
            if isinstance(rpm, (int, float)) and rpm > 0:
                window_start = (now - datetime.timedelta(minutes=1)).isoformat()
                recent = [r for r in logs if r.get("portal_id") == portal_id and r.get("timestamp", "") >= window_start]
                if len(recent) >= int(rpm):
                    status_code = "RATE_LIMIT"
                    _audit(portal_id, status_code)
                    return _err("RATE_LIMIT", "Rate limit exceeded")
            if isinstance(rpd, (int, float)) and rpd > 0:
                day_start = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
                today = [r for r in logs if r.get("portal_id") == portal_id and r.get("timestamp", "") >= day_start]
                if len(today) >= int(rpd):
                    status_code = "QUOTA_EXCEEDED"
                    _audit(portal_id, status_code)
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Fetch + filter (exclude archived by default)
    objs = _load("crm_objects.json")
    rows = [r for r in objs if r.get("portal_id") == portal_id and r.get("object_type") == "meetings" and r.get("archived") is False and r.get("status") == "active"]

    def _parse_row_created_at(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    if ca or cb:
        filtered = []
        for r in rows:
            dt = _parse_row_created_at(r)
            if dt is None:
                continue
            if ca and dt < ca:
                continue
            if cb and dt > cb:
                continue
            filtered.append(r)
        rows = filtered

    # sort stable by created_at then id for deterministic pagination
    def _sort_key(r):
        dt = _parse_row_created_at(r)
        # None sorts first; but these should be filtered out above if ca/cb used. Keep stable anyway.
        return (dt.isoformat() if dt else "", r.get("hubspot_object_id") or r.get("id") or "")
    rows.sort(key=_sort_key)

    start_idx = 0
    if after is not None:
        try:
            start_idx = int(after)
            if start_idx < 0:
                raise ValueError()
        except ValueError:
            status_code = "VALIDATION_ERROR"
            _audit(portal_id, status_code)
            return _err("VALIDATION_ERROR", "after must be a valid cursor string")

    page = rows[start_idx:start_idx + limit]
    next_cursor = None
    has_more = False
    if start_idx + limit < len(rows):
        has_more = True
        next_cursor = str(start_idx + limit)

    def _project(r):
        out_props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        if properties is not None:
            out_props = {k: out_props.get(k, "") for k in properties}
        return {
            "id": r.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
            "archived": bool(r.get("archived")),
        }

    resp = {
        "results": [_project(r) for r in page],
        "paging": {
            "next": {"after": next_cursor} if has_more else None
        },
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    _audit(portal_id, status_code, {"returned": len(page), "total": len(rows), "after": after, "next": next_cursor})
    return resp

