    assoc_edges = _load("crm_associations.json")

    # Build lookup by hubspot_object_id within portal
    hs_lookup = {}
    for r in objs:
        if r.get("portal_id") == portal_id:
            hs_id = r.get("hubspot_object_id")
            if isinstance(hs_id, str):
                hs_lookup[(r.get("object_type"), hs_id)] = r

    def _assoc_type_exists(from_type, to_type, cat, tid):
        for at in assoc_types:
            if at.get("portal_id") != portal_id:
                continue
            if at.get("status") != "active":
                continue
            if at.get("from_object_type") == from_type and at.get("to_object_type") == to_type and at.get("association_category") == cat and int(at.get("association_type_id")) == int(tid):
                return True
        return False

    planned_edges = []
    if associations:
        for a in associations:
            to_hs_id = a["to"]["id"]
            # "to" might be any object type; must exist
            to_obj = None
            # Try each possible type match
            for ot in ["contacts", "companies", "deals", "tickets", "products", "line_items", "quotes", "custom", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements"]:
                cand = hs_lookup.get((ot, to_hs_id))
                if cand and cand.get("status") == "active" and cand.get("archived") is False:
                    to_obj = cand
                    break
            if not to_obj:
                status_code = "NOT_FOUND"
                _audit(portal_id, status_code, {"missing_to_object_hubspot_id": to_hs_id})
                return _err("NOT_FOUND", "Association target object not found", toObjectId=to_hs_id)

            for t in a["types"]:
                cat = t["associationCategory"]
                tid = int(t["associationTypeId"])
                if not _assoc_type_exists("meetings", to_obj.get("object_type"), cat, tid):
