                    _audit(portal_id, status_code, {"invalid_association_type": {"from": "meetings", "to": to_obj.get("object_type"), "associationCategory": cat, "associationTypeId": tid}})
                    return _err("VALIDATION_ERROR", "Association type does not exist or is not active", fromObjectType="meetings", toObjectType=to_obj.get("object_type"), associationCategory=cat, associationTypeId=tid)
                planned_edges.append((to_obj, cat, tid))

    # Create meeting row
    # Generate new ids
    new_hs_id = str(int(time.time() * 1000))  # deterministic-ish monotonic
    existing_hs = {r.get("hubspot_object_id") for r in objs if r.get("portal_id") == portal_id and r.get("object_type") == "meetings"}
    while new_hs_id in existing_hs:
        new_hs_id = str(int(new_hs_id) + 1)

    new_id = "obj_" + uuid.uuid4().hex
    now = _now()
    new_row = {
        "id": new_id,
        "portal_id": portal_id,
        "object_type": "meetings",
        "hubspot_object_id": new_hs_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": dict(properties),
        "properties_version": 1,
        "search_text": None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Enforce uniqueness (portal_id, object_type, hubspot_object_id)
    for r in objs:
        if r.get("portal_id") == portal_id and r.get("object_type") == "meetings" and r.get("hubspot_object_id") == new_hs_id:
            status_code = "CONFLICT"
            _audit(portal_id, status_code)
            return _err("CONFLICT", "Meeting id conflict")

    # Apply writes atomically (as much as possible in file store)
    objs.append(new_row)

    # Upsert/reactivate planned edges
    for (to_obj, cat, tid) in planned_edges:
        # unique constraint: (portal_id, from_object_id, to_object_id, association_category, association_type_id)
        found = None
        for e in assoc_edges:
            if e.get("portal_id") == portal_id and e.get("from_object_id") == new_id and e.get("to_object_id") == to_obj.get("id") and e.get("association_category") == cat and int(e.get("association_type_id")) == int(tid):
                found = e
                break
        if found:
            # upsert active (reactivate if archived)
            found["status"] = "active"
            found["archived"] = False
            found["updated_at"] = now
        else:
            assoc_edges.append({
                "id": "assoc_" + uuid.uuid4().hex,
                "portal_id": portal_id,
                "from_object_id": new_id,
                "to_object_id": to_obj.get("id"),
                "from_object_type": "meetings",
                "to_object_type": to_obj.get("object_type"),
                "association_category": cat,
                "association_type_id": int(tid),
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now,
            })

    _save("crm_objects.json", objs)
    if planned_edges:
        _save("crm_associations.json", assoc_edges)

    # Response in HubSpot-like shape
    resp_props = new_row["properties"]
    result = {
        "id": new_row["hubspot_object_id"],
        "properties": resp_props,
        "createdAt": new_row["hubspot_created_at"],
        "updatedAt": new_row["hubspot_updated_at"],
        "archived": False,
    }

    _audit(portal_id, status_code, {"createdId": new_row["hubspot_object_id"], "associations_created": len(planned_edges)})
    return result

