            return _err("VALIDATION_ERROR", f"{field} must be a string datetime")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            datetime.datetime.fromisoformat(ss)
            return None
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be a valid datetime string")

    portal_id = _resolve_portal()
    if not portal_id:
        status_code = "UNAUTHORIZED"
        _audit(portal_id, status_code, {"reason": "no portal context available"})
        return _err("UNAUTHORIZED", "No authorized portal context available for this request")

    if not isinstance(meetingId, str) or not meetingId.strip():
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "meetingId must be a non-empty string")

    if not isinstance(properties, dict):
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "properties must be an object")

    allowed_keys = {
        "hs_meeting_title",
        "hs_meeting_body",
        "hs_meeting_location",
        "hs_meeting_start_time",
        "hs_meeting_end_time",
        "hs_meeting_outcome",
        "hubspot_owner_id",
    }
    unknown = [k for k in properties.keys() if k not in allowed_keys]
    if unknown:
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code, {"unknown": unknown})
        return _err("VALIDATION_ERROR", "Unsupported property fields in payload", unknown=unknown)

    if "hs_meeting_outcome" in properties and properties["hs_meeting_outcome"] not in (None, "", "SCHEDULED", "COMPLETED", "CANCELED"):
        status_code = "VALIDATION_ERROR"
        _audit(portal_id, status_code)
        return _err("VALIDATION_ERROR", "hs_meeting_outcome must be one of SCHEDULED, COMPLETED, CANCELED")

    for f in ["hs_meeting_start_time", "hs_meeting_end_time"]:
        e = _parse_dt_str(properties.get(f), f)
        if e:
            status_code = "VALIDATION_ERROR"
            _audit(portal_id, status_code)
            return e

    # Quota/rate enforcement if present
    quotas = _load("quotas.json")
    if isinstance(quotas, list) and quotas:
        cfg = None
        for q in quotas:
            if q.get("portal_id") == portal_id and (q.get("scope") in (None, "meetings", "crm", "all")):
                cfg = q
                break
        if cfg:
            logs = _load("request_logs.json")
            now = _now_dt()
            rpm = cfg.get("requests_per_minute")
            rpd = cfg.get("requests_per_day")
            if isinstance(rpm, (int, float)) and rpm > 0:
                window_start = (now - datetime.timedelta(minutes=1)).isoformat()
                recent = [r for r in logs if r.get("portal_id") == portal_id and r.get("timestamp", "") >= window_start]
                if len(recent) >= int(rpm):
                    status_code = "RATE_LIMIT"
                    _audit(portal_id, status_code)
                    return _err("RATE_LIMIT", "Rate limit exceeded")
            if isinstance(rpd, (int, float)) and rpd > 0:
                day_start = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
                today = [r for r in logs if r.get("portal_id") == portal_id and r.get("timestamp", "") >= day_start]
                if len(today) >= int(rpd):
                    status_code = "QUOTA_EXCEEDED"
                    _audit(portal_id, status_code)
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    objs = _load("crm_objects.json")
    idx = None
    for i, r in enumerate(objs):
        if r.get("portal_id") == portal_id and r.get("object_type") == "meetings" and str(r.get("hubspot_object_id")) == meetingId:
            idx = i
            break
    if idx is None:
        status_code = "NOT_FOUND"
        _audit(portal_id, status_code, {"meetingId": meetingId})
        return _err("NOT_FOUND", "Meeting not found")

    row = objs[idx]
    if row.get("archived") is True or row.get("status") != "active":
        status_code = "NOT_FOUND"
        _audit(portal_id, status_code, {"meetingId": meetingId})
        return _err("NOT_FOUND", "Meeting not found")

    # Business rule: reject writes to archived/hidden property definitions when definitions exist
    prop_defs = _load("crm_object_properties.json")
    defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "meetings"]
    if defs:
        known = {d.get("name") for d in defs if isinstance(d.get("name"), str)}
        unknown2 = [k for k in properties.keys() if k not in known]
        if unknown2:
            status_code = "VALIDATION_ERROR"
            _audit(portal_id, status_code, {"unknown_properties": unknown2})
            return _err("VALIDATION_ERROR", "Unknown properties for meetings", unknown=unknown2)

        archived_defs = {d.get("name") for d in defs if d.get("status") == "archived" or d.get("archived") is True}
        hidden_defs = {d.get("name") for d in defs if d.get("hidden") is True}
        bad = [k for k in properties.keys() if k in archived_defs]
        if bad:
            status_code = "VALIDATION_ERROR"
            _audit(portal_id, status_code, {"archived_properties": bad})
            return _err("VALIDATION_ERROR", "Cannot write archived properties", properties=bad)
        if hidden_defs:
            bad2 = [k for k in properties.keys() if k in hidden_defs]
            if bad2:
                status_code = "VALIDATION_ERROR"
                _audit(portal_id, status_code, {"hidden_properties": bad2})
                return _err("VALIDATION_ERROR", "Cannot write hidden properties", properties=bad2)

    # Apply update (empty string means clear)
    current_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
    new_props = dict(current_props)
    for k, v in properties.items():
        if v == "":
            # clearing represented by empty string; keep key with empty string to reflect intent
            new_props[k] = ""
        else:
            new_props[k] = v

    # No success without effect: ensure at least one key changes value
    changed = False
    for k, v in properties.items():
        if current_props.get(k, None) != v:
            changed = True
            break
    if not changed:
        status_code = "CONFLICT"
        _audit(portal_id, status_code, {"meetingId": meetingId, "reason": "no changes"})
        return _err("CONFLICT", "Update would not change the resource")

    now = _now()
    row["properties"] = new_props
    row["properties_version"] = int(row.get("properties_version") or 1) + 1
    row["updated_at"] = now
    row["hubspot_updated_at"] = now
    objs[idx] = row
    _save("crm_objects.json", objs)

    result = {
        "id": row.get("hubspot_object_id"),
        "properties": row.get("properties") if isinstance(row.get("properties"), dict) else {},
        "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
        "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
        "archived": bool(row.get("archived")),
    }

    _audit(portal_id, status_code, {"meetingId": meetingId, "updated_fields": list(properties.keys())})
    return result

def meetings_archive(meetingId, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, portal_id=None, detail=None, latency_ms=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "portal_id": portal_id,
            "detail": detail,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "meetings_archive"

    # Validate input
    if meetingId is None or not isinstance(meetingId, str) or not meetingId.strip():
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "meetingId is required and must be a non-empty string")

    crm_objects = _load("crm_objects.json")
    if not isinstance(crm_objects, list):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No authorized portal context available")

    # Ambient auth: pick a portal that can service the call and contains the object
    target = None
    for o in crm_objects:
        if isinstance(o, dict) and o.get("object_type") == "meetings" and o.get("hubspot_object_id") == meetingId:
            target = o
            break

    if target is None:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "NOT_FOUND"}, latency_ms=latency)
        return _err("NOT_FOUND", "Meeting not found", meetingId=meetingId)

    # Enforce lifecycle transition
    if target.get("status") == "archived" or target.get("archived") is True:
        # idempotent archive: already archived => success with the existing resource state
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "success", portal_id=target.get("portal_id"), latency_ms=latency)
        return {
            "id": target.get("hubspot_object_id"),
            "archived": True,
            "status": "archived",
            "updatedAt": target.get("updated_at"),
        }

    if target.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", portal_id=target.get("portal_id"), detail={"code": "CONFLICT"}, latency_ms=latency)
        return _err("CONFLICT", "Meeting cannot be archived due to its current state", status=target.get("status"))

    # Mutate
    now = _now()
    target["status"] = "archived"
    target["archived"] = True
    target["updated_at"] = now
    target["hubspot_updated_at"] = now
    pv = target.get("properties_version")
    if isinstance(pv, int) and pv >= 1:
        target["properties_version"] = pv + 1
    else:
        target["properties_version"] = 1

    _save("crm_objects.json", crm_objects)

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, "success", portal_id=target.get("portal_id"), latency_ms=latency)
    return {
        "id": target.get("hubspot_object_id"),
        "archived": True,
        "status": "archived",
        "updatedAt": target.get("updated_at"),
    }

def meetings_search(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, portal_id=None, detail=None, latency_ms=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "portal_id": portal_id,
            "detail": detail,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "meetings_search"

    # Validate inputs
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array")

    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or int(limit) != limit or limit < 1 or limit > 100:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "limit must be an integer in range 1..100")
    limit = int(limit)

    if after is not None and (not isinstance(after, str) or not after.strip()):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "after must be a non-empty string cursor when provided")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str) or not p) for p in properties):
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
            return _err("VALIDATION_ERROR", "properties must be an array of strings when provided")

    if sorts is not None:
        if not isinstance(sorts, list):
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
            return _err("VALIDATION_ERROR", "sorts must be an array when provided")
        for s in sorts:
            if not isinstance(s, dict):
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
                return _err("VALIDATION_ERROR", "Each sort must be an object")
            if "propertyName" not in s or "direction" not in s:
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
                return _err("VALIDATION_ERROR", "Each sort must include propertyName and direction")
            if not isinstance(s["propertyName"], str) or not s["propertyName"]:
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
                return _err("VALIDATION_ERROR", "sort.propertyName must be a non-empty string")
            if s["direction"] not in ("ASCENDING", "DESCENDING"):
                latency = int((time.time() - t0) * 1000)
                _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
                return _err("VALIDATION_ERROR", "sort.direction must be ASCENDING or DESCENDING")

    allowed_ops = {
        "EQ", "NEQ", "LT", "LTE", "GT", "GTE", "BETWEEN", "IN", "NOT_IN",
        "HAS_PROPERTY", "NOT_HAS_PROPERTY", "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"
    }

    def _as_number(v):
        if isinstance(v, (int, float)):
            return float(v)
        if isinstance(v, str):
            try:
                return float(v) if v.strip() != "" else None
            except ValueError:
                return None
        return None

    def _cmp(a, b):
        # compare numbers if possible else lexicographic strings
        na, nb = _as_number(a), _as_number(b)
        if na is not None and nb is not None:
            return (na > nb) - (na < nb)
        sa = "" if a is None else str(a)
        sb = "" if b is None else str(b)
        return (sa > sb) - (sa < sb)

    def _tokenize(s):
        if s is None:
            return []
        return [t for t in re.split(r"[^A-Za-z0-9_]+", str(s).lower()) if t]

    def _eval_filter(obj, flt):
        if not isinstance(flt, dict):
            return False, "Filter must be an object"
        if "propertyName" not in flt or "operator" not in flt:
            return False, "Filter must include propertyName and operator"
        pn = flt["propertyName"]
        op = flt["operator"]
        if not isinstance(pn, str) or not pn:
            return False, "propertyName must be a non-empty string"
        if op not in allowed_ops:
            return False, "Unsupported operator"
        props = obj.get("properties") or {}
        has_prop = pn in props and props.get(pn) not in (None, "")
        val = props.get(pn)

        if op == "HAS_PROPERTY":
            return bool(has_prop), None
        if op == "NOT_HAS_PROPERTY":
            return (not has_prop), None

        # operators that need a value
        if op in ("IN", "NOT_IN"):
            v = flt.get("value", None)
            if isinstance(v, list):
                if len(v) == 0:
                    return False, "IN/NOT_IN requires a non-empty values array"
                values = v
            elif v is None:
                return False, "IN/NOT_IN requires value"
            else:
                values = [v]
            in_set = any(str(val) == str(x) for x in values)
            return (in_set if op == "IN" else (not in_set)), None

        if op == "BETWEEN":
            v = flt.get("value", None)
            if not isinstance(v, list) or len(v) != 2:
                return False, "BETWEEN requires a two-value array"
            lo, hi = v[0], v[1]
            return (_cmp(val, lo) >= 0 and _cmp(val, hi) <= 0), None

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            v = flt.get("value", None)
            if v is None or not isinstance(v, str) or not v.strip():
                return False, "CONTAINS_TOKEN requires a non-empty string value"
            tokens = set(_tokenize(val))
            needle = v.strip().lower()
            contains = needle in tokens
            return (contains if op == "CONTAINS_TOKEN" else (not contains)), None

        # EQ/NEQ/LT/LTE/GT/GTE
        if "value" not in flt:
            return False, f"{op} requires value"
        v = flt.get("value")
        c = _cmp(val, v)
        if op == "EQ":
            return c == 0, None
        if op == "NEQ":
            return c != 0, None
        if op == "LT":
            return c < 0, None
        if op == "LTE":
            return c <= 0, None
        if op == "GT":
            return c > 0, None
        if op == "GTE":
            return c >= 0, None
        return False, "Unsupported operator"

    def _matches(obj):
        # OR across groups, AND within group
        for g in filterGroups:
            if not isinstance(g, dict) or "filters" not in g:
                return None, "Each filterGroup must be an object with filters"
            fs = g.get("filters")
            if not isinstance(fs, list) or len(fs) == 0:
                return None, "filterGroup.filters must be a non-empty array"
            ok_group = True
            for flt in fs:
                ok, err = _eval_filter(obj, flt)
                if err:
                    return None, err
                if not ok:
                    ok_group = False
                    break
            if ok_group:
                return True, None
        return False, None

    crm_objects = _load("crm_objects.json")
    if not isinstance(crm_objects, list):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No authorized portal context available")

    # Ambient auth: choose a portal that has meeting rows (else still allow, returning empty for any portal found)
    portal_ids = []
    for o in crm_objects:
        if isinstance(o, dict) and o.get("portal_id"):
            portal_ids.append(o.get("portal_id"))
    portal_id = portal_ids[0] if portal_ids else None
    if portal_id is None:
        # no data at all; still must validate filters already done; return empty
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "success", portal_id=None, latency_ms=latency)
        return {"total": 0, "results": [], "paging": None}

    # Filter rows by portal + meetings + active only (exclude archived)
    candidates = [
        o for o in crm_objects
        if isinstance(o, dict)
        and o.get("portal_id") == portal_id
        and o.get("object_type") == "meetings"
        and o.get("archived") is False
        and o.get("status") == "active"
    ]

    matched = []
    for o in candidates:
        m, err = _matches(o)
        if err:
            latency = int((time.time() - t0) * 1000)
            _log(endpoint, "error", portal_id=portal_id, detail={"code": "VALIDATION_ERROR", "detail": err}, latency_ms=latency)
            return _err("VALIDATION_ERROR", "Malformed filters", detail=err)
        if m:
            matched.append(o)

    # Sorting
    if sorts:
        def _key(o, prop):
            if prop in ("createdAt", "created_at"):
                return o.get("created_at") or ""
            if prop in ("updatedAt", "updated_at"):
                return o.get("updated_at") or ""
            return "" if (o.get("properties") or {}).get(prop) is None else str((o.get("properties") or {}).get(prop))

        # stable sort by applying in reverse order
        for s in reversed(sorts):
            prop = s["propertyName"]
            rev = (s["direction"] == "DESCENDING")
            matched.sort(key=lambda x, p=prop: _key(x, p), reverse=rev)
    else:
        # Default: updated desc, then id
        matched.sort(key=lambda x: (x.get("updated_at") or "", x.get("hubspot_object_id") or ""), reverse=True)

    # Pagination by "after" cursor as numeric offset, or hubspot_object_id marker
    start = 0
    if after:
        # try integer offset
        try:
            start = int(after)
            if start < 0:
                raise ValueError()
        except ValueError:
            # treat as hubspot_object_id cursor: start after that id in current sorted list
            idx = None
            for i, o in enumerate(matched):
                if o.get("hubspot_object_id") == after:
                    idx = i
                    break
            start = (idx + 1) if idx is not None else 0

    page = matched[start:start + limit]
    next_cursor = None
    has_more = start + limit < len(matched)
    if has_more:
        next_cursor = str(start + limit)

    def _project(o):
        out_props = {}
        allp = o.get("properties") or {}
        if properties is None:
            out_props = dict(allp)
        else:
            for p in properties:
                if p in allp:
                    out_props[p] = allp.get(p)
        return {
            "id": o.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
            "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at"),
            "archived": bool(o.get("archived")),
        }

    results = [_project(o) for o in page]
    resp = {
        "total": len(matched),
        "results": results,
        "paging": ({"next": {"after": next_cursor}} if has_more else None),
    }

    latency = int((time.time() - t0) * 1000)
    _log(endpoint, "success", portal_id=portal_id, latency_ms=latency)
    return resp

def meetings_batch_create(inputs, **_extra):
    import json, os, datetime, time, uuid

