        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, portal_id=None, detail=None, latency_ms=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "portal_id": portal_id,
            "detail": detail,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "meetings_batch_create"

    if not isinstance(inputs, list) or len(inputs) == 0:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    crm_objects = _load("crm_objects.json")
    crm_props = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    crm_assocs = _load("crm_associations.json")

    if not isinstance(crm_objects, list) or not isinstance(crm_props, list) or not isinstance(assoc_types, list) or not isinstance(crm_assocs, list):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No authorized portal context available")

    # Ambient auth: pick a portal that can handle meetings. If none exists, create under a portal that exists anywhere.
    portal_ids = []
    for o in crm_objects:
        if isinstance(o, dict) and o.get("portal_id"):
            portal_ids.append(o.get("portal_id"))
    for p in crm_props:
        if isinstance(p, dict) and p.get("portal_id"):
            portal_ids.append(p.get("portal_id"))
    for a in assoc_types:
        if isinstance(a, dict) and a.get("portal_id"):
            portal_ids.append(a.get("portal_id"))
    portal_id = portal_ids[0] if portal_ids else None
    if portal_id is None:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No portal available")

    # Property definitions for meetings
    meeting_defs = [
        r for r in crm_props
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "meetings"
    ]
    defs_by_name = {r.get("name"): r for r in meeting_defs if r.get("name")}

    required_fields = ["hs_timestamp", "hs_meeting_title", "hs_meeting_start_time", "hs_meeting_end_time"]
    allowed_fields = set(required_fields + [
        "hs_meeting_body", "hs_meeting_location", "hs_meeting_outcome", "hubspot_owner_id"
    ])
    allowed_outcomes = {"SCHEDULED", "COMPLETED", "CANCELED"}

    def _validate_props(props):
        if not isinstance(props, dict):
            return "properties must be an object"
        # required
        for rf in required_fields:
            if rf not in props or not isinstance(props.get(rf), str) or props.get(rf) == "":
                return f"Missing or invalid required property: {rf}"
        # additionalProperties false already, but validate anyway
        for k in props.keys():
            if k not in allowed_fields:
                return f"Unsupported property: {k}"
        # validate enums
        if "hs_meeting_outcome" in props and props["hs_meeting_outcome"] is not None:
            if not isinstance(props["hs_meeting_outcome"], str) or props["hs_meeting_outcome"] not in allowed_outcomes:
                return "Invalid hs_meeting_outcome"
        # validate against definitions when present: reject archived (create) / hidden if policy forbids; no policy store => allow hidden
        for k in props.keys():
            if defs_by_name:
                d = defs_by_name.get(k)
                if d is None:
                    return f"Unknown property: {k}"
                if d.get("status") == "archived" or d.get("archived") is True:
                    return f"Property is archived: {k}"
        return None

    def _assoc_type_active(to_type, associationCategory, associationTypeId):
        for r in assoc_types:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("from_object_type") != "meetings":
                continue
            if r.get("to_object_type") != to_type:
                continue
            if r.get("association_category") != associationCategory:
                continue
            if r.get("association_type_id") != associationTypeId:
                continue
            return r.get("status") == "active"
        return False

    def _find_object_by_hubspot_id(to_id):
        # We don't know to-object type from schema input, so allow matching any object_type with hubspot_object_id
        for o in crm_objects:
            if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("hubspot_object_id") == to_id:
                return o
        return None

    results = []
    errors = []
    now = _now()

    # Precompute unique constraint index for objects
    existing_object_keys = set()
    for o in crm_objects:
        if isinstance(o, dict):
            existing_object_keys.add((o.get("portal_id"), o.get("object_type"), o.get("hubspot_object_id")))

    # Per-input atomic: validate first, then apply for that item only if valid
    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object"}})
            continue
        if "properties" not in item:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must include properties"}})
            continue

        props = item.get("properties")
        err = _validate_props(props)
        if err:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": err}})
            continue

        associations = item.get("associations")
        staged_edges = []
        if associations is not None:
            if not isinstance(associations, list):
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array when provided"}})
                continue
            assoc_ok = True
            assoc_err = None
            for a in associations:
                if not isinstance(a, dict) or "to" not in a or "types" not in a:
                    assoc_ok = False
                    assoc_err = "Each association must include to and types"
                    break
                to = a.get("to")
                if not isinstance(to, dict) or "id" not in to or not isinstance(to.get("id"), str) or not to.get("id"):
                    assoc_ok = False
                    assoc_err = "association.to.id must be a non-empty string"
                    break
                types = a.get("types")
                if not isinstance(types, list) or len(types) == 0:
                    assoc_ok = False
                    assoc_err = "association.types must be a non-empty array"
                    break

                to_obj = _find_object_by_hubspot_id(to["id"])
                if to_obj is None:
                    assoc_ok = False
                    assoc_err = f"Associated object not found: {to['id']}"
                    break
                if to_obj.get("archived") is True or to_obj.get("status") == "archived":
                    assoc_ok = False
                    assoc_err = f"Associated object is archived: {to['id']}"
                    break

                to_type = to_obj.get("object_type")
                for t in types:
                    if not isinstance(t, dict) or "associationCategory" not in t or "associationTypeId" not in t:
                        assoc_ok = False
                        assoc_err = "Each association type must include associationCategory and associationTypeId"
                        break
                    if not isinstance(t["associationCategory"], str) or not t["associationCategory"]:
                        assoc_ok = False
                        assoc_err = "associationCategory must be a non-empty string"
                        break
                    if not isinstance(t["associationTypeId"], (int, float)) or int(t["associationTypeId"]) != t["associationTypeId"] or t["associationTypeId"] < 1:
                        assoc_ok = False
                        assoc_err = "associationTypeId must be an integer >= 1"
                        break
                    associationTypeId = int(t["associationTypeId"])
                    if not _assoc_type_active(to_type, t["associationCategory"], associationTypeId):
                        assoc_ok = False
                        assoc_err = "Association type is not active or does not exist for this portal"
                        break
                    staged_edges.append((to_obj, to_type, t["associationCategory"], associationTypeId))
                if not assoc_ok:
                    break
            if not assoc_ok:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": assoc_err}})
                continue

        # Create meeting object row
        hubspot_object_id = str(uuid.uuid4().int % 10**12)  # numeric-like string
        # ensure uniqueness for portal/type/hubspot_object_id
        attempts = 0
        while (portal_id, "meetings", hubspot_object_id) in existing_object_keys and attempts < 5:
            hubspot_object_id = str(uuid.uuid4().int % 10**12)
            attempts += 1
        if (portal_id, "meetings", hubspot_object_id) in existing_object_keys:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": "Unable to allocate unique meeting id"}})
            continue

        obj_row = {
            "id": "obj_" + uuid.uuid4().hex,
            "portal_id": portal_id,
            "object_type": "meetings",
            "hubspot_object_id": hubspot_object_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props),
            "properties_version": 1,
            "search_text": None,
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        # Stage associations rows (upsert active behavior)
        staged_assoc_rows = []
        for (to_obj, to_type, cat, atid) in staged_edges:
            # unique key: portal, from_object_id, to_object_id, category, type_id
            # meeting internal id not yet appended; we can create after we know obj_row["id"]
            staged_assoc_rows.append({
                "portal_id": portal_id,
                "from_object_id": obj_row["id"],
                "to_object_id": to_obj.get("id"),
                "from_object_type": "meetings",
                "to_object_type": to_type,
                "association_category": cat,
                "association_type_id": atid,
            })

        # Apply mutation atomically for this item (only now write to in-memory collections)
        crm_objects.append(obj_row)
        existing_object_keys.add((portal_id, "meetings", hubspot_object_id))

        # upsert edges
        for e in staged_assoc_rows:
            found = None
            for arow in crm_assocs:
                if not isinstance(arow, dict):
                    continue
                if (
                    arow.get("portal_id") == e["portal_id"]
                    and arow.get("from_object_id") == e["from_object_id"]
                    and arow.get("to_object_id") == e["to_object_id"]
                    and arow.get("association_category") == e["association_category"]
                    and arow.get("association_type_id") == e["association_type_id"]
                ):
                    found = arow
                    break
            if found:
                # Reactivate if archived
                if found.get("status") == "archived" or found.get("archived") is True:
                    found["status"] = "active"
                    found["archived"] = False
                    found["updated_at"] = now
            else:
                crm_assocs.append({
                    "id": "asc_" + uuid.uuid4().hex,
                    "portal_id": e["portal_id"],
                    "from_object_id": e["from_object_id"],
                    "to_object_id": e["to_object_id"],
                    "from_object_type": e["from_object_type"],
                    "to_object_type": e["to_object_type"],
                    "association_category": e["association_category"],
                    "association_type_id": e["association_type_id"],
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now,
                })

        results.append({
            "id": obj_row["hubspot_object_id"],
            "properties": obj_row["properties"],
            "createdAt": obj_row["hubspot_created_at"],
            "updatedAt": obj_row["hubspot_updated_at"],
            "archived": False,
        })

    # Persist once at end
    _save("crm_objects.json", crm_objects)
    _save("crm_associations.json", crm_assocs)

    latency = int((time.time() - t0) * 1000)
    status = "success" if len(errors) == 0 else ("partial_success" if len(results) > 0 else "error")
    _log(endpoint, status, portal_id=portal_id, detail={"results": len(results), "errors": len(errors)}, latency_ms=latency)

    return {
        "results": results,
        "errors": errors,
        "total": len(inputs),
        "succeeded": len(results),
        "failed": len(errors),
    }

def meetings_batch_update(inputs, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, portal_id=None, detail=None, latency_ms=None):
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "portal_id": portal_id,
            "detail": detail,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "meetings_batch_update"

    if not isinstance(inputs, list) or len(inputs) == 0:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"}, latency_ms=latency)
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    crm_objects = _load("crm_objects.json")
    crm_props = _load("crm_object_properties.json")

    if not isinstance(crm_objects, list) or not isinstance(crm_props, list):
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No authorized portal context available")

    # Ambient portal: pick from existing meetings if possible else any portal
    portal_id = None
    for o in crm_objects:
        if isinstance(o, dict) and o.get("object_type") == "meetings" and o.get("portal_id"):
            portal_id = o.get("portal_id")
            break
    if portal_id is None:
        for o in crm_objects:
            if isinstance(o, dict) and o.get("portal_id"):
                portal_id = o.get("portal_id")
                break
    if portal_id is None:
        latency = int((time.time() - t0) * 1000)
        _log(endpoint, "error", detail={"code": "UNAUTHORIZED"}, latency_ms=latency)
        return _err("UNAUTHORIZED", "No portal available")

    meeting_defs = [
        r for r in crm_props
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "meetings"
    ]
    defs_by_name = {r.get("name"): r for r in meeting_defs if r.get("name")}

    allowed_fields = {
        "hs_meeting_title", "hs_meeting_body", "hs_meeting_location",
        "hs_meeting_start_time", "hs_meeting_end_time", "hs_meeting_outcome",
        "hubspot_owner_id"
    }
    allowed_outcomes = {"SCHEDULED", "COMPLETED", "CANCELED"}

    def _validate_update_props(props):
        if not isinstance(props, dict):
            return "properties must be an object"
        for k in props.keys():
            if k not in allowed_fields:
                return f"Unsupported property: {k}"
        if "hs_meeting_outcome" in props and props["hs_meeting_outcome"] is not None:
            if not isinstance(props["hs_meeting_outcome"], str) or props["hs_meeting_outcome"] not in allowed_outcomes:
                return "Invalid hs_meeting_outcome"
        # Reject writes to archived definitions; hidden policy not available => allow hidden
        for k in props.keys():
            if defs_by_name:
                d = defs_by_name.get(k)
                if d is None:
                    return f"Unknown property: {k}"
                if d.get("status") == "archived" or d.get("archived") is True:
                    return f"Property is archived: {k}"
        return None

    results = []
    errors = []
    now = _now()

    # Index meeting rows by hubspot_object_id
    by_hid = {}
    for o in crm_objects:
        if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "meetings":
            by_hid[o.get("hubspot_object_id")] = o

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object"}})
            continue
        mid = item.get("id")
        props = item.get("properties")
        if mid is None or not isinstance(mid, str) or not mid.strip():
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must include a non-empty string id"}})
            continue
        if props is None:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must include properties"}})
            continue
        err = _validate_update_props(props)
        if err:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": err}})
            continue

        row = by_hid.get(mid)
        if row is None:
            errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "Meeting not found", "id": mid}})
            continue

        if row.get("status") == "archived" or row.get("archived") is True:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": "Cannot update an archived meeting", "id": mid}})
            continue

        # Apply updates: clearing represented by empty string in properties JSON
        cur = row.get("properties") or {}
        for k, v in props.items():
            if v == "":
                cur[k] = ""
            else:
                cur[k] = v
        row["properties"] = cur
        row["updated_at"] = now
        row["hubspot_updated_at"] = now
        pv = row.get("properties_version")
        if isinstance(pv, int) and pv >= 1:
            row["properties_version"] = pv + 1
        else:
            row["properties_version"] = 1

        results.append({
            "id": row.get("hubspot_object_id"),
            "properties": row.get("properties") or {},
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived")),
        })

    if results:
        _save("crm_objects.json", crm_objects)

    latency = int((time.time() - t0) * 1000)
    status = "success" if len(errors) == 0 else ("partial_success" if len(results) > 0 else "error")
    _log(endpoint, status, portal_id=portal_id, detail={"results": len(results), "errors": len(errors)}, latency_ms=latency)

    return {
        "results": results,
        "errors": errors,
        "total": len(inputs),
        "succeeded": len(results),
        "failed": len(errors),
    }

def meetings_batch_archive(meetingIds, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "meetings_batch_archive"
    status = "success"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve ambient portal context: pick any portal_id present in datastore.
    objs = _load("crm_objects.json")
    portal_id = None
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_id = r.get("portal_id")
            break
    if portal_id is None:
        status = "error"
        _log(status, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")

    # Validate inputs
    if not isinstance(meetingIds, list) or len(meetingIds) == 0:
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "meetingIds must be a non-empty array of strings.")
    bad = [x for x in meetingIds if not isinstance(x, str) or not x.strip()]
    if bad:
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "meetingIds contains invalid id(s).", invalidIds=bad)

    # Build index for fast lookup by hubspot_object_id
    # meetingId is the HubSpot object ID in tools, mapped to crm_objects.hubspot_object_id
    changed = False
    results = []
    now = _now()

    # Ensure uniqueness constraint: (portal_id, object_type, hubspot_object_id)
    # We will operate on the first match; duplicates are a datastore inconsistency -> conflict per item.
    by_key = {}
    for i, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("object_type") != "meetings":
            continue
        k = r.get("hubspot_object_id")
        if not isinstance(k, str):
            continue
        by_key.setdefault(k, []).append((i, r))

    for mid in meetingIds:
        matches = by_key.get(mid, [])
        if not matches:
            results.append({"id": mid, "archived": False, "status": "error", "error": {"code": "NOT_FOUND", "message": "Meeting not found."}})
            continue
        if len(matches) > 1:
            results.append({"id": mid, "archived": False, "status": "error", "error": {"code": "CONFLICT", "message": "Multiple meeting records found for this id."}})
            continue

        idx, row = matches[0]
        cur_status = row.get("status")
        # Archive operation: active -> archived; archived already is idempotent success.
        if cur_status == "archived" or row.get("archived") is True:
            # idempotent
            results.append({"id": mid, "archived": True, "status": "success"})
            continue
        if cur_status != "active":
            results.append({"id": mid, "archived": False, "status": "error", "error": {"code": "CONFLICT", "message": "Meeting cannot be archived due to its current state."}})
            continue

        # Transition active -> archived
        row["status"] = "archived"
        row["archived"] = True
        row["updated_at"] = now
        if isinstance(row.get("properties_version"), int) and row["properties_version"] >= 1:
            row["properties_version"] += 1
        else:
            row["properties_version"] = 2
        objs[idx] = row
        changed = True
        results.append({"id": mid, "archived": True, "status": "success"})

    if changed:
        _save("crm_objects.json", objs)

    _log(status)
    return {
        "results": results,
        "summary": {
            "requested": len(meetingIds),
            "succeeded": sum(1 for r in results if r.get("status") == "success"),
            "failed": sum(1 for r in results if r.get("status") != "success"),
        },
    }

def notes_create(properties, associations=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "notes_create"
    status = "success"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve portal
    objs = _load("crm_objects.json")
    portal_id = None
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_id = r.get("portal_id")
            break
    if portal_id is None:
        status = "error"
        _log(status, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")

    # Validate payload
    if not isinstance(properties, dict):
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.")
    if "hs_note_body" not in properties or not isinstance(properties.get("hs_note_body"), str) or properties.get("hs_note_body") == "":
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hs_note_body is required and must be a non-empty string.")

    # Validate optional known property types when present (additionalProperties allowed)
    for k in ("hs_timestamp", "hubspot_owner_id"):
        if k in properties and properties[k] is not None and not isinstance(properties[k], str):
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{k} must be a string.")

    # Load property definitions for notes (if any) and enforce archived/hidden
    prop_defs = _load("crm_object_properties.json")
    defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "notes"]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    # Policy: allow additional properties (tool schema allows) even if defs exist; but reject writes to archived/hidden defs.
    for pname, pval in properties.items():
        if pname in defs_by_name:
            d = defs_by_name[pname]
            if d.get("status") == "archived" or d.get("archived") is True:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property '{pname}' is archived and cannot be written.")
            if d.get("hidden") is True:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property '{pname}' is hidden and cannot be written.")
        # else: allowed by additionalProperties

    # Validate associations structure
    assoc_inputs = associations
    if assoc_inputs is None:
        assoc_inputs = []
    if not isinstance(assoc_inputs, list):
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "associations must be an array.")
    for a in assoc_inputs:
        if not isinstance(a, dict):
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each association must be an object.")
        if "to" not in a or "types" not in a:
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each association must include 'to' and 'types'.")
        to = a.get("to")
        types = a.get("types")
        if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id").strip():
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Association 'to.id' must be a string.")
        if not isinstance(types, list) or len(types) == 0:
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Association 'types' must be a non-empty array.")
        for t in types:
            if not isinstance(t, dict):
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each association type spec must be an object.")
            if "associationCategory" not in t or "associationTypeId" not in t:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each association type spec must include associationCategory and associationTypeId.")
            if not isinstance(t.get("associationCategory"), str) or not t.get("associationCategory"):
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "associationCategory must be a non-empty string.")
            if not (isinstance(t.get("associationTypeId"), (int, float))) or int(t.get("associationTypeId")) < 1:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "associationTypeId must be a number >= 1.")

    # Create note object with unique hubspot_object_id
    existing_ids = set()
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "notes":
            hid = r.get("hubspot_object_id")
            if isinstance(hid, str):
                existing_ids.add(hid)

    def _new_hubspot_id():
        # numeric-like id as string
        base = int(time.time() * 1000)
        for i in range(0, 10000):
            cand = str(base + i)
            if cand not in existing_ids:
                return cand
        return uuid.uuid4().hex

    now = _now()
    hubspot_object_id = _new_hubspot_id()
    row_id = "obj_" + uuid.uuid4().hex
    note_row = {
        "id": row_id,
        "portal_id": portal_id,
        "object_type": "notes",
        "hubspot_object_id": hubspot_object_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": dict(properties),
        "properties_version": 1,
        "search_text": None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Apply denormalized search_text
    try:
        note_row["search_text"] = " ".join(
            str(v) for v in note_row["properties"].values()
            if v is not None and isinstance(v, (str, int, float, bool))
        )
    except Exception:
        note_row["search_text"] = None

    # Prepare associations writes (validate referential integrity + association type active)
    assoc_types = _load("crm_association_types.json")
    assoc_edges = _load("crm_associations.json")

    # index objects by hubspot_object_id for portal across types
    obj_by_hid = {}
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id") == portal_id and isinstance(r.get("hubspot_object_id"), str):
            obj_by_hid.setdefault((r.get("object_type"), r.get("hubspot_object_id")), []).append(r)

    def _resolve_target(to_id):
        # association 'to.id' is hubspot object id; resolve across all object types (HubSpot style),
        # prefer active & non-archived matches.
        candidates = []
        for (ot, hid), rows in obj_by_hid.items():
            if hid == to_id:
                for rr in rows:
                    if rr.get("status") == "active" and rr.get("archived") is False:
                        candidates.append(rr)
        if candidates:
            return candidates[0]
        # fall back to any match (even archived) for validation; creation still allowed but association should target active
        for (ot, hid), rows in obj_by_hid.items():
            if hid == to_id:
                return rows[0]
        return None

    # Pre-validate all associations before mutating (atomic)
    assoc_to_create = []
    for a in assoc_inputs:
        target = _resolve_target(a["to"]["id"])
        if target is None:
            status = "error"
            _log(status, "NOT_FOUND")
            return _err("NOT_FOUND", "Associated object not found.", toId=a["to"]["id"])
        if target.get("portal_id") != portal_id:
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cross-portal associations are not allowed.")
        if target.get("status") != "active" or target.get("archived") is True:
            status = "error"
            _log(status, "CONFLICT")
            return _err("CONFLICT", "Cannot associate to an archived object.", toId=a["to"]["id"])

        for t in a["types"]:
            cat = t["associationCategory"]
            atid = int(t["associationTypeId"])
            # must exist & active for (from,to,category,typeid) for portal
            ok = False
            for d in assoc_types:
                if not isinstance(d, dict):
                    continue
                if d.get("portal_id") != portal_id:
                    continue
                if d.get("from_object_type") != "notes":
                    continue
                if d.get("to_object_type") != target.get("object_type"):
                    continue
                if d.get("association_category") != cat:
                    continue
                if int(d.get("association_type_id") or 0) != atid:
                    continue
                if d.get("status") == "active":
                    ok = True
                    break
            if not ok:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err(
                    "VALIDATION_ERROR",
                    "Association type is not defined or not active for this portal.",
                    fromObjectType="notes",
                    toObjectType=target.get("object_type"),
                    associationCategory=cat,
                    associationTypeId=atid,
                )
            assoc_to_create.append((target, cat, atid))

    # Persist note + associations
    objs.append(note_row)

    # Create association edges (notes -> target)
    for (target, cat, atid) in assoc_to_create:
        # upsert: if identical exists archived, reactivate
        existing = None
        for e in assoc_edges:
            if not isinstance(e, dict):
                continue
            if e.get("portal_id") != portal_id:
                continue
            if e.get("from_object_id") == row_id and e.get("to_object_id") == target.get("id") and e.get("association_category") == cat and int(e.get("association_type_id") or 0) == atid:
                existing = e
                break
        if existing:
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
                existing["updated_at"] = now
        else:
            assoc_edges.append({
                "id": "asc_" + uuid.uuid4().hex,
                "portal_id": portal_id,
                "from_object_id": row_id,
                "to_object_id": target.get("id"),
                "from_object_type": "notes",
                "to_object_type": target.get("object_type"),
                "association_category": cat,
                "association_type_id": atid,
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now,
            })

    _save("crm_objects.json", objs)
    if assoc_to_create:
        _save("crm_associations.json", assoc_edges)

    _log(status)
    return {
        "id": hubspot_object_id,
        "objectType": "notes",
        "properties": note_row["properties"],
        "createdAt": note_row["hubspot_created_at"],
        "updatedAt": note_row["hubspot_updated_at"],
        "archived": note_row["archived"],
    }

def notes_get(noteId, properties=None, associations=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "notes_get"
    status = "success"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve portal
    objs = _load("crm_objects.json")
    portal_id = None
    for r in objs:
        if isinstance(r, dict) and r.get("portal_id"):
            portal_id = r.get("portal_id")
            break
    if portal_id is None:
        status = "error"
        _log(status, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available for this operation.")

    if not isinstance(noteId, str) or not noteId.strip():
        status = "error"
        _log(status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "noteId must be a non-empty string.")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str)) for p in properties):
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array of strings.")

    supported_assoc = {"contacts", "companies", "deals", "tickets"}
    if associations is not None:
        if not isinstance(associations, list) or any((not isinstance(a, str) or a not in supported_assoc) for a in associations):
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations must be an array containing only supported values.", supported=list(sorted(supported_assoc)))

    # Find note (exclude archived)
    note_row = None
    for r in objs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("object_type") != "notes":
            continue
        if r.get("hubspot_object_id") == noteId:
            note_row = r
            break

    if note_row is None or note_row.get("status") != "active" or note_row.get("archived") is True:
        status = "error"
        _log(status, "NOT_FOUND")
        return _err("NOT_FOUND", "Note not found.")

    # Properties projection
    props_out = dict(note_row.get("properties") or {})
    if properties is not None:
        props_out = {k: props_out.get(k) for k in properties if isinstance(k, str)}

    resp = {
        "id": note_row.get("hubspot_object_id"),
        "objectType": "notes",
        "properties": props_out,
        "createdAt": note_row.get("hubspot_created_at") or note_row.get("created_at"),
        "updatedAt": note_row.get("hubspot_updated_at") or note_row.get("updated_at"),
        "archived": bool(note_row.get("archived")),
    }

    # Associations resolution
    if associations:
        edges = _load("crm_associations.json")
        # object index by internal id -> object row
        by_id = {r.get("id"): r for r in objs if isinstance(r, dict) and r.get("portal_id") == portal_id}
        assoc_out = {}
        for tgt_type in associations:
            assoc_out[tgt_type] = {"results": []}

        for e in edges:
            if not isinstance(e, dict):
                continue
            if e.get("portal_id") != portal_id:
                continue
            if e.get("status") != "active" or e.get("archived") is True:
                continue

            # consider either direction to be robust
            linked_id = None
            linked_type = None
            if e.get("from_object_id") == note_row.get("id"):
                linked_id = e.get("to_object_id")
                linked_type = e.get("to_object_type")
            elif e.get("to_object_id") == note_row.get("id"):
                linked_id = e.get("from_object_id")
                linked_type = e.get("from_object_type")
            else:
                continue

            if linked_type not in supported_assoc or linked_type not in assoc_out:
                continue
            o = by_id.get(linked_id)
            if not o or o.get("status") != "active" or o.get("archived") is True:
                continue
            assoc_out[linked_type]["results"].append({"id": o.get("hubspot_object_id")})

        resp["associations"] = assoc_out

    _log(status)
    return resp

