            if d.get("status") == "archived" or d.get("archived") is True:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property '{pname}' is archived and cannot be written.")
            if d.get("hidden") is True:
                status = "error"
                _log(status, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Property '{pname}' is hidden and cannot be written.")

    # Find note row (must be active/non-archived)
    idx = None
    row = None
    for i, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
