        _log(status, "NOT_FOUND")
        return _err("NOT_FOUND", "Note not found.")

    # Apply updates; clearing represented by empty string (already allowed by schema)
    now = _now()
    cur_props = dict(row.get("properties") or {})
    for k, v in properties.items():
        # Only accept JSON scalar / null / list / object; but store as-is (HubSpot-like)
        if v is not None and not isinstance(v, (str, int, float, bool, list, dict)):
            status = "error"
            _log(status, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Invalid value type for property '{k}'.")
