    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, message=None):
        # Best-effort request log if present in store; do not error if absent.
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "timestamp": _now(),
                        "endpoint": endpoint,
                        "status": status,
                        "message": message,
                    }
                )
                _save(fname, logs)
                break

    t0 = time.time()
    endpoint = "notes_archive"

    if not isinstance(noteId, str) or not noteId.strip():
        _log("error", endpoint, "VALIDATION_ERROR: noteId")
        return _err("VALIDATION_ERROR", "noteId must be a non-empty string")

    crm_objects = _load("crm_objects.json")

    # Ambient auth/tenant resolution: pick a portal that contains this note.
    note_row = None
    for r in crm_objects:
        if r.get("object_type") == "notes" and str(r.get("hubspot_object_id")) == noteId:
            note_row = r
            break

    if not note_row:
        _log("error", endpoint, "NOT_FOUND: note")
        return _err("NOT_FOUND", f"Note {noteId} not found")

    if note_row.get("status") == "archived" or note_row.get("archived") is True:
        _log("error", endpoint, "CONFLICT: already archived")
        return _err("CONFLICT", f"Note {noteId} is already archived")

    # Transition active -> archived only
    if note_row.get("status") != "active":
        _log("error", endpoint, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Note cannot be archived from its current state", current_status=note_row.get("status"))

    note_row["status"] = "archived"
    note_row["archived"] = True
    note_row["updated_at"] = _now()
    # Keep monotonic properties_version
    pv = note_row.get("properties_version")
    try:
        pv_int = int(pv)
    except Exception:
        pv_int = 1
    note_row["properties_version"] = max(1, pv_int)

    _save("crm_objects.json", crm_objects)
    _log("ok", endpoint, f"archived noteId={noteId} in {int((time.time()-t0)*1000)}ms")

    # HubSpot-style archive response is typically empty; return a structured response anyway.
    return {
        "status": "archived",
        "id": noteId,
        "archived": True,
        "updatedAt": note_row.get("updated_at"),
    }

def notes_list(limit=None, after=None, properties=None, associations=None, archived=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, message=None):
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "timestamp": _now(),
                        "endpoint": endpoint,
                        "status": status,
                        "message": message,
                    }
                )
                _save(fname, logs)
                break

    t0 = time.time()
    endpoint = "notes_list"

    if limit is None:
        limit = 100
    if not isinstance(limit, (int, float)) or int(limit) != limit or int(limit) < 1 or int(limit) > 100:
        _log("error", endpoint, "VALIDATION_ERROR: limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    limit = int(limit)

    if after is not None and (not isinstance(after, str) or not after.strip()):
        _log("error", endpoint, "VALIDATION_ERROR: after")
        return _err("VALIDATION_ERROR", "after must be a non-empty string when provided")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str)) for p in properties):
            _log("error", endpoint, "VALIDATION_ERROR: properties")
            return _err("VALIDATION_ERROR", "properties must be an array of strings")

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}
    if associations is not None:
        if not isinstance(associations, list) or any((not isinstance(a, str) or a not in allowed_assoc) for a in associations):
            _log("error", endpoint, "VALIDATION_ERROR: associations")
            return _err("VALIDATION_ERROR", "associations must be an array containing only contacts, companies, deals, tickets")

    if archived is not None and not isinstance(archived, bool):
        _log("error", endpoint, "VALIDATION_ERROR: archived")
        return _err("VALIDATION_ERROR", "archived must be a boolean")

    crm_objects = _load("crm_objects.json")
    crm_assocs = _load("crm_associations.json")

    # Ambient tenant resolution: list per portal; choose a portal with notes.
    portal_ids = sorted({r.get("portal_id") for r in crm_objects if r.get("object_type") == "notes" and r.get("portal_id") is not None})
    if not portal_ids:
        _log("ok", endpoint, f"empty in {int((time.time()-t0)*1000)}ms")
        return {"results": [], "paging": None}

    # If "after" is present, it is a hubspot_object_id cursor; find its portal_id; otherwise use first portal.
    portal_id = portal_ids[0]
    after_int = None
    if after is not None:
        # Find row matching after to determine portal and position
        after_row = None
        for r in crm_objects:
            if r.get("object_type") == "notes" and str(r.get("hubspot_object_id")) == after:
                after_row = r
                break
        if after_row:
            portal_id = after_row.get("portal_id")
        # cursor comparison uses numeric if possible else lexicographic
        try:
            after_int = int(after)
        except Exception:
            after_int = None

    include_archived = bool(archived) if archived is not None else False

    rows = [r for r in crm_objects if r.get("portal_id") == portal_id and r.get("object_type") == "notes"]
    if not include_archived:
        rows = [r for r in rows if not r.get("archived") and r.get("status") == "active"]

    def _key(r):
        hid = str(r.get("hubspot_object_id") or "")
        try:
            return (0, int(hid))
        except Exception:
            return (1, hid)

    rows.sort(key=_key)

    # Apply cursor
    if after is not None:
        def _gt(r):
            hid = str(r.get("hubspot_object_id") or "")
            if after_int is not None:
                try:
                    return int(hid) > after_int
                except Exception:
                    # numeric cursor: treat non-numeric as greater only if after was non-numeric; here after numeric => non-numeric excluded
                    return False
            return hid > after

        rows = [r for r in rows if _gt(r)]

    page = rows[:limit]
    has_more = len(rows) > limit

    # Build association lookup by note internal id
    assoc_index = {}
    if associations:
        want = set(associations)
        for e in crm_assocs:
            if e.get("portal_id") != portal_id:
                continue
            if e.get("status") != "active" or e.get("archived") is True:
                continue
            frm = e.get("from_object_id")
            to = e.get("to_object_id")
            if not frm or not to:
                continue
            # notes can be from or to; normalize to "this note id -> other"
            assoc_index.setdefault(frm, []).append(e)
            assoc_index.setdefault(to, []).append(e)

        # Need objects to map to hubspot ids by type
        obj_by_id = {o.get("id"): o for o in crm_objects if o.get("portal_id") == portal_id}

    results = []
    for r in page:
        props = r.get("properties") or {}
        if properties is not None:
            props = {k: props.get(k) for k in properties}
        out = {
            "id": str(r.get("hubspot_object_id")),
            "properties": props,
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
            "archived": bool(r.get("archived")),
        }
        if associations:
            assoc_out = {}
            edges = assoc_index.get(r.get("id"), [])
            for w in associations:
                assoc_out[w] = {"results": []}
            for e in edges:
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                other_id = e.get("to_object_id") if e.get("from_object_id") == r.get("id") else e.get("from_object_id")
                other = obj_by_id.get(other_id)
                if not other or other.get("status") != "active" or other.get("archived") is True:
                    continue
                otype = other.get("object_type")
                if otype in want:
                    assoc_out[otype]["results"].append({"id": str(other.get("hubspot_object_id"))})
            out["associations"] = assoc_out
        results.append(out)

    paging = None
    if has_more and page:
        paging = {"next": {"after": str(page[-1].get("hubspot_object_id"))}}

    _log("ok", endpoint, f"portal_id={portal_id} returned={len(results)} in {int((time.time()-t0)*1000)}ms")
    return {"results": results, "paging": paging}

def notes_search(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, message=None):
        for fname in ("request_logs.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "timestamp": _now(),
                        "endpoint": endpoint,
                        "status": status,
                        "message": message,
                    }
                )
                _save(fname, logs)
                break

    t0 = time.time()
    endpoint = "notes_search"

    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        _log("error", endpoint, "VALIDATION_ERROR: filterGroups")
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str)) for p in properties):
            _log("error", endpoint, "VALIDATION_ERROR: properties")
            return _err("VALIDATION_ERROR", "properties must be an array of strings")

    if limit is None:
        limit = 100
    if not isinstance(limit, (int, float)) or int(limit) != limit or int(limit) < 1 or int(limit) > 100:
        _log("error", endpoint, "VALIDATION_ERROR: limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    limit = int(limit)

    if after is not None and (not isinstance(after, str) or not after.strip()):
        _log("error", endpoint, "VALIDATION_ERROR: after")
        return _err("VALIDATION_ERROR", "after must be a non-empty string when provided")

    if sorts is not None:
        if not isinstance(sorts, list):
            _log("error", endpoint, "VALIDATION_ERROR: sorts")
            return _err("VALIDATION_ERROR", "sorts must be an array")
        for s in sorts:
            if not isinstance(s, dict) or "propertyName" not in s or "direction" not in s:
                _log("error", endpoint, "VALIDATION_ERROR: sorts items")
                return _err("VALIDATION_ERROR", "each sort must have propertyName and direction")
            if not isinstance(s["propertyName"], str) or s["direction"] not in ("ASCENDING", "DESCENDING"):
                _log("error", endpoint, "VALIDATION_ERROR: sorts values")
                return _err("VALIDATION_ERROR", "invalid sort direction or propertyName")

    supported_ops = {
        "EQ", "NEQ", "LT", "LTE", "GT", "GTE",
        "BETWEEN", "IN", "NOT_IN",
        "HAS_PROPERTY", "NOT_HAS_PROPERTY",
        "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN",
    }

    # Validate filterGroups structure
    for g in filterGroups:
        if not isinstance(g, dict) or "filters" not in g or not isinstance(g["filters"], list) or len(g["filters"]) == 0:
            _log("error", endpoint, "VALIDATION_ERROR: filterGroups.filters")
            return _err("VALIDATION_ERROR", "each filterGroup must contain a non-empty filters array")
        for flt in g["filters"]:
            if not isinstance(flt, dict):
                _log("error", endpoint, "VALIDATION_ERROR: filter")
                return _err("VALIDATION_ERROR", "filters must be objects")
            if "propertyName" not in flt or "operator" not in flt:
                _log("error", endpoint, "VALIDATION_ERROR: filter fields")
                return _err("VALIDATION_ERROR", "each filter must include propertyName and operator")
            if not isinstance(flt["propertyName"], str) or not flt["propertyName"]:
                _log("error", endpoint, "VALIDATION_ERROR: propertyName")
                return _err("VALIDATION_ERROR", "filter propertyName must be a non-empty string")
            op = flt["operator"]
            if op not in supported_ops:
                _log("error", endpoint, "VALIDATION_ERROR: operator")
                return _err("VALIDATION_ERROR", f"Unsupported operator {op}")
            # value presence validation by operator
            if op in ("HAS_PROPERTY", "NOT_HAS_PROPERTY"):
                pass
            elif op == "BETWEEN":
                v = flt.get("value", None)
                if not isinstance(v, list) or len(v) != 2:
                    _log("error", endpoint, "VALIDATION_ERROR: BETWEEN value")
                    return _err("VALIDATION_ERROR", "BETWEEN requires value to be a 2-element array")
            elif op in ("IN", "NOT_IN"):
                v = flt.get("value", None)
                if isinstance(v, list):
                    if len(v) == 0:
                        _log("error", endpoint, "VALIDATION_ERROR: IN/NOT_IN empty")
                        return _err("VALIDATION_ERROR", f"{op} requires a non-empty array value")
                elif v is None:
                    _log("error", endpoint, "VALIDATION_ERROR: IN/NOT_IN missing")
                    return _err("VALIDATION_ERROR", f"{op} requires value")
            else:
                if "value" not in flt:
                    _log("error", endpoint, "VALIDATION_ERROR: value missing")
                    return _err("VALIDATION_ERROR", f"{op} requires value")

    crm_objects = _load("crm_objects.json")

    # Ambient tenant selection: pick first portal that has notes.
    portal_ids = sorted({r.get("portal_id") for r in crm_objects if r.get("object_type") == "notes" and r.get("portal_id") is not None})
    if not portal_ids:
        _log("ok", endpoint, f"empty in {int((time.time()-t0)*1000)}ms")
        return {"total": 0, "results": [], "paging": None}

    portal_id = portal_ids[0]
    if after is not None:
        for r in crm_objects:
            if r.get("object_type") == "notes" and str(r.get("hubspot_object_id")) == after:
                portal_id = r.get("portal_id")
                break

    # Search in HubSpot defaults to exclude archived unless explicitly filtered; here we exclude archived always.
    candidates = [
        r for r in crm_objects
        if r.get("portal_id") == portal_id and r.get("object_type") == "notes" and r.get("status") == "active" and not r.get("archived")
    ]

    def _coerce_num(x):
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    def _tokenize(val):
        if val is None:
            return []
        s = str(val).lower()
        return [t for t in re.split(r"[^a-z0-9_]+", s) if t]

    def _get_prop(row, name):
        props = row.get("properties") or {}
        return props.get(name)

    def _eval_filter(row, flt):
        name = flt["propertyName"]
        op = flt["operator"]
        v = flt.get("value", None)
        prop = _get_prop(row, name)
        has = name in (row.get("properties") or {}) and prop not in (None, "")

        if op == "HAS_PROPERTY":
            return has
        if op == "NOT_HAS_PROPERTY":
            return not has

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            tokens = _tokenize(prop)
            needle = str(v).lower()
            ok = needle in tokens
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        if op in ("IN", "NOT_IN"):
            arr = v if isinstance(v, list) else [v]
            ok = str(prop) in {str(x) for x in arr}
            return ok if op == "IN" else (not ok)

        if op == "BETWEEN":
            lo, hi = v[0], v[1]
            pn = _coerce_num(prop)
            l = _coerce_num(lo)
            h = _coerce_num(hi)
            if pn is not None and l is not None and h is not None:
                return l <= pn <= h
            # fallback lexicographic
            ps = "" if prop is None else str(prop)
            return str(lo) <= ps <= str(hi)

        # Comparisons
        if op in ("EQ", "NEQ"):
            ok = str(prop) == str(v)
            return ok if op == "EQ" else (not ok)

        pn = _coerce_num(prop)
        vn = _coerce_num(v)
        if pn is not None and vn is not None:
            if op == "LT":
                return pn < vn
            if op == "LTE":
                return pn <= vn
            if op == "GT":
                return pn > vn
            if op == "GTE":
                return pn >= vn
        # fallback lexicographic
        ps = "" if prop is None else str(prop)
        vs = str(v)
        if op == "LT":
            return ps < vs
        if op == "LTE":
            return ps <= vs
        if op == "GT":
            return ps > vs
        if op == "GTE":
            return ps >= vs
        return False

    def _matches(row):
        # OR across groups; AND within group
        for g in filterGroups:
            ok = True
            for flt in g["filters"]:
                if not _eval_filter(row, flt):
                    ok = False
                    break
            if ok:
                return True
        return False

    matched = [r for r in candidates if _matches(r)]
    total = len(matched)

    # Sort
    if sorts:
        def _sort_key(row):
            keys = []
            for s in sorts:
                pn = s["propertyName"]
                val = _get_prop(row, pn)
                # numbers first if possible
                n = _coerce_num(val)
                keys.append((0, n) if n is not None else (1, "" if val is None else str(val)))
            # stable tiebreaker by hubspot_object_id
            hid = str(row.get("hubspot_object_id") or "")
            try:
                hidk = (0, int(hid))
            except Exception:
                hidk = (1, hid)
            keys.append(hidk)
            return tuple(keys)

        # If mixed directions, apply by transforming key per direction is complex; do stable multi-pass instead.
        # Implement multi-pass stable sorts from last to first.
        sorted_rows = matched[:]
        # tiebreaker by id always ascending
        sorted_rows.sort(key=lambda r: (0, int(str(r.get("hubspot_object_id")))) if str(r.get("hubspot_object_id", "")).isdigit() else (1, str(r.get("hubspot_object_id") or "")))
        for s in reversed(sorts):
            pn = s["propertyName"]
            direction = s["direction"]
            def _k(r):
                val = _get_prop(r, pn)
                n = _coerce_num(val)
                return (0, n) if n is not None else (1, "" if val is None else str(val))
            sorted_rows.sort(key=_k, reverse=(direction == "DESCENDING"))
        matched = sorted_rows
    else:
        matched.sort(key=lambda r: (0, int(str(r.get("hubspot_object_id")))) if str(r.get("hubspot_object_id", "")).isdigit() else (1, str(r.get("hubspot_object_id") or "")))

    # Cursor
    if after is not None:
        try:
            after_int = int(after)
        except Exception:
            after_int = None

        def _gt(r):
            hid = str(r.get("hubspot_object_id") or "")
            if after_int is not None:
                try:
                    return int(hid) > after_int
                except Exception:
                    return False
            return hid > after

        matched = [r for r in matched if _gt(r)]

    page = matched[:limit]
    has_more = len(matched) > limit

    results = []
    for r in page:
        props = r.get("properties") or {}
        if properties is not None:
            props = {k: props.get(k) for k in properties}
        results.append(
            {
                "id": str(r.get("hubspot_object_id")),
                "properties": props,
                "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
                "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
                "archived": bool(r.get("archived")),
            }
        )

    paging = None
    if has_more and page:
        paging = {"next": {"after": str(page[-1].get("hubspot_object_id"))}}

    _log("ok", endpoint, f"portal_id={portal_id} total={total} returned={len(results)} in {int((time.time()-t0)*1000)}ms")
    return {"total": total, "results": results, "paging": paging}

def notes_batch_create(inputs, **_extra):
