        mx = 0
        for r in crm_objects:
            if r.get("portal_id") == portal_id and r.get("object_type") == "notes":
                hs = r.get("hubspot_object_id")
                try:
                    mx = max(mx, int(str(hs)))
                except Exception:
                    continue
        return str(mx + 1)

    def _make_internal_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    obj_by_hs = {}
    for o in crm_objects:
        if o.get("portal_id") == portal_id:
            obj_by_hs[(o.get("object_type"), str(o.get("hubspot_object_id")))] = o

    results = []
    errors = []
    created_any = False

    for idx, item in enumerate(inputs):
        # Validate structure
        if not isinstance(item, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object"}})
            continue
        if "properties" not in item or not isinstance(item["properties"], dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must include properties object"}})
            continue
        props_in = item["properties"]
        if "hs_note_body" not in props_in or not isinstance(props_in.get("hs_note_body"), str) or props_in.get("hs_note_body") == "":
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "properties.hs_note_body is required and must be a non-empty string"}})
            continue

        # Validate properties against definitions if present (unknown properties disallowed here)
        if enforce_defs:
            unknown = [k for k in props_in.keys() if k not in prop_def_by_name]
            if unknown:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": f"Unknown properties for notes: {', '.join(sorted(unknown))}", "unknownProperties": sorted(unknown)}})
                continue
            bad = []
            for k, d in prop_def_by_name.items():
                if k in props_in:
                    if d.get("status") == "archived" or d.get("archived") is True:
                        bad.append(k)
                    if d.get("hidden") is True:
                        # no portal policy collection provided; default forbid hidden writes when definitions exist
                        bad.append(k)
            if bad:
                bad = sorted(set(bad))
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": f"Attempted to write archived/hidden properties: {', '.join(bad)}", "properties": bad}})
                continue

        # Validate associations payload; atomic per item: validate all first
        assoc_payload = item.get("associations", [])
        if assoc_payload is None:
            assoc_payload = []
        if not isinstance(assoc_payload, list):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array when provided"}})
            continue

        # Build list of association edge mutations for this note (deferred until note created)
        assoc_plans = []
        assoc_validation_error = None
        for a in assoc_payload:
            if not isinstance(a, dict) or "to" not in a or "types" not in a:
                assoc_validation_error = "Each association must include to and types"
                break
            to = a["to"]
            types = a["types"]
            if not isinstance(to, dict) or "id" not in to or not isinstance(to["id"], str) or not to["id"].strip():
                assoc_validation_error = "association.to.id must be a non-empty string"
                break
            if not isinstance(types, list) or len(types) == 0:
                assoc_validation_error = "association.types must be a non-empty array"
                break
            # resolve target object by hubspot id across allowed types
            target_obj = None
            for ot in ("contacts", "companies", "deals", "tickets", "products", "line_items", "quotes", "custom", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements"):
                cand = obj_by_hs.get((ot, str(to["id"])))
                if cand and cand.get("portal_id") == portal_id:
                    target_obj = cand
                    break
            if not target_obj:
                assoc_validation_error = f"Associated object to.id={to['id']} not found"
                break

            for tp in types:
                if not isinstance(tp, dict) or "associationCategory" not in tp or "associationTypeId" not in tp:
                    assoc_validation_error = "Each association type must include associationCategory and associationTypeId"
                    break
                cat = tp["associationCategory"]
                atid = tp["associationTypeId"]
                if not isinstance(cat, str) or not cat:
                    assoc_validation_error = "associationCategory must be a non-empty string"
                    break
                if not isinstance(atid, (int, float)) or int(atid) != atid or int(atid) < 1:
                    assoc_validation_error = "associationTypeId must be a positive integer"
                    break
                atid = int(atid)
                # Validate association type exists and active for (notes -> target_type) OR (target_type -> notes)
                tup1 = ("notes", target_obj.get("object_type"), cat, atid)
                tup2 = (target_obj.get("object_type"), "notes", cat, atid)
                if tup1 not in active_assoc_type and tup2 not in active_assoc_type:
                    assoc_validation_error = f"Association type not found/active for notes<->{target_obj.get('object_type')} category={cat} typeId={atid}"
                    break
                assoc_plans.append(
                    {
                        "target_internal_id": target_obj.get("id"),
                        "target_type": target_obj.get("object_type"),
                        "association_category": cat,
                        "association_type_id": atid,
                        "direction": "notes_to_target" if tup1 in active_assoc_type else "target_to_notes",
                    }
                )
            if assoc_validation_error:
                break

        if assoc_validation_error:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": assoc_validation_error}})
            continue

        # Create the note (atomic with its associations)
        hs_id = _next_hubspot_id_for_notes()
        internal_id = _make_internal_id("obj")

        now = _now()
        new_row = {
            "id": internal_id,
            "portal_id": portal_id,
            "object_type": "notes",
            "hubspot_object_id": hs_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props_in),
            "properties_version": 1,
            "search_text": None,
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        # Enforce uniqueness constraint (portal_id, object_type, hubspot_object_id)
        if any((r.get("portal_id") == portal_id and r.get("object_type") == "notes" and str(r.get("hubspot_object_id")) == hs_id) for r in crm_objects):
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": "Generated note id collided; retry"}})
            continue

        # Prepare association edges (upsert active; reactivate if archived) using internal IDs
        assoc_mutations = []
        for plan in assoc_plans:
            if plan["direction"] == "notes_to_target":
                from_id, to_id = internal_id, plan["target_internal_id"]
                from_type, to_type = "notes", plan["target_type"]
            else:
                from_id, to_id = plan["target_internal_id"], internal_id
                from_type, to_type = plan["target_type"], "notes"

            # constraint from_object_id != to_object_id
            if from_id == to_id:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Association from and to cannot be the same object"}})
                assoc_mutations = None
                break

            assoc_mutations.append(
                {
                    "from_object_id": from_id,
                    "to_object_id": to_id,
                    "from_object_type": from_type,
                    "to_object_type": to_type,
                    "association_category": plan["association_category"],
                    "association_type_id": plan["association_type_id"],
                }
            )
        if assoc_mutations is None:
            continue

        # Commit this item: append object + upsert associations (reactivate archived)
        crm_objects.append(new_row)
        obj_by_hs[("notes", hs_id)] = new_row
        created_any = True

        for m in assoc_mutations:
            existing = None
            for e in crm_assocs:
                if (
                    e.get("portal_id") == portal_id
                    and e.get("from_object_id") == m["from_object_id"]
                    and e.get("to_object_id") == m["to_object_id"]
                    and e.get("association_category") == m["association_category"]
                    and int(e.get("association_type_id") or 0) == int(m["association_type_id"])
                ):
                    existing = e
                    break
            if existing:
                # upsert active associations: reactivate if archived
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = now
                # else already active: idempotent, no change
            else:
                crm_assocs.append(
                    {
                        "id": _make_internal_id("asc"),
                        "portal_id": portal_id,
                        "from_object_id": m["from_object_id"],
                        "to_object_id": m["to_object_id"],
                        "from_object_type": m["from_object_type"],
                        "to_object_type": m["to_object_type"],
                        "association_category": m["association_category"],
                        "association_type_id": int(m["association_type_id"]),
                        "status": "active",
                        "archived": False,
                        "created_at": now,
                        "updated_at": now,
                    }
                )

        # Response record
        results.append(
            {
                "id": hs_id,
                "properties": dict(new_row["properties"]),
                "createdAt": new_row["hubspot_created_at"],
                "updatedAt": new_row["hubspot_updated_at"],
                "archived": False,
            }
        )

    # Persist if any created/changed
    if created_any:
        _save("crm_objects.json", crm_objects)
        _save("crm_associations.json", crm_assocs)

    status = "ok" if len(errors) == 0 else ("partial" if len(results) > 0 else "error")
    _log(status, endpoint, f"portal_id={portal_id} created={len(results)} errors={len(errors)} in {int((time.time()-t0)*1000)}ms")

    return {
        "status": status,
        "results": results,
        "errors": errors,
        "numCreated": len(results),
        "numErrors": len(errors),
    }

def notes_batch_read(inputs, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "notes_batch_read"
    used_portal_id = None
    status_code = "SUCCESS"

    def _log(status, portal_id=None, error_code=None):
        nonlocal used_portal_id
        used_portal_id = used_portal_id or portal_id
        logs = _load("request_logs.json")
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    # Resolve tenant context (ambient auth): pick any existing portal
    objs = _load("crm_objects.json")
    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        status_code = "UNAUTHORIZED"
        _log("ERROR", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available.")
    portal_id = portal_ids[0]

    # Validate inputs
    if not isinstance(inputs, list):
        status_code = "VALIDATION_ERROR"
        _log("ERROR", portal_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be an array.")
    allowed_assoc = {"contacts", "companies", "deals", "tickets"}

    # Build indexes
    obj_by_type_and_hsid = {}
    for r in objs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        key = (r.get("object_type"), r.get("hubspot_object_id"))
        if key[0] and key[1]:
            obj_by_type_and_hsid[key] = r

    # Notes rows by hubspot_object_id (note id param maps here)
    notes_rows = {}
    for r in objs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("object_type") != "notes":
            continue
        notes_rows[r.get("hubspot_object_id")] = r

    assoc_edges = _load("crm_associations.json")

    results = []
    errors = []

    # Helper: return associated object hubspot IDs for requested types
    def _assoc_for_note(note_row, assoc_types):
        out = {}
        if not assoc_types:
            return out
        note_internal_id = note_row.get("id")
        if not note_internal_id:
            return out
        # Only active, non-archived edges; join to non-archived target objects
        for at in assoc_types:
            out[at] = []
        for e in assoc_edges:
            if not isinstance(e, dict):
                continue
            if e.get("portal_id") != portal_id:
                continue
            if e.get("status") != "active" or e.get("archived") is True:
                continue
            if e.get("from_object_id") != note_internal_id and e.get("to_object_id") != note_internal_id:
                continue

            # Determine other side
            if e.get("from_object_id") == note_internal_id:
                other_id = e.get("to_object_id")
                other_type = e.get("to_object_type")
            else:
                other_id = e.get("from_object_id")
                other_type = e.get("from_object_type")

            if other_type not in assoc_types:
                continue

            # Join to object row
            other = None
            # build internal index lazily
            # scan objs for matching internal id within portal (small store)
            for r in objs:
                if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("id") == other_id:
                    other = r
                    break
            if not other:
                continue
            if other.get("status") != "active" or other.get("archived") is True:
                continue
            out[other_type].append(other.get("hubspot_object_id"))
        # De-dupe
        for k in list(out.keys()):
            out[k] = [x for i, x in enumerate(out[k]) if x is not None and x not in out[k][:i]]
        return out

    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append(
                {
                    "index": idx,
                    "id": None,
                    "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."},
                }
            )
            continue

        if "id" not in item or not isinstance(item.get("id"), str) or not item.get("id"):
            errors.append(
                {
                    "index": idx,
                    "id": item.get("id") if isinstance(item.get("id"), str) else None,
                    "error": {"code": "VALIDATION_ERROR", "message": "Each input must include a non-empty string id."},
                }
            )
            continue

        req_props = item.get("properties")
        if req_props is not None:
            if not isinstance(req_props, list) or any(not isinstance(p, str) or not p for p in req_props):
                errors.append(
                    {
                        "index": idx,
                        "id": item.get("id"),
                        "error": {"code": "VALIDATION_ERROR", "message": "properties must be an array of strings."},
                    }
                )
                continue

        req_assoc = item.get("associations")
        if req_assoc is not None:
            if not isinstance(req_assoc, list) or any(a not in allowed_assoc for a in req_assoc):
                errors.append(
                    {
                        "index": idx,
                        "id": item.get("id"),
                        "error": {
                            "code": "VALIDATION_ERROR",
                            "message": "associations must be an array with values in ['contacts','companies','deals','tickets'].",
                        },
                    }
                )
                continue

        note_id = item["id"]
        note_row = notes_rows.get(note_id)
        if not note_row or note_row.get("portal_id") != portal_id:
            errors.append(
                {"index": idx, "id": note_id, "error": {"code": "NOT_FOUND", "message": "Note not found."}}
            )
            continue
        if note_row.get("status") != "active" or note_row.get("archived") is True:
            # Treat archived note as not found for read (since list/search exclude archived unless requested)
            errors.append(
                {"index": idx, "id": note_id, "error": {"code": "NOT_FOUND", "message": "Note not found."}}
            )
            continue

        props = note_row.get("properties") if isinstance(note_row.get("properties"), dict) else {}
        if req_props is not None:
            props = {k: props.get(k) for k in req_props}

        out = {
            "id": note_row.get("hubspot_object_id"),
            "properties": props,
            "createdAt": note_row.get("hubspot_created_at") or note_row.get("created_at"),
            "updatedAt": note_row.get("hubspot_updated_at") or note_row.get("updated_at"),
            "archived": bool(note_row.get("archived")),
        }

        if req_assoc:
            out["associations"] = _assoc_for_note(note_row, req_assoc)

        results.append(out)

    body = {"results": results}
    if errors:
        body["errors"] = errors

    _log("OK", portal_id, None)
    return body

def notes_batch_update(inputs, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "notes_batch_update"
    used_portal_id = None

    def _log(status, portal_id=None, error_code=None):
        nonlocal used_portal_id
        used_portal_id = used_portal_id or portal_id
        logs = _load("request_logs.json")
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    objs = _load("crm_objects.json")
    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        _log("ERROR", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available.")
    portal_id = portal_ids[0]

    # Validate top-level
    if not isinstance(inputs, list):
        _log("ERROR", portal_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be an array.")

    # Load note property definitions (if exist) to enforce archived/hidden restrictions on update
    prop_defs = _load("crm_object_properties.json")
    defs_by_name = {}
    for d in prop_defs:
        if not isinstance(d, dict):
            continue
        if d.get("portal_id") != portal_id or d.get("object_type") != "notes":
            continue
        if isinstance(d.get("name"), str):
            defs_by_name[d["name"]] = d

    # Portal policy (default permissive unless a policy file indicates otherwise)
    policy = {"allow_additional_properties": True, "forbid_hidden_fields": False}
    for row in _load("portal_policies.json"):
        if isinstance(row, dict) and row.get("portal_id") == portal_id:
            policy.update({k: row.get(k) for k in list(row.keys())})
            break

    # Index notes by hubspot_object_id
    note_idx = {}
    for i, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id or r.get("object_type") != "notes":
            continue
        note_idx[r.get("hubspot_object_id")] = i

    results = []
    errors = []
    mutated = False

    # Validate and apply per item (atomic per item)
    for idx, item in enumerate(inputs):
        if not isinstance(item, dict):
            errors.append(
                {"index": idx, "id": None, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}}
            )
            continue

        _id = item.get("id")
        if not isinstance(_id, str) or not _id:
            errors.append(
                {"index": idx, "id": _id if isinstance(_id, str) else None, "error": {"code": "VALIDATION_ERROR", "message": "id is required and must be a string."}}
            )
            continue

        props = item.get("properties")
        if not isinstance(props, dict):
            errors.append(
                {"index": idx, "id": _id, "error": {"code": "VALIDATION_ERROR", "message": "properties is required and must be an object."}}
            )
            continue

        if "hs_note_body" not in props or not isinstance(props.get("hs_note_body"), str):
            errors.append(
                {"index": idx, "id": _id, "error": {"code": "VALIDATION_ERROR", "message": "properties.hs_note_body is required and must be a string."}}
            )
            continue

        # Validate property names/defs where present
        item_error = None
        for k, v in props.items():
            if not isinstance(k, str) or not k:
                item_error = {"code": "VALIDATION_ERROR", "message": "Property names must be non-empty strings."}
                break
            # Values must be strings for these tools (HS APIs store as string); clearing represented by empty string
            if v is not None and not isinstance(v, str):
                item_error = {"code": "VALIDATION_ERROR", "message": f"Property '{k}' value must be a string."}
                break

            d = defs_by_name.get(k)
            if d:
                if d.get("status") == "archived" or d.get("archived") is True:
                    item_error = {"code": "VALIDATION_ERROR", "message": f"Property '{k}' is archived and cannot be updated."}
                    break
                if policy.get("forbid_hidden_fields") and (d.get("hidden") is True):
                    item_error = {"code": "VALIDATION_ERROR", "message": f"Property '{k}' is hidden and cannot be updated."}
                    break
            else:
                if defs_by_name and not policy.get("allow_additional_properties", True):
                    item_error = {"code": "VALIDATION_ERROR", "message": f"Unknown property '{k}' is not allowed."}
                    break

        if item_error:
            errors.append({"index": idx, "id": _id, "error": item_error})
            continue

        note_pos = note_idx.get(_id)
        if note_pos is None:
            errors.append({"index": idx, "id": _id, "error": {"code": "NOT_FOUND", "message": "Note not found."}})
            continue

        row = objs[note_pos]
        if row.get("status") != "active" or row.get("archived") is True:
            errors.append({"index": idx, "id": _id, "error": {"code": "NOT_FOUND", "message": "Note not found."}})
            continue

        # Apply update
        current_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        new_props = dict(current_props)
        for k, v in props.items():
            # Empty string means clear
            if isinstance(v, str) and v == "":
                if k in new_props:
                    new_props[k] = ""
                else:
                    new_props[k] = ""
            else:
                new_props[k] = v

        row["properties"] = new_props
        row["properties_version"] = int(row.get("properties_version") or 0) + 1
        if row["properties_version"] < 1:
            row["properties_version"] = 1
        row["updated_at"] = _now()
        row["hubspot_updated_at"] = row["updated_at"]
        objs[note_pos] = row
        mutated = True

        results.append(
            {
                "id": row.get("hubspot_object_id"),
                "properties": row.get("properties"),
                "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
                "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
                "archived": bool(row.get("archived")),
            }
        )

    if mutated:
        _save("crm_objects.json", objs)

    body = {"results": results}
    if errors:
        body["errors"] = errors

    _log("OK", portal_id, None)
    return body

def notes_batch_archive(noteIds, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "notes_batch_archive"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _now(),
                "endpoint": endpoint,
                "portal_id": portal_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    objs = _load("crm_objects.json")
    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        _log("ERROR", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No portal context available.")
    portal_id = portal_ids[0]

    if not isinstance(noteIds, list):
        _log("ERROR", portal_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "noteIds must be an array of strings.")
    for n in noteIds:
        if not isinstance(n, str) or not n:
            _log("ERROR", portal_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "noteIds must contain only non-empty strings.")

    # Permission check (no explicit tool credential); if policy has can_archive_notes false -> UNAUTHORIZED
    for row in _load("portal_policies.json"):
        if isinstance(row, dict) and row.get("portal_id") == portal_id:
            if row.get("can_archive_notes") is False:
                _log("ERROR", portal_id, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Caller lacks permission to archive notes.")
            break

    # index notes
    note_pos = {}
    for i, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id or r.get("object_type") != "notes":
            continue
        note_pos[r.get("hubspot_object_id")] = i

    results = []
    errors = []
    mutated = False
    now = _now()

    for idx, nid in enumerate(noteIds):
        pos = note_pos.get(nid)
        if pos is None:
            errors.append({"index": idx, "id": nid, "error": {"code": "NOT_FOUND", "message": "Note not found."}})
            continue

        row = objs[pos]
        if row.get("status") == "archived" or row.get("archived") is True:
            errors.append({"index": idx, "id": nid, "error": {"code": "CONFLICT", "message": "Note is already archived."}})
            continue

        # Transition active -> archived
        row["status"] = "archived"
        row["archived"] = True
        row["updated_at"] = now
        row["hubspot_updated_at"] = now
        row["properties_version"] = int(row.get("properties_version") or 0) + 1
        if row["properties_version"] < 1:
            row["properties_version"] = 1
        objs[pos] = row
        mutated = True
        results.append({"id": nid, "archived": True})

    if mutated:
        _save("crm_objects.json", objs)

    body = {"results": results}
    if errors:
        body["errors"] = errors

    _log("OK", portal_id, None)
    return body

def tasks_create(properties, associations=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_like(v, field_name):
        # Accept ISO-8601 strings or ms epoch numeric strings; return normalized string
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field_name} must be a string")
        s = v.strip()
        if s == "":
            return ""  # allow clearing semantics
        # epoch ms?
        if s.isdigit():
            try:
                ms = int(s)
                if ms < 0:
                    return _err("VALIDATION_ERROR", f"{field_name} epoch must be non-negative")
                dt = datetime.datetime.utcfromtimestamp(ms / 1000.0).replace(microsecond=0)
                return dt.isoformat() + "Z"
            except ValueError:
                return _err("VALIDATION_ERROR", f"{field_name} is malformed")
        # ISO-ish
        try:
            # Support trailing Z
            if s.endswith("Z"):
                core = s[:-1]
                dt = datetime.datetime.fromisoformat(core)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                dt = dt.replace(microsecond=0)
                return dt.isoformat() + "Z"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            dt = dt.replace(microsecond=0)
            return dt.isoformat() + "Z"
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field_name} is malformed")

    def _log_call(portal_id, status, latency_ms, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "hubspot_mcp",
            "endpoint": "tasks_create",
            "portal_id": portal_id,
            "credential_id": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_portal_id_for_call():
        # Ambient auth: choose any portal_id that can satisfy prerequisites (none beyond existence).
        objs = _load("crm_objects.json")
        props = _load("crm_object_properties.json")
        assoc_types = _load("crm_association_types.json")
        subs = _load("communications_subscriptions.json")
        # Prefer portal with tasks property definitions if present; otherwise any portal present anywhere.
        portal_candidates = []
        for r in props:
            if r.get("object_type") == "tasks":
                portal_candidates.append(r.get("portal_id"))
        for coll in (objs, assoc_types, subs, props):
            for r in coll:
                pid = r.get("portal_id")
                if pid and pid not in portal_candidates:
                    portal_candidates.append(pid)
        return portal_candidates[0] if portal_candidates else None

    t0 = time.time()
    portal_id = _pick_portal_id_for_call()
    if not portal_id:
        latency = int((time.time() - t0) * 1000)
        # no portal to operate on
        _log_call(None, "UNAUTHORIZED", latency, detail="no_portal_context")
        return _err("UNAUTHORIZED", "No authorized portal context available")

    # Rate limit / quota enforcement if config exists.
    rl = _load("rate_limits.json")
    now_ts = datetime.datetime.utcnow()
    for rule in rl:
        if rule.get("portal_id") not in (None, portal_id):
            continue
        if rule.get("endpoint") not in (None, "tasks_create"):
            continue
        window_sec = rule.get("window_seconds")
        limit = rule.get("limit")
        if isinstance(window_sec, int) and isinstance(limit, int) and window_sec > 0 and limit >= 0:
            logs = _load("request_logs.json")
            cutoff = now_ts - datetime.timedelta(seconds=window_sec)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                if r.get("endpoint") != "tasks_create":
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
                    except ValueError:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= limit:
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "RATE_LIMIT", latency, detail={"window_seconds": window_sec, "limit": limit})
                return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_sec, limit=limit)

    # Validate inputs
    if not isinstance(properties, dict):
        latency = int((time.time() - t0) * 1000)
        _log_call(portal_id, "VALIDATION_ERROR", latency, detail="properties_not_object")
        return _err("VALIDATION_ERROR", "properties must be an object")

    required = ["hs_task_body", "hs_task_subject"]
    missing = [k for k in required if k not in properties or not isinstance(properties.get(k), str) or properties.get(k).strip() == ""]
    if missing:
        latency = int((time.time() - t0) * 1000)
        _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"missing": missing})
        return _err("VALIDATION_ERROR", "Missing required task properties", missing=missing)

    priority = properties.get("hs_task_priority")
    if priority is not None:
        if not isinstance(priority, str):
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="priority_type")
            return _err("VALIDATION_ERROR", "hs_task_priority must be a string")
        if priority not in ("HIGH", "MEDIUM", "LOW") and priority != "":
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="priority_enum")
            return _err("VALIDATION_ERROR", "hs_task_priority is invalid", allowed=["HIGH", "MEDIUM", "LOW"])

    status = properties.get("hs_task_status")
    if status is not None:
        if not isinstance(status, str):
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="status_type")
            return _err("VALIDATION_ERROR", "hs_task_status must be a string")
        if status not in ("NOT_STARTED", "IN_PROGRESS", "WAITING", "COMPLETED", "DEFERRED") and status != "":
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="status_enum")
            return _err(
                "VALIDATION_ERROR",
                "hs_task_status is invalid",
                allowed=["NOT_STARTED", "IN_PROGRESS", "WAITING", "COMPLETED", "DEFERRED"],
            )

    for f in ("hs_timestamp", "hs_task_due_date"):
        if f in properties and properties.get(f) is not None:
            parsed = _parse_dt_like(properties.get(f), f)
            if isinstance(parsed, dict) and "error" in parsed:
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, parsed["error"]["code"], latency, detail={"field": f})
                return parsed
            properties[f] = parsed

    if "hubspot_owner_id" in properties and properties.get("hubspot_owner_id") is not None:
        if not isinstance(properties.get("hubspot_owner_id"), str):
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="owner_type")
            return _err("VALIDATION_ERROR", "hubspot_owner_id must be a string")

    if "hs_task_type" in properties and properties.get("hs_task_type") is not None:
        if not isinstance(properties.get("hs_task_type"), str):
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="type_type")
            return _err("VALIDATION_ERROR", "hs_task_type must be a string")

    # Validate against property definitions when they exist for this portal/object_type
    prop_defs = _load("crm_object_properties.json")
    defs = [d for d in prop_defs if d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}

    # If there are definitions, enforce archived/hidden constraints. Unknown properties are allowed (additionalProperties).
    for k, v in properties.items():
        if k in defs_by_name:
            d = defs_by_name[k]
            if d.get("archived") is True or d.get("status") == "archived":
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"archived_property": k})
                return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be set")
            if d.get("hidden") is True:
                # Portal policy could allow; no policy store given, default forbid hidden
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"hidden_property": k})
                return _err("VALIDATION_ERROR", f"Property '{k}' is hidden and cannot be set")
        # basic JSON-schema type hints for known ones already enforced; others allow any JSON value

    # Validate associations payload
    if associations is not None:
        if not isinstance(associations, list):
            latency = int((time.time() - t0) * 1000)
            _log_call(portal_id, "VALIDATION_ERROR", latency, detail="associations_not_array")
            return _err("VALIDATION_ERROR", "associations must be an array")
        for i, a in enumerate(associations):
            if not isinstance(a, dict):
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i})
                return _err("VALIDATION_ERROR", "Each association must be an object", index=i)
            to = a.get("to")
            types = a.get("types")
            if not isinstance(to, dict) or not isinstance(to.get("id"), str) or to.get("id").strip() == "":
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "field": "to.id"})
                return _err("VALIDATION_ERROR", "Association 'to.id' must be a non-empty string", index=i)
            if not isinstance(types, list) or len(types) == 0:
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "field": "types"})
                return _err("VALIDATION_ERROR", "Association 'types' must be a non-empty array", index=i)
            for j, t in enumerate(types):
                if not isinstance(t, dict):
                    latency = int((time.time() - t0) * 1000)
                    _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "type_index": j})
                    return _err("VALIDATION_ERROR", "Association type must be an object", index=i, type_index=j)
                if not isinstance(t.get("associationCategory"), str) or t.get("associationCategory").strip() == "":
                    latency = int((time.time() - t0) * 1000)
                    _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "type_index": j, "field": "associationCategory"})
                    return _err("VALIDATION_ERROR", "associationCategory must be a non-empty string", index=i, type_index=j)
                if not isinstance(t.get("associationTypeId"), (int, float)) or int(t.get("associationTypeId")) < 1:
                    latency = int((time.time() - t0) * 1000)
                    _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "type_index": j, "field": "associationTypeId"})
                    return _err("VALIDATION_ERROR", "associationTypeId must be a number >= 1", index=i, type_index=j)

    # Load objects for FK checks
    objs = _load("crm_objects.json")

    # Create task object
    now = _now()

    # Generate new hubspot_object_id for tasks within portal (monotonic-ish)
    max_num = 0
    for r in objs:
        if r.get("portal_id") == portal_id and r.get("object_type") == "tasks":
            hid = r.get("hubspot_object_id")
            if isinstance(hid, str) and hid.isdigit():
                n = int(hid)
                if n > max_num:
                    max_num = n
    hubspot_object_id = str(max_num + 1) if max_num > 0 else str(int(time.time() * 1000))

    # Ensure unique(portal_id, object_type, hubspot_object_id)
    for r in objs:
        if r.get("portal_id") == portal_id and r.get("object_type") == "tasks" and r.get("hubspot_object_id") == hubspot_object_id:
            hubspot_object_id = str(int(time.time() * 1000) + 1)

    task_row_id = "obj_" + uuid.uuid4().hex

    # Build search_text
    def _mk_search_text(props):
        parts = []
        for k, v in props.items():
            if v is None:
                continue
            if isinstance(v, (str, int, float, bool)):
                parts.append(str(v))
        return " ".join(parts).lower() if parts else None

    task_row = {
        "id": task_row_id,
        "portal_id": portal_id,
        "object_type": "tasks",
        "hubspot_object_id": hubspot_object_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": properties,
        "properties_version": 1,
        "search_text": _mk_search_text(properties),
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Validate object constraints before writing
    if task_row["properties_version"] < 1:
        latency = int((time.time() - t0) * 1000)
        _log_call(portal_id, "VALIDATION_ERROR", latency, detail="properties_version")
        return _err("VALIDATION_ERROR", "properties_version must be >= 1")

    # Prepare association edges to write (validate association type existence & target object existence)
    assoc_type_defs = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")
    edges_to_upsert = []

    if associations:
        # Build target lookup by hubspot_object_id within portal (tool 'to.id' is HubSpot object id)
        for i, a in enumerate(associations):
            to_hs_id = a["to"]["id"].strip()
            # Find a unique active/non-archived object in this portal with that hubspot_object_id (any type).
            targets = [r for r in objs if r.get("portal_id") == portal_id and r.get("hubspot_object_id") == to_hs_id]
            if len(targets) == 0:
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "NOT_FOUND", latency, detail={"assoc_index": i, "to": to_hs_id})
                return _err("NOT_FOUND", f"Associated object not found: {to_hs_id}", index=i)
            if len(targets) > 1:
                latency = int((time.time() - t0) * 1000)
                _log_call(portal_id, "CONFLICT", latency, detail={"assoc_index": i, "to": to_hs_id})
                return _err("CONFLICT", f"Associated object id is ambiguous in this portal: {to_hs_id}", index=i)

            target = targets[0]
            to_object_id = target["id"]
            to_object_type = target["object_type"]

            for j, t in enumerate(a["types"]):
                cat = t["associationCategory"]
                atid = int(t["associationTypeId"])
                # Validate association type exists and is active for this portal and type pair
                ok = False
                for d in assoc_type_defs:
                    if d.get("portal_id") != portal_id:
                        continue
                    if d.get("from_object_type") != "tasks":
                        continue
                    if d.get("to_object_type") != to_object_type:
                        continue
                    if d.get("association_category") != cat:
                        continue
                    if int(d.get("association_type_id", -1)) != atid:
                        continue
                    if d.get("status") != "active":
                        break
                    ok = True
                    break
                if not ok:
                    latency = int((time.time() - t0) * 1000)
                    _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "type_index": j, "from": "tasks", "to": to_object_type, "cat": cat, "atid": atid})
                    return _err(
                        "VALIDATION_ERROR",
                        "Association type is not defined or not active for this portal",
                        index=i,
                        type_index=j,
                        from_object_type="tasks",
                        to_object_type=to_object_type,
                        associationCategory=cat,
                        associationTypeId=atid,
                    )

                if to_object_id == task_row_id:
                    latency = int((time.time() - t0) * 1000)
                    _log_call(portal_id, "VALIDATION_ERROR", latency, detail={"assoc_index": i, "type_index": j, "self_edge": True})
                    return _err("VALIDATION_ERROR", "from_object_id must not equal to_object_id", index=i, type_index=j)

                edges_to_upsert.append(
                    {
                        "portal_id": portal_id,
                        "from_object_id": task_row_id,
                        "to_object_id": to_object_id,
                        "from_object_type": "tasks",
                        "to_object_type": to_object_type,
                        "association_category": cat,
                        "association_type_id": atid,
                    }
                )

    # Persist task + associations (atomic for this single create)
    objs.append(task_row)

    for e in edges_to_upsert:
        # upsert active: if exists archived, reactivate; else create
        existing = None
        for r in assocs:
            if (
                r.get("portal_id") == e["portal_id"]
                and r.get("from_object_id") == e["from_object_id"]
                and r.get("to_object_id") == e["to_object_id"]
                and r.get("association_category") == e["association_category"]
                and int(r.get("association_type_id", -1)) == int(e["association_type_id"])
            ):
                existing = r
                break
        if existing:
            # reactivate if needed; otherwise keep active
            if existing.get("status") == "archived" or existing.get("archived") is True:
                existing["status"] = "active"
                existing["archived"] = False
            existing["updated_at"] = now
        else:
            assocs.append(
                {
                    "id": "asc_" + uuid.uuid4().hex,
                    "portal_id": e["portal_id"],
                    "from_object_id": e["from_object_id"],
                    "to_object_id": e["to_object_id"],
                    "from_object_type": e["from_object_type"],
                    "to_object_type": e["to_object_type"],
                    "association_category": e["association_category"],
                    "association_type_id": e["association_type_id"],
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now,
                }
            )

    _save("crm_objects.json", objs)
    if edges_to_upsert:
        _save("crm_associations.json", assocs)

    latency = int((time.time() - t0) * 1000)
    _log_call(portal_id, "SUCCESS", latency)

    # Return created task in a HubSpot-like envelope
    return {
        "id": task_row["hubspot_object_id"],
        "objectType": "tasks",
        "archived": task_row["archived"],
        "properties": task_row["properties"],
        "createdAt": task_row["hubspot_created_at"],
        "updatedAt": task_row["hubspot_updated_at"],
        "propertiesVersion": task_row["properties_version"],
    }

def tasks_get(taskId, properties=None, associations=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "SUCCESS"
    portal_id_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, portal_id=None, detail=None):
        nonlocal status_code, portal_id_used
        portal_id_used = portal_id_used or portal_id
        status_code = status
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "portal_id": portal_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _enforce_limits(portal_id):
        cfg = _load("portal_policies.json")
        pol = next((p for p in cfg if p.get("portal_id") == portal_id), None)
        # Rate limit
        if pol and isinstance(pol.get("rate_limit_per_minute"), (int, float)) and pol["rate_limit_per_minute"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["rate_limit_per_minute"]:
                return _err("RATE_LIMIT", "Rate limit exceeded", portal_id=portal_id)
        # Daily quota
        if pol and isinstance(pol.get("quota_per_day"), (int, float)) and pol["quota_per_day"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["quota_per_day"]:
                return _err("QUOTA_EXCEEDED", "Quota exceeded", portal_id=portal_id)
        return None

    def _select_portal():
        objs = _load("crm_objects.json")
        # Prefer portal that has tasks present; otherwise any portal from any collection.
        for o in objs:
            if o.get("object_type") == "tasks":
                return o.get("portal_id")
        for o in objs:
            if o.get("portal_id"):
                return o.get("portal_id")
        # maybe only properties/types exist
        for p in _load("crm_object_properties.json"):
            if p.get("portal_id"):
                return p.get("portal_id")
        for a in _load("crm_association_types.json"):
            if a.get("portal_id"):
                return a.get("portal_id")
        return None

    def _validate_task_props(portal_id, requested_props):
        if requested_props is None:
            return None
        if not isinstance(requested_props, list) or any(not isinstance(x, str) for x in requested_props):
            return _err("VALIDATION_ERROR", "properties must be an array of strings")
        defs = [d for d in _load("crm_object_properties.json") if d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
        # Only validate if definitions exist for this portal/object_type
        if defs:
            names = {d.get("name") for d in defs if isinstance(d.get("name"), str)}
            unknown = [p for p in requested_props if p not in names]
            if unknown:
                return _err("VALIDATION_ERROR", "Requested properties contain invalid task properties", invalidProperties=unknown)
        return None

    def _validate_associations(assoc):
        supported = {"contacts", "companies", "deals", "tickets"}
        if assoc is None:
            return None
        if not isinstance(assoc, list) or any((not isinstance(x, str) or x not in supported) for x in assoc):
            return _err("VALIDATION_ERROR", "associations contains unsupported values")
        return None

    try:
        if not isinstance(taskId, str) or not taskId.strip():
            _log("tasks_get", "VALIDATION_ERROR", None, {"field": "taskId"})
            return _err("VALIDATION_ERROR", "taskId is required and must be a non-empty string")
        taskId = taskId.strip()

        portal_id = _select_portal()
        if not portal_id:
            _log("tasks_get", "UNAUTHORIZED", None)
            return _err("UNAUTHORIZED", "No portal context available")

        lim_err = _enforce_limits(portal_id)
        if lim_err:
            _log("tasks_get", lim_err["error"]["code"], portal_id)
            return lim_err

        v1 = _validate_associations(associations)
        if v1:
            _log("tasks_get", "VALIDATION_ERROR", portal_id)
            return v1
        v2 = _validate_task_props(portal_id, properties)
        if v2:
            _log("tasks_get", "VALIDATION_ERROR", portal_id)
            return v2

        objs = _load("crm_objects.json")
        row = next((o for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == "tasks" and str(o.get("hubspot_object_id")) == taskId), None)
        if not row or row.get("status") == "archived" or row.get("archived") is True:
            _log("tasks_get", "NOT_FOUND", portal_id, {"taskId": taskId})
            return _err("NOT_FOUND", "Task not found", taskId=taskId)

        props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        if properties is not None:
            proj = {}
            for k in properties:
                if k in props:
                    proj[k] = props.get(k)
            props_out = proj
        else:
            props_out = props

        result = {
            "id": row.get("hubspot_object_id"),
            "properties": props_out,
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived"))
        }

        if associations:
            assoc_rows = _load("crm_associations.json")
            objs_by_id = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}
            out_assoc = {}
            for assoc_type in associations:
                to_type = assoc_type
                links = []
                for e in assoc_rows:
                    if e.get("portal_id") != portal_id:
                        continue
                    if e.get("status") != "active" or e.get("archived") is True:
                        continue
                    if e.get("from_object_id") != row.get("id"):
                        continue
                    if e.get("from_object_type") != "tasks" or e.get("to_object_type") != to_type:
                        continue
                    to_obj = objs_by_id.get(e.get("to_object_id"))
                    if not to_obj:
                        continue
                    if to_obj.get("status") == "archived" or to_obj.get("archived") is True:
                        continue
                    links.append({"id": to_obj.get("hubspot_object_id")})
                out_assoc[assoc_type] = {"results": links}
            result["associations"] = out_assoc

        _log("tasks_get", "SUCCESS", portal_id, {"taskId": taskId})
        return result
    except Exception as e:
        _log("tasks_get", "CONFLICT", portal_id_used, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error")

def tasks_update(taskId, properties, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    portal_id_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, portal_id=None, detail=None):
        nonlocal portal_id_used
        portal_id_used = portal_id_used or portal_id
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "portal_id": portal_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _enforce_limits(portal_id):
        cfg = _load("portal_policies.json")
        pol = next((p for p in cfg if p.get("portal_id") == portal_id), None)
        if pol and isinstance(pol.get("rate_limit_per_minute"), (int, float)) and pol["rate_limit_per_minute"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["rate_limit_per_minute"]:
                return _err("RATE_LIMIT", "Rate limit exceeded", portal_id=portal_id)
        if pol and isinstance(pol.get("quota_per_day"), (int, float)) and pol["quota_per_day"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["quota_per_day"]:
                return _err("QUOTA_EXCEEDED", "Quota exceeded", portal_id=portal_id)
        return None

    def _select_portal():
        objs = _load("crm_objects.json")
        for o in objs:
            if o.get("object_type") == "tasks":
                return o.get("portal_id")
        for o in objs:
            if o.get("portal_id"):
                return o.get("portal_id")
        for p in _load("crm_object_properties.json"):
            if p.get("portal_id"):
                return p.get("portal_id")
        return None

    def _policy(portal_id):
        pols = _load("portal_policies.json")
        return next((p for p in pols if p.get("portal_id") == portal_id), {}) or {}

    try:
        if not isinstance(taskId, str) or not taskId.strip():
            _log("tasks_update", "VALIDATION_ERROR", None, {"field": "taskId"})
            return _err("VALIDATION_ERROR", "taskId is required and must be a non-empty string")
        if not isinstance(properties, dict):
            _log("tasks_update", "VALIDATION_ERROR", None, {"field": "properties"})
            return _err("VALIDATION_ERROR", "properties must be an object")
        if "hs_task_body" not in properties or "hs_task_subject" not in properties:
            _log("tasks_update", "VALIDATION_ERROR", None, {"missing": ["hs_task_body", "hs_task_subject"]})
            return _err("VALIDATION_ERROR", "Required properties hs_task_body and hs_task_subject are missing")

        # enum validations (only when provided)
        if "hs_task_priority" in properties and properties["hs_task_priority"] is not None:
            if properties["hs_task_priority"] not in {"HIGH", "MEDIUM", "LOW"}:
                _log("tasks_update", "VALIDATION_ERROR", None, {"field": "hs_task_priority"})
                return _err("VALIDATION_ERROR", "Invalid hs_task_priority")
        if "hs_task_status" in properties and properties["hs_task_status"] is not None:
            if properties["hs_task_status"] not in {"NOT_STARTED", "IN_PROGRESS", "WAITING", "COMPLETED", "DEFERRED"}:
                _log("tasks_update", "VALIDATION_ERROR", None, {"field": "hs_task_status"})
                return _err("VALIDATION_ERROR", "Invalid hs_task_status")

        portal_id = _select_portal()
        if not portal_id:
            _log("tasks_update", "UNAUTHORIZED", None)
            return _err("UNAUTHORIZED", "No portal context available")

        lim_err = _enforce_limits(portal_id)
        if lim_err:
            _log("tasks_update", lim_err["error"]["code"], portal_id)
            return lim_err

        pol = _policy(portal_id)
        if pol.get("deny_tasks_write") is True:
            _log("tasks_update", "UNAUTHORIZED", portal_id)
            return _err("UNAUTHORIZED", "Not permitted to update tasks", portal_id=portal_id)

        objs = _load("crm_objects.json")
        idx = None
        for i, o in enumerate(objs):
            if o.get("portal_id") == portal_id and o.get("object_type") == "tasks" and str(o.get("hubspot_object_id")) == taskId.strip():
                idx = i
                break
        if idx is None:
            _log("tasks_update", "NOT_FOUND", portal_id, {"taskId": taskId})
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
        row = objs[idx]
        if row.get("status") == "archived" or row.get("archived") is True:
            _log("tasks_update", "CONFLICT", portal_id, {"taskId": taskId, "reason": "archived"})
            return _err("CONFLICT", "Task is archived", taskId=taskId)

        # Validate property definitions if exist; reject archived/hidden when policy forbids
        defs = [d for d in _load("crm_object_properties.json") if d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
        defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
        if defs:
            for k in properties.keys():
                if not isinstance(k, str):
                    _log("tasks_update", "VALIDATION_ERROR", portal_id, {"field": "properties"})
                    return _err("VALIDATION_ERROR", "Property names must be strings")
                d = defs_by_name.get(k)
                if d is None:
                    # tool schema allows additionalProperties; portal policy may disallow unknown
                    if pol.get("allow_additional_properties") is False:
                        _log("tasks_update", "VALIDATION_ERROR", portal_id, {"invalidProperty": k})
                        return _err("VALIDATION_ERROR", "Unknown property is not allowed", property=k)
                    continue
                if d.get("status") == "archived" or d.get("archived") is True:
                    _log("tasks_update", "VALIDATION_ERROR", portal_id, {"property": k})
                    return _err("VALIDATION_ERROR", "Cannot write to archived property", property=k)
                if pol.get("forbid_hidden_fields") is True and d.get("hidden") is True:
                    _log("tasks_update", "VALIDATION_ERROR", portal_id, {"property": k})
                    return _err("VALIDATION_ERROR", "Cannot write to hidden property", property=k)

        current_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        # Clearing represented by empty string; accept as value
        for k, v in properties.items():
            # ensure JSON-serializable primitives/structures; reject unserializable types
            if isinstance(v, (str, int, float, bool)) or v is None or isinstance(v, (list, dict)):
                current_props[k] = v
            else:
                _log("tasks_update", "VALIDATION_ERROR", portal_id, {"property": k})
                return _err("VALIDATION_ERROR", "Invalid property value type", property=k)

        row["properties"] = current_props
        row["properties_version"] = int(row.get("properties_version") or 0) + 1
        row["updated_at"] = _now()
        row["hubspot_updated_at"] = row["updated_at"]
        # maintain archived/status invariant
        row["archived"] = bool(row.get("status") == "archived")
        # refresh search_text (simple join of stringified values)
        try:
            row["search_text"] = " ".join([str(v) for v in current_props.values() if v is not None])
        except Exception:
            row["search_text"] = row.get("search_text")

        objs[idx] = row
        _save("crm_objects.json", objs)

        out = {
            "id": row.get("hubspot_object_id"),
            "properties": row.get("properties") if isinstance(row.get("properties"), dict) else {},
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived"))
        }
        _log("tasks_update", "SUCCESS", portal_id, {"taskId": taskId})
        return out
    except Exception as e:
        _log("tasks_update", "CONFLICT", portal_id_used, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error")

