        # lifecycle: active -> archived
        row["status"] = "archived"
        row["archived"] = True
        row["updated_at"] = _now()
        row["hubspot_updated_at"] = row["updated_at"]
        row["properties_version"] = int(row.get("properties_version") or 0) + 1
        objs[idx] = row

        # Cascade delete associations referencing this object (schema says on delete cascade; archive isn't delete,
        # but HubSpot archive effectively removes it from active graph; mark those edges archived)
        assocs = _load("crm_associations.json")
        changed = False
        for e in assocs:
            if e.get("portal_id") != portal_id:
