                    e["updated_at"] = _now()
                    changed = True

        _save("crm_objects.json", objs)
        if changed:
            _save("crm_associations.json", assocs)

        _log("tasks_archive", "SUCCESS", portal_id, {"taskId": taskId})
        return {}
    except Exception as e:
        _log("tasks_archive", "CONFLICT", portal_id_used, {"exception": type(e).__name__})
