        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    portal_id_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, portal_id=None, detail=None):
        nonlocal portal_id_used
        portal_id_used = portal_id_used or portal_id
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "status": status,
            "portal_id": portal_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _enforce_limits(portal_id):
        cfg = _load("portal_policies.json")
        pol = next((p for p in cfg if p.get("portal_id") == portal_id), None)
        if pol and isinstance(pol.get("rate_limit_per_minute"), (int, float)) and pol["rate_limit_per_minute"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["rate_limit_per_minute"]:
                return _err("RATE_LIMIT", "Rate limit exceeded", portal_id=portal_id)
        if pol and isinstance(pol.get("quota_per_day"), (int, float)) and pol["quota_per_day"] > 0:
            logs = _load("request_logs.json")
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if r.get("portal_id") != portal_id:
                    continue
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= pol["quota_per_day"]:
                return _err("QUOTA_EXCEEDED", "Quota exceeded", portal_id=portal_id)
        return None

    def _select_portal():
        objs = _load("crm_objects.json")
        for o in objs:
            if o.get("object_type") == "tasks":
                return o.get("portal_id")
        for o in objs:
            if o.get("portal_id"):
                return o.get("portal_id")
        for p in _load("crm_object_properties.json"):
            if p.get("portal_id"):
                return p.get("portal_id")
        return None

    def _validate_task_props(portal_id, requested_props):
        if requested_props is None:
            return None
        if not isinstance(requested_props, list) or any(not isinstance(x, str) for x in requested_props):
            return _err("VALIDATION_ERROR", "properties must be an array of strings")
        defs = [d for d in _load("crm_object_properties.json") if d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
        if defs:
            names = {d.get("name") for d in defs if isinstance(d.get("name"), str)}
            unknown = [p for p in requested_props if p not in names]
            if unknown:
                return _err("VALIDATION_ERROR", "Requested properties contain invalid task properties", invalidProperties=unknown)
        return None

    def _validate_associations(assoc):
        supported = {"contacts", "companies", "deals", "tickets"}
        if assoc is None:
            return None
        if not isinstance(assoc, list) or any((not isinstance(x, str) or x not in supported) for x in assoc):
            return _err("VALIDATION_ERROR", "associations contains unsupported values")
        return None

    try:
        if limit is None:
            limit = 100
        if not isinstance(limit, (int, float)) or int(limit) != limit:
            _log("tasks_list", "VALIDATION_ERROR", None, {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
        limit = int(limit)
        if limit < 1 or limit > 100:
            _log("tasks_list", "VALIDATION_ERROR", None, {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

        if archived is not None and not isinstance(archived, bool):
            _log("tasks_list", "VALIDATION_ERROR", None, {"field": "archived"})
            return _err("VALIDATION_ERROR", "archived must be boolean")

        portal_id = _select_portal()
        if not portal_id:
            _log("tasks_list", "UNAUTHORIZED", None)
            return _err("UNAUTHORIZED", "No portal context available")

        lim_err = _enforce_limits(portal_id)
        if lim_err:
            _log("tasks_list", lim_err["error"]["code"], portal_id)
            return lim_err

        v1 = _validate_associations(associations)
        if v1:
            _log("tasks_list", "VALIDATION_ERROR", portal_id)
            return v1
        v2 = _validate_task_props(portal_id, properties)
        if v2:
            _log("tasks_list", "VALIDATION_ERROR", portal_id)
            return v2

        # after cursor: use hubspot_object_id lexicographic ordering
        after_val = None
        if after is not None:
            if not isinstance(after, str):
                _log("tasks_list", "VALIDATION_ERROR", portal_id, {"field": "after"})
                return _err("VALIDATION_ERROR", "after must be a string")
            after_val = after

        objs = _load("crm_objects.json")
        tasks = [o for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == "tasks"]
        if archived is True:
            # include both active and archived? HubSpot "archived=true" typically returns archived records only.
            tasks = [o for o in tasks if (o.get("status") == "archived" or o.get("archived") is True)]
        else:
            tasks = [o for o in tasks if not (o.get("status") == "archived" or o.get("archived") is True)]

        # sort by hubspot_object_id as stable cursor
        tasks.sort(key=lambda r: str(r.get("hubspot_object_id") or ""))

        if after_val is not None:
            tasks = [r for r in tasks if str(r.get("hubspot_object_id") or "") > after_val]

        page = tasks[:limit]
        has_more = len(tasks) > limit
        next_after = str(page[-1].get("hubspot_object_id")) if (has_more and page) else None

        # Prepare association join helpers
        assoc_rows = _load("crm_associations.json") if associations else []
        objs_by_id = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}

        results = []
        for row in page:
            props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
            if properties is not None:
                proj = {}
                for k in properties:
                    if k in props:
                        proj[k] = props.get(k)
                props_out = proj
            else:
                props_out = props

            item = {
                "id": row.get("hubspot_object_id"),
                "properties": props_out,
                "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
                "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
                "archived": bool(row.get("archived"))
            }

            if associations:
                out_assoc = {}
                for assoc_type in associations:
                    links = []
                    for e in assoc_rows:
                        if e.get("portal_id") != portal_id:
                            continue
                        if e.get("status") != "active" or e.get("archived") is True:
                            continue
                        if e.get("from_object_id") != row.get("id"):
                            continue
                        if e.get("from_object_type") != "tasks" or e.get("to_object_type") != assoc_type:
                            continue
                        to_obj = objs_by_id.get(e.get("to_object_id"))
                        if not to_obj:
                            continue
                        if to_obj.get("status") == "archived" or to_obj.get("archived") is True:
                            continue
                        links.append({"id": to_obj.get("hubspot_object_id")})
                    out_assoc[assoc_type] = {"results": links}
                item["associations"] = out_assoc

            results.append(item)

        resp = {"results": results}
        if has_more:
            resp["paging"] = {"next": {"after": next_after}}
        _log("tasks_list", "SUCCESS", portal_id, {"limit": limit, "after": after})
        return resp
    except Exception as e:
        _log("tasks_list", "CONFLICT", portal_id_used, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error")

def tasks_search(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Ambient auth: choose a portal_id that can serve the call (any existing tenant)
    objs = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")

    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        portal_ids = sorted({r.get("portal_id") for r in props_defs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        # No tenant context available in datastore
        return _err("UNAUTHORIZED", "No portal context available to serve request")

    portal_id = portal_ids[0]

    # Validation
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array")

    if properties is not None and (not isinstance(properties, list) or not all(isinstance(x, str) for x in properties)):
        return _err("VALIDATION_ERROR", "properties must be an array of strings")

    if limit is None:
        limit = 10
    if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
        return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100")
    limit = int(limit)
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    if after is not None and not isinstance(after, str):
        return _err("VALIDATION_ERROR", "after must be a string cursor")

    if sorts is not None:
        if not isinstance(sorts, list):
            return _err("VALIDATION_ERROR", "sorts must be an array")
        for s in sorts:
            if not isinstance(s, dict):
                return _err("VALIDATION_ERROR", "Each sort must be an object")
            if set(s.keys()) - {"propertyName", "direction"}:
                return _err("VALIDATION_ERROR", "Sort contains unsupported fields")
            if "propertyName" not in s or "direction" not in s:
                return _err("VALIDATION_ERROR", "Each sort requires propertyName and direction")
            if not isinstance(s["propertyName"], str) or not s["propertyName"]:
                return _err("VALIDATION_ERROR", "sort.propertyName must be a non-empty string")
            if s["direction"] not in ("ASCENDING", "DESCENDING"):
                return _err("VALIDATION_ERROR", "sort.direction must be ASCENDING or DESCENDING")

    allowed_ops = {
        "EQ", "NEQ", "LT", "LTE", "GT", "GTE",
        "BETWEEN", "IN", "NOT_IN", "HAS_PROPERTY", "NOT_HAS_PROPERTY",
        "CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"
    }

    def _parse_dt(val):
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            # treat as ms epoch if big enough, else seconds
            v = float(val)
            if v > 1e12:
                v = v / 1000.0
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(val, str):
            s = val.strip()
            if not s:
                return None
            # Support ISO8601 with Z
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            try:
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                pass
            # digits as epoch ms/sec
            if re.fullmatch(r"-?\d+", s):
                try:
                    v = int(s)
                    if abs(v) > 1e12:
                        v = v / 1000.0
                    return datetime.datetime.utcfromtimestamp(v)
                except Exception:
                    return None
        return None

    def _coerce_num(val):
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            return float(val)
        if isinstance(val, str):
            try:
                return float(val)
            except Exception:
                return None
        return None

    def _coerce_bool(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            if val.lower() in ("true", "false"):
                return val.lower() == "true"
        return None

    # Build property definition lookup for tasks
    task_prop_defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
    task_prop_by_name = {d.get("name"): d for d in task_prop_defs if d.get("name")}

    def _tokenize(s):
        if not isinstance(s, str):
            return []
        return [t for t in re.split(r"[^A-Za-z0-9_]+", s.lower()) if t]

    def _get_prop_value(obj_props, name):
        if not isinstance(obj_props, dict):
            return None
        return obj_props.get(name)

    def _has_prop(obj_props, name):
        if not isinstance(obj_props, dict):
            return False
        v = obj_props.get(name, None)
        # HubSpot semantics: property exists if key present and value not empty string?
        if name in obj_props and v is not None and v != "":
            return True
        return False

    def _compare(op, lhs, rhs, prop_type=None):
        # Empty string is a valid stored "cleared" marker: treat as absent for comparisons except EQ/NEQ?
        # We'll treat "" as value for EQ/NEQ, but for numeric/date comparisons it fails.
        if op in ("HAS_PROPERTY", "NOT_HAS_PROPERTY"):
            return None  # handled elsewhere

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            if rhs is None:
                return _err("VALIDATION_ERROR", f"{op} requires value")
            if not isinstance(rhs, str):
                rhs = str(rhs)
            tokens_rhs = set(_tokenize(rhs))
            tokens_lhs = set(_tokenize(lhs if isinstance(lhs, str) else ("" if lhs is None else str(lhs))))
            ok = any(t in tokens_lhs for t in tokens_rhs) if tokens_rhs else False
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        if op in ("IN", "NOT_IN"):
            vals = rhs
            if isinstance(vals, list):
                if len(vals) == 0:
                    return _err("VALIDATION_ERROR", f"{op} requires a non-empty values array")
                options = vals
            else:
                options = [vals]
            ok = any((lhs == v) for v in options)
            return ok if op == "IN" else (not ok)

        if op == "BETWEEN":
            if not isinstance(rhs, list) or len(rhs) != 2:
                return _err("VALIDATION_ERROR", "BETWEEN requires a two-value array")
            lo, hi = rhs[0], rhs[1]

            # attempt typed compare
            if prop_type in ("number",):
                a = _coerce_num(lhs)
                b = _coerce_num(lo)
                c = _coerce_num(hi)
                if a is None or b is None or c is None:
                    return _err("VALIDATION_ERROR", "BETWEEN bounds/value must be numeric for number property")
                return b <= a <= c
            if prop_type in ("date", "datetime"):
                a = _parse_dt(lhs)
                b = _parse_dt(lo)
                c = _parse_dt(hi)
                if a is None or b is None or c is None:
                    return _err("VALIDATION_ERROR", "BETWEEN bounds/value must be date/datetime")
                return b <= a <= c

            # fallback string compare
            if lhs is None:
                return False
            return str(lo) <= str(lhs) <= str(hi)

        # Simple compares
        if op in ("LT", "LTE", "GT", "GTE"):
            if prop_type == "number":
                a = _coerce_num(lhs)
                b = _coerce_num(rhs)
                if a is None or b is None:
                    return _err("VALIDATION_ERROR", f"{op} requires numeric comparable values for number property")
                if op == "LT":
                    return a < b
                if op == "LTE":
                    return a <= b
                if op == "GT":
                    return a > b
                if op == "GTE":
                    return a >= b
            if prop_type in ("date", "datetime"):
                a = _parse_dt(lhs)
                b = _parse_dt(rhs)
                if a is None or b is None:
                    return _err("VALIDATION_ERROR", f"{op} requires date/datetime comparable values")
                if op == "LT":
                    return a < b
                if op == "LTE":
                    return a <= b
                if op == "GT":
                    return a > b
                if op == "GTE":
                    return a >= b
            # string fallback
            if lhs is None or rhs is None:
                return False
            if op == "LT":
                return str(lhs) < str(rhs)
            if op == "LTE":
                return str(lhs) <= str(rhs)
            if op == "GT":
                return str(lhs) > str(rhs)
            if op == "GTE":
                return str(lhs) >= str(rhs)

        if op in ("EQ", "NEQ"):
            ok = (lhs == rhs)
            return ok if op == "EQ" else (not ok)

        return _err("VALIDATION_ERROR", f"Unsupported operator: {op}")

    # Validate filterGroups structure
    for gi, g in enumerate(filterGroups):
        if not isinstance(g, dict) or "filters" not in g or set(g.keys()) - {"filters"}:
            return _err("VALIDATION_ERROR", "Each filterGroup must be an object with only 'filters'")
        if not isinstance(g["filters"], list) or len(g["filters"]) == 0:
            return _err("VALIDATION_ERROR", "Each filterGroup.filters must be a non-empty array")
        for fi, flt in enumerate(g["filters"]):
            if not isinstance(flt, dict):
                return _err("VALIDATION_ERROR", "Each filter must be an object")
            if set(flt.keys()) - {"propertyName", "operator", "value"}:
                return _err("VALIDATION_ERROR", "Filter contains unsupported fields")
            if "propertyName" not in flt or "operator" not in flt:
                return _err("VALIDATION_ERROR", "Filter requires propertyName and operator")
            if not isinstance(flt["propertyName"], str) or not flt["propertyName"]:
                return _err("VALIDATION_ERROR", "filter.propertyName must be a non-empty string")
            if flt["operator"] not in allowed_ops:
                return _err("VALIDATION_ERROR", f"Unsupported operator {flt['operator']}")
            op = flt["operator"]
            if op in ("HAS_PROPERTY", "NOT_HAS_PROPERTY"):
                # value optional
                continue
            if "value" not in flt:
                return _err("VALIDATION_ERROR", f"Operator {op} requires value")
            if op == "BETWEEN":
                if not isinstance(flt["value"], list) or len(flt["value"]) != 2:
                    return _err("VALIDATION_ERROR", "BETWEEN requires value as two-element array")
            if op in ("IN", "NOT_IN"):
                v = flt["value"]
                if isinstance(v, list):
                    if len(v) == 0:
                        return _err("VALIDATION_ERROR", f"{op} requires a non-empty array")
                # scalar allowed (singleton)

    # Candidate rows: tasks in portal, non-archived
    candidates = [
        r for r in objs
        if isinstance(r, dict)
        and r.get("portal_id") == portal_id
        and r.get("object_type") == "tasks"
        and r.get("status") == "active"
        and r.get("archived") is False
    ]

    def _matches(obj_row):
        obj_props = obj_row.get("properties") if isinstance(obj_row.get("properties"), dict) else {}
        search_text = obj_row.get("search_text")

        # OR across groups, AND within group
        for g in filterGroups:
            ok_group = True
            for flt in g["filters"]:
                pname = flt["propertyName"]
                op = flt["operator"]
                prop_def = task_prop_by_name.get(pname)
                prop_type = prop_def.get("type") if prop_def else None

                # special: allow searching against denormalized search_text if propertyName == "search_text"
                if pname == "search_text":
                    lhs = search_text
                else:
                    lhs = _get_prop_value(obj_props, pname)

                if op == "HAS_PROPERTY":
                    ok = _has_prop(obj_props, pname) if pname != "search_text" else (isinstance(search_text, str) and search_text != "")
                elif op == "NOT_HAS_PROPERTY":
                    ok = (not _has_prop(obj_props, pname)) if pname != "search_text" else (not (isinstance(search_text, str) and search_text != ""))
                else:
                    rhs = flt.get("value")
                    res = _compare(op, lhs, rhs, prop_type=prop_type)
                    if isinstance(res, dict) and "error" in res:
                        return res
                    ok = bool(res)

                if not ok:
                    ok_group = False
                    break
            if ok_group:
                return True
        return False

    matched = []
    for r in candidates:
        res = _matches(r)
        if isinstance(res, dict) and "error" in res:
            return res
        if res:
            matched.append(r)

    # Sorting
    def _sort_key(row, prop):
        if prop == "createdAt":
            return row.get("created_at") or ""
        if prop == "updatedAt":
            return row.get("updated_at") or ""
        if prop == "hs_object_id":
            return row.get("hubspot_object_id") or ""
        # property in properties dict
        p = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        v = p.get(prop)
        if v is None:
            return ""
        return v

    if sorts:
        # stable multi-sort: apply in reverse order
        for s in reversed(sorts):
            rev = (s["direction"] == "DESCENDING")
            prop = s["propertyName"]
            matched.sort(key=lambda r, pr=prop: _sort_key(r, pr), reverse=rev)
    else:
        # default: updated desc
        matched.sort(key=lambda r: r.get("updated_at") or "", reverse=True)

    # Pagination via "after" cursor, interpreted as offset or last id.
    start = 0
    if after:
        # try numeric offset
        if re.fullmatch(r"\d+", after.strip()):
            start = int(after.strip())
        else:
            # treat as hubspot_object_id cursor
            idx = None
            for i, r in enumerate(matched):
                if str(r.get("hubspot_object_id")) == after or str(r.get("id")) == after:
                    idx = i
                    break
            if idx is not None:
                start = idx + 1

    page = matched[start:start + limit]
    next_cursor = None
    has_more = False
    if start + limit < len(matched):
        has_more = True
        next_cursor = str(start + limit)

    # Projection
    def _to_task_result(row):
        out_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        if properties is not None:
            out_props = {k: out_props.get(k) for k in properties}
        return {
            "id": str(row.get("hubspot_object_id")),
            "properties": out_props,
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived")),
        }

    results = [_to_task_result(r) for r in page]
    latency_ms = int((time.time() - _t0) * 1000)

    # Request log dynamics (best-effort, if file exists)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now,
            "endpoint": "tasks_search",
            "portal_id": portal_id,
            "status": "ok",
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    return {
        "total": len(matched),
        "results": results,
        "paging": {"next": {"after": next_cursor}} if has_more else None
    }

def tasks_batch_create(inputs, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        portal_ids = sorted({r.get("portal_id") for r in prop_defs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        return _err("UNAUTHORIZED", "No portal context available to serve request")
    portal_id = portal_ids[0]

    if not isinstance(inputs, list) or len(inputs) == 0:
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    # Property defs for tasks
    task_defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
    def_by_name = {d.get("name"): d for d in task_defs if d.get("name")}

    allowed_priority = {"HIGH", "MEDIUM", "LOW"}
    allowed_status = {"NOT_STARTED", "IN_PROGRESS", "WAITING", "COMPLETED", "DEFERRED"}

    # Association type validation helper
    def _assoc_type_active(from_type, to_type, cat, tid):
        for r in assoc_types:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("from_object_type") != from_type or r.get("to_object_type") != to_type:
                continue
            if r.get("association_category") != cat:
                continue
            try:
                if float(r.get("association_type_id")) != float(tid):
                    continue
            except Exception:
                continue
            return r.get("status") == "active"
        return False

    # Resolve "to" ids: tool uses HubSpot object ids; map to internal crm_objects.id
    def _resolve_object_internal_id(object_type, hubspot_id):
        for r in objs:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("object_type") != object_type:
                continue
            if str(r.get("hubspot_object_id")) == str(hubspot_id):
                return r.get("id"), r
        return None, None

    # Generate ids
    def _new_internal_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _next_hubspot_id_for_type(obj_type):
        max_id = 0
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == obj_type:
                s = str(r.get("hubspot_object_id") or "")
                if re.fullmatch(r"\d+", s):
                    max_id = max(max_id, int(s))
        return str(max_id + 1 if max_id else int(time.time() * 1000) % 10**12)

    # Validate each item first; build staged writes for atomic per-item behavior
    results = []
    errors = []
    staged = []  # list of dict: {"obj_row":..., "assoc_rows":[...]}
    for idx, item in enumerate(inputs):
        if not isinstance(item, dict) or set(item.keys()) - {"properties", "associations"}:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object with properties and optional associations"}})
            staged.append(None)
            continue
        if "properties" not in item or not isinstance(item["properties"], dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input requires properties object"}})
            staged.append(None)
            continue

        p = item["properties"]
        if "hs_task_body" not in p or "hs_task_subject" not in p:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing required properties hs_task_body and/or hs_task_subject"}})
            staged.append(None)
            continue
        if not isinstance(p.get("hs_task_body"), str) or not isinstance(p.get("hs_task_subject"), str):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "hs_task_body and hs_task_subject must be strings"}})
            staged.append(None)
            continue

        if "hs_task_priority" in p and p["hs_task_priority"] is not None:
            if p["hs_task_priority"] not in allowed_priority:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_task_priority"}})
                staged.append(None)
                continue
        if "hs_task_status" in p and p["hs_task_status"] is not None:
            if p["hs_task_status"] not in allowed_status:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_task_status"}})
                staged.append(None)
                continue

        # Validate property names against definitions when definitions exist
        if len(def_by_name) > 0:
            for k in p.keys():
                d = def_by_name.get(k)
                if d is None:
                    # tool allows additionalProperties, and portal policy unknown => allow
                    continue
                if d.get("status") == "archived" or d.get("archived") is True:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": f"Property '{k}' is archived and cannot be written"}})
                    break
                if d.get("hidden") is True:
                    # portal policy unknown => allow (no evidence to forbid)
                    pass
            else:
                pass
            # If broke due to error
            if errors and errors[-1].get("index") == idx:
                staged.append(None)
                continue

        assoc_rows = []
        if "associations" in item and item["associations"] is not None:
            if not isinstance(item["associations"], list):
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array"}})
                staged.append(None)
                continue
            for a in item["associations"]:
                if not isinstance(a, dict) or set(a.keys()) - {"to", "types"}:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each association must contain to and types"}})
                    break
                to = a.get("to")
                types = a.get("types")
                if not isinstance(to, dict) or set(to.keys()) - {"id"} or "id" not in to or not isinstance(to["id"], str) or not to["id"]:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.to.id must be a string"}})
                    break
                if not isinstance(types, list) or len(types) == 0:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.types must be a non-empty array"}})
                    break

                # Determine target internal object from hubspot id by trying supported types
                target_internal = None
                target_row = None
                target_type = None
                for cand_type in ("contacts", "companies", "deals", "tickets", "products", "line_items", "quotes", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements", "custom"):
                    iid, row = _resolve_object_internal_id(cand_type, to["id"])
                    if iid:
                        target_internal, target_row, target_type = iid, row, cand_type
                        break
                if not target_internal:
                    errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": f"Associated object id {to['id']} not found"}})
                    break

                for t in types:
                    if not isinstance(t, dict) or set(t.keys()) - {"associationCategory", "associationTypeId"}:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Association type entries require associationCategory and associationTypeId"}})
                        break
                    cat = t.get("associationCategory")
                    tid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationCategory must be a string"}})
                        break
                    if not (isinstance(tid, int) or isinstance(tid, float)) or isinstance(tid, bool) or tid < 1:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationTypeId must be a number >= 1"}})
                        break
                    if not _assoc_type_active("tasks", target_type, cat, tid):
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Association type is not defined/active for this portal"}})
                        break

                    # Stage edge using internal ids (task internal id unknown yet; fill later)
                    assoc_rows.append({
                        "to_internal_id": target_internal,
                        "to_object_type": target_type,
                        "association_category": cat,
                        "association_type_id": float(tid),
                    })
                if errors and errors[-1].get("index") == idx:
                    break
            if errors and errors[-1].get("index") == idx:
                staged.append(None)
                continue

        # Stage task object
        hubspot_id = _next_hubspot_id_for_type("tasks")
        internal_id = _new_internal_id("obj")

        # basic search_text
        st_parts = []
        for k, v in p.items():
            if v is None:
                continue
            st_parts.append(str(v))
        search_text = " ".join(st_parts) if st_parts else None

        obj_row = {
            "id": internal_id,
            "portal_id": portal_id,
            "object_type": "tasks",
            "hubspot_object_id": str(hubspot_id),
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(p),
            "properties_version": 1,
            "search_text": search_text,
            "created_at": _now,
            "updated_at": _now,
            "hubspot_created_at": _now,
            "hubspot_updated_at": _now,
        }
        staged.append({"obj_row": obj_row, "assoc_rows": assoc_rows})

    # Persist staged successful items; each item atomic
    created_results = []
    created_count = 0
    for idx, stage in enumerate(staged):
        if stage is None:
            continue
        obj_row = stage["obj_row"]
        assoc_rows = stage["assoc_rows"]

        # Ensure uniqueness constraint (portal_id, object_type, hubspot_object_id)
        exists = False
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "tasks" and str(r.get("hubspot_object_id")) == str(obj_row["hubspot_object_id"]):
                exists = True
                break
        if exists:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": "Task with this id already exists"}})
            continue

        objs.append(obj_row)

        # Write associations: create edges tasks -> target; if identical archived exists, reactivate
        for a in assoc_rows:
            # find existing edge
            existing = None
            for e in assocs:
                if not isinstance(e, dict):
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("from_object_id") != obj_row["id"]:
                    continue
                if e.get("to_object_id") != a["to_internal_id"]:
                    continue
                if e.get("association_category") != a["association_category"]:
                    continue
                try:
                    if float(e.get("association_type_id")) != float(a["association_type_id"]):
                        continue
                except Exception:
                    continue
                existing = e
                break

            if existing:
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = _now
                # else already active: idempotent upsert
            else:
                assocs.append({
                    "id": _new_internal_id("asc"),
                    "portal_id": portal_id,
                    "from_object_id": obj_row["id"],
                    "to_object_id": a["to_internal_id"],
                    "from_object_type": "tasks",
                    "to_object_type": a["to_object_type"],
                    "association_category": a["association_category"],
                    "association_type_id": float(a["association_type_id"]),
                    "status": "active",
                    "archived": False,
                    "created_at": _now,
                    "updated_at": _now,
                })

        created_count += 1
        created_results.append({
            "id": str(obj_row["hubspot_object_id"]),
            "properties": obj_row["properties"],
            "createdAt": obj_row["hubspot_created_at"],
            "updatedAt": obj_row["hubspot_updated_at"],
            "archived": False,
        })

    if created_count > 0:
        _save("crm_objects.json", objs)
        _save("crm_associations.json", assocs)

    latency_ms = int((time.time() - _t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now,
            "endpoint": "tasks_batch_create",
            "portal_id": portal_id,
            "status": "ok" if not errors else "partial",
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    return {
        "results": created_results,
        "errors": errors if errors else None,
        "numCreated": created_count,
    }

def tasks_batch_read(inputs, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    assocs = _load("crm_associations.json")

    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        return _err("UNAUTHORIZED", "No portal context available to serve request")
    portal_id = portal_ids[0]

    if not isinstance(inputs, list) or len(inputs) == 0:
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}

    # Index objects by internal id and by hubspot id for tasks
    tasks_by_hs = {}
    objs_by_internal = {}
    for r in objs:
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") != portal_id:
            continue
        rid = r.get("id")
        if rid:
            objs_by_internal[rid] = r
        if r.get("object_type") == "tasks" and str(r.get("hubspot_object_id")):
            tasks_by_hs[str(r.get("hubspot_object_id"))] = r

    results = []
    errors = []
    for idx, item in enumerate(inputs):
        if not isinstance(item, dict) or set(item.keys()) - {"id", "properties", "associations"}:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object with id and optional properties/associations"}})
            continue
        tid = item.get("id")
        if not isinstance(tid, str) or not tid:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"}})
            continue

        props_req = item.get("properties")
        if props_req is not None and (not isinstance(props_req, list) or not all(isinstance(x, str) for x in props_req)):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "properties must be an array of strings"}})
            continue

        assoc_req = item.get("associations")
        if assoc_req is not None:
            if not isinstance(assoc_req, list) or not all(isinstance(x, str) for x in assoc_req):
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array of strings"}})
                continue
            bad = [a for a in assoc_req if a not in allowed_assoc]
            if bad:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations contains unsupported values", "unsupported": bad}})
                continue

        row = tasks_by_hs.get(str(tid))
        if row is None:
            errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": f"Task id {tid} not found"}})
            continue

        if row.get("status") == "archived" or row.get("archived") is True:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": f"Task id {tid} is archived"}})
            continue

        out_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        if props_req is not None:
            out_props = {k: out_props.get(k) for k in props_req}

        out = {
            "id": str(row.get("hubspot_object_id")),
            "properties": out_props,
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived")),
        }

        # Associations: return ids of associated objects by type (only active)
        if assoc_req:
            assoc_out = {}
            for t in assoc_req:
                assoc_out[t] = []
            from_internal = row.get("id")
            if from_internal:
                for e in assocs:
                    if not isinstance(e, dict):
                        continue
                    if e.get("portal_id") != portal_id:
                        continue
                    if e.get("status") != "active" or e.get("archived") is True:
                        continue
                    if e.get("from_object_id") != from_internal:
                        continue
                    to_internal = e.get("to_object_id")
                    to_row = objs_by_internal.get(to_internal)
                    if not to_row or to_row.get("status") != "active" or to_row.get("archived") is True:
                        continue
                    to_type = to_row.get("object_type")
                    if to_type in assoc_out:
                        assoc_out[to_type].append(str(to_row.get("hubspot_object_id")))
            out["associations"] = assoc_out

        results.append(out)

    latency_ms = int((time.time() - _t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now,
            "endpoint": "tasks_batch_read",
            "portal_id": portal_id,
            "status": "ok" if not errors else "partial",
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    return {
        "results": results,
        "errors": errors if errors else None,
        "numRequested": len(inputs),
        "numReturned": len(results),
    }

def tasks_batch_update(inputs, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")

    portal_ids = sorted({r.get("portal_id") for r in objs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        portal_ids = sorted({r.get("portal_id") for r in prop_defs if isinstance(r, dict) and r.get("portal_id")})
    if not portal_ids:
        return _err("UNAUTHORIZED", "No portal context available to serve request")
    portal_id = portal_ids[0]

    if not isinstance(inputs, list) or len(inputs) == 0:
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    task_defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "tasks"]
    def_by_name = {d.get("name"): d for d in task_defs if d.get("name")}

    allowed_priority = {"HIGH", "MEDIUM", "LOW"}
    allowed_status = {"NOT_STARTED", "IN_PROGRESS", "WAITING", "COMPLETED", "DEFERRED"}

    # index tasks by hubspot id and track list positions for mutation
    task_index = {}
    for i, r in enumerate(objs):
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "tasks":
            task_index[str(r.get("hubspot_object_id"))] = i

    results = []
    errors = []
    updated_any = False

    # Validate+apply per-item (atomic per item). If item fails, do not partially update it.
    for idx, item in enumerate(inputs):
        if not isinstance(item, dict) or set(item.keys()) - {"id", "properties"}:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object with id and properties"}})
            continue
        tid = item.get("id")
        if not isinstance(tid, str) or not tid:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"}})
            continue
        p = item.get("properties")
        if not isinstance(p, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "properties must be an object"}})
            continue
        if "hs_task_body" not in p or "hs_task_subject" not in p:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing required properties hs_task_body and/or hs_task_subject"}})
            continue
        if not isinstance(p.get("hs_task_body"), str) or not isinstance(p.get("hs_task_subject"), str):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "hs_task_body and hs_task_subject must be strings"}})
            continue

        if "hs_task_priority" in p and p["hs_task_priority"] is not None and p["hs_task_priority"] not in allowed_priority:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_task_priority"}})
            continue
        if "hs_task_status" in p and p["hs_task_status"] is not None and p["hs_task_status"] not in allowed_status:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_task_status"}})
            continue

        pos = task_index.get(str(tid))
        if pos is None:
            errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": f"Task id {tid} not found"}})
            continue

        row = objs[pos]
        if row.get("status") == "archived" or row.get("archived") is True:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": f"Task id {tid} is archived"}})
            continue

        # Validate against property defs: reject archived defs; hidden allowed (policy unknown)
        if len(def_by_name) > 0:
            bad = None
            for k in p.keys():
                d = def_by_name.get(k)
                if d is None:
                    continue
                if d.get("status") == "archived" or d.get("archived") is True:
                    bad = k
                    break
            if bad:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": f"Property '{bad}' is archived and cannot be written"}})
                continue

        # Apply update atomically for this item
        cur_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        new_props = dict(cur_props)
        for k, v in p.items():
            # clearing represented by empty string; accept as-is
            new_props[k] = v
        row["properties"] = new_props
        row["properties_version"] = int(row.get("properties_version") or 0) + 1
        row["updated_at"] = _now
        row["hubspot_updated_at"] = _now

        # update search_text
        st_parts = []
        for k, v in new_props.items():
            if v is None:
                continue
            if v == "":
                continue
            st_parts.append(str(v))
        row["search_text"] = " ".join(st_parts) if st_parts else None

        objs[pos] = row
        updated_any = True

        results.append({
            "id": str(row.get("hubspot_object_id")),
            "properties": row["properties"],
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived")),
        })

    if updated_any:
        _save("crm_objects.json", objs)

    latency_ms = int((time.time() - _t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now,
            "endpoint": "tasks_batch_update",
            "portal_id": portal_id,
            "status": "ok" if not errors else "partial",
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    return {
        "results": results,
        "errors": errors if errors else None,
        "numUpdated": len(results),
    }

def tasks_batch_archive(taskIds, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Input validation
    if not isinstance(taskIds, list) or len(taskIds) == 0:
        return _err("VALIDATION_ERROR", "taskIds must be a non-empty array of strings.")
    bad = [i for i, v in enumerate(taskIds) if not isinstance(v, str) or not v.strip()]
    if bad:
        return _err("VALIDATION_ERROR", "taskIds contains invalid id(s).", invalid_indexes=bad)

    # Resolve tenant context (ambient auth): choose a portal that can serve by finding tasks in some portal.
    objs = _load("crm_objects.json")
    tasks = [o for o in objs if o.get("object_type") == "tasks"]
    if not tasks:
        # No portal can possibly have tasks, therefore no combination can serve this call.
        return _err("UNAUTHORIZED", "No accessible portal/workspace could be resolved for tasks archive.")

    # Determine portal_id by matching provided ids to existing tasks; require all in same portal.
    id_to_row = {}
    portals = set()
    for tid in taskIds:
        r = next((o for o in objs if o.get("object_type") == "tasks" and o.get("hubspot_object_id") == tid), None)
        if r is None:
            return _err("NOT_FOUND", f"Task not found: {tid}", taskId=tid)
        id_to_row[tid] = r
        portals.add(r.get("portal_id"))
    if len(portals) != 1:
        return _err("VALIDATION_ERROR", "All taskIds must belong to the same portal/tenant.", portal_ids=sorted([p for p in portals if p is not None]))
    portal_id = next(iter(portals))

    # Conflict if any already archived
    already = [tid for tid, r in id_to_row.items() if r.get("status") == "archived" or r.get("archived") is True]
    if already:
        return _err("CONFLICT", "One or more tasks are already archived.", taskIds=already)

    # Apply lifecycle transition: active -> archived
    # Enforce "no success without effect": all must be updated
    updated = 0
    for o in objs:
        if o.get("portal_id") == portal_id and o.get("object_type") == "tasks" and o.get("hubspot_object_id") in id_to_row:
            if o.get("status") != "active":
                return _err("INVALID_TRANSITION", f"Cannot archive task in status '{o.get('status')}'.", taskId=o.get("hubspot_object_id"))
            o["status"] = "archived"
            o["archived"] = True
            o["updated_at"] = now
            # keep hubspot_updated_at in sync if present/known
            o["hubspot_updated_at"] = now
            pv = o.get("properties_version")
            if isinstance(pv, int) and pv >= 1:
                o["properties_version"] = pv + 1
            else:
                o["properties_version"] = 1
            updated += 1

    if updated != len(taskIds):
        # Should not happen because we pre-resolved all rows, but keep contract strong.
        return _err("NOT_FOUND", "One or more tasks could not be archived (missing during update).", affected=updated, requested=len(taskIds))

    _save("crm_objects.json", objs)

    # Return empty-ish success response consistent with "empty success response"
    return {
        "status": "success",
        "results": {},
        "meta": {
            "portal_id": portal_id,
            "archived_count": updated,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }

def engagement_details_get(engagementId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(engagementId, str) or not engagementId.strip():
        return _err("VALIDATION_ERROR", "engagementId must be a non-empty string.")

    objs = _load("crm_objects.json")

    row = next((o for o in objs if o.get("object_type") == "engagements" and o.get("hubspot_object_id") == engagementId), None)
    if row is None:
        return _err("NOT_FOUND", "Engagement not found.", engagementId=engagementId)
    if row.get("status") == "archived" or row.get("archived") is True:
        # HubSpot typically treats archived as not accessible through standard get.
        return _err("NOT_FOUND", "Engagement not found.", engagementId=engagementId)

    portal_id = row.get("portal_id")

    # Build response: engagement payload stored in properties; metadata under properties.metadata
    props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
    engagement = dict(props)
    metadata = {}
    if isinstance(props.get("metadata"), dict):
        metadata = props.get("metadata")

    # Associations: join edges where from is this engagement OR to is this engagement, return only active non-archived objects.
    assocs = _load("crm_associations.json")
    # Create a quick map for objects in this portal
    portal_objs = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}
    contactIds, companyIds, dealIds, ticketIds, ownerIds = set(), set(), set(), set(), set()

    this_id = row.get("id")
    for e in assocs:
        if e.get("portal_id") != portal_id:
            continue
        if e.get("status") != "active" or e.get("archived") is True:
            continue

        other_id = None
        other_type = None

        if e.get("from_object_id") == this_id:
            other_id = e.get("to_object_id")
            other_type = e.get("to_object_type")
        elif e.get("to_object_id") == this_id:
            other_id = e.get("from_object_id")
            other_type = e.get("from_object_type")
        else:
            continue

        other = portal_objs.get(other_id)
        if not other or other.get("status") != "active" or other.get("archived") is True:
            continue

        hs_id = other.get("hubspot_object_id")
        if not isinstance(hs_id, str):
            continue

        if other_type == "contacts":
            contactIds.add(hs_id)
        elif other_type == "companies":
            companyIds.add(hs_id)
        elif other_type == "deals":
            dealIds.add(hs_id)
        elif other_type == "tickets":
            ticketIds.add(hs_id)
        # Owner is not a CRM object in this schema; if stored as an association to something, preserve under ownerIds.
        else:
            ownerIds.add(hs_id)

    out = {
        "id": engagementId,
        "portalId": portal_id,
        "engagement": engagement,
        "metadata": metadata,
        "associations": {
            "contactIds": sorted(contactIds),
            "companyIds": sorted(companyIds),
            "dealIds": sorted(dealIds),
            "ticketIds": sorted(ticketIds),
            "ownerIds": sorted(ownerIds),
        },
        "archived": False,
        "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
        "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }
    return out

def engagement_details_create(engagement, associations=None, metadata=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate engagement object
    if not isinstance(engagement, dict):
        return _err("VALIDATION_ERROR", "engagement must be an object.")
    et = engagement.get("type")
    title = engagement.get("title")
    if et not in ["EMAIL", "CALL", "MEETING", "TASK", "NOTE"]:
        return _err("VALIDATION_ERROR", "engagement.type must be one of EMAIL, CALL, MEETING, TASK, NOTE.")
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "engagement.title must be a non-empty string.")

    if associations is not None and not isinstance(associations, dict):
        return _err("VALIDATION_ERROR", "associations must be an object when provided.")
    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided.")

    # Validate association arrays shape
    assoc_lists = {}
    allowed_assoc_keys = ["contactIds", "companyIds", "dealIds", "ownerIds", "ticketIds"]
    if associations is None:
        associations = {}
    for k in list(associations.keys()):
        if k not in allowed_assoc_keys:
            return _err("VALIDATION_ERROR", f"Unknown associations field '{k}'.")
    for k in allowed_assoc_keys:
        v = associations.get(k, [])
        if v is None:
            v = []
        if not isinstance(v, list) or any((not isinstance(x, str) or not x.strip()) for x in v):
            return _err("VALIDATION_ERROR", f"associations.{k} must be an array of strings.")
        assoc_lists[k] = v

    # Resolve a portal (ambient): choose a portal that can satisfy referenced objects; if none referenced, choose any portal with crm_objects rows.
    objs = _load("crm_objects.json")
    portals = sorted({o.get("portal_id") for o in objs if isinstance(o.get("portal_id"), str) and o.get("portal_id")})
    if not portals:
        return _err("UNAUTHORIZED", "No accessible portal/workspace could be resolved.")

    # If there are referenced ids (contacts/companies/deals/tickets), infer portal by matching; all must belong to same portal.
    def _find_obj(portal_id, obj_type, hs_id):
        return next((o for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == obj_type and o.get("hubspot_object_id") == hs_id), None)

    referenced = []
    for hs_id in assoc_lists["contactIds"]:
        referenced.append(("contacts", hs_id))
    for hs_id in assoc_lists["companyIds"]:
        referenced.append(("companies", hs_id))
    for hs_id in assoc_lists["dealIds"]:
        referenced.append(("deals", hs_id))
    for hs_id in assoc_lists["ticketIds"]:
        referenced.append(("tickets", hs_id))

    portal_id = None
    if referenced:
        candidate_portals = None
        for obj_type, hs_id in referenced:
            hits = [o.get("portal_id") for o in objs if o.get("object_type") == obj_type and o.get("hubspot_object_id") == hs_id and o.get("status") == "active" and o.get("archived") is False]
            hits = [p for p in hits if isinstance(p, str) and p]
            if not hits:
                return _err("NOT_FOUND", f"Associated {obj_type[:-1]} not found or archived: {hs_id}", objectType=obj_type, objectId=hs_id)
            hs_portals = set(hits)
            candidate_portals = hs_portals if candidate_portals is None else (candidate_portals & hs_portals)
            if not candidate_portals:
                return _err("VALIDATION_ERROR", "Associated objects must belong to the same portal/tenant.")
        portal_id = sorted(candidate_portals)[0]
    else:
        portal_id = portals[0]

    # Association type validation: must exist and be active.
    assoc_types = _load("crm_association_types.json")
    # Build a lookup for a portal: (from_type,to_type) -> list of active defs; allow any category/type id by selecting an available one if possible.
    def _pick_assoc_type(from_t, to_t):
        cands = [a for a in assoc_types if a.get("portal_id") == portal_id and a.get("from_object_type") == from_t and a.get("to_object_type") == to_t and a.get("status") == "active"]
        if not cands:
            return None
        # Deterministic pick: lowest association_type_id
        cands.sort(key=lambda r: (r.get("association_type_id") if isinstance(r.get("association_type_id"), (int, float)) else 10**18))
        return cands[0]

    # Create new engagement row
    # Generate hubspot_object_id as string numeric-ish: use current epoch ms + random suffix to avoid collision.
    epoch_ms = int(time.time() * 1000)
    hubspot_object_id = str(epoch_ms)
    # Ensure uniqueness per portal/type/hsid
    existing_hs = {(o.get("portal_id"), o.get("object_type"), o.get("hubspot_object_id")) for o in objs}
    if (portal_id, "engagements", hubspot_object_id) in existing_hs:
        hubspot_object_id = str(epoch_ms) + str(uuid.uuid4().int % 10000).zfill(4)

    new_id = "crmobj_" + uuid.uuid4().hex
    props = dict(engagement)
    if metadata is not None:
        props["metadata"] = metadata

    row = {
        "id": new_id,
        "portal_id": portal_id,
        "object_type": "engagements",
        "hubspot_object_id": hubspot_object_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": props,
        "properties_version": 1,
        "search_text": None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Validate associations and prepare edges
    edges = _load("crm_associations.json")
    new_edges = []

    def _add_edges_for(target_type, id_list):
        nonlocal new_edges
        assoc_def = _pick_assoc_type("engagements", target_type)
        if assoc_def is None:
            return _err("VALIDATION_ERROR", f"No active association type available for engagements -> {target_type} in this portal.", from_object_type="engagements", to_object_type=target_type)
        for hs_id in id_list:
            target = _find_obj(portal_id, target_type, hs_id)
            if target is None or target.get("status") != "active" or target.get("archived") is True:
                return _err("NOT_FOUND", f"Associated {target_type[:-1]} not found or archived: {hs_id}", objectType=target_type, objectId=hs_id)
            edge = {
                "id": "assoc_" + uuid.uuid4().hex,
                "portal_id": portal_id,
                "from_object_id": new_id,
                "to_object_id": target.get("id"),
                "from_object_type": "engagements",
                "to_object_type": target_type,
                "association_category": assoc_def.get("association_category"),
                "association_type_id": assoc_def.get("association_type_id"),
                "status": "active",
                "archived": False,
                "created_at": now,
                "updated_at": now,
            }
            new_edges.append(edge)
        return None

    # OwnerIds cannot be validated against crm_objects (no owners object_type). Store in engagement properties for traceability.
    if assoc_lists["ownerIds"]:
        props["ownerIds"] = list(dict.fromkeys(assoc_lists["ownerIds"]))

    for target_type, key in [("contacts", "contactIds"), ("companies", "companyIds"), ("deals", "dealIds"), ("tickets", "ticketIds")]:
        err = _add_edges_for(target_type, assoc_lists[key])
        if err:
            return err

    # Ensure uniqueness constraint for edges is preserved and avoid self-loop handled by schema (not possible here)
    existing_edge_keys = {(e.get("portal_id"), e.get("from_object_id"), e.get("to_object_id"), e.get("association_category"), e.get("association_type_id")) for e in edges}
    for e in new_edges:
        k = (e["portal_id"], e["from_object_id"], e["to_object_id"], e["association_category"], e["association_type_id"])
        if k in existing_edge_keys:
            # Should not happen for brand new engagement id, but guard anyway.
            return _err("CONFLICT", "Association already exists.", association=k)

    # Persist
    objs.append(row)
    edges.extend(new_edges)
    _save("crm_objects.json", objs)
    _save("crm_associations.json", edges)

    return {
        "id": hubspot_object_id,
        "portalId": portal_id,
        "engagement": row["properties"],
        "metadata": row["properties"].get("metadata") if isinstance(row["properties"].get("metadata"), dict) else (metadata or {}),
        "associations": {
            "contactIds": list(dict.fromkeys(assoc_lists["contactIds"])),
            "companyIds": list(dict.fromkeys(assoc_lists["companyIds"])),
            "dealIds": list(dict.fromkeys(assoc_lists["dealIds"])),
            "ticketIds": list(dict.fromkeys(assoc_lists["ticketIds"])),
            "ownerIds": list(dict.fromkeys(assoc_lists["ownerIds"])),
        },
        "archived": False,
        "createdAt": now,
        "updatedAt": now,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }

def engagement_details_update(engagementId, engagement, metadata=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(engagementId, str) or not engagementId.strip():
        return _err("VALIDATION_ERROR", "engagementId must be a non-empty string.")
    if not isinstance(engagement, dict):
        return _err("VALIDATION_ERROR", "engagement must be an object.")
    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided.")

    et = engagement.get("type")
    title = engagement.get("title")
    if et not in ["EMAIL", "CALL", "MEETING", "TASK", "NOTE"]:
        return _err("VALIDATION_ERROR", "engagement.type must be one of EMAIL, CALL, MEETING, TASK, NOTE.")
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "engagement.title must be a non-empty string.")

    objs = _load("crm_objects.json")

    idx = None
    row = None
    for i, o in enumerate(objs):
        if o.get("object_type") == "engagements" and o.get("hubspot_object_id") == engagementId:
            idx = i
            row = o
            break
    if row is None:
        return _err("NOT_FOUND", "Engagement not found.", engagementId=engagementId)
    if row.get("status") == "archived" or row.get("archived") is True:
        return _err("NOT_FOUND", "Engagement not found.", engagementId=engagementId)

    # Update properties (merge, allowing clearing via empty string)
    props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
    # Overwrite/merge the engagement fields provided
    for k, v in engagement.items():
        props[k] = v
    # Update metadata if provided
    if metadata is not None:
        props["metadata"] = metadata

    row["properties"] = props
    row["updated_at"] = now
    row["hubspot_updated_at"] = now
    pv = row.get("properties_version")
    if isinstance(pv, int) and pv >= 1:
        row["properties_version"] = pv + 1
    else:
        row["properties_version"] = 1

    objs[idx] = row
    _save("crm_objects.json", objs)

    # Return updated with associations resolved (same as get)
    portal_id = row.get("portal_id")
    assocs = _load("crm_associations.json")
    portal_objs = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}
    contactIds, companyIds, dealIds, ticketIds, ownerIds = set(), set(), set(), set(), set()
    this_id = row.get("id")

    for e in assocs:
        if e.get("portal_id") != portal_id:
            continue
        if e.get("status") != "active" or e.get("archived") is True:
            continue

        other_id = None
        other_type = None
        if e.get("from_object_id") == this_id:
            other_id = e.get("to_object_id")
            other_type = e.get("to_object_type")
        elif e.get("to_object_id") == this_id:
            other_id = e.get("from_object_id")
            other_type = e.get("from_object_type")
        else:
            continue

        other = portal_objs.get(other_id)
        if not other or other.get("status") != "active" or other.get("archived") is True:
            continue
        hs_id = other.get("hubspot_object_id")
        if not isinstance(hs_id, str):
            continue

        if other_type == "contacts":
            contactIds.add(hs_id)
        elif other_type == "companies":
            companyIds.add(hs_id)
        elif other_type == "deals":
            dealIds.add(hs_id)
        elif other_type == "tickets":
            ticketIds.add(hs_id)
        else:
            ownerIds.add(hs_id)

    props_out = row.get("properties") if isinstance(row.get("properties"), dict) else {}
    meta_out = props_out.get("metadata") if isinstance(props_out.get("metadata"), dict) else (metadata or {})

    return {
        "id": engagementId,
        "portalId": portal_id,
        "engagement": props_out,
        "metadata": meta_out,
        "associations": {
            "contactIds": sorted(contactIds),
            "companyIds": sorted(companyIds),
            "dealIds": sorted(dealIds),
            "ticketIds": sorted(ticketIds),
            "ownerIds": sorted(ownerIds),
        },
        "archived": False,
        "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
        "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }

def engagement_details_list(limit=None, offset=None, startTime=None, endTime=None, activityTypes=None, **_extra):
