    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "OK"
    portal_id = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_time(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(f"{field} must be a non-empty string when provided")
        st = s.strip()
        # Accept milliseconds since epoch as string, or ISO-8601
        if st.isdigit():
            ms = int(st)
            if ms < 0:
                raise ValueError(f"{field} must be >= 0 when numeric")
            return datetime.datetime.utcfromtimestamp(ms / 1000.0)
        try:
            ss = st[:-1] if st.endswith("Z") else st
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be ISO-8601 or epoch-millis string")

    def _get_portal():
        # Ambient auth: choose any portal with data; if none, still allow reads with empty results.
        objs = _load("crm_objects.json")
        if objs:
            for r in objs:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        # fallback from other collections
        for fn in ("crm_object_properties.json", "crm_association_types.json", "communications_subscriptions.json"):
            rows = _load(fn)
            for r in rows:
                if isinstance(r, dict) and r.get("portal_id"):
                    return r.get("portal_id")
        return "default_portal"

    def _log(endpoint, status, latency_ms, portal_id_used):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id_used,
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(portal_id_used):
        # Best-effort: enforce if a policy file exists; otherwise unlimited.
        policy = None
        try:
            with open(os.path.join(_DB, "rate_limits.json"), encoding="utf-8") as f:
                policy = json.load(f)
        except Exception:
            return None
        if not isinstance(policy, dict):
            return None
        # policy example: {"per_minute": 120, "per_day": 5000}
        per_min = policy.get("per_minute")
        per_day = policy.get("per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        def _ts_parse(z):
            try:
                s = z[:-1] if isinstance(z, str) and z.endswith("Z") else z
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("portal_id") != portal_id_used:
                continue
            ts = _ts_parse(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= minute_ago:
                c_min += 1
            if ts >= day_ago:
                c_day += 1
        if isinstance(per_min, (int, float)) and per_min >= 0 and c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded (per_minute).", limit=per_min)
        if isinstance(per_day, (int, float)) and per_day >= 0 and c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Quota exceeded (per_day).", quota=per_day)
        return None

    try:
        if limit is None:
            limit = 100
        if not isinstance(limit, (int, float)) or int(limit) != limit:
            status_code = "VALIDATION_ERROR"
            res = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        else:
            limit = int(limit)
            if limit < 1 or limit > 100:
                status_code = "VALIDATION_ERROR"
                res = _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
            else:
                if offset is None:
                    offset = 0
                if not isinstance(offset, (int, float)) or int(offset) != offset:
                    status_code = "VALIDATION_ERROR"
                    res = _err("VALIDATION_ERROR", "offset must be an integer >= 0.")
                else:
                    offset = int(offset)
                    if offset < 0:
                        status_code = "VALIDATION_ERROR"
                        res = _err("VALIDATION_ERROR", "offset must be an integer >= 0.")
                    else:
                        if activityTypes is not None:
                            if not isinstance(activityTypes, list) or any(not isinstance(x, str) for x in activityTypes):
                                status_code = "VALIDATION_ERROR"
                                res = _err("VALIDATION_ERROR", "activityTypes must be an array of strings when provided.")
                            else:
                                res = None
                        else:
                            res = None

        portal_id = _get_portal()
        # rate limit / quota
        rl = _rate_limit_check(portal_id)
        if rl is not None:
            status_code = rl["error"]["code"]
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_list", status_code, latency, portal_id)
            return rl

        if res is not None:
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_list", status_code, latency, portal_id)
            return res

        try:
            st = _parse_time(startTime, "startTime")
            et = _parse_time(endTime, "endTime")
            if st is not None and et is not None and et < st:
                status_code = "VALIDATION_ERROR"
                latency = int((time.time() - t0) * 1000)
                _log("engagement_details_list", status_code, latency, portal_id)
                return _err("VALIDATION_ERROR", "endTime must be >= startTime.")
        except ValueError as ve:
            status_code = "VALIDATION_ERROR"
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_list", status_code, latency, portal_id)
            return _err("VALIDATION_ERROR", str(ve))

        objs = _load("crm_objects.json")
        if not isinstance(objs, list):
            objs = []

        # Filter engagements by portal, type, not archived
        rows = []
        atypes = set([a.strip() for a in activityTypes]) if isinstance(activityTypes, list) else None
        for r in objs:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("object_type") != "engagements":
                continue
            if r.get("archived") is True or r.get("status") == "archived":
                continue
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            # time filter: prefer hs_timestamp then created/updated
            ts_val = props.get("hs_timestamp") or r.get("hubspot_created_at") or r.get("created_at") or r.get("updated_at")
            ts = None
            if isinstance(ts_val, (int, float)):
                ts = datetime.datetime.utcfromtimestamp(float(ts_val) / 1000.0)
            elif isinstance(ts_val, str):
                try:
                    ts = _parse_time(ts_val, "hs_timestamp")
                except Exception:
                    ts = None
            if st is not None and ts is not None and ts < st:
                continue
            if et is not None and ts is not None and ts > et:
                continue
            if atypes is not None and len(atypes) > 0:
                act = props.get("activityType") or props.get("hs_activity_type") or props.get("type")
                if not isinstance(act, str) or act not in atypes:
                    continue
            rows.append(r)

        # Sort by timestamp desc then hubspot_object_id desc
        def _sort_key(r):
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            ts_val = props.get("hs_timestamp") or r.get("hubspot_created_at") or r.get("created_at") or r.get("updated_at")
            ts = None
            if isinstance(ts_val, (int, float)):
                ts = datetime.datetime.utcfromtimestamp(float(ts_val) / 1000.0)
            elif isinstance(ts_val, str):
                try:
                    ts = _parse_time(ts_val, "hs_timestamp")
                except Exception:
                    ts = None
            return (ts or datetime.datetime(1970, 1, 1), str(r.get("hubspot_object_id") or ""))
        rows.sort(key=_sort_key, reverse=True)

        total = len(rows)
        slice_rows = rows[offset: offset + limit]
        has_more = (offset + limit) < total
        next_offset = (offset + limit) if has_more else None

        resp = {
            "results": slice_rows,
            "paging": {
                "offset": offset,
                "limit": limit,
                "total": total,
                "hasMore": has_more,
                "nextOffset": next_offset
            }
        }
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_list", status_code, latency, portal_id)
        return resp

    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_list", "VALIDATION_ERROR", latency, portal_id or "default_portal")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def engagement_details_archive(engagementId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    portal_id = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_portal():
        objs = _load("crm_objects.json")
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        return "default_portal"

    def _log(endpoint, status, latency_ms, portal_id_used):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id_used,
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _quota_check(portal_id_used):
        # Enforce if quota policy exists for writes
        policy = None
        try:
            with open(os.path.join(_DB, "quotas.json"), encoding="utf-8") as f:
                policy = json.load(f)
        except Exception:
            return None
        if not isinstance(policy, dict):
            return None
        per_day_writes = policy.get("writes_per_day")
        if not isinstance(per_day_writes, (int, float)) or per_day_writes < 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        day_ago = now - datetime.timedelta(days=1)
        def _ts_parse(z):
            try:
                s = z[:-1] if isinstance(z, str) and z.endswith("Z") else z
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id_used:
                continue
            if not isinstance(r.get("endpoint"), str):
                continue
            # crude heuristic: archive is a write
            if r.get("endpoint") not in ("engagement_details_archive", "calls_create"):
                continue
            ts = _ts_parse(r.get("timestamp"))
            if ts is not None and ts >= day_ago:
                c += 1
        if c >= per_day_writes:
            return _err("QUOTA_EXCEEDED", "Write quota exceeded.", quota=per_day_writes)
        return None

    try:
        portal_id = _get_portal()
        if not isinstance(engagementId, str) or not engagementId.strip():
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_archive", "VALIDATION_ERROR", latency, portal_id)
            return _err("VALIDATION_ERROR", "engagementId must be a non-empty string.")

        q = _quota_check(portal_id)
        if q is not None:
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_archive", q["error"]["code"], latency, portal_id)
            return q

        objs = _load("crm_objects.json")
        if not isinstance(objs, list):
            objs = []
        idx = None
        row = None
        for i, r in enumerate(objs):
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id:
                continue
            if r.get("object_type") == "engagements" and str(r.get("hubspot_object_id")) == engagementId:
                idx = i
                row = r
                break

        if row is None:
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_archive", "NOT_FOUND", latency, portal_id)
            return _err("NOT_FOUND", "Engagement not found.", engagementId=engagementId)

        if row.get("status") == "archived" or row.get("archived") is True:
            latency = int((time.time() - t0) * 1000)
            _log("engagement_details_archive", "CONFLICT", latency, portal_id)
            return _err("CONFLICT", "Engagement is already archived.", engagementId=engagementId)

        # transition active -> archived
        row["status"] = "archived"
        row["archived"] = True
        row["properties_version"] = int(row.get("properties_version") or 1) + 1
        row["updated_at"] = _now()
        row["hubspot_updated_at"] = _now()
        objs[idx] = row

        # Cascade: archive associations involving this object (simulate on delete cascade? schema says on delete cascade,
        # but archive isn't delete; still, HubSpot archive generally hides edges; we archive edges too.)
        assocs = _load("crm_associations.json")
        if not isinstance(assocs, list):
            assocs = []
        changed = False
        for a in assocs:
            if not isinstance(a, dict):
                continue
            if a.get("portal_id") != portal_id:
                continue
            if a.get("from_object_id") == row.get("id") or a.get("to_object_id") == row.get("id"):
                if a.get("status") != "archived" or a.get("archived") is not True:
                    a["status"] = "archived"
                    a["archived"] = True
                    a["updated_at"] = _now()
                    changed = True
        _save("crm_objects.json", objs)
        if changed:
            _save("crm_associations.json", assocs)

        resp = {
            "id": engagementId,
            "archived": True,
            "status": "archived",
            "updatedAt": row["updated_at"]
        }
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_archive", "OK", latency, portal_id)
        return resp

    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_archive", "VALIDATION_ERROR", latency, portal_id or "default_portal")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

