                continue
            if atypes is not None and len(atypes) > 0:
                act = props.get("activityType") or props.get("hs_activity_type") or props.get("type")
                if not isinstance(act, str) or act not in atypes:
                    continue
            engaged.append(r)

        engaged.sort(key=lambda r: (_eng_time(r) or datetime.datetime(1970, 1, 1), str(r.get("hubspot_object_id") or "")), reverse=True)
        total = len(engaged)
        slice_rows = engaged[offset: offset + limit]
        has_more = (offset + limit) < total
        next_offset = (offset + limit) if has_more else None

        resp = {
            "results": slice_rows,
            "paging": {
                "offset": offset,
                "limit": limit,
                "total": total,
                "hasMore": has_more,
                "nextOffset": next_offset
            }
        }
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_get_associated", "OK", latency, portal_id)
        return resp

    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _log("engagement_details_get_associated", "VALIDATION_ERROR", latency, portal_id or "default_portal")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def calls_create(properties, associations=None, **_extra):
    import json, os, datetime, time, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    portal_id = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_portal():
        objs = _load("crm_objects.json")
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        # fallback from definitions
        props = _load("crm_object_properties.json")
        for r in props:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        assoc_types = _load("crm_association_types.json")
        for r in assoc_types:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        return "default_portal"

    def _log(endpoint, status, latency_ms, portal_id_used):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id_used,
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _quota_check(portal_id_used):
        policy = None
        try:
            with open(os.path.join(_DB, "quotas.json"), encoding="utf-8") as f:
                policy = json.load(f)
        except Exception:
            return None
        if not isinstance(policy, dict):
            return None
        per_day_writes = policy.get("writes_per_day")
        if not isinstance(per_day_writes, (int, float)) or per_day_writes < 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        day_ago = now - datetime.timedelta(days=1)
        def _ts_parse(z):
            try:
                s = z[:-1] if isinstance(z, str) and z.endswith("Z") else z
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") != portal_id_used:
                continue
            if r.get("endpoint") in ("calls_create", "engagement_details_archive"):
                ts = _ts_parse(r.get("timestamp"))
                if ts is not None and ts >= day_ago:
                    c += 1
        if c >= per_day_writes:
            return _err("QUOTA_EXCEEDED", "Write quota exceeded.", quota=per_day_writes)
        return None

    def _is_uri(s):
        if not isinstance(s, str) or not s:
            return False
        try:
            u = urllib.parse.urlparse(s)
            return u.scheme in ("http", "https") and bool(u.netloc)
        except Exception:
            return False

    def _new_id(prefix, existing_ids):
        i = 1
        while True:
            cand = f"{prefix}_{int(time.time()*1000)}_{i}"
            if cand not in existing_ids:
                return cand
            i += 1

    def _build_search_text(props):
        parts = []
        if isinstance(props, dict):
            for k, v in props.items():
                if v is None:
                    continue
                if isinstance(v, (str, int, float, bool)):
                    parts.append(str(v))
        return " ".join(parts)[:20000] if parts else None

    try:
        portal_id = _get_portal()

        q = _quota_check(portal_id)
        if q is not None:
            latency = int((time.time() - t0) * 1000)
            _log("calls_create", q["error"]["code"], latency, portal_id)
            return q

        if not isinstance(properties, dict):
            latency = int((time.time() - t0) * 1000)
            _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
            return _err("VALIDATION_ERROR", "properties must be an object.")

        # Required
        for req in ("hs_call_body", "hs_call_title"):
            if req not in properties or not isinstance(properties.get(req), str) or properties.get(req) == "":
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", f"Missing required property: {req}.")

        # Enums / formats from schema
        if "hs_call_direction" in properties and properties["hs_call_direction"] is not None:
            if properties["hs_call_direction"] not in ("INBOUND", "OUTBOUND"):
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", "hs_call_direction must be INBOUND or OUTBOUND.")
        if "hs_call_status" in properties and properties["hs_call_status"] is not None:
            if properties["hs_call_status"] not in ("SCHEDULED", "COMPLETED", "CANCELED", "NO_ANSWER"):
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", "hs_call_status must be one of SCHEDULED, COMPLETED, CANCELED, NO_ANSWER.")
        if "hs_call_duration" in properties and properties["hs_call_duration"] is not None:
            if not isinstance(properties["hs_call_duration"], (int, float)) or properties["hs_call_duration"] < 0:
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", "hs_call_duration must be a non-negative number.")
        if "hs_call_recording_url" in properties and properties["hs_call_recording_url"] is not None:
            if not _is_uri(properties["hs_call_recording_url"]):
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", "hs_call_recording_url must be a valid http(s) URI.")
        # hs_timestamp must be string if provided
        if "hs_timestamp" in properties and properties["hs_timestamp"] is not None and not isinstance(properties["hs_timestamp"], str):
            latency = int((time.time() - t0) * 1000)
            _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
            return _err("VALIDATION_ERROR", "hs_timestamp must be a string when provided.")

        # Validate property names against crm_object_properties when definitions exist
        prop_defs = _load("crm_object_properties.json")
        if not isinstance(prop_defs, list):
            prop_defs = []
        call_defs = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "calls"]
        if call_defs:
            def_by_name = {d.get("name"): d for d in call_defs if isinstance(d.get("name"), str)}
            # policy: allow additionalProperties (tool schema permits) => allow unknown unless portal policy forbids.
            policy = None
            try:
                with open(os.path.join(_DB, "portal_policies.json"), encoding="utf-8") as f:
                    policy = json.load(f)
            except Exception:
                policy = {}
            allow_unknown = True
            forbid_hidden = False
            if isinstance(policy, dict):
                p = policy.get(portal_id) if portal_id in policy else policy.get("default")
                if isinstance(p, dict):
                    if p.get("allow_unknown_properties") is False:
                        allow_unknown = False
                    if p.get("forbid_hidden_properties") is True:
                        forbid_hidden = True
            for k in properties.keys():
                d = def_by_name.get(k)
                if d is None:
                    if not allow_unknown:
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", f"Unknown property '{k}' for object_type calls.")
                else:
                    if d.get("status") == "archived" or d.get("archived") is True:
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be written.")
                    if forbid_hidden and d.get("hidden") is True:
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", f"Property '{k}' is hidden and cannot be written by policy.")

        # Associations validation + prepare edges (atomic per item: this tool is single item, so all-or-nothing)
        assoc_edges_to_create = []
        if associations is not None:
            if not isinstance(associations, list):
                latency = int((time.time() - t0) * 1000)
                _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                return _err("VALIDATION_ERROR", "associations must be an array when provided.")
            # Load needed tables
            objs = _load("crm_objects.json")
            if not isinstance(objs, list):
                objs = []
            assoc_types = _load("crm_association_types.json")
            if not isinstance(assoc_types, list):
                assoc_types = []
            assocs_existing = _load("crm_associations.json")
            if not isinstance(assocs_existing, list):
                assocs_existing = []

            # index objects by hubspot_object_id across portal
            obj_by_hsid = {}
            for r in objs:
                if not isinstance(r, dict):
                    continue
                if r.get("portal_id") != portal_id:
                    continue
                obj_by_hsid.setdefault((r.get("object_type"), str(r.get("hubspot_object_id"))), r)

            # validate each association item
            for item in associations:
                if not isinstance(item, dict):
                    latency = int((time.time() - t0) * 1000)
                    _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                    return _err("VALIDATION_ERROR", "Each association must be an object.")
                to = item.get("to")
                types = item.get("types")
                if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id").strip():
                    latency = int((time.time() - t0) * 1000)
                    _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                    return _err("VALIDATION_ERROR", "associations[].to.id must be a non-empty string.")
                if not isinstance(types, list) or len(types) == 0:
                    latency = int((time.time() - t0) * 1000)
                    _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                    return _err("VALIDATION_ERROR", "associations[].types must be a non-empty array.")
                # Resolve "to" object: try common CRM objects by hubspot id within portal
                to_row = None
                for ot in ("contacts", "companies", "deals", "tickets", "products", "line_items", "quotes", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements", "custom"):
                    cand = obj_by_hsid.get((ot, str(to["id"])))
                    if cand and cand.get("archived") is not True and cand.get("status") != "archived":
                        to_row = cand
                        break
                if to_row is None:
                    latency = int((time.time() - t0) * 1000)
                    _log("calls_create", "NOT_FOUND", latency, portal_id)
                    return _err("NOT_FOUND", "Associated 'to' object not found.", toId=to["id"])
                # For each type, validate association type definition exists and active for portal and (calls -> to_object_type)
                for t in types:
                    if not isinstance(t, dict):
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", "associations[].types[] must be an object.")
                    cat = t.get("associationCategory")
                    tid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat.strip():
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", "associationCategory must be a non-empty string.")
                    if not isinstance(tid, (int, float)) or int(tid) != tid or int(tid) < 1:
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", "associationTypeId must be an integer >= 1.")
                    tid = int(tid)
                    ok = False
                    for d in assoc_types:
                        if not isinstance(d, dict):
                            continue
                        if d.get("portal_id") != portal_id:
                            continue
                        if d.get("from_object_type") == "calls" and d.get("to_object_type") == to_row.get("object_type") and d.get("association_category") == cat and int(d.get("association_type_id") or 0) == tid and d.get("status") == "active":
                            ok = True
                            break
                    if not ok:
                        latency = int((time.time() - t0) * 1000)
                        _log("calls_create", "VALIDATION_ERROR", latency, portal_id)
                        return _err("VALIDATION_ERROR", "Association type is not defined or not active for this portal.", fromObjectType="calls", toObjectType=to_row.get("object_type"), associationCategory=cat, associationTypeId=tid)
                    assoc_edges_to_create.append({
                        "to_row": to_row,
                        "association_category": cat,
                        "association_type_id": tid
                    })

        # Create call object row
        objs = _load("crm_objects.json")
        if not isinstance(objs, list):
            objs = []
        existing_ids = set()
        existing_hsids = set()
        for r in objs:
            if isinstance(r, dict):
                if r.get("id"):
                    existing_ids.add(r["id"])
                if r.get("portal_id") == portal_id and r.get("object_type") == "calls":
                    existing_hsids.add(str(r.get("hubspot_object_id")))

        # Create a new hubspot_object_id as increasing integer-like string if possible
        max_num = 0
        for s in existing_hsids:
            if isinstance(s, str) and s.isdigit():
                max_num = max(max_num, int(s))
        new_hsid = str(max_num + 1) if max_num > 0 else str(int(time.time() * 1000))

        # Ensure uniqueness (portal_id, object_type, hubspot_object_id)
        if new_hsid in existing_hsids:
            new_hsid = str(int(time.time() * 1000))

        row_id = _new_id("obj", existing_ids)
        now = _now()
        call_row = {
            "id": row_id,
            "portal_id": portal_id,
            "object_type": "calls",
            "hubspot_object_id": new_hsid,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": properties,
            "properties_version": 1,
            "search_text": _build_search_text(properties),
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now
        }

        # Persist call, then associations edges (still single-tool atomic in this implementation: validate before write;
        # after write, association creation should not fail due to prior validation.)
        objs.append(call_row)

        assocs = _load("crm_associations.json")
        if not isinstance(assocs, list):
            assocs = []
        assoc_existing_keys = set()
        assoc_ids = set()
        for a in assocs:
            if isinstance(a, dict):
                if a.get("id"):
                    assoc_ids.add(a["id"])
                if a.get("portal_id") == portal_id:
                    assoc_existing_keys.add((a.get("from_object_id"), a.get("to_object_id"), a.get("association_category"), int(a.get("association_type_id") or 0)))

        # Create edges from call -> to_object
        for e in assoc_edges_to_create:
            to_row = e["to_row"]
            k = (call_row["id"], to_row["id"], e["association_category"], e["association_type_id"])
            # Upsert active: if exists archived, reactivate; if exists active, keep
            found = False
            for a in assocs:
                if not isinstance(a, dict):
                    continue
                if a.get("portal_id") != portal_id:
                    continue
                if a.get("from_object_id") == call_row["id"] and a.get("to_object_id") == to_row["id"] and a.get("association_category") == e["association_category"] and int(a.get("association_type_id") or 0) == e["association_type_id"]:
                    found = True
                    if a.get("status") == "archived" or a.get("archived") is True:
                        a["status"] = "active"
                        a["archived"] = False
                        a["updated_at"] = now
                    break
            if not found:
                assoc_id = _new_id("assoc", assoc_ids)
                assoc_ids.add(assoc_id)
                assocs.append({
                    "id": assoc_id,
                    "portal_id": portal_id,
                    "from_object_id": call_row["id"],
                    "to_object_id": to_row["id"],
                    "from_object_type": "calls",
                    "to_object_type": to_row.get("object_type"),
                    "association_category": e["association_category"],
                    "association_type_id": e["association_type_id"],
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now
                })

        _save("crm_objects.json", objs)
        if assoc_edges_to_create:
            _save("crm_associations.json", assocs)

        resp = {
            "id": call_row["hubspot_object_id"],
            "objectType": "calls",
            "archived": False,
            "properties": call_row["properties"],
            "createdAt": call_row["hubspot_created_at"],
            "updatedAt": call_row["hubspot_updated_at"]
        }
        latency = int((time.time() - t0) * 1000)
        _log("calls_create", "OK", latency, portal_id)
        return resp

    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        _log("calls_create", "VALIDATION_ERROR", latency, portal_id or "default_portal")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def calls_get(callId, properties=None, associations=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_get"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(callId, str) or not callId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "callId must be a non-empty string")

    props_req = None
    if properties is not None:
        if not isinstance(properties, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array when provided")
        props_req = [str(p) for p in properties]

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}
    assoc_req = None
    if associations is not None:
        if not isinstance(associations, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations must be an array when provided")
        assoc_req = []
        for a in associations:
            if not isinstance(a, str) or a not in allowed_assoc:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "associations contains unsupported types")
            assoc_req.append(a)

    objs = _load("crm_objects.json")
    edges = _load("crm_associations.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(edges, list): edges = []

    call_row = None
    for o in objs:
        if isinstance(o, dict) and o.get("object_type") == "calls" and (str(o.get("hubspot_object_id")) == callId or str(o.get("id")) == callId):
            call_row = o
            break
    if not call_row or call_row.get("status") == "archived" or call_row.get("archived") is True:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Call not found")

    portal_id = call_row.get("portal_id")
    call_internal = call_row.get("id")

    # Build response object like HubSpot: id + properties
    all_props = call_row.get("properties") if isinstance(call_row.get("properties"), dict) else {}
    if props_req is None:
        out_props = dict(all_props)
    else:
        out_props = {k: all_props.get(k, "") for k in props_req}

    result = {
        "id": str(call_row.get("hubspot_object_id")),
        "properties": out_props,
        "createdAt": call_row.get("hubspot_created_at") or call_row.get("created_at"),
        "updatedAt": call_row.get("hubspot_updated_at") or call_row.get("updated_at"),
        "archived": bool(call_row.get("archived")),
    }

    if assoc_req:
        by_internal = {o.get("id"): o for o in objs if isinstance(o, dict) and o.get("portal_id") == portal_id and isinstance(o.get("id"), str)}
        assoc_out = {}
        for atype in assoc_req:
            assoc_ids = []
            for e in edges:
                if not isinstance(e, dict): 
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("from_object_id") != call_internal:
                    continue
                if e.get("status") != "active" or e.get("archived") is True:
                    continue
                if e.get("to_object_type") != atype:
                    continue
                to_obj = by_internal.get(e.get("to_object_id"))
                if not isinstance(to_obj, dict):
                    continue
                if to_obj.get("status") == "archived" or to_obj.get("archived") is True:
                    continue
                assoc_ids.append(str(to_obj.get("hubspot_object_id")))
            assoc_out[atype] = assoc_ids
        result["associations"] = assoc_out

    _log("success", portal_id=portal_id)
    return {"result": result}

def calls_update(callId, properties, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_update"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(callId, str) or not callId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "callId must be a non-empty string")
    if not isinstance(properties, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object")

    # Required fields per tool schema (for update too, per tool schema)
    for req in ("hs_call_body", "hs_call_title"):
        if req not in properties or not isinstance(properties.get(req), str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Missing or invalid required property: {req}", field=req)

    if "hs_call_direction" in properties and properties["hs_call_direction"] not in ("INBOUND", "OUTBOUND", "", None):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hs_call_direction must be INBOUND or OUTBOUND", field="hs_call_direction")
    if "hs_call_status" in properties and properties["hs_call_status"] not in ("SCHEDULED", "COMPLETED", "CANCELED", "NO_ANSWER", "", None):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hs_call_status must be one of SCHEDULED, COMPLETED, CANCELED, NO_ANSWER", field="hs_call_status")
    if "hs_call_duration" in properties and properties["hs_call_duration"] not in ("", None):
        if not isinstance(properties["hs_call_duration"], (int, float)) or properties["hs_call_duration"] < 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "hs_call_duration must be a non-negative number", field="hs_call_duration")
    if "hs_call_recording_url" in properties and properties["hs_call_recording_url"] not in ("", None):
        if not isinstance(properties["hs_call_recording_url"], str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "hs_call_recording_url must be a string", field="hs_call_recording_url")
        # simple uri-ish check
        if not (properties["hs_call_recording_url"].startswith("http://") or properties["hs_call_recording_url"].startswith("https://")):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "hs_call_recording_url must be a valid uri", field="hs_call_recording_url")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []

    idx = None
    row = None
    for i, o in enumerate(objs):
        if isinstance(o, dict) and o.get("object_type") == "calls" and (str(o.get("hubspot_object_id")) == callId or str(o.get("id")) == callId):
            idx = i
            row = o
            break
    if not row:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Call not found")

    portal_id = row.get("portal_id")
    if row.get("status") == "archived" or row.get("archived") is True:
        _log("error", portal_id=portal_id, error_code="CONFLICT")
        return _err("CONFLICT", "Call is archived and cannot be updated.")

    now = _iso_now()
    new_row = dict(row)
    cur_props = new_row.get("properties")
    if not isinstance(cur_props, dict):
        cur_props = {}
    # Update semantics: empty string clears property; otherwise set value as provided
    for k, v in properties.items():
        cur_props[str(k)] = v
    new_row["properties"] = cur_props
    new_row["updated_at"] = now
    new_row["hubspot_updated_at"] = now
    try:
        pv = int(new_row.get("properties_version") or 1)
    except Exception:
        pv = 1
    new_row["properties_version"] = max(1, pv + 1)

    objs[idx] = new_row
    _save("crm_objects.json", objs)

    _log("success", portal_id=portal_id)
    return {
        "result": {
            "id": str(new_row.get("hubspot_object_id")),
            "properties": dict(new_row.get("properties") if isinstance(new_row.get("properties"), dict) else {}),
            "createdAt": new_row.get("hubspot_created_at") or new_row.get("created_at"),
            "updatedAt": new_row.get("hubspot_updated_at") or new_row.get("updated_at"),
            "archived": bool(new_row.get("archived")),
        }
    }

