def calls_list(limit=None, after=None, properties=None, associations=None, archived=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_list"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _iso_now(),
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "portal_id": portal_id,
                "credential_id": None,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    if limit is None:
        limit = 100
    if not isinstance(limit, (int, float)) or int(limit) != limit or int(limit) < 1 or int(limit) > 100:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    limit = int(limit)

    if after is not None and (not isinstance(after, str) or not after.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a non-empty string when provided")

    if properties is not None:
        if not isinstance(properties, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array when provided")
        props_req = [str(p) for p in properties]
    else:
        props_req = None

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}
    if associations is not None:
        if not isinstance(associations, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations must be an array when provided")
        assoc_req = []
        for a in associations:
            if not isinstance(a, str) or a not in allowed_assoc:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "associations contains unsupported value(s)")
            assoc_req.append(a)
    else:
        assoc_req = None

    if archived is not None and not isinstance(archived, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be a boolean when provided")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []

    # Determine portal context from existing calls; pick portal with most calls
    counts = {}
    for r in objs:
        if r.get("object_type") == "calls":
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                counts[pid] = counts.get(pid, 0) + 1
    if not counts:
        _log("success", portal_id=None)
        return {"results": [], "paging": None}

    portal_id = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]

    rows = [r for r in objs if r.get("portal_id") == portal_id and r.get("object_type") == "calls"]
    if not archived:
        rows = [r for r in rows if r.get("archived") is False and r.get("status") == "active"]

    rows.sort(key=lambda r: str(r.get("hubspot_object_id") or r.get("id") or ""))

    start = 0
    if after:
        for i, r in enumerate(rows):
            if str(r.get("hubspot_object_id")) == after or r.get("id") == after:
                start = i + 1
                break

    page = rows[start : start + limit]
    results = []
    assocs = _load("crm_associations.json")
    if not isinstance(assocs, list):
        assocs = []
    by_id = {r.get("id"): r for r in objs if r.get("portal_id") == portal_id}

    for r in page:
        out_props = dict(r.get("properties") or {})
        if props_req is not None:
            out_props = {k: out_props.get(k) for k in props_req}
        item = {
            "id": str(r.get("hubspot_object_id")),
            "properties": out_props,
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
            "archived": bool(r.get("archived")),
        }
        if assoc_req:
            assoc_block = {}
            for assoc_type in assoc_req:
                ids = []
                for e in assocs:
                    if (
                        e.get("portal_id") == portal_id
                        and e.get("status") == "active"
                        and e.get("archived") is False
                        and e.get("from_object_id") == r.get("id")
                        and e.get("to_object_type") == assoc_type
                    ):
                        tgt = by_id.get(e.get("to_object_id"))
                        if tgt and tgt.get("status") == "active" and tgt.get("archived") is False:
                            ids.append(str(tgt.get("hubspot_object_id")))
                assoc_block[assoc_type] = {"results": [{"id": i} for i in ids]}
            item["associations"] = assoc_block
        results.append(item)

    paging = None
    if start + limit < len(rows):
        next_after = str(page[-1].get("hubspot_object_id"))
        paging = {"next": {"after": next_after}}

    _log("success", portal_id=portal_id)
    return {"results": results, "paging": paging}

def calls_search(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_search"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # Validate filterGroups: allow presence of malformed empty dicts? no—tool requires propertyName/operator
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filterGroups must be a non-empty array")

    props_req = None
    if properties is not None:
        if not isinstance(properties, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array when provided")
        props_req = [str(p) for p in properties]

    if limit is None:
        lim = 10
    else:
        if not isinstance(limit, (int, float)):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100")
        lim = int(limit)
    if lim < 1 or lim > 100:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    if after is not None and (not isinstance(after, str)):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a string when provided")

    allowed_ops = {"EQ","NEQ","LT","LTE","GT","GTE","BETWEEN","IN","NOT_IN","HAS_PROPERTY","NOT_HAS_PROPERTY","CONTAINS_TOKEN","NOT_CONTAINS_TOKEN"}

    # Validate filters
    for gi, g in enumerate(filterGroups):
        if not isinstance(g, dict) or "filters" not in g or not isinstance(g.get("filters"), list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each filterGroup must include a filters array.", field=f"filterGroups[{gi}]")
        if len(g["filters"]) == 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each filterGroup.filters must be non-empty.", field=f"filterGroups[{gi}].filters")
        for fi, flt in enumerate(g["filters"]):
            if not isinstance(flt, dict):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each filter must be an object.", field=f"filterGroups[{gi}].filters[{fi}]")
            if "propertyName" not in flt or "operator" not in flt:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each filter must include propertyName and operator.", field=f"filterGroups[{gi}].filters[{fi}]")
            if not isinstance(flt.get("propertyName"), str) or not flt["propertyName"].strip():
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "propertyName must be a non-empty string.", field=f"filterGroups[{gi}].filters[{fi}].propertyName")
            if flt.get("operator") not in allowed_ops:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "operator is not supported.", field=f"filterGroups[{gi}].filters[{fi}].operator")

    # Validate sorts
    norm_sorts = []
    if sorts is not None:
        if not isinstance(sorts, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sorts must be an array when provided.")
        for i, s in enumerate(sorts):
            if not isinstance(s, dict) or "propertyName" not in s or "direction" not in s:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each sort must include propertyName and direction.", field=f"sorts[{i}]")
            pn = s.get("propertyName")
            dr = s.get("direction")
            if not isinstance(pn, str) or not pn.strip():
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sorts.propertyName must be a non-empty string.", field=f"sorts[{i}].propertyName")
            if dr not in ("ASCENDING", "DESCENDING"):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sorts.direction must be ASCENDING or DESCENDING.", field=f"sorts[{i}].direction")
            norm_sorts.append((pn, dr))

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []

    # Determine portal context from data (tenant-scoped): calls rows exist in a portal.
    portals = sorted({o.get("portal_id") for o in objs if isinstance(o, dict) and o.get("object_type") == "calls" and isinstance(o.get("portal_id"), str)})
    portal_id = portals[0] if portals else None

    # Filter evaluation helpers
    def _get_prop(o, pname):
        props = o.get("properties")
        if not isinstance(props, dict): 
            return None
        return props.get(pname)

    def _as_num(v):
        if v is None: return None
        if isinstance(v, (int, float)): return float(v)
        if isinstance(v, str) and v.strip() != "":
            try: return float(v)
            except Exception: return None
        return None

    def _match_filter(o, flt):
        pname = flt["propertyName"]
        op = flt["operator"]
        val = flt.get("value", None)
        prop_val = _get_prop(o, pname)

        if op == "HAS_PROPERTY":
            return prop_val is not None and not (isinstance(prop_val, str) and prop_val == "")
        if op == "NOT_HAS_PROPERTY":
            return prop_val is None or (isinstance(prop_val, str) and prop_val == "")
        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            hay = ""
            # Prefer search_text if targeting it; otherwise stringify property
            if pname == "search_text" and isinstance(o.get("search_text"), str):
                hay = o.get("search_text") or ""
            else:
                hay = "" if prop_val is None else str(prop_val)
            needle = "" if val is None else str(val)
            present = needle.lower() in hay.lower()
            return present if op == "CONTAINS_TOKEN" else (not present)

        if op in ("IN", "NOT_IN"):
            if isinstance(val, list):
                vals = val
            elif val is None:
                vals = []
            else:
                vals = [val]
            if len(vals) == 0:
                return False if op == "IN" else True
            s = str(prop_val) if prop_val is not None else None
            in_set = any(str(v) == s for v in vals)
            return in_set if op == "IN" else (not in_set)

        # comparisons: attempt numeric else string compare
        if op == "BETWEEN":
            if not isinstance(val, list) or len(val) != 2:
                return False
            a = _as_num(prop_val)
            lo = _as_num(val[0]); hi = _as_num(val[1])
            if a is not None and lo is not None and hi is not None:
                return lo <= a <= hi
            # fallback lexicographic
            s = "" if prop_val is None else str(prop_val)
            return str(val[0]) <= s <= str(val[1])

        # single-value comparisons
        if op in ("EQ", "NEQ"):
            res = str(prop_val) == str(val)
            return res if op == "EQ" else (not res)

        a = _as_num(prop_val)
        b = _as_num(val)
        if a is None or b is None:
            # fallback to lexicographic
            s1 = "" if prop_val is None else str(prop_val)
            s2 = "" if val is None else str(val)
            if op == "LT": return s1 < s2
            if op == "LTE": return s1 <= s2
            if op == "GT": return s1 > s2
            if op == "GTE": return s1 >= s2
            return False
        if op == "LT": return a < b
        if op == "LTE": return a <= b
        if op == "GT": return a > b
        if op == "GTE": return a >= b
        return False

    def _match_groups(o):
        # OR across groups; AND within group filters
        for g in filterGroups:
            ok = True
            for flt in g["filters"]:
                if not _match_filter(o, flt):
                    ok = False
                    break
            if ok:
                return True
        return False

    # Collect matching calls, excluding archived
    rows = []
    for o in objs:
        if not isinstance(o, dict): 
            continue
        if o.get("object_type") != "calls":
            continue
        if portal_id is not None and o.get("portal_id") != portal_id:
            continue
        if o.get("status") == "archived" or o.get("archived") is True:
            continue
        if _match_groups(o):
            rows.append(o)

    # Sorting
    def _sort_key(o, prop):
        if prop in ("createdAt", "created_at"):
            return o.get("hubspot_created_at") or o.get("created_at") or ""
        if prop in ("updatedAt", "updated_at"):
            return o.get("hubspot_updated_at") or o.get("updated_at") or ""
        v = _get_prop(o, prop)
        return "" if v is None else str(v)

    for prop, direction in reversed(norm_sorts):
        rev = (direction == "DESCENDING")
        rows.sort(key=lambda o, p=prop: _sort_key(o, p), reverse=rev)

    # Cursor is hubspot_object_id
    rows.sort(key=lambda o: str(o.get("hubspot_object_id") or o.get("id") or "")) if not norm_sorts else None

    start = 0
    if after:
        for i, o in enumerate(rows):
            if str(o.get("hubspot_object_id")) == after or str(o.get("id")) == after:
                start = i + 1
                break

    page = rows[start:start + lim]
    results = []
    for o in page:
        all_props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
        out_props = dict(all_props) if props_req is None else {k: all_props.get(k, "") for k in props_req}
        results.append({
            "id": str(o.get("hubspot_object_id")),
            "properties": out_props,
            "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
            "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at"),
            "archived": bool(o.get("archived")),
        })

    next_after = None
    if start + lim < len(rows) and page:
        next_after = str(page[-1].get("hubspot_object_id"))

    _log("success", portal_id=portal_id)
    resp = {"total": len(rows), "results": results}
    if next_after is not None:
        resp["paging"] = {"next": {"after": next_after}}
    return resp

def calls_batch_create(inputs, **_extra):
    import json, os, datetime, time, uuid, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_batch_create"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        props = _load("crm_object_properties.json")
        assoc_types = _load("crm_association_types.json")
        subs = _load("communications_subscriptions.json")
        candidates = []
        for r in objs:
            if r.get("object_type") == "calls":
                candidates.append(r.get("portal_id"))
        for r in props:
            if r.get("object_type") == "calls":
                candidates.append(r.get("portal_id"))
        for r in assoc_types:
            candidates.append(r.get("portal_id"))
        for r in subs:
            candidates.append(r.get("portal_id"))
        candidates = [c for c in candidates if isinstance(c, str) and c]
        if candidates:
            counts = {}
            for c in candidates:
                counts[c] = counts.get(c, 0) + 1
            return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
        return None

    portal_id = _resolve_portal_id()
    if not portal_id:
        return _err("UNAUTHORIZED", "No portal context available to serve this request.")

    def _log(status, latency_ms, error_code=None):
        fname = "service_usage.json"
        usage = _load(fname)
        if not isinstance(usage, list):
            usage = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "portal_id": portal_id,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if error_code:
            row["error_code"] = error_code
        usage.append(row)
        _save(fname, usage)

    def _rate_limit_check():
        fname = "service_usage.json"
        usage = _load(fname)
        if not isinstance(usage, list):
            return None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in usage:
            if r.get("portal_id") != portal_id or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                n += 1
        if n >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", (time.time() - t0) * 1000, rl["error"]["code"])
        return rl

    # ---------- Validation ----------
    if not isinstance(inputs, list) or len(inputs) == 0:
        e = _err("VALIDATION_ERROR", "inputs must be a non-empty array.")
        _log("error", (time.time() - t0) * 1000, e["error"]["code"])
        return e

    allowed_direction = {"INBOUND", "OUTBOUND"}
    allowed_status = {"SCHEDULED", "COMPLETED", "CANCELED", "NO_ANSWER"}

    def _is_uri(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    assocs = _load("crm_associations.json")

    # property name validation: if definitions exist for calls, require provided properties to be known,
    # BUT tool schema allows additionalProperties; allow unknowns (policy assumed permissive).
    defs_by_name = {}
    for d in prop_defs:
        if d.get("portal_id") == portal_id and d.get("object_type") == "calls":
            defs_by_name[d.get("name")] = d
    definitions_exist = any(d.get("portal_id") == portal_id and d.get("object_type") == "calls" for d in prop_defs)

    # map hubspot_object_id -> internal id for association targets in this portal
    idx_by_hid = {}
    for r in objs:
        if r.get("portal_id") == portal_id:
            idx_by_hid[(r.get("object_type"), r.get("hubspot_object_id"))] = r.get("id")

    # association type active lookup for portal
    assoc_type_active = set()
    for at in assoc_types:
        if at.get("portal_id") == portal_id and at.get("status") == "active":
            assoc_type_active.add((at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), at.get("association_type_id")))

    def _new_internal_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _next_hubspot_id_for_calls():
        mx = 0
        for r in objs:
            if r.get("portal_id") == portal_id and r.get("object_type") == "calls":
                hid = r.get("hubspot_object_id")
                try:
                    mx = max(mx, int(hid))
                except Exception:
                    continue
        return str(mx + 1)

    def _compute_search_text(properties_dict):
        if not isinstance(properties_dict, dict):
            return None
        parts = []
        for k in ("hs_call_title", "hs_call_body", "hs_call_disposition", "hs_call_status", "hs_call_direction"):
            v = properties_dict.get(k)
            if isinstance(v, str) and v.strip():
                parts.append(v.strip())
        return " ".join(parts) if parts else None

    results = []
    created_any = False

    # Precompute unique constraint for (portal_id, object_type, hubspot_object_id)
    existing_key = set()
    for r in objs:
        if r.get("portal_id") == portal_id:
            existing_key.add((r.get("object_type"), r.get("hubspot_object_id")))

    for i, inp in enumerate(inputs):
        if not isinstance(inp, dict):
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object."}})
            continue
        props = inp.get("properties")
        if not isinstance(props, dict):
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "properties must be an object."}})
            continue
        # required
        if "hs_call_body" not in props or "hs_call_title" not in props:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Missing required properties: hs_call_body, hs_call_title."}})
            continue
        if not isinstance(props.get("hs_call_body"), str) or not isinstance(props.get("hs_call_title"), str):
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "hs_call_body and hs_call_title must be strings."}})
            continue
        if "hs_call_direction" in props and props["hs_call_direction"] is not None and props["hs_call_direction"] not in allowed_direction:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_call_direction."}})
            continue
        if "hs_call_status" in props and props["hs_call_status"] is not None and props["hs_call_status"] not in allowed_status:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_call_status."}})
            continue
        if "hs_call_recording_url" in props and props["hs_call_recording_url"] is not None:
            if not _is_uri(props["hs_call_recording_url"]):
                results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_call_recording_url URI."}})
                continue
        if "hs_call_duration" in props and props["hs_call_duration"] is not None:
            if not isinstance(props["hs_call_duration"], (int, float)) or isinstance(props["hs_call_duration"], bool):
                results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "hs_call_duration must be a number."}})
                continue

        # property definition check (unknown allowed by policy; but if defined and archived/hidden isn't applicable on create)
        if definitions_exist:
            for pn in props.keys():
                if not isinstance(pn, str):
                    results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Property names must be strings."}})
                    break
                d = defs_by_name.get(pn)
                if d and d.get("status") == "archived":
                    results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": f"Property '{pn}' is archived and cannot be set."}})
                    break
            else:
                pass
            if results and results[-1].get("status") == "error" and "Property" in results[-1].get("error", {}).get("message", ""):
                continue

        # associations validation and prepare atomic changes
        assoc_payload = inp.get("associations", None)
        assoc_creates = []
        if assoc_payload is not None:
            if not isinstance(assoc_payload, list):
                results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array."}})
                continue
            bad = None
            for a in assoc_payload:
                if not isinstance(a, dict) or "to" not in a or "types" not in a:
                    bad = "Each association must include 'to' and 'types'."
                    break
                to = a.get("to")
                if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                    bad = "association.to.id must be a non-empty string."
                    break
                types = a.get("types")
                if not isinstance(types, list) or len(types) == 0:
                    bad = "association.types must be a non-empty array."
                    break
                for t in types:
                    if not isinstance(t, dict) or "associationCategory" not in t or "associationTypeId" not in t:
                        bad = "Each association type must include associationCategory and associationTypeId."
                        break
                    if not isinstance(t["associationCategory"], str) or not isinstance(t["associationTypeId"], (int, float)) or isinstance(t["associationTypeId"], bool):
                        bad = "Invalid associationCategory/associationTypeId."
                        break
                if bad:
                    break
            if bad:
                results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": bad}})
                continue

        # Build object row + association edges, but apply only if all valid (atomic per item).
        new_hid = _next_hubspot_id_for_calls()
        if ("calls", new_hid) in existing_key:
            results.append({"status": "error", "error": {"code": "CONFLICT", "message": "Generated call id conflicted; retry."}})
            continue

        internal_id = _new_internal_id("obj")
        obj_row = {
            "id": internal_id,
            "portal_id": portal_id,
            "object_type": "calls",
            "hubspot_object_id": new_hid,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props),
            "properties_version": 1,
            "search_text": _compute_search_text(props),
            "created_at": _now(),
            "updated_at": _now(),
            "hubspot_created_at": None,
            "hubspot_updated_at": None,
        }

        # prepare associations
        if assoc_payload:
            for a in assoc_payload:
                to_hid = a["to"]["id"]
                # infer target type by looking up any object with matching hubspot_object_id across supported types
                # (real HubSpot tool would know; here we resolve within portal).
                target_internal_id = None
                target_type = None
                for (ot, hid), iid in idx_by_hid.items():
                    if hid == to_hid and isinstance(iid, str):
                        target_internal_id = iid
                        target_type = ot
                        break
                if not target_internal_id:
                    results.append({"status": "error", "error": {"code": "NOT_FOUND", "message": f"Association target object id '{to_hid}' not found."}})
                    obj_row = None
                    break
                for t in a["types"]:
                    cat = t["associationCategory"]
                    tid = int(t["associationTypeId"])
                    if ("calls", target_type, cat, tid) not in assoc_type_active:
                        results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Association type is not valid or not active for this portal."}})
                        obj_row = None
                        break
                    assoc_creates.append({
                        "from_object_id": internal_id,
                        "to_object_id": target_internal_id,
                        "from_object_type": "calls",
                        "to_object_type": target_type,
                        "association_category": cat,
                        "association_type_id": tid
                    })
                if obj_row is None:
                    break
            if obj_row is None:
                continue

        # Apply mutations: add object, and upsert associations (reactivate archived if exists)
        objs.append(obj_row)
        existing_key.add(("calls", new_hid))
        idx_by_hid[("calls", new_hid)] = internal_id

        # upsert associations
        for ec in assoc_creates:
            # unique key: portal_id, from_object_id, to_object_id, association_category, association_type_id
            found = None
            for ar in assocs:
                if ar.get("portal_id") != portal_id:
                    continue
                if (ar.get("from_object_id") == ec["from_object_id"]
                    and ar.get("to_object_id") == ec["to_object_id"]
                    and ar.get("association_category") == ec["association_category"]
                    and ar.get("association_type_id") == ec["association_type_id"]):
                    found = ar
                    break
            if found:
                if found.get("status") == "archived" or found.get("archived") is True:
                    found["status"] = "active"
                    found["archived"] = False
                    found["updated_at"] = _now()
            else:
                assocs.append({
                    "id": _new_internal_id("asc"),
                    "portal_id": portal_id,
                    "from_object_id": ec["from_object_id"],
                    "to_object_id": ec["to_object_id"],
                    "from_object_type": ec["from_object_type"],
                    "to_object_type": ec["to_object_type"],
                    "association_category": ec["association_category"],
                    "association_type_id": ec["association_type_id"],
                    "status": "active",
                    "archived": False,
                    "created_at": _now(),
                    "updated_at": _now(),
                })

        created_any = True
        results.append({
            "status": "created",
            "id": new_hid,
            "properties": obj_row["properties"],
            "createdAt": obj_row["created_at"],
            "updatedAt": obj_row["updated_at"],
            "archived": False
        })

    if created_any:
        _save("crm_objects.json", objs)
        _save("crm_associations.json", assocs)

    resp = {"results": results}
    _log("ok", (time.time() - t0) * 1000)
    return resp

def calls_batch_read(inputs, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_batch_read"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}
    norm_inputs = []
    for it in inputs:
        if not isinstance(it, dict) or "id" not in it:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each input must include id")
        if not isinstance(it["id"], str) or not it["id"].strip():
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each input id must be a non-empty string")

        props_req = None
        if "properties" in it and it["properties"] is not None:
            if not isinstance(it["properties"], list):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "properties must be an array when provided")
            props_req = [str(p) for p in it["properties"]]

        assoc_req = None
        if "associations" in it and it["associations"] is not None:
            if not isinstance(it["associations"], list):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "associations must be an array when provided")
            assoc_req = []
            for a in it["associations"]:
                if not isinstance(a, str) or a not in allowed_assoc:
                    _log("error", error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "associations contains unsupported types")
                assoc_req.append(a)

        norm_inputs.append({"id": it["id"], "properties": props_req, "associations": assoc_req})

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []
    assocs = _load("crm_associations.json")
    if not isinstance(assocs, list): assocs = []

    # index
    by_id = {}
    by_hs = {}
    for o in objs:
        if o.get("object_type") != "calls":
            continue
        if isinstance(o.get("id"), str):
            by_id[o["id"]] = o
        by_hs[str(o.get("hubspot_object_id"))] = o

    # Choose portal from first resolved call if possible
    portal_id = None
    results = []
    for it in norm_inputs:
        cid = it["id"]
        row = by_hs.get(cid) or by_id.get(cid)
        if not row or row.get("status") == "archived" or row.get("archived") is True:
            results.append({"id": cid, "error": {"code": "NOT_FOUND", "message": "Call not found"}})
            continue

        portal_id = portal_id or row.get("portal_id")
        out_props = dict(row.get("properties") or {})
        if it["properties"] is not None:
            out_props = {k: out_props.get(k) for k in it["properties"]}

        item = {
            "id": str(row.get("hubspot_object_id") or row.get("id")),
            "properties": out_props,
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived")),
        }

        if it["associations"]:
            id_to_obj = {o.get("id"): o for o in objs if isinstance(o.get("id"), str)}
            assoc_out = {a: {"results": []} for a in it["associations"]}
            for a in assocs:
                if a.get("portal_id") != row.get("portal_id"):
                    continue
                if a.get("status") != "active" or a.get("archived") is True:
                    continue
                if a.get("from_object_id") != row.get("id"):
                    continue
                to_obj = id_to_obj.get(a.get("to_object_id"))
                if not to_obj or to_obj.get("status") == "archived" or to_obj.get("archived") is True:
                    continue
                to_type = to_obj.get("object_type")
                if to_type in assoc_out:
                    assoc_out[to_type]["results"].append({"id": str(to_obj.get("hubspot_object_id") or to_obj.get("id"))})
            item["associations"] = assoc_out

        results.append(item)

    _log("success", portal_id=portal_id)
    return {"results": results}

def calls_batch_update(inputs, **_extra):
    import json, os, datetime, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_batch_update"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _iso_now(),
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "portal_id": portal_id,
                "credential_id": None,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inputs must be a non-empty array")

    # preload objects
    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []

    # build quick lookup for calls by id/hubspot_object_id
    hub_to_index = {}
    id_to_index = {}
    for i, o in enumerate(objs):
        if o.get("object_type") == "calls":
            hub_to_index[str(o.get("hubspot_object_id"))] = i
            if isinstance(o.get("id"), str):
                id_to_index[o.get("id")] = i

    # group property definitions by portal for validation (defined props only)
    prop_defs = _load("crm_object_properties.json")
    if not isinstance(prop_defs, list):
        prop_defs = []
    defs_by_portal = {}
    for d in prop_defs:
        if d.get("object_type") == "calls":
            pid = d.get("portal_id")
            if isinstance(pid, str) and pid:
                defs_by_portal.setdefault(pid, {})[d.get("name")] = d

    def _validate_props(p, portal_id):
        if not isinstance(p, dict):
            return "properties must be an object"
        for req in ("hs_call_body", "hs_call_title"):
            if req not in p or not isinstance(p.get(req), str):
                return f"Missing or invalid required property: {req}"
        if "hs_call_direction" in p and p["hs_call_direction"] not in ("INBOUND", "OUTBOUND"):
            return "hs_call_direction must be INBOUND or OUTBOUND"
        if "hs_call_status" in p and p["hs_call_status"] not in ("SCHEDULED", "COMPLETED", "CANCELED", "NO_ANSWER"):
            return "hs_call_status must be one of SCHEDULED, COMPLETED, CANCELED, NO_ANSWER"
        if "hs_call_recording_url" in p and p["hs_call_recording_url"] is not None:
            if not isinstance(p["hs_call_recording_url"], str):
                return "hs_call_recording_url must be a string URI"
            u = urllib.parse.urlparse(p["hs_call_recording_url"])
            if not (u.scheme and u.netloc):
                return "hs_call_recording_url must be a valid URI"
        if "hs_call_duration" in p and p["hs_call_duration"] is not None and not isinstance(p["hs_call_duration"], (int, float)):
            return "hs_call_duration must be a number"

        defs = defs_by_portal.get(portal_id) or {}
        for k in p.keys():
            d = defs.get(k)
            if d and (d.get("archived") is True or d.get("status") == "archived"):
                return f"Property '{k}' is archived and cannot be written"
        return None

    results = []
    portal_for_log = None
    any_mutation = False

    # Apply per-item atomic updates; still proceed per item and return per-item errors
    for it in inputs:
        if not isinstance(it, dict) or "id" not in it or "properties" not in it:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Each input must contain id and properties"}})
            continue
        if not isinstance(it["id"], str) or not it["id"].strip():
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Each input id must be a non-empty string"}})
            continue

        idx = hub_to_index.get(it["id"]) if it["id"] in hub_to_index else id_to_index.get(it["id"])
        if idx is None:
            results.append({"status": "error", "error": {"code": "NOT_FOUND", "message": "Call not found", "id": it["id"]}})
            continue

        row = objs[idx]
        portal_id = row.get("portal_id")
        portal_for_log = portal_for_log or portal_id

        if row.get("archived") is True or row.get("status") == "archived":
            results.append({"status": "error", "error": {"code": "CONFLICT", "message": "Call is archived and cannot be updated", "id": it["id"]}})
            continue

        emsg = _validate_props(it.get("properties"), portal_id)
        if emsg:
            results.append({"status": "error", "error": {"code": "VALIDATION_ERROR", "message": emsg, "id": it["id"]}})
            continue

        # mutate
        now = _iso_now()
        new_row = dict(row)
        new_props = dict(row.get("properties") or {})
        new_props.update(it["properties"])
        new_row["properties"] = new_props
        new_row["updated_at"] = now
        new_row["hubspot_updated_at"] = now
        new_row["properties_version"] = int(new_row.get("properties_version") or 1) + 1
        objs[idx] = new_row
        any_mutation = True

        results.append(
            {
                "status": "success",
                "id": str(new_row.get("hubspot_object_id")),
                "properties": dict(new_row.get("properties") or {}),
                "createdAt": new_row.get("hubspot_created_at") or new_row.get("created_at"),
                "updatedAt": new_row.get("hubspot_updated_at") or new_row.get("updated_at"),
                "archived": bool(new_row.get("archived")),
            }
        )

    if any_mutation:
        _save("crm_objects.json", objs)
        _log("success", portal_id=portal_for_log)
    else:
        # No success without effect: if every item failed, return the per-item results (batch APIs do),
        # but log as error to reflect no write occurred.
        _log("error", portal_id=portal_for_log, error_code="NOT_FOUND")

    return {"results": results}

def calls_batch_archive(callIds, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calls_batch_archive"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if callIds is None or not isinstance(callIds, list) or len(callIds) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "callIds must be a non-empty array of strings")
    if any((not isinstance(x, str) or not x.strip()) for x in callIds):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "callIds contains invalid id(s); all must be non-empty strings")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []

    # Build index to mutate in place
    hub_to_index = {}
    id_to_index = {}
    for i, o in enumerate(objs):
        if o.get("object_type") != "calls":
            continue
        hub_to_index[str(o.get("hubspot_object_id"))] = i
        if isinstance(o.get("id"), str):
            id_to_index[o["id"]] = i

    now = _iso_now()
    portal_id = None
    results = []
    any_mutation = False

    for cid in callIds:
        idx = hub_to_index.get(cid)
        if idx is None:
            idx = id_to_index.get(cid)
        if idx is None:
            results.append({"id": cid, "error": {"code": "NOT_FOUND", "message": "Call not found"}})
            continue

        row = objs[idx]
        portal_id = portal_id or row.get("portal_id")

        if row.get("status") == "archived" or row.get("archived") is True:
            results.append({"id": str(row.get("hubspot_object_id") or row.get("id")), "error": {"code": "CONFLICT", "message": "Call is already archived"}})
            continue

        new_row = dict(row)
        new_row["status"] = "archived"
        new_row["archived"] = True
        new_row["updated_at"] = now
        new_row["hubspot_updated_at"] = now
        pv = new_row.get("properties_version")
        try:
            pv_i = int(pv)
        except Exception:
            pv_i = 1
        new_row["properties_version"] = max(1, pv_i + 1)

        objs[idx] = new_row
        any_mutation = True
        results.append({"id": str(new_row.get("hubspot_object_id") or new_row.get("id")), "archived": True})

    if any_mutation:
        _save("crm_objects.json", objs)

    _log("success", portal_id=portal_id)
    return {"results": results, "archivedAt": now}

def emails_create(properties, associations=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "emails_create"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, portal_id=None, detail=None):
        # No request-log collection provided in schema; do nothing.
        return

    def _is_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s or "@" not in s:
            return False
        # Simple robust-enough validation
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    # Validate properties payload
    if properties is None or not isinstance(properties, dict):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object")

    required = ["hs_email_subject", "hs_email_text", "hs_email_from_email", "hs_email_to_email"]
    missing = [k for k in required if k not in properties or properties.get(k) is None or (isinstance(properties.get(k), str) and properties.get(k).strip() == "")]
    if missing:
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required email properties", missing=missing)

    # Enum validations
    if "hs_email_status" in properties and properties["hs_email_status"] is not None:
        if properties["hs_email_status"] not in ["SENT", "DRAFT", "SCHEDULED"]:
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid hs_email_status")
    if "hs_email_direction" in properties and properties["hs_email_direction"] is not None:
        if properties["hs_email_direction"] not in ["INBOUND", "OUTBOUND"]:
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid hs_email_direction")

    # Email format validations
    if not _is_email(properties.get("hs_email_from_email")):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid hs_email_from_email email format")
    if not _is_email(properties.get("hs_email_to_email")):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid hs_email_to_email email format")

    for fld in ["hs_email_cc", "hs_email_bcc"]:
        if fld in properties and properties[fld] is not None:
            if not isinstance(properties[fld], list):
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{fld} must be an array of emails")
            for e in properties[fld]:
                if not _is_email(e):
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Invalid email in {fld}", value=e)

    if "hs_email_headers" in properties and properties["hs_email_headers"] is not None:
        if not isinstance(properties["hs_email_headers"], dict):
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "hs_email_headers must be an object")
        for k, v in properties["hs_email_headers"].items():
            if not isinstance(k, str) or not isinstance(v, str):
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "hs_email_headers must map string->string")

    # Validate associations payload
    if associations is not None:
        if not isinstance(associations, list):
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations must be an array")
        for a in associations:
            if not isinstance(a, dict):
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each association must be an object")
            if "to" not in a or "types" not in a:
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Association requires to and types")
            if not isinstance(a["to"], dict) or "id" not in a["to"] or not isinstance(a["to"]["id"], str) or not a["to"]["id"].strip():
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Association.to.id must be a non-empty string")
            if not isinstance(a["types"], list) or len(a["types"]) == 0:
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Association.types must be a non-empty array")
            for t in a["types"]:
                if not isinstance(t, dict):
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Association types entries must be objects")
                if "associationCategory" not in t or "associationTypeId" not in t:
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Association type requires associationCategory and associationTypeId")
                if not isinstance(t["associationCategory"], str) or not t["associationCategory"].strip():
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "associationCategory must be a string")
                if not isinstance(t["associationTypeId"], (int, float)) or int(t["associationTypeId"]) < 1:
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "associationTypeId must be a number >= 1")

    crm_objects = _load("crm_objects.json")
    crm_object_properties = _load("crm_object_properties.json")
    assoc_types = _load("crm_association_types.json")
    crm_associations = _load("crm_associations.json")

    # Resolve portal_id (ambient). Prefer portal that has email property definitions; else any portal.
    portal_ids = sorted({r.get("portal_id") for r in crm_objects if r.get("portal_id") is not None})
    portal_ids_props = sorted({r.get("portal_id") for r in crm_object_properties if r.get("portal_id") is not None and r.get("object_type") == "emails"})
    portal_id = portal_ids_props[0] if portal_ids_props else (portal_ids[0] if portal_ids else None)
    if portal_id is None:
        _append_log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible portal context")

    # Property name validation against definitions if definitions exist for this portal/object_type
    defs = [d for d in crm_object_properties if d.get("portal_id") == portal_id and d.get("object_type") == "emails"]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    if defs:
        unknown = [k for k in properties.keys() if k not in defs_by_name]
        # tool schema allows additionalProperties, but business rule says may be allowed only if portal policy allows.
        # No portal policy collection provided; default to allow unknown properties.
        # Still, reject writes to archived/hidden definitions if present.
        for k, v in properties.items():
            if k in defs_by_name:
                d = defs_by_name[k]
                if d.get("status") == "archived" or d.get("archived") is True:
                    _append_log("VALIDATION_ERROR", portal_id=portal_id)
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be set")
                # hidden-field policy not defined; allow.
        # unknown allowed by default

    # Prepare new object ids
    now = _iso_now()
    internal_id = "obj_" + uuid.uuid4().hex
    hubspot_object_id = str(int(time.time() * 1000)) + str(int(uuid.uuid4().int % 100000)).zfill(5)

    # uniqueness constraint: unique(portal_id, object_type, hubspot_object_id)
    if any(r.get("portal_id") == portal_id and r.get("object_type") == "emails" and r.get("hubspot_object_id") == hubspot_object_id for r in crm_objects):
        # extremely unlikely; regenerate once
        hubspot_object_id = str(int(time.time() * 1000)) + str(int(uuid.uuid4().int % 100000)).zfill(5)

    # Create object row
    search_blob = " ".join([str(v) for v in properties.values() if isinstance(v, (str, int, float))])
    obj_row = {
        "id": internal_id,
        "portal_id": portal_id,
        "object_type": "emails",
        "hubspot_object_id": hubspot_object_id,
        "custom_object_schema_id": None,
        "archived": False,
        "status": "active",
        "properties": properties,
        "properties_version": 1,
        "search_text": search_blob if search_blob else None,
        "created_at": now,
        "updated_at": now,
        "hubspot_created_at": now,
        "hubspot_updated_at": now,
    }

    # Build associations to create (validate references and association type definitions are active)
    created_assocs = []
    if associations:
        # Build index of existing objects by hubspot_object_id and internal id for this portal
        objs_portal = [r for r in crm_objects if r.get("portal_id") == portal_id and r.get("status") == "active" and r.get("archived") is False]
        by_internal = {r.get("id"): r for r in objs_portal if isinstance(r.get("id"), str)}
        by_hubspot = {}
        for r in objs_portal:
            hid = r.get("hubspot_object_id")
            if isinstance(hid, str):
                by_hubspot.setdefault(hid, r)

        # Validate all association targets exist first (atomic)
        assoc_ops = []
        for a in associations:
            to_id_in = a["to"]["id"]
            to_obj = by_internal.get(to_id_in)
            if to_obj is None:
                to_obj = by_hubspot.get(to_id_in)
            if to_obj is None:
                _append_log("NOT_FOUND", portal_id=portal_id)
                return _err("NOT_FOUND", "Association target not found", targetId=to_id_in)

            for t in a["types"]:
                cat = t["associationCategory"]
                atid = int(t["associationTypeId"])
                # Validate association type exists and active
                ok = False
                for d in assoc_types:
                    if d.get("portal_id") != portal_id:
                        continue
                    if d.get("status") != "active":
                        continue
                    if d.get("association_category") == cat and int(d.get("association_type_id")) == atid:
                        # from/to type must match this edge
                        if d.get("from_object_type") == "emails" and d.get("to_object_type") == to_obj.get("object_type"):
                            ok = True
                            break
                        if d.get("from_object_type") == to_obj.get("object_type") and d.get("to_object_type") == "emails":
                            ok = True
                            break
                if not ok:
                    _append_log("VALIDATION_ERROR", portal_id=portal_id)
                    return _err("VALIDATION_ERROR", "Association type is not defined/active for this portal and object pair",
                                associationCategory=cat, associationTypeId=atid, toObjectType=to_obj.get("object_type"))

                assoc_ops.append((to_obj, cat, atid))

        # Create/upsert edges (reactivate if archived), direction: from email to to_obj if definition supports either;
        # We'll store as from=email, to=target when possible; otherwise reverse.
        # Precompute assoc_type rows to know direction.
        assoc_type_rows = [d for d in assoc_types if d.get("portal_id") == portal_id and d.get("status") == "active"]
        def _find_assoc_type(from_t, to_t, cat, atid):
            for d in assoc_type_rows:
                if d.get("from_object_type") == from_t and d.get("to_object_type") == to_t and d.get("association_category") == cat and int(d.get("association_type_id")) == int(atid):
                    return d
            return None

        for (to_obj, cat, atid) in assoc_ops:
            dir_row = _find_assoc_type("emails", to_obj.get("object_type"), cat, atid)
            if dir_row is not None:
                from_id, to_id = internal_id, to_obj["id"]
                from_type, to_type = "emails", to_obj.get("object_type")
            else:
                from_id, to_id = to_obj["id"], internal_id
                from_type, to_type = to_obj.get("object_type"), "emails"

            # Upsert active association; if identical exists archived => reactivate
            existing_idx = None
            for i, e in enumerate(crm_associations):
                if e.get("portal_id") == portal_id and e.get("from_object_id") == from_id and e.get("to_object_id") == to_id and e.get("association_category") == cat and int(e.get("association_type_id")) == int(atid):
                    existing_idx = i
                    break
            if existing_idx is not None:
                e = crm_associations[existing_idx]
                if e.get("status") == "archived" or e.get("archived") is True:
                    e["status"] = "active"
                    e["archived"] = False
                    e["updated_at"] = now
                created_assocs.append({
                    "id": e.get("id"),
                    "fromObjectId": from_id,
                    "toObjectId": to_id,
                    "associationCategory": cat,
                    "associationTypeId": int(atid),
                    "status": e.get("status")
                })
            else:
                edge = {
                    "id": "as_" + uuid.uuid4().hex,
                    "portal_id": portal_id,
                    "from_object_id": from_id,
                    "to_object_id": to_id,
                    "from_object_type": from_type,
                    "to_object_type": to_type,
                    "association_category": cat,
                    "association_type_id": int(atid),
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now,
                }
                crm_associations.append(edge)
                created_assocs.append({
                    "id": edge["id"],
                    "fromObjectId": from_id,
                    "toObjectId": to_id,
                    "associationCategory": cat,
                    "associationTypeId": int(atid),
                    "status": "active"
                })

    # Persist object and associations
    crm_objects.append(obj_row)
    _save("crm_objects.json", crm_objects)
    if associations:
        _save("crm_associations.json", crm_associations)

    latency_ms = int((time.time() - t0) * 1000)
    _append_log("OK", portal_id=portal_id, detail={"latency_ms": latency_ms})

    # Return in a HubSpot-like envelope
    resp = {
        "id": hubspot_object_id,
        "objectType": "emails",
        "portal_id": portal_id,
        "archived": False,
        "createdAt": obj_row["hubspot_created_at"],
        "updatedAt": obj_row["hubspot_updated_at"],
        "properties": obj_row["properties"],
    }
    if created_assocs:
        resp["associationsCreated"] = created_assocs
    return resp

def emails_get(emailId, properties=None, associations=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "emails_get"

    def _append_log(status, portal_id=None, detail=None):
        # No request-log collection provided in schema; do nothing.
        return

    if emailId is None or not isinstance(emailId, str) or not emailId.strip():
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "emailId must be a non-empty string")

    if properties is not None:
        if not isinstance(properties, list) or any((not isinstance(p, str) or not p.strip()) for p in properties):
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "properties must be an array of strings")

    supported_assoc = {"contacts", "companies", "deals", "tickets"}
    if associations is not None:
        if not isinstance(associations, list) or any((not isinstance(a, str) or a not in supported_assoc) for a in associations):
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "associations contains unsupported value(s)")

    crm_objects = _load("crm_objects.json")
    crm_associations = _load("crm_associations.json")

    # Find email in any portal (ambient auth). Must be active/non-archived by default.
    email_row = None
    portal_id = None
    for r in crm_objects:
        if r.get("object_type") != "emails":
            continue
        if r.get("hubspot_object_id") == emailId or r.get("id") == emailId:
            if r.get("status") == "archived" or r.get("archived") is True:
                # treat as not found for get unless caller asked archived (tool doesn't support)
                continue
            email_row = r
            portal_id = r.get("portal_id")
            break
    if email_row is None:
        _append_log("NOT_FOUND")
        return _err("NOT_FOUND", "Email not found", emailId=emailId)

    # Filter properties
    out_props = email_row.get("properties") or {}
    if properties is not None:
        out_props = {k: out_props.get(k) for k in properties if k in out_props}

    resp = {
        "id": email_row.get("hubspot_object_id"),
        "objectType": "emails",
        "portal_id": portal_id,
        "archived": bool(email_row.get("archived")),
        "createdAt": email_row.get("hubspot_created_at") or email_row.get("created_at"),
        "updatedAt": email_row.get("hubspot_updated_at") or email_row.get("updated_at"),
        "properties": out_props,
    }

    # Associations join: return only active edges and active, non-archived associated objects
    if associations:
        # build object index by internal id
        obj_by_id = {o.get("id"): o for o in crm_objects if o.get("portal_id") == portal_id}
        assoc_out = {}
        email_internal = email_row.get("id")

        for want in associations:
            assoc_out[want] = {"results": []}

        for e in crm_associations:
            if e.get("portal_id") != portal_id:
                continue
            if e.get("status") != "active" or e.get("archived") is True:
                continue

            other_id = None
            other_type = None
            if e.get("from_object_id") == email_internal and e.get("from_object_type") == "emails":
                other_id = e.get("to_object_id")
                other_type = e.get("to_object_type")
            elif e.get("to_object_id") == email_internal and e.get("to_object_type") == "emails":
                other_id = e.get("from_object_id")
                other_type = e.get("from_object_type")

            if other_id is None or other_type is None:
                continue
            if other_type not in supported_assoc:
                continue
            if other_type not in assoc_out:
                continue

            o = obj_by_id.get(other_id)
            if not o or o.get("status") != "active" or o.get("archived") is True:
                continue
            assoc_out[other_type]["results"].append({
                "id": o.get("hubspot_object_id"),
                "objectType": other_type
            })

        resp["associations"] = assoc_out

    latency_ms = int((time.time() - t0) * 1000)
    _append_log("OK", portal_id=portal_id, detail={"latency_ms": latency_ms})
    resp["meta"] = {"latency_ms": latency_ms}
    return resp

def emails_update(emailId, properties, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "emails_update"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, portal_id=None, detail=None):
        # No request-log collection provided in schema; do nothing.
        return

    def _is_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s or "@" not in s:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    if emailId is None or not isinstance(emailId, str) or not emailId.strip():
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "emailId must be a non-empty string")
    if properties is None or not isinstance(properties, dict):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object")

    # Required fields must be present in update payload per tool description/schema
    required = ["hs_email_subject", "hs_email_text", "hs_email_from_email", "hs_email_to_email"]
    missing = [k for k in required if k not in properties or properties.get(k) is None or (isinstance(properties.get(k), str) and properties.get(k).strip() == "")]
    if missing:
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required email properties in update", missing=missing)

    # Enum validations
    if "hs_email_status" in properties and properties["hs_email_status"] is not None:
        if properties["hs_email_status"] not in ["SENT", "DRAFT", "SCHEDULED"]:
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid hs_email_status")
    if "hs_email_direction" in properties and properties["hs_email_direction"] is not None:
        if properties["hs_email_direction"] not in ["INBOUND", "OUTBOUND"]:
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid hs_email_direction")

    # Email format validations
    if not _is_email(properties.get("hs_email_from_email")):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid hs_email_from_email email format")
    if not _is_email(properties.get("hs_email_to_email")):
        _append_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid hs_email_to_email email format")

    for fld in ["hs_email_cc", "hs_email_bcc"]:
        if fld in properties and properties[fld] is not None:
            if not isinstance(properties[fld], list):
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{fld} must be an array of emails")
            for e in properties[fld]:
                if not _is_email(e):
                    _append_log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Invalid email in {fld}", value=e)

    if "hs_email_headers" in properties and properties["hs_email_headers"] is not None:
        if not isinstance(properties["hs_email_headers"], dict):
            _append_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "hs_email_headers must be an object")
        for k, v in properties["hs_email_headers"].items():
            if not isinstance(k, str) or not isinstance(v, str):
                _append_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "hs_email_headers must map string->string")

    crm_objects = _load("crm_objects.json")
    crm_object_properties = _load("crm_object_properties.json")

    # Locate the email across portals (ambient auth)
    idx = None
    email_row = None
    for i, r in enumerate(crm_objects):
        if r.get("object_type") != "emails":
            continue
        if r.get("hubspot_object_id") == emailId or r.get("id") == emailId:
            email_row = r
            idx = i
            break
    if email_row is None:
        _append_log("NOT_FOUND")
        return _err("NOT_FOUND", "Email not found", emailId=emailId)

    portal_id = email_row.get("portal_id")
    if email_row.get("status") == "archived" or email_row.get("archived") is True:
        _append_log("INVALID_TRANSITION", portal_id=portal_id)
        return _err("INVALID_TRANSITION", "Cannot update an archived email")

    # Validate against property definitions if exist
    defs = [d for d in crm_object_properties if d.get("portal_id") == portal_id and d.get("object_type") == "emails"]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    if defs:
        for k, v in properties.items():
            if k in defs_by_name:
                d = defs_by_name[k]
                if d.get("status") == "archived" or d.get("archived") is True:
                    _append_log("VALIDATION_ERROR", portal_id=portal_id)
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be updated")
                # hidden-field policy not defined; allow.
            # unknown allowed by default because tool schema allows additionalProperties

    # Apply update; clearing is empty string in properties JSON (allowed)
    now = _iso_now()
    merged = dict(email_row.get("properties") or {})
    for k, v in properties.items():
        merged[k] = v

    # Update search_text and versions
    search_blob = " ".join([str(v) for v in merged.values() if isinstance(v, (str, int, float))])
    email_row["properties"] = merged
    email_row["properties_version"] = int(email_row.get("properties_version") or 1) + 1
    email_row["search_text"] = search_blob if search_blob else None
    email_row["updated_at"] = now
    email_row["hubspot_updated_at"] = now

    crm_objects[idx] = email_row
    _save("crm_objects.json", crm_objects)

    latency_ms = int((time.time() - t0) * 1000)
    _append_log("OK", portal_id=portal_id, detail={"latency_ms": latency_ms})

    return {
        "id": email_row.get("hubspot_object_id"),
        "objectType": "emails",
        "portal_id": portal_id,
        "archived": bool(email_row.get("archived")),
        "createdAt": email_row.get("hubspot_created_at") or email_row.get("created_at"),
        "updatedAt": email_row.get("hubspot_updated_at") or email_row.get("updated_at"),
        "properties": email_row.get("properties") or {},
        "meta": {"latency_ms": latency_ms, "properties_version": email_row.get("properties_version")}
    }

def emails_archive(emailId, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "emails_archive"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(portal_id):
        limits = _load("service_limits.json")
        if not isinstance(limits, list): limits = []
        lim = None
        for r in limits:
            if isinstance(r, dict) and r.get("portal_id") == portal_id:
                lim = r
                break
        if not lim:
            return None  # no limits configured

        now = datetime.datetime.utcnow()
        # per-minute
        rpm = lim.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)

        # daily quota
        dq = lim.get("requests_per_day")
        if isinstance(dq, int) and dq > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= dq:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=dq, window_seconds=86400)

        return None

    # Validate input
    if emailId is None or not isinstance(emailId, str) or not emailId.strip():
        _log("VALIDATION_ERROR", None, {"field": "emailId"})
        return _err("VALIDATION_ERROR", "emailId is required and must be a non-empty string", field="emailId")

    # Resolve ambient portal_id by finding a portal that can service emails operations
    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []
    candidate_portals = []
    for o in objs:
        if isinstance(o, dict) and o.get("object_type") == "emails":
            pid = o.get("portal_id")
            if isinstance(pid, str) and pid and pid not in candidate_portals:
                candidate_portals.append(pid)

    if not candidate_portals:
        _log("UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No authenticated portal context available for emails operations")

    # Find the email in any portal (but operations are tenant-scoped; pick portal where id exists)
    target = None
    portal_id = None
    for pid in candidate_portals:
        for o in objs:
            if not isinstance(o, dict): 
                continue
            if o.get("portal_id") != pid or o.get("object_type") != "emails":
                continue
            if str(o.get("hubspot_object_id")) == emailId:
                target = o
                portal_id = pid
                break
        if target:
            break

    if portal_id is None:
        # Still enforce rate limits? Real services usually charge even on 404; but portal unknown. Log without portal.
        _log("NOT_FOUND", None, {"emailId": emailId})
        return _err("NOT_FOUND", "Email not found", emailId=emailId)

    rl = _rate_limit_check(portal_id)
    if rl:
        _log(rl["error"]["code"], portal_id)
        return rl

    # Mutate: archive object
    if not target:
        _log("NOT_FOUND", portal_id, {"emailId": emailId})
        return _err("NOT_FOUND", "Email not found", emailId=emailId)

    # Transition check
    status = target.get("status")
    if status not in ("active", "archived"):
        _log("CONFLICT", portal_id, {"emailId": emailId})
        return _err("CONFLICT", "Corrupt lifecycle state for email", emailId=emailId, status=status)

    if status == "archived":
        # Idempotent archive: already archived => success with current record
        resp = {"id": target.get("hubspot_object_id"), "archived": True}
        _log("OK", portal_id, {"emailId": emailId, "idempotent": True})
        return resp

    # Apply transition active -> archived
    now = _now()
    target["status"] = "archived"
    target["archived"] = True
    target["updated_at"] = now
    target["hubspot_updated_at"] = now
    pv = target.get("properties_version")
    if isinstance(pv, int) and pv >= 1:
        target["properties_version"] = pv + 1
    else:
        target["properties_version"] = 1

    _save("crm_objects.json", objs)

    _log("OK", portal_id, {"emailId": emailId})
    return {"id": target.get("hubspot_object_id"), "archived": True}

def emails_list(limit=None, after=None, properties=None, associations=None, archived=None, **_extra):
