        _save("request_logs.json", logs)

    def _rate_limit_check(portal_id):
        limits = _load("service_limits.json")
        if not isinstance(limits, list): limits = []
        lim = None
        for r in limits:
            if isinstance(r, dict) and r.get("portal_id") == portal_id:
                lim = r
                break
        if not lim:
            return None
        now = datetime.datetime.utcnow()
        rpm = lim.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        dq = lim.get("requests_per_day")
        if isinstance(dq, int) and dq > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= dq:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=dq, window_seconds=86400)
        return None

    # Validate inputs
    if limit is None:
        limit = 100
    if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
        _log("VALIDATION_ERROR", None, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100", field="limit")
    limit = int(limit)
    if limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", None, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if after is not None and (not isinstance(after, str)):
        _log("VALIDATION_ERROR", None, {"field": "after"})
        return _err("VALIDATION_ERROR", "after must be a string cursor", field="after")

    if properties is not None:
        if not isinstance(properties, list) or any(not isinstance(p, str) for p in properties):
            _log("VALIDATION_ERROR", None, {"field": "properties"})
            return _err("VALIDATION_ERROR", "properties must be an array of strings", field="properties")

    allowed_assoc = {"contacts", "companies", "deals", "tickets"}
    if associations is not None:
        if not isinstance(associations, list) or any((not isinstance(a, str) or a not in allowed_assoc) for a in associations):
            _log("VALIDATION_ERROR", None, {"field": "associations"})
            return _err("VALIDATION_ERROR", "associations contains an unsupported type", field="associations", allowed=sorted(list(allowed_assoc)))

    if archived is not None and not isinstance(archived, bool):
        _log("VALIDATION_ERROR", None, {"field": "archived"})
        return _err("VALIDATION_ERROR", "archived must be a boolean", field="archived")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []

    # Resolve portal_id with any emails capability
    portal_ids = []
    for o in objs:
        if isinstance(o, dict) and o.get("object_type") == "emails":
            pid = o.get("portal_id")
            if isinstance(pid, str) and pid and pid not in portal_ids:
                portal_ids.append(pid)

    if not portal_ids:
        _log("UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No authenticated portal context available for emails operations")

    portal_id = portal_ids[0]
    rl = _rate_limit_check(portal_id)
    if rl:
        _log(rl["error"]["code"], portal_id)
        return rl

    # Filter for portal + object_type + archived flag
    want_archived = bool(archived) if archived is not None else False
    rows = []
    for o in objs:
        if not isinstance(o, dict): 
            continue
        if o.get("portal_id") != portal_id or o.get("object_type") != "emails":
            continue
        if not want_archived and o.get("archived") is True:
            continue
        rows.append(o)

    # Default sort: created_at desc (HubSpot list endpoints often return by createdAt desc)
    def _dt(s):
        if not isinstance(s, str): 
            return datetime.datetime.min
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min
    rows.sort(key=lambda r: _dt(r.get("created_at")), reverse=True)

    # Cursor pagination: after is an offset encoded as string int
    start = 0
    if after:
        try:
            start = int(after)
            if start < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR", portal_id, {"field": "after"})
            return _err("VALIDATION_ERROR", "after must be a valid cursor", field="after")

    page = rows[start:start + limit]
    next_after = None
    if start + limit < len(rows):
        next_after = str(start + limit)

    # Build associations if requested
    assoc_edges = _load("crm_associations.json")
    if not isinstance(assoc_edges, list): assoc_edges = []
    objs_by_id = {}
    for o in objs:
        if isinstance(o, dict) and o.get("portal_id") == portal_id:
            oid = o.get("id")
            if isinstance(oid, str):
                objs_by_id[oid] = o

    def _assoc_for(email_row):
        if not associations:
            return None
        email_internal_id = email_row.get("id")
        out = {}
        for atype in associations:
            out[atype] = {"results": []}
        for e in assoc_edges:
            if not isinstance(e, dict): 
                continue
            if e.get("portal_id") != portal_id:
                continue
            if e.get("status") != "active" or e.get("archived") is True:
                continue
            if e.get("from_object_id") != email_internal_id:
                continue
            to_id = e.get("to_object_id")
            to_obj = objs_by_id.get(to_id)
            if not to_obj or to_obj.get("archived") is True or to_obj.get("status") != "active":
                continue
            to_type = to_obj.get("object_type")
            if to_type in out:
                out[to_type]["results"].append({"id": to_obj.get("hubspot_object_id")})
        return out

    results = []
    for r in page:
        item = {
            "id": r.get("hubspot_object_id"),
            "archived": bool(r.get("archived")),
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
        }
        props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        if properties is None:
            item["properties"] = dict(props)
        else:
            item["properties"] = {k: props.get(k) for k in properties}
        assoc_block = _assoc_for(r)
        if assoc_block is not None:
            item["associations"] = assoc_block
        results.append(item)

    resp = {
        "total": len(rows),
        "results": results,
        "paging": {"next": {"after": next_after}} if next_after is not None else None
    }
    _log("OK", portal_id, {"returned": len(results), "total": len(rows), "after_in": after, "after_out": next_after})
    return resp

def emails_search(filterGroups, properties=None, limit=None, after=None, sorts=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "emails_search"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(portal_id):
        limits = _load("service_limits.json")
        if not isinstance(limits, list): limits = []
        lim = None
        for r in limits:
            if isinstance(r, dict) and r.get("portal_id") == portal_id:
                lim = r
                break
        if not lim:
            return None
        now = datetime.datetime.utcnow()
        rpm = lim.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        dq = lim.get("requests_per_day")
        if isinstance(dq, int) and dq > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= dq:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=dq, window_seconds=86400)
        return None

    # Validate
    if not isinstance(filterGroups, list) or len(filterGroups) == 0:
        _log("VALIDATION_ERROR", None, {"field": "filterGroups"})
        return _err("VALIDATION_ERROR", "filterGroups is required and must be a non-empty array", field="filterGroups")
    for i, g in enumerate(filterGroups):
        if not isinstance(g, dict) or "filters" not in g or not isinstance(g["filters"], list):
            _log("VALIDATION_ERROR", None, {"field": "filterGroups"})
            return _err("VALIDATION_ERROR", "Each filterGroup must contain a filters array", field="filterGroups", index=i)
        for j, f in enumerate(g["filters"]):
            if not isinstance(f, dict):
                _log("VALIDATION_ERROR", None, {"field": "filterGroups"})
                return _err("VALIDATION_ERROR", "Each filter must be an object", field="filterGroups", group=i, index=j)
            if "propertyName" not in f or "operator" not in f:
                _log("VALIDATION_ERROR", None, {"field": "filterGroups"})
                return _err("VALIDATION_ERROR", "Each filter must include propertyName and operator", field="filterGroups", group=i, index=j)
            if not isinstance(f["propertyName"], str) or not f["propertyName"]:
                _log("VALIDATION_ERROR", None, {"field": "propertyName"})
                return _err("VALIDATION_ERROR", "propertyName must be a non-empty string", field="propertyName", group=i, index=j)
            if f["operator"] not in {"EQ","NEQ","LT","LTE","GT","GTE","BETWEEN","IN","NOT_IN","HAS_PROPERTY","NOT_HAS_PROPERTY","CONTAINS_TOKEN","NOT_CONTAINS_TOKEN"}:
                _log("VALIDATION_ERROR", None, {"field": "operator"})
                return _err("VALIDATION_ERROR", "Unsupported operator", field="operator", group=i, index=j, operator=f["operator"])

    if properties is not None:
        if not isinstance(properties, list) or any(not isinstance(p, str) for p in properties):
            _log("VALIDATION_ERROR", None, {"field": "properties"})
            return _err("VALIDATION_ERROR", "properties must be an array of strings", field="properties")

    if limit is None:
        limit = 100
    if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
        _log("VALIDATION_ERROR", None, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100", field="limit")
    limit = int(limit)
    if limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", None, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if after is not None and not isinstance(after, str):
        _log("VALIDATION_ERROR", None, {"field": "after"})
        return _err("VALIDATION_ERROR", "after must be a string cursor", field="after")

    if sorts is not None:
        if not isinstance(sorts, list):
            _log("VALIDATION_ERROR", None, {"field": "sorts"})
            return _err("VALIDATION_ERROR", "sorts must be an array", field="sorts")
        for i, s in enumerate(sorts):
            if not isinstance(s, dict) or "propertyName" not in s or "direction" not in s:
                _log("VALIDATION_ERROR", None, {"field": "sorts"})
                return _err("VALIDATION_ERROR", "Each sort must include propertyName and direction", field="sorts", index=i)
            if not isinstance(s["propertyName"], str) or not s["propertyName"]:
                _log("VALIDATION_ERROR", None, {"field": "sorts"})
                return _err("VALIDATION_ERROR", "sort.propertyName must be a non-empty string", field="sorts", index=i)
            if s["direction"] not in {"ASCENDING","DESCENDING"}:
                _log("VALIDATION_ERROR", None, {"field": "sorts"})
                return _err("VALIDATION_ERROR", "sort.direction must be ASCENDING or DESCENDING", field="sorts", index=i)

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []

    # Resolve portal_id with any emails
    portal_ids = []
    for o in objs:
        if isinstance(o, dict) and o.get("object_type") == "emails":
            pid = o.get("portal_id")
            if isinstance(pid, str) and pid and pid not in portal_ids:
                portal_ids.append(pid)
    if not portal_ids:
        _log("UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No authenticated portal context available for emails operations")
    portal_id = portal_ids[0]

    rl = _rate_limit_check(portal_id)
    if rl:
        _log(rl["error"]["code"], portal_id)
        return rl

    # Operator evaluation
    def _to_num(v):
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
        if isinstance(v, str):
            try:
                return float(v)
            except Exception:
                return None
        return None

    def _get_prop(row, pname):
        props = row.get("properties")
        if isinstance(props, dict) and pname in props:
            return props.get(pname)
        if pname == "hs_object_id":
            return row.get("hubspot_object_id")
        return None

    def _tokens(s):
        if not isinstance(s, str):
            return []
        return [t for t in re.split(r"[\s,;|]+", s.lower()) if t]

    def _match_filter(row, f):
        pname = f["propertyName"]
        op = f["operator"]
        val = f.get("value", None)
        prop_val = _get_prop(row, pname)

        if op == "HAS_PROPERTY":
            return prop_val is not None and prop_val != ""
        if op == "NOT_HAS_PROPERTY":
            return prop_val is None or prop_val == ""

        if op in ("IN", "NOT_IN"):
            vals = val
            if isinstance(vals, list):
                if len(vals) == 0:
                    return False
            else:
                vals = [vals]
            ok = any(str(prop_val) == str(x) for x in vals)
            return ok if op == "IN" else (not ok)

        if op == "BETWEEN":
            if not isinstance(val, list) or len(val) != 2:
                return False
            a, b = val[0], val[1]
            pn = _to_num(prop_val)
            an = _to_num(a); bn = _to_num(b)
            if pn is not None and an is not None and bn is not None:
                lo, hi = (an, bn) if an <= bn else (bn, an)
                return lo <= pn <= hi
            ps = str(prop_val) if prop_val is not None else ""
            return str(a) <= ps <= str(b)

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            needle = str(val) if val is not None else ""
            if needle == "":
                return False if op == "CONTAINS_TOKEN" else True
            st = row.get("search_text")
            hay = st if isinstance(st, str) and st else ""
            ok = needle.lower() in _tokens(hay)
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        # comparisons
        if prop_val is None:
            return False if op in ("EQ","LT","LTE","GT","GTE") else True  # NEQ: missing treated as not equal
        if op == "EQ":
            return str(prop_val) == str(val)
        if op == "NEQ":
            return str(prop_val) != str(val)

        pn = _to_num(prop_val)
        vn = _to_num(val)
        if pn is not None and vn is not None:
            if op == "LT": return pn < vn
            if op == "LTE": return pn <= vn
            if op == "GT": return pn > vn
            if op == "GTE": return pn >= vn
        # string fallback
        ps = str(prop_val)
        vs = str(val)
        if op == "LT": return ps < vs
        if op == "LTE": return ps <= vs
        if op == "GT": return ps > vs
        if op == "GTE": return ps >= vs
        return False

    def _match(row):
        # OR across groups, AND within group
        for g in filterGroups:
            ok = True
            for f in g["filters"]:
                if not _match_filter(row, f):
                    ok = False
                    break
            if ok:
                return True
        return False

    rows = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("portal_id") != portal_id or o.get("object_type") != "emails":
            continue
        if o.get("archived") is True:
            continue
        if _match(o):
            rows.append(o)

    def _dt(s):
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min

    # Sorting
    if sorts and len(sorts) > 0:
        # stable sort from last key to first
        for s in reversed(sorts):
            pname = s["propertyName"]
            desc = (s["direction"] == "DESCENDING")
            def _key(r):
                if pname in ("createdAt", "created_at"):
                    return _dt(r.get("created_at"))
                if pname in ("updatedAt", "updated_at"):
                    return _dt(r.get("updated_at"))
                v = _get_prop(r, pname)
                n = _to_num(v)
                return (0, n) if n is not None else (1, "" if v is None else str(v))
            rows.sort(key=_key, reverse=desc)
    else:
        rows.sort(key=lambda r: _dt(r.get("created_at")), reverse=True)

    # Pagination by offset cursor
    start = 0
    if after:
        try:
            start = int(after)
            if start < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR", portal_id, {"field": "after"})
            return _err("VALIDATION_ERROR", "after must be a valid cursor", field="after")

    page = rows[start:start + limit]
    next_after = str(start + limit) if (start + limit) < len(rows) else None

    results = []
    for r in page:
        props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        out_props = dict(props) if properties is None else {k: props.get(k) for k in properties}
        results.append({
            "id": r.get("hubspot_object_id"),
            "archived": bool(r.get("archived")),
            "createdAt": r.get("hubspot_created_at") or r.get("created_at"),
            "updatedAt": r.get("hubspot_updated_at") or r.get("updated_at"),
            "properties": out_props
        })

    resp = {
        "total": len(rows),
        "results": results,
        "paging": {"next": {"after": next_after}} if next_after is not None else None
    }
    _log("OK", portal_id, {"returned": len(results), "total": len(rows), "after_in": after, "after_out": next_after})
    return resp

def emails_batch_create(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
