        _save("request_logs.json", logs)

    def _rate_limit_check(portal_id):
        limits = _load("service_limits.json")
        if not isinstance(limits, list): limits = []
        lim = None
        for r in limits:
            if isinstance(r, dict) and r.get("portal_id") == portal_id:
                lim = r
                break
        if not lim:
            return None
        now = datetime.datetime.utcnow()
        rpm = lim.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        dq = lim.get("requests_per_day")
        if isinstance(dq, int) and dq > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for lr in logs:
                if not isinstance(lr, dict): 
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = lr.get("timestamp")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= dq:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=dq, window_seconds=86400)
        return None

    # Validate inputs list
    if not isinstance(inputs, list) or len(inputs) == 0:
        _log("VALIDATION_ERROR", None, {"field": "inputs"})
        return _err("VALIDATION_ERROR", "inputs is required and must be a non-empty array", field="inputs")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []
    props_defs = _load("crm_object_properties.json")
    if not isinstance(props_defs, list): props_defs = []
    assoc_types = _load("crm_association_types.json")
    if not isinstance(assoc_types, list): assoc_types = []
    assoc_edges = _load("crm_associations.json")
    if not isinstance(assoc_edges, list): assoc_edges = []

    # Resolve portal_id with any existing records; if none, but there are defs for emails, use that portal; else unauthorized
    portal_ids = []
    for o in objs:
        if isinstance(o, dict):
            pid = o.get("portal_id")
            if isinstance(pid, str) and pid and pid not in portal_ids:
                portal_ids.append(pid)
    if not portal_ids:
        for d in props_defs:
            if isinstance(d, dict):
                pid = d.get("portal_id")
                if isinstance(pid, str) and pid and pid not in portal_ids:
                    portal_ids.append(pid)
    if not portal_ids:
        _log("UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No authenticated portal context available")

    portal_id = portal_ids[0]
    rl = _rate_limit_check(portal_id)
    if rl:
        _log(rl["error"]["code"], portal_id)
        return rl

    # Email address validation
    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    required_props = ["hs_email_subject", "hs_email_text", "hs_email_from_email", "hs_email_to_email"]
    allowed_enum_status = {"SENT", "DRAFT", "SCHEDULED"}
    allowed_enum_dir = {"INBOUND", "OUTBOUND"}

    # Build property definitions map for emails in this portal
    defs = [d for d in props_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "emails"]
    defs_by_name = {d.get("name"): d for d in defs if isinstance(d.get("name"), str)}
    defs_exist = len(defs_by_name) > 0

    # Prepare crm_objects lookup for association targets by hubspot_object_id (string) within portal
    by_hs = {}
    by_internal = {}
    for o in objs:
        if not isinstance(o, dict) or o.get("portal_id") != portal_id:
            continue
        hid = o.get("hubspot_object_id")
        iid = o.get("id")
        if isinstance(hid, str):
            by_hs[(o.get("object_type"), hid)] = o
        if isinstance(iid, str):
            by_internal[iid] = o

    # Active association type set for portal for fast validation
    active_assoc_type_keys = set()
    for at in assoc_types:
        if not isinstance(at, dict): 
            continue
        if at.get("portal_id") != portal_id:
            continue
        if at.get("status") != "active":
            continue
        k = (at.get("from_object_type"), at.get("to_object_type"), at.get("association_category"), at.get("association_type_id"))
        active_assoc_type_keys.add(k)

    # Helpers
    def _gen_id(prefix, existing_ids):
        # simple monotonic-ish id
        base = int(time.time() * 1000)
        i = 0
        while True:
            cid = f"{prefix}_{base}_{i}"
            if cid not in existing_ids:
                return cid
            i += 1

    def _next_hubspot_object_id():
        mx = 0
        for o in objs:
            if not isinstance(o, dict) or o.get("portal_id") != portal_id or o.get("object_type") != "emails":
                continue
            s = o.get("hubspot_object_id")
            try:
                n = int(str(s))
                if n > mx:
                    mx = n
            except Exception:
                continue
        return str(mx + 1 if mx >= 0 else 1)

    existing_obj_ids = set([o.get("id") for o in objs if isinstance(o, dict) and isinstance(o.get("id"), str)])
    existing_edge_ids = set([e.get("id") for e in assoc_edges if isinstance(e, dict) and isinstance(e.get("id"), str)])

    results = []
    errors = []

    now = _now()

    # Process each input atomically (per-item)
    for idx, inp in enumerate(inputs):
        if not isinstance(inp, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each input must be an object"}})
            continue
        props = inp.get("properties")
        if not isinstance(props, dict):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "properties is required and must be an object", "field": "properties"}})
            continue

        missing = [p for p in required_props if not isinstance(props.get(p), str) or props.get(p) == ""]
        if missing:
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Missing required properties", "missing": missing}})
            continue

        # validate known enums
        if "hs_email_status" in props and props["hs_email_status"] is not None:
            if not isinstance(props["hs_email_status"], str) or props["hs_email_status"] not in allowed_enum_status:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_email_status", "field": "hs_email_status"}})
                continue
        if "hs_email_direction" in props and props["hs_email_direction"] is not None:
            if not isinstance(props["hs_email_direction"], str) or props["hs_email_direction"] not in allowed_enum_dir:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid hs_email_direction", "field": "hs_email_direction"}})
                continue

        # validate emails
        fe = props.get("hs_email_from_email")
        te = props.get("hs_email_to_email")
        if not (isinstance(fe, str) and email_re.match(fe or "")):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid from email", "field": "hs_email_from_email"}})
            continue
        if not (isinstance(te, str) and email_re.match(te or "")):
            errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Invalid to email", "field": "hs_email_to_email"}})
            continue
        for f in ("hs_email_cc", "hs_email_bcc"):
            if f in props and props[f] is not None:
                if not isinstance(props[f], list) or any((not isinstance(x, str) or not email_re.match(x or "")) for x in props[f]):
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": f"Invalid email(s) in {f}", "field": f}})
                    break
        else:
            pass
        if errors and len(errors) > 0 and errors[-1].get("index") == idx:
            continue

        # validate property names if definitions exist (unknown allowed by tool schema, but business rule says validate when defs exist)
        if defs_exist:
            bad = []
            for k in props.keys():
                if not isinstance(k, str):
                    bad.append(str(k))
                    continue
                d = defs_by_name.get(k)
                if d is None:
                    bad.append(k)
                else:
                    if d.get("status") == "archived" or d.get("archived") is True:
                        bad.append(k)
                    if d.get("hidden") is True:
                        # no portal policy store provided; default forbid hidden writes when hidden=true
                        bad.append(k)
            if bad:
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Unknown/archived/hidden properties not allowed", "properties": bad}})
                continue

        # validate associations if present
        assocs = inp.get("associations")
        planned_edges = []
        if assocs is not None:
            if not isinstance(assocs, list):
                errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associations must be an array", "field": "associations"}})
                continue
            ok = True
            for a_i, a in enumerate(assocs):
                if not isinstance(a, dict) or "to" not in a or "types" not in a:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each association must include to and types", "field": "associations", "associationIndex": a_i}})
                    ok = False
                    break
                to = a.get("to")
                if not isinstance(to, dict) or not isinstance(to.get("id"), str) or not to.get("id"):
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.to.id is required", "field": "associations", "associationIndex": a_i}})
                    ok = False
                    break
                types = a.get("types")
                if not isinstance(types, list) or len(types) == 0:
                    errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "association.types must be a non-empty array", "field": "associations", "associationIndex": a_i}})
                    ok = False
                    break

                # Resolve target object in portal across known CRM object types
                target_internal = None
                target_type = None
                # try common types first + any
                for ot in ["contacts", "companies", "deals", "tickets", "products", "line_items", "quotes", "leads", "meetings", "notes", "tasks", "calls", "emails", "engagements", "custom"]:
                    o = by_hs.get((ot, to["id"]))
                    if o and o.get("archived") is not True and o.get("status") == "active":
                        target_internal = o.get("id")
                        target_type = ot
                        break
                if not target_internal:
                    errors.append({"index": idx, "error": {"code": "NOT_FOUND", "message": "Association target not found", "associationIndex": a_i, "toId": to.get("id")}})
                    ok = False
                    break

                for t_i, t in enumerate(types):
                    if not isinstance(t, dict) or "associationCategory" not in t or "associationTypeId" not in t:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Each association type must include associationCategory and associationTypeId", "associationIndex": a_i, "typeIndex": t_i}})
                        ok = False
                        break
                    cat = t.get("associationCategory")
                    tid = t.get("associationTypeId")
                    if not isinstance(cat, str) or not cat:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationCategory must be a string", "associationIndex": a_i, "typeIndex": t_i}})
                        ok = False
                        break
                    if not (isinstance(tid, int) or isinstance(tid, float)) or isinstance(tid, bool) or int(tid) < 1:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "associationTypeId must be a number >= 1", "associationIndex": a_i, "typeIndex": t_i}})
                        ok = False
                        break
                    tid = int(tid)

                    key = ("emails", target_type, cat, tid)
                    if key not in active_assoc_type_keys:
                        errors.append({"index": idx, "error": {"code": "VALIDATION_ERROR", "message": "Association type is not defined/active", "associationIndex": a_i, "typeIndex": t_i, "from": "emails", "to": target_type, "associationCategory": cat, "associationTypeId": tid}})
                        ok = False
                        break
                    planned_edges.append({"to_object_id": target_internal, "to_object_type": target_type, "association_category": cat, "association_type_id": tid})
                if not ok:
                    break
            if not ok:
                continue

        # Item is valid => apply changes to in-memory copies, then persist once at end (safe per-item atomicity in return)
        # Create the email object row
        new_internal_id = _gen_id("obj", existing_obj_ids)
        existing_obj_ids.add(new_internal_id)
        new_hs_id = _next_hubspot_object_id()

        # search_text from some properties
        st_parts = []
        for k in ["hs_email_subject", "hs_email_text", "hs_email_html", "hs_email_from_email", "hs_email_to_email"]:
            v = props.get(k)
            if isinstance(v, str) and v:
                st_parts.append(v)
        search_text = " ".join(st_parts) if st_parts else None

        obj_row = {
            "id": new_internal_id,
            "portal_id": portal_id,
            "object_type": "emails",
            "hubspot_object_id": new_hs_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": dict(props),
            "properties_version": 1,
            "search_text": search_text,
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now
        }

        # Enforce unique(portal_id, object_type, hubspot_object_id)
        conflict = False
        for o in objs:
            if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "emails" and o.get("hubspot_object_id") == new_hs_id:
                conflict = True
                break
        if conflict:
            errors.append({"index": idx, "error": {"code": "CONFLICT", "message": "Generated hubspot_object_id conflict"}})
            continue

        # Create/upsert associations (if an identical edge exists archived, reactivate)
        created_edges = []
        for pe in planned_edges:
            # unique(portal_id, from_object_id, to_object_id, association_category, association_type_id)
            existing = None
            for e in assoc_edges:
                if not isinstance(e, dict):
                    continue
                if e.get("portal_id") != portal_id:
                    continue
                if e.get("from_object_id") == new_internal_id and e.get("to_object_id") == pe["to_object_id"] and e.get("association_category") == pe["association_category"] and int(e.get("association_type_id")) == int(pe["association_type_id"]):
                    existing = e
                    break
            if existing:
                if existing.get("status") == "archived" or existing.get("archived") is True:
                    existing["status"] = "active"
                    existing["archived"] = False
                    existing["updated_at"] = now
                created_edges.append(existing)
            else:
                edge_id = _gen_id("assoc", existing_edge_ids)
                existing_edge_ids.add(edge_id)
                edge_row = {
                    "id": edge_id,
                    "portal_id": portal_id,
                    "from_object_id": new_internal_id,
                    "to_object_id": pe["to_object_id"],
                    "from_object_type": "emails",
                    "to_object_type": pe["to_object_type"],
                    "association_category": pe["association_category"],
                    "association_type_id": pe["association_type_id"],
                    "status": "active",
                    "archived": False,
                    "created_at": now,
                    "updated_at": now
                }
                assoc_edges.append(edge_row)
                created_edges.append(edge_row)

        # Commit object
        objs.append(obj_row)
        by_hs[("emails", new_hs_id)] = obj_row
        by_internal[new_internal_id] = obj_row

        # Output record
        results.append({
            "id": new_hs_id,
            "archived": False,
            "createdAt": now,
            "updatedAt": now,
            "properties": dict(obj_row["properties"]),
        })

    # Persist if any successes or association reactivations happened
    # We must ensure "no success without effect": if no results and no association edits, return a validation error? Here, inputs non-empty.
    # We'll save only when something actually changed: results length > 0 OR we reactivated any edge (possible even without results? not in this tool).
    if len(results) > 0:
        _save("crm_objects.json", objs)
        _save("crm_associations.json", assoc_edges)

    resp = {"results": results}
    if errors:
        resp["errors"] = errors

    _log("OK" if results else ("VALIDATION_ERROR" if errors else "NOT_FOUND"), portal_id, {"created": len(results), "errors": len(errors)})
    if not results and errors:
        # When all items invalid, behave like real batch endpoints: still 200-ish with per-item errors. Use OK envelope already.
        return resp
    if not results and not errors:
        return _err("NOT_FOUND", "No inputs were created")
    return resp

def emails_batch_read(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Ambient auth/tenant resolution (best-effort, choose any portal with email objects) ---
    objs = _load("crm_objects.json")
    portals_with_email = {o.get("portal_id") for o in objs if o.get("object_type") == "emails"}
    portal_id = None
    if portals_with_email:
        portal_id = sorted([p for p in portals_with_email if isinstance(p, str) and p])[0]
    else:
        # If no emails exist, still pick any portal_id available; otherwise unauthorized.
        any_portals = {o.get("portal_id") for o in objs if isinstance(o.get("portal_id"), str) and o.get("portal_id")}
        portal_id = sorted(list(any_portals))[0] if any_portals else None

    # Request log dynamics (if collection exists)
    reqlog = _load("request_logs.json")
    has_reqlog = isinstance(reqlog, list)
    if portal_id is None:
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": None,
                "endpoint": "emails_batch_read",
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "No authorized portal context available for emails read.")

    # --- Validate inputs ---
    if not isinstance(inputs, list) or len(inputs) == 0:
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": portal_id,
                "endpoint": "emails_batch_read",
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "`inputs` must be a non-empty array.")

    supported_assocs = {"contacts", "companies", "deals", "tickets"}
    for i, it in enumerate(inputs):
        if not isinstance(it, dict):
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_read",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Each input must be an object. Invalid at index {i}.")
        if "id" not in it or not isinstance(it.get("id"), str) or not it.get("id"):
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_read",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Missing or invalid `id` for input at index {i}.")
        if "properties" in it and it["properties"] is not None:
            if not isinstance(it["properties"], list) or any(not isinstance(p, str) for p in it["properties"]):
                if has_reqlog:
                    reqlog.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "portal_id": portal_id,
                        "endpoint": "emails_batch_read",
                        "status": "VALIDATION_ERROR",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now
                    })
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"`properties` must be an array of strings at index {i}.")
        if "associations" in it and it["associations"] is not None:
            if not isinstance(it["associations"], list) or any((not isinstance(a, str) or a not in supported_assocs) for a in it["associations"]):
                if has_reqlog:
                    reqlog.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "portal_id": portal_id,
                        "endpoint": "emails_batch_read",
                        "status": "VALIDATION_ERROR",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now
                    })
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"Unsupported association name in input at index {i}.")

    # --- Build indices ---
    # Emails looked up by hubspot_object_id string, tenant-scoped, non-archived only.
    email_by_hsid = {}
    for o in objs:
        if o.get("portal_id") == portal_id and o.get("object_type") == "emails" and not o.get("archived") and o.get("status") == "active":
            hsid = o.get("hubspot_object_id")
            if isinstance(hsid, str):
                email_by_hsid[hsid] = o

    assocs = _load("crm_associations.json")
    obj_by_id = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}

    # --- Per-item read results ---
    results = []
    errors = []
    for idx, it in enumerate(inputs):
        eid = it["id"]
        row = email_by_hsid.get(eid)
        if not row:
            errors.append({
                "index": idx,
                "id": eid,
                "error": {"code": "NOT_FOUND", "message": f"Email with id {eid} not found."}
            })
            continue

        prop_filter = it.get("properties")
        out_props = {}
        src_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        if isinstance(prop_filter, list) and len(prop_filter) > 0:
            for p in prop_filter:
                if p in src_props:
                    out_props[p] = src_props.get(p)
        else:
            out_props = dict(src_props)

        out = {
            "id": row.get("hubspot_object_id"),
            "properties": out_props,
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived"))
        }

        assoc_names = it.get("associations") or []
        if assoc_names:
            # For each requested association type, return active associated objects' hubspot ids
            assoc_block = {}
            from_id = row.get("id")
            for aname in assoc_names:
                to_type = aname
                ids = []
                for e in assocs:
                    if e.get("portal_id") != portal_id:
                        continue
                    if e.get("status") != "active" or e.get("archived"):
                        continue
                    # edge could be either direction; for email association expansion, accept both directions
                    if e.get("from_object_id") == from_id and e.get("to_object_type") == to_type:
                        to_obj = obj_by_id.get(e.get("to_object_id"))
                        if to_obj and to_obj.get("status") == "active" and not to_obj.get("archived"):
                            ids.append(to_obj.get("hubspot_object_id"))
                    elif e.get("to_object_id") == from_id and e.get("from_object_type") == to_type:
                        from_obj = obj_by_id.get(e.get("from_object_id"))
                        if from_obj and from_obj.get("status") == "active" and not from_obj.get("archived"):
                            ids.append(from_obj.get("hubspot_object_id"))
                assoc_block[aname] = {"results": [{"id": i} for i in ids if isinstance(i, str) and i]}
            out["associations"] = assoc_block

        results.append(out)

    status = "OK" if not errors else ("PARTIAL" if results else "NOT_FOUND")
    if has_reqlog:
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}",
            "portal_id": portal_id,
            "endpoint": "emails_batch_read",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", reqlog)

    return {
        "results": results,
        "errors": errors,
        "totalRequested": len(inputs),
        "totalReturned": len(results)
    }

def emails_batch_update(inputs, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Ambient portal resolution: pick a portal that has any email object, else any portal.
    objs = _load("crm_objects.json")
    portals_with_email = {o.get("portal_id") for o in objs if o.get("object_type") == "emails"}
    portal_id = None
    if portals_with_email:
        portal_id = sorted([p for p in portals_with_email if isinstance(p, str) and p])[0]
    else:
        any_portals = {o.get("portal_id") for o in objs if isinstance(o.get("portal_id"), str) and o.get("portal_id")}
        portal_id = sorted(list(any_portals))[0] if any_portals else None

    reqlog = _load("request_logs.json")
    has_reqlog = isinstance(reqlog, list)

    if portal_id is None:
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": None,
                "endpoint": "emails_batch_update",
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "No authorized portal context available for emails update.")

    # Validate inputs list
    if not isinstance(inputs, list) or len(inputs) == 0:
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": portal_id,
                "endpoint": "emails_batch_update",
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "`inputs` must be a non-empty array.")

    # Email format validation
    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    required_props = ["hs_email_subject", "hs_email_text", "hs_email_from_email", "hs_email_to_email"]

    # Load property definitions for validation of archived/hidden definitions on update
    prop_defs = _load("crm_object_properties.json")
    defs_by_name = {}
    for d in prop_defs:
        if d.get("portal_id") == portal_id and d.get("object_type") == "emails" and isinstance(d.get("name"), str):
            defs_by_name[d["name"]] = d

    # Validate per-item shapes
    for i, it in enumerate(inputs):
        if not isinstance(it, dict):
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_update",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Each input must be an object. Invalid at index {i}.")
        if "id" not in it or not isinstance(it.get("id"), str) or not it.get("id"):
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_update",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Missing or invalid `id` for input at index {i}.")
        if "properties" not in it or not isinstance(it.get("properties"), dict):
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_update",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Missing or invalid `properties` for input at index {i}.")

        props = it["properties"]
        # Required within properties for this tool schema
        missing = [p for p in required_props if p not in props or not isinstance(props.get(p), str) or props.get(p) == ""]
        if missing:
            if has_reqlog:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_update",
                    "status": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", f"Missing required properties at index {i}: {', '.join(missing)}")

        # Validate enums if present
        if "hs_email_status" in props and props["hs_email_status"] is not None:
            if props["hs_email_status"] not in ["SENT", "DRAFT", "SCHEDULED"]:
                if has_reqlog:
                    reqlog.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "portal_id": portal_id,
                        "endpoint": "emails_batch_update",
                        "status": "VALIDATION_ERROR",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now
                    })
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"Invalid hs_email_status at index {i}.")
        if "hs_email_direction" in props and props["hs_email_direction"] is not None:
            if props["hs_email_direction"] not in ["INBOUND", "OUTBOUND"]:
                if has_reqlog:
                    reqlog.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "portal_id": portal_id,
                        "endpoint": "emails_batch_update",
                        "status": "VALIDATION_ERROR",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now
                    })
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"Invalid hs_email_direction at index {i}.")

        # Validate email formatted fields
        for ef in ["hs_email_from_email", "hs_email_to_email"]:
            v = props.get(ef)
            if not isinstance(v, str) or not email_re.match(v):
                if has_reqlog:
                    reqlog.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "portal_id": portal_id,
                        "endpoint": "emails_batch_update",
                        "status": "VALIDATION_ERROR",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now
                    })
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"Invalid email format for {ef} at index {i}.")

        for ef_arr in ["hs_email_cc", "hs_email_bcc"]:
            if ef_arr in props and props[ef_arr] is not None:
                if not isinstance(props[ef_arr], list) or any((not isinstance(x, str) or not email_re.match(x)) for x in props[ef_arr]):
                    if has_reqlog:
                        reqlog.append({
                            "id": f"req_{int(time.time()*1000)}",
                            "portal_id": portal_id,
                            "endpoint": "emails_batch_update",
                            "status": "VALIDATION_ERROR",
                            "latency_ms": int((time.time() - t0) * 1000),
                            "timestamp": now
                        })
                        _save("request_logs.json", reqlog)
                    return _err("VALIDATION_ERROR", f"Invalid email format in {ef_arr} at index {i}.")

        # Validate against archived/hidden property definitions if they exist
        for pname in props.keys():
            d = defs_by_name.get(pname)
            if d:
                if d.get("archived") or d.get("status") == "archived":
                    if has_reqlog:
                        reqlog.append({
                            "id": f"req_{int(time.time()*1000)}",
                            "portal_id": portal_id,
                            "endpoint": "emails_batch_update",
                            "status": "VALIDATION_ERROR",
                            "latency_ms": int((time.time() - t0) * 1000),
                            "timestamp": now
                        })
                        _save("request_logs.json", reqlog)
                    return _err("VALIDATION_ERROR", f"Property '{pname}' is archived and cannot be written (index {i}).")
                # If hidden fields forbidden by policy: no explicit policy store exists; default to allow.
                # (If policy existed, enforce here.)

    # Index email objects by (portal, hubspot_object_id)
    email_rows_idx = {}
    for pos, o in enumerate(objs):
        if o.get("portal_id") == portal_id and o.get("object_type") == "emails":
            hsid = o.get("hubspot_object_id")
            if isinstance(hsid, str):
                email_rows_idx[hsid] = pos

    results = []
    errors = []
    mutated = False

    for idx, it in enumerate(inputs):
        eid = it["id"]
        pos = email_rows_idx.get(eid)
        if pos is None:
            errors.append({
                "index": idx,
                "id": eid,
                "error": {"code": "NOT_FOUND", "message": f"Email with id {eid} not found."}
            })
            continue

        row = objs[pos]
        if row.get("archived") or row.get("status") == "archived":
            errors.append({
                "index": idx,
                "id": eid,
                "error": {"code": "CONFLICT", "message": "Cannot update an archived email."}
            })
            continue

        # Apply update: clearing represented by empty string in properties JSON
        props = row.get("properties")
        if not isinstance(props, dict):
            props = {}

        incoming = it["properties"]
        for k, v in incoming.items():
            props[k] = v

        row["properties"] = props
        # Increment properties_version monotonic >=1
        pv = row.get("properties_version")
        if not isinstance(pv, int) or pv < 1:
            pv = 1
        row["properties_version"] = pv + 1
        row["updated_at"] = now
        row["hubspot_updated_at"] = now
        objs[pos] = row
        mutated = True

        results.append({
            "id": row.get("hubspot_object_id"),
            "properties": dict(row.get("properties") or {}),
            "createdAt": row.get("hubspot_created_at") or row.get("created_at"),
            "updatedAt": row.get("hubspot_updated_at") or row.get("updated_at"),
            "archived": bool(row.get("archived"))
        })

    if mutated:
        _save("crm_objects.json", objs)

    status = "OK" if not errors else ("PARTIAL" if results else "NOT_FOUND")
    if has_reqlog:
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}",
            "portal_id": portal_id,
            "endpoint": "emails_batch_update",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", reqlog)

    # No success without effect: if all failed with NOT_FOUND/CONFLICT, we still return errors (not ok true)
    return {
        "results": results,
        "errors": errors,
        "totalRequested": len(inputs),
        "totalUpdated": len(results)
    }

def emails_batch_archive(emailIds, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    objs = _load("crm_objects.json")
    portals_with_email = {o.get("portal_id") for o in objs if o.get("object_type") == "emails"}
    portal_id = sorted([p for p in portals_with_email if isinstance(p, str) and p])[0] if portals_with_email else None

    reqlog = _load("request_logs.json")
    has_reqlog = isinstance(reqlog, list)

    if portal_id is None:
        # If there is no email context at all, treat as unauthorized (no tenant can serve this call).
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": None,
                "endpoint": "emails_batch_archive",
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "No authorized portal context available for emails archive.")

    if not isinstance(emailIds, list) or len(emailIds) == 0 or any((not isinstance(x, str) or not x) for x in emailIds):
        if has_reqlog:
            reqlog.append({
                "id": f"req_{int(time.time()*1000)}",
                "portal_id": portal_id,
                "endpoint": "emails_batch_archive",
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "`emailIds` must be a non-empty array of strings.")

    # Rate limit/quota enforcement via request_logs if present (simple rolling window)
    # If schema had explicit limits, we'd enforce them; here implement conservative defaults.
    if has_reqlog:
        window_s = 10
        limit = 50
        try:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
            def _parse(ts):
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            recent = 0
            for r in reqlog:
                if r.get("portal_id") != portal_id:
                    continue
                if r.get("endpoint") != "emails_batch_archive":
                    continue
                ts = _parse(r.get("timestamp"))
                if ts and ts >= cutoff:
                    recent += 1
            if recent >= limit:
                reqlog.append({
                    "id": f"req_{int(time.time()*1000)}",
                    "portal_id": portal_id,
                    "endpoint": "emails_batch_archive",
                    "status": "RATE_LIMIT",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": now
                })
                _save("request_logs.json", reqlog)
                return _err("RATE_LIMIT", "Rate limit exceeded for emails_batch_archive.")
        except Exception:
            # Do not fail open with exception; but also don't crash.
            pass

    # Index emails
    idx = {}
    for pos, o in enumerate(objs):
        if o.get("portal_id") == portal_id and o.get("object_type") == "emails":
            hsid = o.get("hubspot_object_id")
            if isinstance(hsid, str):
                idx[hsid] = pos

    results = {"archived": [], "notFound": [], "conflicts": []}
    mutated = False

    for eid in emailIds:
        pos = idx.get(eid)
        if pos is None:
            results["notFound"].append(eid)
            continue
        row = objs[pos]
        # If already archived, idempotent archive (treat as archived)
        if row.get("status") == "archived" or row.get("archived") is True:
            results["archived"].append(eid)
            continue

        # Lifecycle transition active -> archived allowed
        if row.get("status") != "active":
            results["conflicts"].append(eid)
            continue

        row["status"] = "archived"
        row["archived"] = True
        row["updated_at"] = now
        row["hubspot_updated_at"] = now
        pv = row.get("properties_version")
        if not isinstance(pv, int) or pv < 1:
            pv = 1
        row["properties_version"] = pv + 1
        objs[pos] = row
        mutated = True
        results["archived"].append(eid)

    if mutated:
        _save("crm_objects.json", objs)

    # If any notFound/conflict -> expose as errors array too
    errors = []
    for eid in results["notFound"]:
        errors.append({"id": eid, "error": {"code": "NOT_FOUND", "message": f"Email with id {eid} not found."}})
    for eid in results["conflicts"]:
        errors.append({"id": eid, "error": {"code": "CONFLICT", "message": f"Email with id {eid} cannot be archived due to its current state."}})

    status = "OK" if not errors else ("PARTIAL" if results["archived"] else "NOT_FOUND")
    if has_reqlog:
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}",
            "portal_id": portal_id,
            "endpoint": "emails_batch_archive",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", reqlog)

    return {
        "results": {"archived": results["archived"]},
        "errors": errors,
        "totalRequested": len(emailIds),
        "totalArchived": len(results["archived"])
    }

def communications_get_preferences(contactId, subscriptionId=None, **_extra):
