    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "communications_get_preferences"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _iso_now(),
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "portal_id": portal_id,
                "credential_id": None,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(contactId, str) or not contactId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contactId is required and must be a non-empty string")

    if subscriptionId is not None:
        if not isinstance(subscriptionId, str) or not subscriptionId.strip() or len(subscriptionId) > 256:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "subscriptionId is malformed")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list):
        objs = []
    subs = _load("communications_subscriptions.json")
    if not isinstance(subs, list):
        subs = []

    # Resolve contact (accept either hubspot_object_id or internal id)
    contact_row = None
    for o in objs:
        if o.get("object_type") == "contacts" and (str(o.get("hubspot_object_id")) == contactId or o.get("id") == contactId):
            contact_row = o
            break
    if not contact_row or contact_row.get("archived") is True or contact_row.get("status") != "active":
        _log("error", portal_id=(contact_row or {}).get("portal_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found")

    portal_id = contact_row.get("portal_id")
    contact_object_id = contact_row.get("id")

    rows = [
        r
        for r in subs
        if r.get("portal_id") == portal_id and r.get("row_type") == "contact_status" and r.get("contact_object_id") == contact_object_id
    ]
    if subscriptionId is not None:
        rows = [r for r in rows if str(r.get("subscription_id")) == subscriptionId]

    # Prefer stable ordering by subscription_id
    rows.sort(key=lambda r: str(r.get("subscription_id") or ""))

    results = []
    for r in rows:
        results.append(
            {
                "subscriptionId": str(r.get("subscription_id")),
                "status": r.get("status"),
                "legalBasis": r.get("legal_basis"),
                "legalBasisExplanation": r.get("legal_basis_explanation"),
            }
        )

    _log("success", portal_id=portal_id)
    return {"contactId": str(contact_row.get("hubspot_object_id")), "results": results}

def communications_update_preferences(contactId, subscriptionId, preferences, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "communications_update_preferences"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(existing):
        existing_ids = set()
        if isinstance(existing, list):
            for r in existing:
                if isinstance(r, dict) and isinstance(r.get("id"), str):
                    existing_ids.add(r["id"])
        while True:
            nid = f"hs_comm_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{secrets.token_hex(8)}"
            if nid not in existing_ids:
                return nid

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    allowed_status = {"SUBSCRIBED", "UNSUBSCRIBED", "NOT_OPTED"}
    allowed_legal = {
        "LEGITIMATE_INTEREST_CLIENT",
        "LEGITIMATE_INTEREST_PUB",
        "PERFORMANCE_OF_CONTRACT",
        "CONSENT_WITH_NOTICE",
        "CONSENT_WITH_NOTICE_AND_OPT_OUT",
    }

    if not isinstance(contactId, str) or not contactId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contactId is required and must be a non-empty string.", field="contactId")
    if not isinstance(subscriptionId, str) or not subscriptionId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subscriptionId is required and must be a non-empty string.", field="subscriptionId")
    if not isinstance(preferences, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences is required and must be an object.", field="preferences")

    pref_sub_id = preferences.get("subscriptionId")
    pref_status = preferences.get("status")
    pref_legal_basis = preferences.get("legalBasis")
    pref_legal_expl = preferences.get("legalBasisExplanation")

    if not isinstance(pref_sub_id, str) or not pref_sub_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences.subscriptionId is required and must be a non-empty string.", field="preferences.subscriptionId")
    if str(pref_sub_id) != str(subscriptionId):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences.subscriptionId must match subscriptionId.", field="preferences.subscriptionId")
    if pref_status not in allowed_status:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences.status must be one of SUBSCRIBED, UNSUBSCRIBED, NOT_OPTED.", field="preferences.status")
    if pref_legal_basis is not None and pref_legal_basis not in allowed_legal:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences.legalBasis is not supported.", field="preferences.legalBasis")
    if pref_legal_expl is not None and not isinstance(pref_legal_expl, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "preferences.legalBasisExplanation must be a string when provided.", field="preferences.legalBasisExplanation")

    objs = _load("crm_objects.json")
    subs = _load("communications_subscriptions.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(subs, list): subs = []

    # Resolve contact in some portal; accept tool ID as hubspot_object_id or internal id
    contact_row = None
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("object_type") != "contacts":
            continue
        if str(o.get("hubspot_object_id")) == contactId or str(o.get("id")) == contactId:
            contact_row = o
            break
    if not contact_row:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found.", contactId=contactId)

    portal_id = contact_row.get("portal_id")
    contact_internal = contact_row.get("id")

    # Validate subscription definition exists for portal (allow archived definitions too? read tools filter by archived; updates can target existing)
    def_ok = False
    for r in subs:
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("row_type") == "definition" and str(r.get("subscription_id")) == str(subscriptionId):
            def_ok = True
            break
    if not def_ok:
        _log("error", portal_id=portal_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Subscription definition not found.", subscriptionId=subscriptionId)

    # Upsert contact_status row
    now = _iso_now()
    match_idx = None
    for i, r in enumerate(subs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") == portal_id and r.get("row_type") == "contact_status" and str(r.get("subscription_id")) == str(subscriptionId) and r.get("contact_object_id") == contact_internal:
            match_idx = i
            break

    if match_idx is None:
        new_row = {
            "id": _new_id(subs),
            "portal_id": portal_id,
            "row_type": "contact_status",
            "subscription_id": str(subscriptionId),
            "definition_name": None,
            "definition_description": None,
            "contact_object_id": contact_internal,
            "status": pref_status,
            "legal_basis": pref_legal_basis,
            "legal_basis_explanation": pref_legal_expl if pref_legal_expl is not None else None,
            "archived": False,
            "created_at": now,
            "updated_at": now,
        }
        subs.append(new_row)
        out = new_row
    else:
        r = subs[match_idx]
        r2 = dict(r)
        r2["status"] = pref_status
        r2["legal_basis"] = pref_legal_basis
        r2["legal_basis_explanation"] = pref_legal_expl if pref_legal_expl is not None else None
        r2["updated_at"] = now
        # archived must be false for contact_status
        r2["archived"] = False
        subs[match_idx] = r2
        out = r2

    _save("communications_subscriptions.json", subs)
    _log("success", portal_id=portal_id)
    return {"result": out}

def communications_unsubscribe_contact(contactId, portalSubscriptionLegalBasis=None, portalSubscriptionLegalBasisExplanation=None, **_extra):
