            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(contactId, str) or not contactId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contactId is required and must be a non-empty string")

    allowed_legal = {
        "LEGITIMATE_INTEREST_CLIENT",
        "LEGITIMATE_INTEREST_PUB",
        "PERFORMANCE_OF_CONTRACT",
        "CONSENT_WITH_NOTICE",
        "CONSENT_WITH_NOTICE_AND_OPT_OUT",
    }
    if portalSubscriptionLegalBasis is not None and (not isinstance(portalSubscriptionLegalBasis, str) or portalSubscriptionLegalBasis not in allowed_legal):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "portalSubscriptionLegalBasis must be a supported value when provided")
    if portalSubscriptionLegalBasisExplanation is not None and not isinstance(portalSubscriptionLegalBasisExplanation, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "portalSubscriptionLegalBasisExplanation must be a string when provided")

    objs = _load("crm_objects.json")
    if not isinstance(objs, list): objs = []
    subs = _load("communications_subscriptions.json")
    if not isinstance(subs, list): subs = []

    contact_row = None
    for o in objs:
        if o.get("object_type") == "contacts" and (o.get("id") == contactId or str(o.get("hubspot_object_id")) == contactId):
