    portal_id = contact_row.get("portal_id")
    if not isinstance(portal_id, str) or not portal_id:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible portal context for contact.")

    # Get all subscription definitions (not archived only; unsubscribe should cover all in portal)
    defs = [r for r in subs if r.get("portal_id") == portal_id and r.get("row_type") == "definition"]
    def_ids = [str(r.get("subscription_id")) for r in defs if r.get("subscription_id") is not None]
    if not def_ids:
        # No definitions; still produce global status response but no row to update.
        _log("success", portal_id=portal_id)
        return {"contactId": str(contact_row.get("hubspot_object_id") or contact_row.get("id")), "status": "UNSUBSCRIBED", "updatedAt": _iso_now()}

