def communications_get_subscription_definitions(archived=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    endpoint = "communications_get_subscription_definitions"
    portal_id_used = None

    try:
        if archived is not None and not isinstance(archived, bool):
            return _err("VALIDATION_ERROR", "archived must be a boolean when provided.")
        include_archived = bool(archived) if archived is not None else False

        subs = _load("communications_subscriptions.json")
        crm_objects = _load("crm_objects.json")
        reqlog = _load("request_log.json")

        # Ambient auth / portal resolution:
        # pick a portal that actually has definitions.
        portal_candidates = []
        for s in subs:
            if s.get("row_type") == "definition" and isinstance(s.get("portal_id"), str):
                portal_candidates.append(s.get("portal_id"))
        # fallback: any portal present in crm_objects
        if not portal_candidates:
            for o in crm_objects:
                if isinstance(o.get("portal_id"), str):
                    portal_candidates.append(o.get("portal_id"))
        portal_candidates = [p for i, p in enumerate(portal_candidates) if p and p not in portal_candidates[:i]]

        if not portal_candidates:
            return _err("UNAUTHORIZED", "No portal context available to read subscription definitions.")

        # Choose portal with at least one definition in store
        chosen = None
        for p in portal_candidates:
            if any(s.get("portal_id") == p and s.get("row_type") == "definition" for s in subs):
                chosen = p
                break
        if chosen is None:
            # No definitions anywhere; return empty set for a valid read
            chosen = portal_candidates[0]

        portal_id_used = chosen

        rows = []
        for s in subs:
            if s.get("portal_id") != portal_id_used or s.get("row_type") != "definition":
                continue
            if not include_archived and s.get("archived") is True:
                continue
            rows.append(
                {
                    "id": s.get("subscription_id"),
                    "name": s.get("definition_name"),
                    "description": s.get("definition_description"),
                    "archived": bool(s.get("archived")),
                    "createdAt": s.get("created_at"),
                    "updatedAt": s.get("updated_at"),
                }
            )

        now = _now()
        latency_ms = int((time.time() - t0) * 1000)
        if isinstance(reqlog, list):
            reqlog.append(
                {
                    "id": "req_" + uuid.uuid4().hex,
                    "timestamp": now,
                    "endpoint": endpoint,
                    "portal_id": portal_id_used,
                    "status": "200",
                    "latency_ms": latency_ms,
                }
            )
            _save("request_log.json", reqlog)

        return {
            "result": {
                "portalId": portal_id_used,
                "definitions": rows,
                "total": len(rows),
                "archivedIncluded": include_archived,
            }
        }
    except Exception as e:
        now = _now()
        try:
            reqlog = _load("request_log.json")
            if isinstance(reqlog, list):
                reqlog.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "timestamp": now,
                        "endpoint": endpoint,
                        "portal_id": portal_id_used,
                        "status": "500",
                        "latency_ms": int((time.time() - t0) * 1000),
                        "error": str(e),
                    }
                )
                _save("request_log.json", reqlog)
        except Exception:
            pass
        return _err("CONFLICT", "Internal error while reading subscription definitions.", detail=str(e))

def communications_get_subscription_status(subscriptionId, contactIds, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "communications_get_subscription_status"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    if not isinstance(subscriptionId, str) or not subscriptionId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subscriptionId must be a non-empty string", field="subscriptionId")
    if not isinstance(contactIds, list) or len(contactIds) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contactIds must be a non-empty array of strings", field="contactIds")
    for i, x in enumerate(contactIds):
        if not isinstance(x, str) or not x.strip():
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contactIds must be a non-empty array of non-empty strings", field=f"contactIds[{i}]")

    objs = _load("crm_objects.json")
    subs = _load("communications_subscriptions.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(subs, list): subs = []

    # Build subscription definitions by portal
    portals_with_def = set()
    for r in subs:
        if isinstance(r, dict) and r.get("row_type") == "definition" and str(r.get("subscription_id")) == str(subscriptionId):
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                portals_with_def.add(pid)
    if not portals_with_def:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Subscription definition not found", subscriptionId=subscriptionId)

    # Resolve contacts (may span portals, return per-contact result)
    # If a contact isn't found in any portal, return NOT_FOUND per contact in results (not whole request).
    contacts = {}
    for o in objs:
        if not isinstance(o, dict): 
            continue
        if o.get("object_type") != "contacts":
            continue
        hid = str(o.get("hubspot_object_id"))
        iid = str(o.get("id"))
        contacts[hid] = o
        contacts[iid] = o

    results = []
    # choose a portal to log: if any contact resolved, use its portal; else use any portal_with_def
    log_portal = None

    for cid in contactIds:
        c = contacts.get(cid)
        if not c:
            results.append({
                "contactId": cid,
                "subscriptionId": str(subscriptionId),
                "status": None,
                "error": {"code": "NOT_FOUND", "message": "Contact not found"}
            })
            continue
        pid = c.get("portal_id")
        if log_portal is None:
            log_portal = pid
        # If definition doesn't exist in that portal, report NOT_FOUND for that contact+portal
        if pid not in portals_with_def:
            results.append({
                "contactId": str(c.get("hubspot_object_id")),
                "subscriptionId": str(subscriptionId),
                "status": None,
                "error": {"code": "NOT_FOUND", "message": "Subscription definition not found for contact's portal"}
            })
            continue
        contact_internal = c.get("id")
        status_row = None
        for r in subs:
            if isinstance(r, dict) and r.get("portal_id") == pid and r.get("row_type") == "contact_status" and str(r.get("subscription_id")) == str(subscriptionId) and r.get("contact_object_id") == contact_internal:
                status_row = r
                break
        results.append({
            "contactId": str(c.get("hubspot_object_id")),
            "subscriptionId": str(subscriptionId),
            "status": status_row.get("status") if status_row else "NOT_OPTED",
            "legalBasis": status_row.get("legal_basis") if status_row else None,
            "legalBasisExplanation": status_row.get("legal_basis_explanation") if status_row else None,
        })

    _log("success", portal_id=log_portal or (sorted(portals_with_def)[0] if portals_with_def else None))
    return {"results": results}

def communications_update_subscription_status(subscriptionId, updates, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "communications_update_subscription_status"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(existing):
        existing_ids = set()
        if isinstance(existing, list):
            for r in existing:
                if isinstance(r, dict) and isinstance(r.get("id"), str):
                    existing_ids.add(r["id"])
        while True:
            nid = f"hs_comm_{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S')}_{secrets.token_hex(8)}"
            if nid not in existing_ids:
                return nid

    def _log(status, portal_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": None,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    allowed_status = {"SUBSCRIBED", "UNSUBSCRIBED", "NOT_OPTED"}
    allowed_legal = {
        "LEGITIMATE_INTEREST_CLIENT",
        "LEGITIMATE_INTEREST_PUB",
        "PERFORMANCE_OF_CONTRACT",
        "CONSENT_WITH_NOTICE",
        "CONSENT_WITH_NOTICE_AND_OPT_OUT",
    }

    if not isinstance(subscriptionId, str) or not subscriptionId.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subscriptionId must be a non-empty string", field="subscriptionId")
    if not isinstance(updates, list) or len(updates) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "updates must be a non-empty array", field="updates")

    for i, u in enumerate(updates):
        if not isinstance(u, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each update must be an object.", field=f"updates[{i}]")
        if "contactId" not in u or "status" not in u:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each update must include contactId and status.", field=f"updates[{i}]")
        if not isinstance(u.get("contactId"), str) or not u["contactId"].strip():
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contactId must be a non-empty string.", field=f"updates[{i}].contactId")
        if u.get("status") not in allowed_status:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be SUBSCRIBED, UNSUBSCRIBED, or NOT_OPTED.", field=f"updates[{i}].status")
        if "legalBasis" in u and u["legalBasis"] is not None and u["legalBasis"] not in allowed_legal:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "legalBasis is not supported.", field=f"updates[{i}].legalBasis")
        if "legalBasisExplanation" in u and u["legalBasisExplanation"] is not None and not isinstance(u["legalBasisExplanation"], str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "legalBasisExplanation must be a string when provided.", field=f"updates[{i}].legalBasisExplanation")

    objs = _load("crm_objects.json")
    subs = _load("communications_subscriptions.json")
    if not isinstance(objs, list): objs = []
    if not isinstance(subs, list): subs = []

    # Build contact lookup
    contact_lookup = {}
    for o in objs:
        if isinstance(o, dict) and o.get("object_type") == "contacts":
            if isinstance(o.get("hubspot_object_id"), str):
                contact_lookup[o["hubspot_object_id"]] = o
            if isinstance(o.get("id"), str):
                contact_lookup[o["id"]] = o

    # Verify subscription definition exists in at least one portal
    portals_with_def = set()
    for r in subs:
        if isinstance(r, dict) and r.get("row_type") == "definition" and str(r.get("subscription_id")) == str(subscriptionId) and isinstance(r.get("portal_id"), str):
            portals_with_def.add(r.get("portal_id"))
    if not portals_with_def:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Subscription definition not found.", subscriptionId=subscriptionId)

    now = _iso_now()
    results = []
    any_success_portal = None

    for u in updates:
        cid = u["contactId"]
        status = u["status"]
        legal = u.get("legalBasis")
        expl = u.get("legalBasisExplanation")

        c = contact_lookup.get(cid)
        if not c:
            results.append({"contactId": cid, "success": False, "error": {"code": "NOT_FOUND", "message": "Contact not found"}})
            continue

        portal_id = c.get("portal_id")
        if any_success_portal is None:
            any_success_portal = portal_id

        if portal_id not in portals_with_def:
            results.append({"contactId": str(c.get("hubspot_object_id")), "success": False, "error": {"code": "NOT_FOUND", "message": "Subscription definition not found for contact's portal"}})
            continue

        contact_internal = c.get("id")

        # upsert contact_status
        match_idx = None
        for i, r in enumerate(subs):
            if not isinstance(r, dict):
                continue
            if r.get("portal_id") == portal_id and r.get("row_type") == "contact_status" and str(r.get("subscription_id")) == str(subscriptionId) and r.get("contact_object_id") == contact_internal:
                match_idx = i
                break

        if match_idx is None:
            new_row = {
                "id": _new_id(subs),
                "portal_id": portal_id,
                "row_type": "contact_status",
                "subscription_id": str(subscriptionId),
                "definition_name": None,
                "definition_description": None,
                "contact_object_id": contact_internal,
                "status": status,
                "legal_basis": legal,
                "legal_basis_explanation": expl if expl is not None else None,
                "archived": False,
                "created_at": now,
                "updated_at": now,
            }
            subs.append(new_row)
            results.append({"contactId": str(c.get("hubspot_object_id")), "success": True, "result": new_row})
        else:
            r = subs[match_idx]
            r2 = dict(r)
            r2["status"] = status
            r2["legal_basis"] = legal
            r2["legal_basis_explanation"] = expl if expl is not None else None
            r2["updated_at"] = now
            r2["archived"] = False
            subs[match_idx] = r2
            results.append({"contactId": str(c.get("hubspot_object_id")), "success": True, "result": r2})

    # Persist only if any success (otherwise no-op)
    if any(r.get("success") for r in results):
        _save("communications_subscriptions.json", subs)
        _log("success", portal_id=any_success_portal)
    else:
        _log("error", portal_id=any_success_portal, error_code="NOT_FOUND")

    return {"results": results}

