    portal_candidates = sorted({o.get("portal_id") for o in objs if isinstance(o.get("portal_id"), str) and o.get("portal_id") and o.get("object_type") == "products"})
    portal_id = portal_candidates[0] if portal_candidates else None

    # Validate limit
    if limit is None:
        limit_n = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            resp = _err("VALIDATION_ERROR", "limit must be a number")
            limit_n = None
        else:
            limit_n = int(limit)
            if limit_n < 1:
                resp = _err("VALIDATION_ERROR", "limit must be >= 1")
            else:
                resp = None

    # Validate after cursor
    start = 0
    if resp is None:
        if after is not None:
            if not isinstance(after, str) or not after.strip():
                resp = _err("VALIDATION_ERROR", "after must be a non-empty string when provided")
            else:
                try:
                    start = int(after)
                    if start < 0:
                        resp = _err("VALIDATION_ERROR", "after cursor is invalid")
                except ValueError:
                    resp = _err("VALIDATION_ERROR", "after cursor is malformed")

    # Validate properties list
    if resp is None:
        if properties is not None:
            if not isinstance(properties, list) or any((not isinstance(p, str) or not p.strip()) for p in properties):
                resp = _err("VALIDATION_ERROR", "properties must be an array of non-empty strings")
        # Unknown property validation against definitions when they exist
        if resp is None and properties is not None and portal_id is not None:
            known = {d.get("name") for d in props_defs if d.get("portal_id") == portal_id and d.get("object_type") == "products" and d.get("status") == "active"}
            known = {k for k in known if isinstance(k, str) and k}
            if known:
                unknown = [p for p in properties if p not in known]
                if unknown:
                    resp = _err("VALIDATION_ERROR", "Unknown properties requested", unknownProperties=unknown)

    if resp is None and portal_id is None:
        # No portals/products available => unauthorized context, per contract.
        resp = _err("UNAUTHORIZED", "No authorized portal context available")

    if resp is None:
        # Default properties if omitted: return all active defined properties if exist, else return stored properties as-is.
        active_defs = [d for d in props_defs if d.get("portal_id") == portal_id and d.get("object_type") == "products" and d.get("status") == "active"]
        def_names = [d.get("name") for d in active_defs if isinstance(d.get("name"), str) and d.get("name")]
        if properties is None:
            requested_props = def_names if def_names else None
        else:
            requested_props = properties

        # Filter non-archived products by default
        products = [o for o in objs if o.get("portal_id") == portal_id and o.get("object_type") == "products" and o.get("status") == "active" and o.get("archived") is False]
        # Sort by hubspot_object_id numeric where possible, else string
        def _key(o):
            v = o.get("hubspot_object_id")
            try:
                return (0, int(v))
            except Exception:
                return (1, str(v))
        products.sort(key=_key)

        total = len(products)
        page = products[start:start + limit_n]
        next_after = None
        if start + limit_n < total:
            next_after = str(start + limit_n)

        results = []
        for o in page:
            p = o.get("properties") if isinstance(o.get("properties"), dict) else {}
            if requested_props is None:
                out_props = dict(p)
            else:
                out_props = {k: p.get(k) for k in requested_props}
            results.append({
                "id": o.get("hubspot_object_id"),
                "properties": out_props,
                "createdAt": o.get("hubspot_created_at") or o.get("created_at"),
                "updatedAt": o.get("hubspot_updated_at") or o.get("updated_at"),
                "archived": bool(o.get("archived"))
            })

        resp = {
            "portalId": portal_id,
            "results": results,
            "total": total,
            "paging": ({"next": {"after": next_after}} if next_after is not None else None)
        }

    # Request logging best-effort
    latency_ms = int((time.time() - t0) * 1000)
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "endpoint": endpoint,
        "portal_id": portal_id,
        "status": (resp.get("error", {}).get("code") if isinstance(resp, dict) and resp.get("error") else "OK"),
        "latency_ms": latency_ms
    }
    reqlog = _load("request_log.json")
    if isinstance(reqlog, list):
        reqlog.append(log_row)
        _save("request_log.json", reqlog)

    return resp

def products_read(productId, properties=None, associations=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "products_read"

    objs = _load("crm_objects.json")
    props_defs = _load("crm_object_properties.json")
    assoc_edges = _load("crm_associations.json")

    # Validate productId
    if not isinstance(productId, str) or not productId.strip():
        resp = _err("VALIDATION_ERROR", "productId must be a non-empty string")
        portal_id = None
    else:
        portal_id = None
        product_row = None
        for o in objs:
            if o.get("object_type") == "products" and o.get("hubspot_object_id") == productId:
                if o.get("status") == "active" and o.get("archived") is False:
                    product_row = o
                    portal_id = o.get("portal_id")
                    break
                else:
                    # product exists but archived => treat as not found for read
                    portal_id = o.get("portal_id")
                    product_row = None
                    break

        if portal_id is None:
            # No matching product anywhere; if store has portals at all, NOT_FOUND else UNAUTHORIZED.
            any_portal = any(isinstance(o.get("portal_id"), str) and o.get("portal_id") for o in objs)
            resp = _err("NOT_FOUND" if any_portal else "UNAUTHORIZED", "Product not found" if any_portal else "No authorized portal context available", productId=productId)
        else:
            # Validate properties list
            if properties is not None:
                if not isinstance(properties, list) or any((not isinstance(p, str) or not p.strip()) for p in properties):
                    resp = _err("VALIDATION_ERROR", "properties must be an array of non-empty strings")
                else:
                    known = {d.get("name") for d in props_defs if d.get("portal_id") == portal_id and d.get("object_type") == "products" and d.get("status") == "active"}
                    known = {k for k in known if isinstance(k, str) and k}
                    if known:
                        unknown = [p for p in properties if p not in known]
                        if unknown:
                            resp = _err("VALIDATION_ERROR", "Unknown properties requested", unknownProperties=unknown)
                    # else: allow any stored keys if no definitions exist
            else:
                resp = None

            # Validate associations list (only validate type; expansions depend on data; return empty lists if none)
            if resp is None and associations is not None:
                if not isinstance(associations, list) or any((not isinstance(a, str) or not a.strip()) for a in associations):
                    resp = _err("VALIDATION_ERROR", "associations must be an array of non-empty strings")

            if resp is None and product_row is None:
                resp = _err("NOT_FOUND", "Product not found", productId=productId)

            if resp is None:
                # Build properties output
                p = product_row.get("properties") if isinstance(product_row.get("properties"), dict) else {}
                if properties is None:
                    # default to all active defined props if exist, else all stored props
                    active_defs = [d for d in props_defs if d.get("portal_id") == portal_id and d.get("object_type") == "products" and d.get("status") == "active"]
                    def_names = [d.get("name") for d in active_defs if isinstance(d.get("name"), str) and d.get("name")]
                    if def_names:
                        out_props = {k: p.get(k) for k in def_names}
                    else:
                        out_props = dict(p)
                else:
                    out_props = {k: p.get(k) for k in properties}

                # Associations expansions: join edges + target objects; only active edges and active target objects
                assoc_out = None
                if associations is not None:
                    # HubSpot typically returns map of association name -> results
                    # We'll interpret each association string as an object_type to return associated object IDs.
                    assoc_out = {}
                    from_id = product_row.get("id")
                    # Index objects by internal id
                    obj_by_id = {o.get("id"): o for o in objs if o.get("portal_id") == portal_id}
                    for assoc_name in associations:
                        # normalize: accept common synonyms (line_items vs lineItems) by matching stored enum names; here just use as-is.
                        targets = []
                        for e in assoc_edges:
                            if (
                                e.get("portal_id") == portal_id and
                                e.get("status") == "active" and e.get("archived") is False and
                                e.get("from_object_id") == from_id and
                                e.get("to_object_type") == assoc_name
                            ):
                                to_obj = obj_by_id.get(e.get("to_object_id"))
                                if to_obj and to_obj.get("status") == "active" and to_obj.get("archived") is False:
                                    targets.append({"id": to_obj.get("hubspot_object_id")})
                        assoc_out[assoc_name] = {"results": targets}

                resp = {
                    "portalId": portal_id,
                    "id": product_row.get("hubspot_object_id"),
                    "properties": out_props,
                    "createdAt": product_row.get("hubspot_created_at") or product_row.get("created_at"),
                    "updatedAt": product_row.get("hubspot_updated_at") or product_row.get("updated_at"),
                    "archived": bool(product_row.get("archived")),
                    "associations": assoc_out
                }

    # Request logging best-effort
    latency_ms = int((time.time() - t0) * 1000)
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "endpoint": endpoint,
        "portal_id": portal_id if "portal_id" in locals() else None,
        "status": (resp.get("error", {}).get("code") if isinstance(resp, dict) and resp.get("error") else "OK"),
        "latency_ms": latency_ms
    }
    reqlog = _load("request_log.json")
    if isinstance(reqlog, list):
        reqlog.append(log_row)
        _save("request_log.json", reqlog)

    return resp

def products_create(properties, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "hubspot_mcp",
            "endpoint": "products_create",
            "portal_id": portal_id,
            "credential_id": None,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        props = _load("crm_object_properties.json")
        for r in props:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        assoc = _load("crm_association_types.json")
        for r in assoc:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        subs = _load("communications_subscriptions.json")
        for r in subs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        return None

    try:
        if not isinstance(properties, dict):
            _log("error")
            return _err("VALIDATION_ERROR", "`properties` must be an object")

        portal_id = _resolve_portal_id()
        if not portal_id:
            _log("error")
            return _err("UNAUTHORIZED", "No tenant context available")

        # Validate property names/types against definitions when present
        defs = _load("crm_object_properties.json")
        product_defs = [d for d in defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "products"]
        defs_by_name = {d.get("name"): d for d in product_defs if d.get("name")}

        unknown = []
        if product_defs:
            for k in properties.keys():
                if k not in defs_by_name:
                    unknown.append(k)
            if unknown:
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "Unknown property name(s) for products", unknownProperties=unknown)

        # Reject writes to archived/hidden definitions
        for k, v in properties.items():
            d = defs_by_name.get(k)
            if d:
                if d.get("status") == "archived" or d.get("archived") is True:
                    _log("error", portal_id)
                    return _err("VALIDATION_ERROR", f"Property '{k}' is archived and cannot be set")
                if d.get("hidden") is True:
                    _log("error", portal_id)
                    return _err("VALIDATION_ERROR", f"Property '{k}' is hidden and cannot be set")
                # Simple type checks
                dtype = d.get("type")
                if v == "" or v is None:
                    # allow clearing semantics by empty string; on create None becomes absent
                    continue
                if dtype == "number":
                    if not isinstance(v, (int, float)) or isinstance(v, bool):
                        _log("error", portal_id)
                        return _err("VALIDATION_ERROR", f"Property '{k}' must be a number")
                elif dtype == "bool":
                    if not isinstance(v, bool):
                        _log("error", portal_id)
                        return _err("VALIDATION_ERROR", f"Property '{k}' must be a boolean")
                elif dtype in ("string", "date", "datetime", "enumeration"):
                    if not isinstance(v, str):
                        _log("error", portal_id)
                        return _err("VALIDATION_ERROR", f"Property '{k}' must be a string")

        # Enforce unique property constraints when configured
        unique_props = [d.get("name") for d in product_defs if d.get("has_unique_value") is True and d.get("status") == "active" and d.get("archived") is False]
        objs = _load("crm_objects.json")
        for up in unique_props:
            if up in properties and properties.get(up) not in ("", None):
                val = properties.get(up)
                for o in objs:
                    if not isinstance(o, dict):
                        continue
                    if o.get("portal_id") != portal_id or o.get("object_type") != "products":
                        continue
                    if o.get("status") == "archived" or o.get("archived") is True:
                        continue
                    if isinstance(o.get("properties"), dict) and o["properties"].get(up) == val:
                        _log("error", portal_id)
                        return _err("CONFLICT", f"Unique constraint violated for property '{up}'", property=up, value=val)

        # Generate ids
        now = _now()
        hubspot_object_id = str(int(time.time() * 1000)) + uuid.uuid4().hex[:6]

        # Ensure unique (portal_id, object_type, hubspot_object_id)
        for o in objs:
            if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "products" and o.get("hubspot_object_id") == hubspot_object_id:
                hubspot_object_id = str(int(time.time() * 1000)) + uuid.uuid4().hex[:8]
                break

        row_id = "obj_" + uuid.uuid4().hex

        # Build search_text
        def _search_blob(props):
            try:
                parts = []
                for k, v in props.items():
                    if v is None or v == "":
                        continue
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        parts.append(str(v))
                    elif isinstance(v, str):
                        parts.append(v)
                blob = " ".join(parts).strip()
                return blob.lower() if blob else None
            except Exception:
                return None

        clean_props = dict(properties)
        # Remove None keys (HubSpot-like create typically just omits)
        for k in list(clean_props.keys()):
            if clean_props[k] is None:
                del clean_props[k]

        obj_row = {
            "id": row_id,
            "portal_id": portal_id,
            "object_type": "products",
            "hubspot_object_id": hubspot_object_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": clean_props,
            "properties_version": 1,
            "search_text": _search_blob(clean_props),
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        objs.append(obj_row)
        _save("crm_objects.json", objs)

        _log("ok", portal_id)
        # Return HubSpot-style-ish record with id + properties
        return {
            "id": hubspot_object_id,
            "properties": obj_row["properties"],
            "createdAt": obj_row["hubspot_created_at"],
            "updatedAt": obj_row["hubspot_updated_at"],
            "archived": obj_row["archived"],
        }
    except Exception as e:
        try:
            portal_id = locals().get("portal_id")
            _log("error", portal_id)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

