        _log("ok", portal_id)
        return {
            "id": target["hubspot_object_id"],
            "properties": target["properties"],
            "createdAt": target.get("hubspot_created_at"),
            "updatedAt": target.get("hubspot_updated_at"),
            "archived": target.get("archived", False),
        }
    except Exception as e:
        try:
            portal_id = locals().get("portal_id")
            _log("error", portal_id)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def products_archive(productId, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "hubspot_mcp",
            "endpoint": "products_archive",
            "portal_id": portal_id,
            "credential_id": None,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        props = _load("crm_object_properties.json")
        for r in props:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        return None

    try:
        if not isinstance(productId, str) or not productId.strip():
            _log("error")
            return _err("VALIDATION_ERROR", "`productId` must be a non-empty string")

        portal_id = _resolve_portal_id()
        if not portal_id:
            _log("error")
            return _err("UNAUTHORIZED", "No tenant context available")

        objs = _load("crm_objects.json")
        target = None
        for o in objs:
            if isinstance(o, dict) and o.get("portal_id") == portal_id and o.get("object_type") == "products" and o.get("hubspot_object_id") == productId:
                target = o
                break

        if not target:
            _log("error", portal_id)
            return _err("NOT_FOUND", "Product not found", productId=productId)

        # Transition active<->archived (archive operation: must go to archived)
        if target.get("status") == "archived" or target.get("archived") is True:
            # idempotent archive: already archived -> success with empty response
            _log("ok", portal_id)
            return {}

        target["status"] = "archived"
        target["archived"] = True
        now = _now()
        target["updated_at"] = now
        target["hubspot_updated_at"] = now
        target["properties_version"] = int(target.get("properties_version") or 0) + 1

        _save("crm_objects.json", objs)

        _log("ok", portal_id)
        return {}
    except Exception as e:
        try:
            portal_id = locals().get("portal_id")
            _log("error", portal_id)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def products_search(filterGroups, query=None, limit=None, after=None, sorts=None, properties=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, portal_id=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "hubspot_mcp",
            "endpoint": "products_search",
            "portal_id": portal_id,
            "credential_id": None,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_portal_id():
        objs = _load("crm_objects.json")
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        props = _load("crm_object_properties.json")
        for r in props:
            if isinstance(r, dict) and r.get("portal_id"):
                return r.get("portal_id")
        return None

    def _coerce_num(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str) and x.strip() != "":
            try:
                return float(x)
            except ValueError:
                return None
        return None

    def _eval_filter(obj_props, f):
        pn = f.get("propertyName")
        op = f.get("operator")
        val = f.get("value", None)
        vals = f.get("values", None)

        has = isinstance(obj_props, dict) and pn in obj_props and obj_props.get(pn) not in (None, "")
        cur = obj_props.get(pn) if isinstance(obj_props, dict) else None

        if op == "HAS_PROPERTY":
            return has
        if op == "NOT_HAS_PROPERTY":
            return not has

        if op in ("IN", "NOT_IN"):
            if vals is None:
                if val is None:
                    return False
                test_vals = [val]
            else:
                if not isinstance(vals, list) or len(vals) == 0:
                    return False
                test_vals = vals
            # compare as string/number loosely
            if isinstance(cur, (int, float)) and not isinstance(cur, bool):
                cur_norm = _coerce_num(cur)
                tvn = []
                for x in test_vals:
                    xn = _coerce_num(x)
                    tvn.append(xn if xn is not None else x)
                in_set = cur_norm in tvn or cur in test_vals or str(cur) in [str(x) for x in test_vals]
            else:
                in_set = str(cur) in [str(x) for x in test_vals]
            return in_set if op == "IN" else (not in_set)

        if op in ("CONTAINS_TOKEN", "NOT_CONTAINS_TOKEN"):
            if not isinstance(val, str):
                return False
            token = val.strip().lower()
            if token == "":
                return False
            hay = ""
            if isinstance(obj_props, dict):
                v = obj_props.get(pn)
                if isinstance(v, str):
                    hay = v.lower()
                elif v is not None:
                    hay = str(v).lower()
            ok = token in hay.split() or token in hay
            return ok if op == "CONTAINS_TOKEN" else (not ok)

        # For comparisons, if missing property -> false except NEQ (treat missing as not equal) and NOT_CONTAINS_TOKEN (handled above)
        if cur in (None, ""):
            if op == "NEQ":
                return True
            return False

        # BETWEEN
        if op == "BETWEEN":
            if not isinstance(vals, list) or len(vals) != 2:
                return False
            a = _coerce_num(vals[0])
            b = _coerce_num(vals[1])
            c = _coerce_num(cur)
            if a is None or b is None or c is None:
                # fall back lexicographic
                lo, hi = str(vals[0]), str(vals[1])
                cc = str(cur)
                return lo <= cc <= hi
            lo, hi = (a, b) if a <= b else (b, a)
            return lo <= c <= hi

        # EQ/NEQ and LT/LTE/GT/GTE
        if op in ("EQ", "NEQ"):
            eq = str(cur) == str(val) if val is not None else False
            return eq if op == "EQ" else (not eq)

        if op in ("LT", "LTE", "GT", "GTE"):
            cn = _coerce_num(cur)
            vn = _coerce_num(val)
            if cn is not None and vn is not None:
                if op == "LT": return cn < vn
                if op == "LTE": return cn <= vn
                if op == "GT": return cn > vn
                if op == "GTE": return cn >= vn
            # lexicographic fallback
            cs = str(cur)
            vs = "" if val is None else str(val)
            if op == "LT": return cs < vs
            if op == "LTE": return cs <= vs
            if op == "GT": return cs > vs
            if op == "GTE": return cs >= vs

        return False

    try:
        portal_id = _resolve_portal_id()
        if not portal_id:
            _log("error")
            return _err("UNAUTHORIZED", "No tenant context available")

        if not isinstance(filterGroups, list) or len(filterGroups) == 0:
            _log("error", portal_id)
            return _err("VALIDATION_ERROR", "`filterGroups` must be a non-empty array")

        if query is not None and not isinstance(query, str):
            _log("error", portal_id)
            return _err("VALIDATION_ERROR", "`query` must be a string")

        if limit is None:
            limit_n = 10
        else:
            if not isinstance(limit, (int, float)) or isinstance(limit, bool):
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "`limit` must be a number")
            limit_n = int(limit)
        if limit_n < 1 or limit_n > 100:
            _log("error", portal_id)
            return _err("VALIDATION_ERROR", "`limit` must be between 1 and 100")

        if after is not None and not isinstance(after, str):
            _log("error", portal_id)
            return _err("VALIDATION_ERROR", "`after` must be a string")

        if sorts is not None:
            if not isinstance(sorts, list) or any(not isinstance(s, str) for s in sorts):
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "`sorts` must be an array of strings")

        if properties is not None:
            if not isinstance(properties, list) or any(not isinstance(p, str) for p in properties):
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "`properties` must be an array of strings")

        # Validate filters structure/operators
        valid_ops = {"EQ","NEQ","LT","LTE","GT","GTE","BETWEEN","IN","NOT_IN","HAS_PROPERTY","NOT_HAS_PROPERTY","CONTAINS_TOKEN","NOT_CONTAINS_TOKEN"}
        for gi, g in enumerate(filterGroups):
            if not isinstance(g, dict) or "filters" not in g:
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "Each filterGroup must be an object with `filters`")
            if not isinstance(g["filters"], list) or len(g["filters"]) == 0:
                _log("error", portal_id)
                return _err("VALIDATION_ERROR", "Each filterGroup.filters must be a non-empty array", groupIndex=gi)
            for fi, f in enumerate(g["filters"]):
                if not isinstance(f, dict):
                    _log("error", portal_id)
                    return _err("VALIDATION_ERROR", "Each filter must be an object", groupIndex=gi, filterIndex=fi)
                if not isinstance(f.get("propertyName"), str) or not f.get("propertyName"):
                    _log("error", portal_id)
                    return _err("VALIDATION_ERROR", "filter.propertyName must be a non-empty string", groupIndex=gi, filterIndex=fi)
                if f.get("operator") not in valid_ops:
                    _log("error", portal_id)
                    return _err("VALIDATION_ERROR", "Invalid filter operator", operator=f.get("operator"), groupIndex=gi, filterIndex=fi)
                op = f.get("operator")
                if op == "BETWEEN":
                    vals = f.get("values", None)
                    if not isinstance(vals, list) or len(vals) != 2:
                        _log("error", portal_id)
                        return _err("VALIDATION_ERROR", "BETWEEN requires `values` array of length 2", groupIndex=gi, filterIndex=fi)
                if op in ("IN","NOT_IN"):
                    if f.get("values", None) is None and f.get("value", None) is None:
                        _log("error", portal_id)
                        return _err("VALIDATION_ERROR", f"{op} requires `value` or non-empty `values`", groupIndex=gi, filterIndex=fi)
                    if f.get("values", None) is not None:
                        if not isinstance(f["values"], list) or len(f["values"]) == 0:
                            _log("error", portal_id)
                            return _err("VALIDATION_ERROR", f"{op} requires non-empty `values` when provided", groupIndex=gi, filterIndex=fi)

        objs = _load("crm_objects.json")
        rows = []
        q = (query or "").strip().lower()
        for o in objs:
            if not isinstance(o, dict):
                continue
            if o.get("portal_id") != portal_id or o.get("object_type") != "products":
                continue
            if o.get("archived") is True or o.get("status") == "archived":
                continue

            # query free-text: match against search_text or property values
            if q:
                st = o.get("search_text") or ""
                if q not in str(st).lower():
                    # also scan property values
                    found = False
                    props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
                    for v in props.values():
                        if v is None:
                            continue
                        if q in str(v).lower():
                            found = True
                            break
                    if not found:
                        continue

            # filterGroups OR; filters within group AND
            props = o.get("properties") if isinstance(o.get("properties"), dict) else {}
            group_ok = False
            for g in filterGroups:
                ok = True
                for f in g.get("filters", []):
                    if not _eval_filter(props, f):
                        ok = False
                        break
                if ok:
                    group_ok = True
                    break
            if not group_ok:
                continue

            rows.append(o)

        # Sorting
        def _sort_key_maker(s):
            desc = False
            field = s
            if isinstance(s, str) and s.startswith("-"):
                desc = True
                field = s[1:]
            return field, desc

        if sorts:
            keys = [_sort_key_maker(s) for s in sorts]
            # Apply stable sorts from last to first
            for field, desc in reversed(keys):
                if field in ("createdAt", "created_at"):
                    rows.sort(key=lambda r: (r.get("hubspot_created_at") or r.get("created_at") or ""), reverse=desc)
                elif field in ("updatedAt", "updated_at"):
                    rows.sort(key=lambda r: (r.get("hubspot_updated_at") or r.get("updated_at") or ""), reverse=desc)
                else:
                    rows.sort(key=lambda r: str((r.get("properties") or {}).get(field, "")).lower(), reverse=desc)
        else:
            rows.sort(key=lambda r: str(r.get("hubspot_object_id") or ""))

        # Paging: `after` as hubspot_object_id cursor (exclusive)
        start = 0
        if after:
            for i, r in enumerate(rows):
                if str(r.get("hubspot_object_id")) == after:
                    start = i + 1
                    break

        page = rows[start:start + limit_n]
        next_after = None
        if start + limit_n < len(rows) and page:
            next_after = str(page[-1].get("hubspot_object_id"))

        # Shape results
        wanted = properties  # if None => return all stored properties
        results = []
        for r in page:
            all_props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            if wanted is None:
                out_props = dict(all_props)
            else:
                out_props = {k: all_props.get(k) for k in wanted if k in all_props}
            results.append({
                "id": str(r.get("hubspot_object_id")),
                "properties": out_props,
                "createdAt": r.get("hubspot_created_at"),
                "updatedAt": r.get("hubspot_updated_at"),
                "archived": bool(r.get("archived")),
            })

        resp = {"total": len(rows), "results": results}
        if next_after is not None:
            resp["paging"] = {"next": {"after": next_after}}

        _log("ok", portal_id)
        return resp
    except Exception as e:
        try:
            portal_id = locals().get("portal_id")
            _log("error", portal_id)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def products_batch_archive(productIds, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "products_batch_archive"

    # --- quota/rate logging helpers (best-effort; do not fail call if missing collection) ---
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        # discover any plausible request log file
        for fn in ("request_log.json", "request_logs.json", "audit_log.json", "usage.json", "usage_log.json", "requests.json"):
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn
        return None

    def _log_request(portal_id, status_code, status_text, credential_id=None, meta=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex[:18],
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status_text,
            "status_code": int(status_code),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    # --- input validation ---
    if not isinstance(productIds, list) or len(productIds) == 0:
        resp = _err("VALIDATION_ERROR", "`productIds` must be a non-empty array of strings.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp
    bad = [x for x in productIds if not isinstance(x, str) or not x.strip()]
    if bad:
        resp = _err("VALIDATION_ERROR", "All `productIds` entries must be non-empty strings.", invalidIds=bad[:50])
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp

    objs = _load("crm_objects.json")

    # --- ambient auth / portal resolution ---
    # Pick any portal that actually has product objects or product property definitions; if none, UNAUTHORIZED.
    props_defs = _load("crm_object_properties.json")
    portal_candidates = set()
    for r in objs:
        if isinstance(r, dict) and r.get("object_type") == "products":
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                portal_candidates.add(pid)
    for d in props_defs:
        if isinstance(d, dict) and d.get("object_type") == "products":
            pid = d.get("portal_id")
            if isinstance(pid, str) and pid:
                portal_candidates.add(pid)

    if not portal_candidates:
        resp = _err("UNAUTHORIZED", "No authorized HubSpot portal context available for product archive.")
        _log_request(None, 401, "error", meta={"error": resp["error"]})
        return resp

    # Process per portal: since tool does not take portal_id, we must route each ID to an existing product in some portal.
    # If an ID exists in multiple portals (shouldn't in real HS; here possible), pick the first matching portal but be consistent.
    by_hs_id = {}
    for idx, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("object_type") != "products":
            continue
        hs_id = r.get("hubspot_object_id")
        if isinstance(hs_id, str) and hs_id:
            by_hs_id.setdefault(hs_id, []).append((idx, r))

    results = []
    changed = False
    now = _now()

    for pid in productIds:
        matches = by_hs_id.get(pid, [])
        if not matches:
            results.append({"id": pid, "archived": False, "status": "error", "error": {"code": "NOT_FOUND", "message": "Product not found."}})
            continue

        # Prefer an active row if exists
        chosen_idx = None
        chosen = None
        for idx, r in matches:
            if r.get("status") == "active" and r.get("archived") is False:
                chosen_idx, chosen = idx, r
                break
        if chosen is None:
            chosen_idx, chosen = matches[0]

        # transition: active->archived is legal; archived->archived is idempotent
        st = chosen.get("status")
        if st == "archived" or chosen.get("archived") is True:
            # idempotent success
            results.append({"id": pid, "archived": True, "status": "success"})
            continue
        if st != "active":
            results.append({"id": pid, "archived": False, "status": "error", "error": {"code": "INVALID_TRANSITION", "message": f"Cannot archive product from status '{st}'."}})
            continue

        # apply archive
        objs[chosen_idx]["status"] = "archived"
        objs[chosen_idx]["archived"] = True
        objs[chosen_idx]["updated_at"] = now
        # keep hubspot_updated_at in sync if present/known
        objs[chosen_idx]["hubspot_updated_at"] = now
        # increment properties_version monotonic
        pv = objs[chosen_idx].get("properties_version")
        if isinstance(pv, int) and pv >= 1:
            objs[chosen_idx]["properties_version"] = pv + 1
        else:
            objs[chosen_idx]["properties_version"] = 1
        changed = True
        results.append({"id": pid, "archived": True, "status": "success"})

    if changed:
        _save("crm_objects.json", objs)

    # Pick a portal_id for logging: if any successes, log that portal; else None.
    portal_for_log = None
    for pid in productIds:
        matches = by_hs_id.get(pid, [])
        if matches:
            portal_for_log = matches[0][1].get("portal_id")
            break

    resp = {"results": results}
    _log_request(portal_for_log, 200, "ok", meta={"count": len(results)})
    return resp

