        logs.append(row)
        _save(fn, logs)

    # --- validate inputs ---
    if not isinstance(inputs, list) or len(inputs) == 0:
        resp = _err("VALIDATION_ERROR", "`inputs` must be a non-empty array.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp

    for i, inp in enumerate(inputs):
        if not isinstance(inp, dict):
            resp = _err("VALIDATION_ERROR", "Each input must be an object.", index=i)
            _log_request(None, 400, "error", meta={"error": resp["error"]})
            return resp
        if "properties" not in inp:
            resp = _err("VALIDATION_ERROR", "Each input must include `properties`.", index=i)
            _log_request(None, 400, "error", meta={"error": resp["error"]})
            return resp
        if not isinstance(inp.get("properties"), dict):
            resp = _err("VALIDATION_ERROR", "`properties` must be an object.", index=i)
            _log_request(None, 400, "error", meta={"error": resp["error"]})
            return resp

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")

    # --- portal resolution (ambient auth) ---
    # Choose a portal that has product property definitions (preferred) else any portal seen in store.
    portal_id = None
    for d in prop_defs:
        if isinstance(d, dict) and d.get("object_type") == "products":
            pid = d.get("portal_id")
            if isinstance(pid, str) and pid:
                portal_id = pid
                break
    if portal_id is None:
        for r in objs:
            if isinstance(r, dict):
                pid = r.get("portal_id")
                if isinstance(pid, str) and pid:
                    portal_id = pid
                    break
    if portal_id is None:
        resp = _err("UNAUTHORIZED", "No authorized HubSpot portal context available for product creation.")
        _log_request(None, 401, "error", meta={"error": resp["error"]})
        return resp

    # Build property definitions map for validation (only when definitions exist)
    defs_for_portal = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "products"]
    defs_by_name = {d.get("name"): d for d in defs_for_portal if isinstance(d.get("name"), str)}
    definitions_exist = len(defs_by_name) > 0

    # determine unique properties (has_unique_value=true)
    unique_props = {n for n, d in defs_by_name.items() if d.get("has_unique_value") is True and d.get("status") == "active" and d.get("archived") is False}

    # index existing objects for uniqueness checks
    existing_products = [r for r in objs if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "products"]
    unique_index = {p: {} for p in unique_props}
    for r in existing_products:
        props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        for p in unique_props:
            v = props.get(p)
            if v is None:
                continue
            key = str(v)
            unique_index[p].setdefault(key, []).append(r.get("id"))

    def _validate_value_type(pname, pdef, val):
        # accept clearing as empty string
        if val == "":
            return True, None
        ptype = pdef.get("type")
        if ptype == "string" or ptype == "enumeration":
            if isinstance(val, str):
                return True, None
            return False, "must be a string"
        if ptype == "number":
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                return True, None
            return False, "must be a number"
        if ptype == "bool":
            if isinstance(val, bool):
                return True, None
            return False, "must be a boolean"
        if ptype in ("date", "datetime"):
            if isinstance(val, str):
                return True, None
            return False, "must be an ISO date/datetime string"
        # unknown definition type: accept as stringifiable
        return True, None

    now = _now()

    results = []
    # We'll accumulate successful creations then persist once
    new_rows = []
    changed = False

    # For assigning hubspot_object_id (client-visible ID). We'll generate numeric-like strings.
    def _next_hs_id():
        max_id = 0
        for r in objs:
            if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "products":
                hs = r.get("hubspot_object_id")
                if isinstance(hs, str) and hs.isdigit():
                    max_id = max(max_id, int(hs))
        for r in new_rows:
            hs = r.get("hubspot_object_id")
            if isinstance(hs, str) and hs.isdigit():
                max_id = max(max_id, int(hs))
        return str(max_id + 1)

    def _new_internal_id():
        return "obj_" + uuid.uuid4().hex[:20]

    for i, inp in enumerate(inputs):
        props = inp.get("properties", {})
        # atomic per item: validate everything before adding to new_rows
        if not isinstance(props, dict):
            results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "`properties` must be an object."}})
            continue

        # property name validation if definitions exist
        if definitions_exist:
            unknown = [k for k in props.keys() if k not in defs_by_name]
            if unknown:
                results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Unknown properties are not allowed for products in this portal.", "unknownProperties": unknown}})
                continue

            # reject archived/hidden definitions
            bad = []
            for k, v in props.items():
                d = defs_by_name.get(k)
                if not d:
                    continue
                if d.get("archived") is True or d.get("status") == "archived":
                    bad.append({"property": k, "reason": "property definition is archived"})
                if d.get("hidden") is True:
                    bad.append({"property": k, "reason": "property definition is hidden"})
                ok, why = _validate_value_type(k, d, v)
                if not ok:
                    bad.append({"property": k, "reason": why})
                if d.get("type") == "enumeration" and v != "":
                    if isinstance(v, str):
                        opts = d.get("options")
                        if isinstance(opts, list) and opts:
                            allowed = {str(o.get("value")) for o in opts if isinstance(o, dict) and "value" in o}
                            if allowed and v not in allowed:
                                bad.append({"property": k, "reason": "value not in enumeration options"})
            if bad:
                results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Invalid product properties.", "details": bad}})
                continue

        # unique constraint checks
        conflict = None
        for p in unique_props:
            if p in props and props.get(p) not in (None, ""):
                key = str(props.get(p))
                # also check against rows created earlier in this batch
                if key in unique_index.get(p, {}):
                    conflict = {"property": p, "value": props.get(p)}
                    break
        if conflict:
            results.append({"index": i, "status": "error", "error": {"code": "CONFLICT", "message": "Unique property constraint violated.", "conflict": conflict}})
            continue

        # create row
        hs_id = _next_hs_id()
        internal_id = _new_internal_id()

        # denormalized search_text
        def _mk_search_text(d):
            parts = []
            for k, v in d.items():
                if v is None:
                    continue
                if isinstance(v, (dict, list)):
                    continue
                s = str(v).strip()
                if s:
                    parts.append(s)
            return " ".join(parts) if parts else None

        row = {
            "id": internal_id,
            "portal_id": portal_id,
            "object_type": "products",
            "hubspot_object_id": hs_id,
            "custom_object_schema_id": None,
            "archived": False,
            "status": "active",
            "properties": props.copy(),
            "properties_version": 1,
            "search_text": _mk_search_text(props),
            "created_at": now,
            "updated_at": now,
            "hubspot_created_at": now,
            "hubspot_updated_at": now,
        }

        # record uniqueness in batch index
        for p in unique_props:
            if p in props and props.get(p) not in (None, ""):
                unique_index[p].setdefault(str(props.get(p)), []).append(internal_id)

        new_rows.append(row)
        results.append({"index": i, "status": "success", "id": hs_id, "properties": row["properties"]})
        changed = True

    if changed:
        objs.extend(new_rows)
        _save("crm_objects.json", objs)

    resp = {"results": results}
    _log_request(portal_id, 200, "ok", meta={"created": len([r for r in results if r.get("status") == "success"]), "total": len(results)})
    return resp

def products_batch_read(propertiesWithHistory, productIds, properties, idProperty=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "products_batch_read"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_log.json", "request_logs.json", "audit_log.json", "usage.json", "usage_log.json", "requests.json"):
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn
        return None

    def _log_request(portal_id, status_code, status_text, credential_id=None, meta=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex[:18],
            "timestamp": _now(),
            "endpoint": endpoint,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "status": status_text,
            "status_code": int(status_code),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    # --- validate inputs ---
    if not isinstance(productIds, list) or len(productIds) == 0:
        resp = _err("VALIDATION_ERROR", "`productIds` must be a non-empty array of strings.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp
    if any((not isinstance(x, str) or not x.strip()) for x in productIds):
        resp = _err("VALIDATION_ERROR", "All `productIds` entries must be non-empty strings.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp
    if not isinstance(properties, list) or not isinstance(propertiesWithHistory, list):
        resp = _err("VALIDATION_ERROR", "`properties` and `propertiesWithHistory` must be arrays of strings.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp
    if any((not isinstance(p, str) or not p) for p in properties + propertiesWithHistory):
        resp = _err("VALIDATION_ERROR", "All property names in `properties`/`propertiesWithHistory` must be non-empty strings.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp
    if idProperty is not None and (not isinstance(idProperty, str) or not idProperty.strip()):
        resp = _err("VALIDATION_ERROR", "`idProperty` must be a non-empty string when provided.")
        _log_request(None, 400, "error", meta={"error": resp["error"]})
        return resp

    objs = _load("crm_objects.json")
    prop_defs = _load("crm_object_properties.json")

    # --- portal resolution (ambient auth) ---
    portal_id = None
    for r in objs:
        if isinstance(r, dict) and r.get("object_type") == "products":
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                portal_id = pid
                break
    if portal_id is None:
        for d in prop_defs:
            if isinstance(d, dict) and d.get("object_type") == "products":
                pid = d.get("portal_id")
                if isinstance(pid, str) and pid:
                    portal_id = pid
                    break
    if portal_id is None:
        resp = _err("UNAUTHORIZED", "No authorized HubSpot portal context available for product read.")
        _log_request(None, 401, "error", meta={"error": resp["error"]})
        return resp

    defs_for_portal = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "products"]
    defs_by_name = {d.get("name"): d for d in defs_for_portal if isinstance(d.get("name"), str)}

    # Validate requested property names (when definitions exist, must be valid)
    if defs_by_name:
        invalid = [p for p in set(properties + propertiesWithHistory) if p not in defs_by_name]
        if invalid:
            resp = _err("VALIDATION_ERROR", "Requested property names include invalid properties for products.", invalidProperties=sorted(invalid))
            _log_request(portal_id, 400, "error", meta={"error": resp["error"]})
            return resp

    # Validate idProperty is a unique property
    if idProperty is not None:
        if not defs_by_name:
            resp = _err("VALIDATION_ERROR", "`idProperty` requires product property definitions to be present for this portal.")
            _log_request(portal_id, 400, "error", meta={"error": resp["error"]})
            return resp
        d = defs_by_name.get(idProperty)
        if not d or d.get("has_unique_value") is not True or d.get("status") != "active" or d.get("archived") is True:
            resp = _err("VALIDATION_ERROR", "`idProperty` must be an active unique property for products.", idProperty=idProperty)
            _log_request(portal_id, 400, "error", meta={"error": resp["error"]})
            return resp

    products = [r for r in objs if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "products" and r.get("archived") is False and r.get("status") == "active"]

    # Build lookup based on idProperty or hubspot_object_id
    results = []
    if idProperty is None:
        lookup = {}
        for r in products:
            hs = r.get("hubspot_object_id")
            if isinstance(hs, str):
                lookup[hs] = r
        for pid in productIds:
            r = lookup.get(pid)
            if not r:
                results.append({"id": pid, "status": "error", "error": {"code": "NOT_FOUND", "message": "Product not found."}})
                continue
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            out_props = {k: props.get(k) for k in properties}
            # No history store exists in schema; return empty arrays per property requested with history
            out_hist = {k: [] for k in propertiesWithHistory}
            results.append({"id": r.get("hubspot_object_id"), "status": "success", "properties": out_props, "propertiesWithHistory": out_hist})
    else:
        # uniqueness enforced: multiple matches -> CONFLICT-like validation error for that id
        index = {}
        for r in products:
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            v = props.get(idProperty)
            if v is None or v == "":
                continue
            key = str(v)
            index.setdefault(key, []).append(r)
        for pid in productIds:
            matches = index.get(pid, [])
            if not matches:
                results.append({"id": pid, "status": "error", "error": {"code": "NOT_FOUND", "message": "Product not found."}})
                continue
            if len(matches) > 1:
                results.append({"id": pid, "status": "error", "error": {"code": "CONFLICT", "message": "Multiple products matched the provided unique idProperty value.", "idProperty": idProperty}})
                continue
            r = matches[0]
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            out_props = {k: props.get(k) for k in properties}
            out_hist = {k: [] for k in propertiesWithHistory}
            results.append({"id": r.get("hubspot_object_id"), "status": "success", "properties": out_props, "propertiesWithHistory": out_hist})

    resp = {"results": results}
    _log_request(portal_id, 200, "ok", meta={"returned": len([r for r in results if r.get("status") == "success"]), "total": len(results)})
    return resp

