            _log_request(None, 400, "error", meta={"error": resp["error"]})
            return resp
        if "idProperty" in inp and inp.get("idProperty") is not None and (not isinstance(inp.get("idProperty"), str) or not inp.get("idProperty").strip()):
            resp = _err("VALIDATION_ERROR", "`idProperty` must be a non-empty string when provided.", index=i)
            _log_request(None, 400, "error", meta={"error": resp["error"]})
