    portal_id = None
    for r in objs:
        if isinstance(r, dict) and r.get("object_type") == "products":
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                portal_id = pid
                break
    if portal_id is None:
        for d in prop_defs:
            if isinstance(d, dict) and d.get("object_type") == "products":
                pid = d.get("portal_id")
                if isinstance(pid, str) and pid:
                    portal_id = pid
                    break
    if portal_id is None:
        resp = _err("UNAUTHORIZED", "No authorized HubSpot portal context available for product update.")
        _log_request(None, 401, "error", meta={"error": resp["error"]})
        return resp

    defs_for_portal = [d for d in prop_defs if isinstance(d, dict) and d.get("portal_id") == portal_id and d.get("object_type") == "products"]
    defs_by_name = {d.get("name"): d for d in defs_for_portal if isinstance(d.get("name"), str)}
    definitions_exist = bool(defs_by_name)

    # unique properties index for conflict checks
    unique_props = {n for n, d in defs_by_name.items() if d.get("has_unique_value") is True and d.get("status") == "active" and d.get("archived") is False}
    products_idxs = []
    for idx, r in enumerate(objs):
        if isinstance(r, dict) and r.get("portal_id") == portal_id and r.get("object_type") == "products":
            products_idxs.append(idx)

    unique_index = {p: {} for p in unique_props}
    for idx in products_idxs:
        r = objs[idx]
        if r.get("archived") is True or r.get("status") == "archived":
            continue
        props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
        for p in unique_props:
            v = props.get(p)
            if v is None or v == "":
                continue
            unique_index[p].setdefault(str(v), []).append(r.get("id"))

    def _validate_value_type(pname, pdef, val):
