            return True, None
        ptype = pdef.get("type")
        if ptype == "string" or ptype == "enumeration":
            return (isinstance(val, str), "must be a string" if not isinstance(val, str) else None)
        if ptype == "number":
            ok = isinstance(val, (int, float)) and not isinstance(val, bool)
            return (ok, "must be a number" if not ok else None)
        if ptype == "bool":
            return (isinstance(val, bool), "must be a boolean" if not isinstance(val, bool) else None)
        if ptype in ("date", "datetime"):
            return (isinstance(val, str), "must be an ISO date/datetime string" if not isinstance(val, str) else None)
