            if r.get("archived") is True or r.get("status") == "archived":
                continue
            props = r.get("properties") if isinstance(r.get("properties"), dict) else {}
            v = props.get(prop)
            if v is None:
                continue
            if str(v) == str(value):
                matches.append((idx, r))
        if len(matches) == 1:
            return matches[0][0], matches[0][1], None
        if len(matches) == 0:
            return None, None, "NOT_FOUND"
        return None, None, "CONFLICT"

    now = _now()
    results = []
    changed = False

    # We'll apply updates in-memory per item only after validating that item (atomic per item).
    for i, inp in enumerate(inputs):
