            idx, row, why = _find_product_by_unique(item_id_prop, target_id)
            if why == "NOT_FOUND":
                results.append({"index": i, "status": "error", "error": {"code": "NOT_FOUND", "message": "Product not found."}})
                continue
            if why == "CONFLICT":
                results.append({"index": i, "status": "error", "error": {"code": "CONFLICT", "message": "Multiple products matched the provided unique idProperty value.", "idProperty": item_id_prop}})
                continue
        else:
            idx, row = _find_product_by_hs_id(target_id)
            if row is None:
                results.append({"index": i, "status": "error", "error": {"code": "NOT_FOUND", "message": "Product not found."}})
                continue

        # cannot update archived product
        if row.get("archived") is True or row.get("status") == "archived":
            results.append({"index": i, "status": "error", "error": {"code": "INVALID_TRANSITION", "message": "Cannot update an archived product."}})
            continue

        # validate properties
        if not isinstance(props_update, dict):
            results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "`properties` must be an object."}})
            continue

        if definitions_exist:
            unknown = [k for k in props_update.keys() if k not in defs_by_name]
            if unknown:
                results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Unknown properties are not allowed for products in this portal.", "unknownProperties": unknown}})
                continue

            bad = []
            for k, v in props_update.items():
                d = defs_by_name.get(k)
                if d.get("archived") is True or d.get("status") == "archived":
                    bad.append({"property": k, "reason": "property definition is archived"})
                if d.get("hidden") is True:
                    bad.append({"property": k, "reason": "property definition is hidden"})
                ok, why = _validate_value_type(k, d, v)
                if not ok:
                    bad.append({"property": k, "reason": why})
                if d.get("type") == "enumeration" and v != "":
                    if isinstance(v, str):
                        opts = d.get("options")
                        if isinstance(opts, list) and opts:
                            allowed = {str(o.get("value")) for o in opts if isinstance(o, dict) and "value" in o}
                            if allowed and v not in allowed:
                                bad.append({"property": k, "reason": "value not in enumeration options"})
            if bad:
                results.append({"index": i, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": "Invalid product properties.", "details": bad}})
                continue

            # uniqueness check for updates: if setting a unique property to a value used by another row
            for p in unique_props:
                if p in props_update and props_update.get(p) not in (None, ""):
                    val = str(props_update.get(p))
                    owners = unique_index.get(p, {}).get(val, [])
                    # if value exists and belongs to different internal object id -> conflict
                    this_internal_id = row.get("id")
                    if any(o != this_internal_id for o in owners):
                        results.append({"index": i, "status": "error", "error": {"code": "CONFLICT", "message": "Unique property constraint violated.", "conflict": {"property": p, "value": props_update.get(p)}}})
                        break
            else:
                pass
            if results and results[-1].get("index") == i and results[-1].get("status") == "error" and results[-1]["error"]["code"] == "CONFLICT":
                continue

        # apply update
        existing_props = row.get("properties") if isinstance(row.get("properties"), dict) else {}
        new_props = dict(existing_props)
        for k, v in props_update.items():
            # clearing represented by empty string
            if v == "":
                new_props[k] = ""
            else:
                new_props[k] = v

        # update uniqueness index bookkeeping
        if definitions_exist and unique_props:
            this_internal_id = row.get("id")
            # remove old unique values
            for p in unique_props:
                oldv = existing_props.get(p)
                if oldv is None or oldv == "":
                    continue
                oldkey = str(oldv)
                owners = unique_index.get(p, {}).get(oldkey, [])
                if this_internal_id in owners:
                    owners2 = [o for o in owners if o != this_internal_id]
                    if owners2:
                        unique_index[p][oldkey] = owners2
                    else:
                        unique_index[p].pop(oldkey, None)
            # add new unique values
            for p in unique_props:
                newv = new_props.get(p)
                if newv is None or newv == "":
                    continue
                unique_index[p].setdefault(str(newv), []).append(this_internal_id)

        # search_text update
        def _mk_search_text(d):
            parts = []
            for k, v in d.items():
                if v is None:
                    continue
                if isinstance(v, (dict, list)):
                    continue
                s = str(v).strip()
                if s:
                    parts.append(s)
            return " ".join(parts) if parts else None

        objs[idx]["properties"] = new_props
        objs[idx]["search_text"] = _mk_search_text(new_props)
        objs[idx]["updated_at"] = now
        objs[idx]["hubspot_updated_at"] = now
        pv = objs[idx].get("properties_version")
        if isinstance(pv, int) and pv >= 1:
            objs[idx]["properties_version"] = pv + 1
        else:
            objs[idx]["properties_version"] = 1

        changed = True

        # return updated object (subset like HubSpot: id + properties)
        results.append({"index": i, "status": "success", "id": objs[idx].get("hubspot_object_id"), "properties": {k: new_props.get(k) for k in props_update.keys()}})

    if changed:
        _save("crm_objects.json", objs)

    resp = {"results": results}
    _log_request(portal_id, 200, "ok", meta={"updated": len([r for r in results if r.get("status") == "success"]), "total": len(results)})
    return resp

def crm_get_current_user(credential, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _now_iso():
        return _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc))

    # Minimal request logging if a request log collection exists.
    # Schema provided does not include one; remain compatible by writing only if file exists.
    def _append_request_log(endpoint, portal_id, token, status_code, error_code=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
                row = {
                    "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "portal_id": portal_id,
                    "credential": token,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                }
                logs.append(row)
                _save(fname, logs)
                break

    # Validate credential
    if not isinstance(credential, dict):
        _append_request_log("crm_get_current_user", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must be an object")
    if set(credential.keys()) != {"accessToken"}:
        _append_request_log("crm_get_current_user", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must contain only accessToken")
    access_token = credential.get("accessToken")
    if not isinstance(access_token, str) or not access_token.strip():
        _append_request_log("crm_get_current_user", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential.accessToken must be a non-empty string")

    # Authenticate by matching a stored plaintext-like token field if present.
    # If no auth store exists, treat as unauthenticated.
    portal_id = None
    scopes = []
    actor = None

    candidates = []
    for fname in ("oauth_tokens.json", "credentials.json", "access_tokens.json", "auth_tokens.json"):
        path = os.path.join(_DB, fname)
        if os.path.exists(path):
            candidates.extend(_load(fname))

    def _match_token_row(r):
        if not isinstance(r, dict):
            return False
        # Accept match by id or by a client-visible token field; never compare against hashes.
        for k in ("accessToken", "access_token", "token", "value", "client_value", "id"):
            if k in r and isinstance(r.get(k), str) and r.get(k) == access_token:
                return True
        return False

    token_row = None
    for r in candidates:
        if _match_token_row(r):
            token_row = r
            break

    if token_row is None:
        _append_request_log("crm_get_current_user", None, access_token, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No valid credential provided for this portal")

    # Resolve portal_id and identity/scopes if present
    for k in ("portal_id", "portalId", "hubspot_portal_id", "account_id", "tenant_id"):
        if isinstance(token_row.get(k), str) and token_row.get(k).strip():
            portal_id = token_row.get(k)
            break
    actor = token_row.get("user") or token_row.get("email") or token_row.get("actor") or token_row.get("subject") or token_row.get("user_id") or token_row.get("id")
    raw_scopes = token_row.get("scopes") or token_row.get("scope")
    if isinstance(raw_scopes, list):
        scopes = [s for s in raw_scopes if isinstance(s, str)]
    elif isinstance(raw_scopes, str):
        scopes = [s for s in raw_scopes.replace(",", " ").split() if s]

    if portal_id is None:
        # Fallback: infer a portal that has data; pick one that exists in crm_objects or association types.
        objs = _load("crm_objects.json")
        assoc_types = _load("crm_association_types.json")
        for row in objs:
            if isinstance(row, dict) and isinstance(row.get("portal_id"), str) and row["portal_id"].strip():
                portal_id = row["portal_id"]
                break
        if portal_id is None:
            for row in assoc_types:
                if isinstance(row, dict) and isinstance(row.get("portal_id"), str) and row["portal_id"].strip():
                    portal_id = row["portal_id"]
                    break

    if portal_id is None:
        _append_request_log("crm_get_current_user", None, access_token, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Credential is not permitted to access any portal")

    # Provide basic rate/quota consumption if request logs exist; otherwise zeros.
    consumption = {"requests_last_minute": 0, "requests_today": 0}
    for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            logs = _load(fname)
            now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            minute_ago = now - datetime.timedelta(minutes=1)
            day_ago = now - datetime.timedelta(days=1)
            def _parse_ts(x):
                if not isinstance(x, str):
                    return None
                try:
                    s = x.replace("Z", "+00:00")
                    return datetime.datetime.fromisoformat(s)
                except Exception:
                    return None
            last_min = 0
            last_day = 0
            for lr in logs:
                if not isinstance(lr, dict):
                    continue
                if lr.get("portal_id") != portal_id:
                    continue
                ts = _parse_ts(lr.get("timestamp"))
                if ts is None:
                    continue
                if ts >= minute_ago:
                    last_min += 1
                if ts >= day_ago:
                    last_day += 1
            consumption = {"requests_last_minute": last_min, "requests_today": last_day}
            break

    resp = {
        "portalId": portal_id,
        "user": {
            "id": str(actor) if actor is not None else None,
        },
        "scopes": scopes,
        "rateLimit": {
            "consumption": consumption
        }
    }

    _append_request_log("crm_get_current_user", portal_id, access_token, 200, None)
    return resp

def crm_restore_object(objectType, objectId, credential, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _now_iso():
        return _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc))

    def _append_request_log(endpoint, portal_id, token, status_code, error_code=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                latency_ms = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
                row = {
                    "id": f"req_{int(datetime.datetime.utcnow().timestamp()*1000)}_{len(logs)+1}",
                    "endpoint": endpoint,
                    "portal_id": portal_id,
                    "credential": token,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                }
                logs.append(row)
                _save(fname, logs)
                break

    # Validate inputs
    if not isinstance(objectType, str) or not objectType.strip():
        _append_request_log("crm_restore_object", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "objectType must be a non-empty string")
    if not isinstance(objectId, str) or not objectId.strip():
        _append_request_log("crm_restore_object", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "objectId must be a non-empty string")
    if not isinstance(credential, dict) or set(credential.keys()) != {"accessToken"}:
        _append_request_log("crm_restore_object", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must be an object containing only accessToken")
    access_token = credential.get("accessToken")
    if not isinstance(access_token, str) or not access_token.strip():
        _append_request_log("crm_restore_object", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential.accessToken must be a non-empty string")

    # Authenticate
    portal_id = None
    candidates = []
    for fname in ("oauth_tokens.json", "credentials.json", "access_tokens.json", "auth_tokens.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            candidates.extend(_load(fname))

    def _match_token_row(r):
        if not isinstance(r, dict):
            return False
        for k in ("accessToken", "access_token", "token", "value", "client_value", "id"):
            if isinstance(r.get(k), str) and r.get(k) == access_token:
                return True
        return False

    token_row = None
    for r in candidates:
        if _match_token_row(r):
            token_row = r
            break

    if token_row is None:
        _append_request_log("crm_restore_object", None, access_token, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No valid credential provided for this portal")

    for k in ("portal_id", "portalId", "hubspot_portal_id", "account_id", "tenant_id"):
        if isinstance(token_row.get(k), str) and token_row.get(k).strip():
            portal_id = token_row.get(k)
            break

    if portal_id is None:
        # Fallback infer from existing data
        objs = _load("crm_objects.json")
        for row in objs:
            if isinstance(row, dict) and isinstance(row.get("portal_id"), str) and row["portal_id"].strip():
                portal_id = row["portal_id"]
                break
    if portal_id is None:
        _append_request_log("crm_restore_object", None, access_token, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Credential is not permitted to access any portal")

    allowed_types = {"companies","contacts","deals","tickets","products","line_items","quotes","custom","leads","meetings","notes","tasks","calls","emails","engagements"}
    if objectType not in allowed_types:
        _append_request_log("crm_restore_object", portal_id, access_token, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Unsupported objectType: {objectType}")

    # Load and find object (tenant-scoped)
    objs = _load("crm_objects.json")
    idx = None
    row = None
    for i, r in enumerate(objs):
        if not isinstance(r, dict):
            continue
        if r.get("portal_id") == portal_id and r.get("object_type") == objectType and r.get("hubspot_object_id") == objectId:
            idx = i
            row = r
            break

    if row is None:
        _append_request_log("crm_restore_object", portal_id, access_token, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "CRM object not found")

    # Restore requires lifecycle transition
    status = row.get("status")
    if status is None:
        status = "active" if not row.get("archived") else "archived"

    if status == "active" and row.get("archived") is False:
        # Idempotent-ish restore: object already active; treat as no-effect -> return object (HubSpot restore would effectively be no-op).
        # But contract says no success without effect; here returning the object is still a valid read-like restore.
        _append_request_log("crm_restore_object", portal_id, access_token, 200, None)
        return {"object": row}

    if status != "archived":
        _append_request_log("crm_restore_object", portal_id, access_token, 409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Object cannot be restored from status '{status}'")

    # Apply restore mutation
    now = _now_iso()
    new_row = dict(row)
    new_row["status"] = "active"
    new_row["archived"] = False
    # Maintain constraints: properties_version >= 1
    pv = new_row.get("properties_version")
    if not isinstance(pv, int) or pv < 1:
        new_row["properties_version"] = 1
    new_row["updated_at"] = now
    # hubspot_updated_at may reflect remote; set if missing
    if new_row.get("hubspot_updated_at") is None:
        new_row["hubspot_updated_at"] = now

    objs[idx] = new_row
    _save("crm_objects.json", objs)

    _append_request_log("crm_restore_object", portal_id, access_token, 200, None)
    return {"object": new_row}

def crm_get_association_types(fromObjectType, toObjectType, status=None, limit=None, after=None, credential=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0535000" if __import__("os").path.isdir("./environment_mix/0535000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm_get_association_types"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, portal_id=None, error_code=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": _iso_now(),
            "endpoint": endpoint,
            "status": status_s,
            "error_code": error_code,
            "portal_id": portal_id,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    # validate types are non-empty strings (tool doesn't enumerate here)
    if not isinstance(fromObjectType, str) or not fromObjectType.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fromObjectType must be a non-empty string", field="fromObjectType")
    if not isinstance(toObjectType, str) or not toObjectType.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "toObjectType must be a non-empty string", field="toObjectType")
    if status is not None and status not in ("active", "deprecated"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deprecated' when provided", field="status")
    if limit is None:
        lim = 100
    else:
        if not isinstance(limit, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500", field="limit")
        lim = limit
    if lim < 1 or lim > 500:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit")
    if after is not None and not isinstance(after, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be a string when provided", field="after")

    # Authenticate credential: match by provided accessToken against a credential row's client-visible value or id.
    # Datastore may not include credentials; when missing, treat as UNAUTHORIZED only if no portal can serve request.
    cred_token = None
    if not isinstance(credential, dict) or not isinstance(credential.get("accessToken"), str) or not credential["accessToken"].strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential.accessToken is required and must be a non-empty string", field="credential.accessToken")
    cred_token = credential["accessToken"].strip()

    # Resolve portal: if a credentials store exists, use it; otherwise fall back to any portal that has matching association types
    cred_id = None
    portal_id = None
    cred_rows = _load("credentials.json")
    if isinstance(cred_rows, list) and cred_rows:
        for r in cred_rows:
            if not isinstance(r, dict): 
                continue
            if str(r.get("id")) == cred_token or str(r.get("access_token")) == cred_token or str(r.get("token")) == cred_token or str(r.get("value")) == cred_token:
                # pick active if field exists
                if r.get("status") in (None, "active") and r.get("active") in (None, True):
                    portal_id = r.get("portal_id") or r.get("hubspot_portal_id")
                    cred_id = r.get("id")
                    break

    assoc_types = _load("crm_association_types.json")
    if not isinstance(assoc_types, list): assoc_types = []

    if portal_id is None:
        # choose a portal that can satisfy request
        candidates = []
        for r in assoc_types:
            if not isinstance(r, dict): 
                continue
            if r.get("from_object_type") != fromObjectType or r.get("to_object_type") != toObjectType:
                continue
            pid = r.get("portal_id")
            if isinstance(pid, str) and pid:
                candidates.append(pid)
        if candidates:
            portal_id = sorted(set(candidates))[0]

    if portal_id is None:
        _log("error", error_code="UNAUTHORIZED", credential_id=cred_id)
        return _err("UNAUTHORIZED", "No valid credential provided for any portal that can serve this request.")

    # Filter, sort, paginate
    rows = []
    for r in assoc_types:
        if not isinstance(r, dict): 
            continue
        if r.get("portal_id") != portal_id:
            continue
        if r.get("from_object_type") != fromObjectType or r.get("to_object_type") != toObjectType:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    rows.sort(key=lambda r: str(r.get("id") or ""))

    start = 0
    if after:
        for i, r in enumerate(rows):
            if str(r.get("id")) == after:
                start = i + 1
                break
    page = rows[start:start + lim]
    next_after = None
    if start + lim < len(rows) and page:
        next_after = str(page[-1].get("id"))

    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "associationCategory": r.get("association_category"),
            "associationTypeId": r.get("association_type_id"),
            "label": r.get("label"),
            "status": r.get("status"),
            "fromObjectType": r.get("from_object_type"),
            "toObjectType": r.get("to_object_type"),
        })

    _log("success", portal_id=portal_id, credential_id=cred_id)
    resp = {"total": len(rows), "results": out}
    if next_after is not None:
        resp["paging"] = {"next": {"after": next_after}}
    return resp
